            if !short.is_empty() {
                eprintln!(
                    "[gemv-v4] PTX の引数が {} 本でない ({}) → v3 へ。\
                     `bash build_ptx.sh moe_v4` で再生成する",
                    V4_NARGS,
                    short.join(", ")
                );
                return None;
            }
            image.push(0); // cuModuleLoadData は NUL 終端の PTX を期待する
            let lib = lib().ok()?;
