#[cfg(test)]
mod pf_exp_tc_tests {
    //! task 250: tensor core グループ GEMM (`kernels_exp_iq_tc.cu`) の**索引**を
    //! GPU 無しで固定する。
    //!
    //! カーネルは 32 要素ぶんの重みを 8 個ずつ (j = 0..3) デコードする。その
    //! 索引算術を .cu の行から 1 対 1 で写し、CPU の参照
    //! (`kquant::dequant_row_into`) と要素ごとに比べる。丸め順の一致ではなく
    //! **索引の取り違え**を落とすためのテスト (型ごとに 1 行 512 要素)。

    use super::*;
    use crate::kquant::{dequant_row_into, GgmlType};
    use crate::kquant_tables::{IQ2S_GRID, IQ3S_GRID, IQ3XXS_GRID, KVALUES_IQ4NL, KSIGNS_IQ2XS};

    /// .cu の `dno_tcq_f16` と同じ式 (IEEE の f16 → f32)。
    fn f16v(b: &[u8]) -> f32 {
        let h = b[0] as u32 | ((b[1] as u32) << 8);
        let sign = (h & 0x8000) << 16;
        let exp = (h >> 10) & 0x1f;
        let mut man = h & 0x3ff;
        let bits = if exp == 0 {
            if man == 0 {
                sign
            } else {
                let mut e: i32 = -14;
                while man & 0x400 == 0 {
                    man <<= 1;
                    e -= 1;
                }
                man &= 0x3ff;
                sign | (((e + 127) as u32) << 23) | (man << 13)
            }
        } else if exp == 31 {
            sign | 0x7f80_0000 | (man << 13)
        } else {
            sign | ((exp + 112) << 23) | (man << 13)
        };
        f32::from_bits(bits)
    }

    fn u32le(b: &[u8]) -> u32 {
        b[0] as u32 | ((b[1] as u32) << 8) | ((b[2] as u32) << 16) | ((b[3] as u32) << 24)
    }

    fn sgn(signs: u32, u: usize) -> f32 {
        if signs & (1 << u) != 0 {
            -1.0
        } else {
            1.0
        }
    }

    /// カーネルの 1 要素ぶんのデコード (.cu の `dno_tc_w8_*` を k で引く形)。
    fn mirror(ty: GgmlType, row: &[u8], k: usize) -> f32 {
        let s = k >> 5;
        let sb = s >> 3;
        let sub = s & 7;
        let j = (k & 31) >> 3;
        let u = k & 7;
        match ty {
            GgmlType::IQ2S => {
                let blk = &row[sb * 82..];
                let d = f16v(blk);
                let qh = blk[66 + sub] as u32;
                let idx = (blk[2 + sub * 4 + j] as u32 | ((qh << (8 - 2 * j)) & 0x300)) as usize;
                let sg = blk[34 + sub * 4 + j] as u32;
                let sc = blk[74 + sub] as u32;
                let nib = if j & 2 != 0 { sc >> 4 } else { sc & 0x0f };
                let db = d * (0.5 + nib as f32) * 0.25;
                let grid = IQ2S_GRID[idx];
                let gv = ((grid >> (8 * u)) & 0xff) as f32;
                db * gv * sgn(sg, u)
            }
            GgmlType::IQ3Xxs => {
                let blk = &row[sb * 98..];
                let d = f16v(blk);
                let aux = u32le(&blk[66 + sub * 4..]);
                let db = d * (0.5 + (aux >> 28) as f32) * 0.5;
                let signs = KSIGNS_IQ2XS[((aux >> (7 * j)) & 127) as usize] as u32;
                let g1 = IQ3XXS_GRID[blk[2 + sub * 8 + 2 * j] as usize];
                let g2 = IQ3XXS_GRID[blk[2 + sub * 8 + 2 * j + 1] as usize];
                if u < 4 {
                    db * ((g1 >> (8 * u)) & 0xff) as f32 * sgn(signs, u)
                } else {
                    db * ((g2 >> (8 * (u - 4))) & 0xff) as f32 * sgn(signs, u)
                }
            }
            GgmlType::IQ3S => {
                let blk = &row[sb * 110..];
                let d = f16v(blk);
                let sc = blk[106 + (sub >> 1)] as u32;
                let nib = if sub & 1 != 0 { sc >> 4 } else { sc & 0x0f };
                let db = d * (1.0 + 2.0 * nib as f32);
                let qh = blk[66 + sub] as u32;
                let idx1 = (blk[2 + sub * 8 + 2 * j] as u32 | ((qh << (8 - 2 * j)) & 256)) as usize;
                let idx2 = (blk[2 + sub * 8 + 2 * j + 1] as u32 | ((qh << (7 - 2 * j)) & 256)) as usize;
                let signs = blk[74 + sub * 4 + j] as u32;
                let g1 = IQ3S_GRID[idx1];
                let g2 = IQ3S_GRID[idx2];
                if u < 4 {
                    db * ((g1 >> (8 * u)) & 0xff) as f32 * sgn(signs, u)
                } else {
                    db * ((g2 >> (8 * (u - 4))) & 0xff) as f32 * sgn(signs, u)
                }
            }
            GgmlType::IQ4Xs => {
                let blk = &row[sb * 136..];
                let d = f16v(blk);
                let half = j >> 1;
                let jbase = (j & 1) * 8;
                let sh = blk[2] as u32 | ((blk[3] as u32) << 8);
                let sl = blk[4 + (sub >> 1)] as u32;
                let ls = ((sl >> (4 * (sub & 1))) & 0x0f) | (((sh >> (2 * sub)) & 3) << 4);
                let dl = d * (ls as f32 - 32.0);
                let qs = &blk[8 + sub * 16 + jbase..];
                let q = if half != 0 { qs[u] >> 4 } else { qs[u] & 0x0f };
                dl * KVALUES_IQ4NL[q as usize] as f32
            }
            GgmlType::IQ4Nl => {
                let blk = &row[(k >> 5) * 18..];
                let d = f16v(blk);
                let half = j >> 1;
                let b0 = (j & 1) * 8;
                let byte = blk[2 + b0 + u] as u32;
                let q = if half != 0 { byte >> 4 } else { byte & 0x0f };
                d * KVALUES_IQ4NL[q as usize] as f32
            }
            GgmlType::Q2_0 => {
                let blk = &row[(k >> 6) * 18..];
                let d = f16v(blk);
                let p = k & 63;
                let q = ((blk[2 + (p >> 2)] as u32) >> ((p & 3) * 2)) & 3;
                ((q as i32) - 1) as f32 * d
            }
            _ => unreachable!("6 型だけ"),
        }
    }

    /// 決定的な擬似乱数で 1 行ぶんのバイト列を作る。d (f16) だけは 1.0 に固定する
    /// (NaN/Inf を避ける。他の欄は全ビット模様が有効なので任意でよい)。
    fn make_row(ty: GgmlType, n: usize, seed: u64) -> Vec<u8> {
        let ts = ty.type_size();
        let bs = ty.blck_size();
        let mut v = vec![0u8; (n / bs) * ts];
        let mut s = seed.wrapping_mul(6364136223846793005).wrapping_add(1);
        for b in v.iter_mut() {
            s = s.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
            *b = (s >> 33) as u8;
        }
        for i in 0..(n / bs) {
            v[i * ts] = 0x00;
            v[i * ts + 1] = 0x3C; // f16 の 1.0
        }
        v
    }

    /// 索引が参照と一致する (型ごとに 1 行 512 要素 = 2 ブロック)。
    #[test]
    fn tc_kernel_index_mirror_matches_cpu_reference() {
        for (ty, seed) in [
            (GgmlType::IQ2S, 11u64),
            (GgmlType::IQ3Xxs, 12),
            (GgmlType::IQ3S, 13),
            (GgmlType::IQ4Xs, 14),
            (GgmlType::IQ4Nl, 15),
            (GgmlType::Q2_0, 16),
        ] {
            let n = 512usize;
            let row = make_row(ty, n, seed);
            let mut r = vec![0.0f32; n];
            dequant_row_into(ty, &row, &mut r);
            let mut worst = 0.0f32;
            let mut bad = 0usize;
            for k in 0..n {
                let g = mirror(ty, &row, k);
                let d = (g - r[k]).abs();
                let rel = d / r[k].abs().max(1e-6);
                if !(rel <= 1e-5) {
                    bad += 1;
                    if bad <= 4 {
                        eprintln!("[pf-tc-test] {ty:?} k={k} mirror={g} ref={} rel={rel}", r[k]);
                    }
                }
                worst = worst.max(rel);
            }
            assert_eq!(bad, 0, "{ty:?}: 索引が参照と違う要素 {bad} 個 (worst rel {worst})");
        }
    }

    /// ゲートの真理値表 (既定 off・明示的な真値だけ on)。
    #[test]
    fn tc_exp_gate_is_strictly_opt_in() {
        // task 265: 既定 on、明示的な偽値だけ off。
        assert!(crate::model::exp_pf::tc_exp_from_value(None));
        assert!(crate::model::exp_pf::tc_exp_from_value(Some("")));
        assert!(!crate::model::exp_pf::tc_exp_from_value(Some("0")));
        assert!(!crate::model::exp_pf::tc_exp_from_value(Some("off")));
        assert!(!crate::model::exp_pf::tc_exp_from_value(Some(" false ")));
        assert!(crate::model::exp_pf::tc_exp_from_value(Some("1")));
        assert!(crate::model::exp_pf::tc_exp_from_value(Some("on")));
        assert!(crate::model::exp_pf::tc_exp_from_value(Some("true")));
    }

    /// task 250: 層優先 MoE のトークン分割は「重複なし・取りこぼしなし」。
    #[test]
    fn lm_tile_covers_the_prompt_exactly_once() {
        use crate::model::exp_pf::lm_tile_from_value;
        assert_eq!(lm_tile_from_value(None), 5120, "task 265: 既定は 5120");
        assert_eq!(lm_tile_from_value(Some("")), 5120);
        assert_eq!(lm_tile_from_value(Some("0")), 0);
        assert_eq!(lm_tile_from_value(Some("1023")), 0, "1024 未満は分割しない");
        assert_eq!(lm_tile_from_value(Some("7168")), 7168);
        assert_eq!(lm_tile_from_value(Some("x")), 0);
        for nt in [3826usize, 14018] {
            for t in [5120usize, 7168] {
                let tile = if t >= nt { nt } else { t };
                let mut cover = vec![0u8; nt];
                let mut s0 = 0usize;
                while s0 < nt {
                    let n = tile.min(nt - s0);
                    for c in cover[s0..s0 + n].iter_mut() {
                        *c += 1;
                    }
                    s0 += n;
                }
                assert!(cover.iter().all(|&c| c == 1), "nt={nt} tile={t} に穴か重複");
            }
        }
    }

    /// 作業域の外部予約のゲートも既定 off・明示的な真値だけ on。
    #[test]
    fn lm_reserve_gate_is_strictly_opt_in() {
        use crate::model::exp_pf::{lm_reserve_from_value, tc_exp_from_value};
        for v in [None, Some(""), Some("0"), Some("off"), Some("false")] {
            assert!(!lm_reserve_from_value(v), "lm_reserve({v:?})");
        }
        // task 265: tc_exp is default on; only explicit false values turn it off.
        for v in [Some("0"), Some("off"), Some("false")] {
            assert!(!tc_exp_from_value(v), "tc_exp({v:?})");
        }
        for v in [None, Some("")] {
            assert!(tc_exp_from_value(v), "tc_exp({v:?})");
        }
        for v in [Some("1"), Some("on"), Some("true"), Some(" yes ")] {
            assert!(lm_reserve_from_value(v), "lm_reserve({v:?})");
        }
    }

    /// 形の契約: gate と up が同じ型・4 型・k が 256 の倍数・n が 64 の倍数。
    #[test]
    fn tc_shapes_ok_pins_the_contract() {
        // 実モデルの形 (e = 2560 / ff = 1024)。
        assert!(tc_shapes_ok(Some(1), Some(3), true, 2560, 1024, 1024, 2560));
        // gate と up が違う型は不可。
        assert!(!tc_shapes_ok(Some(1), Some(3), false, 2560, 1024, 1024, 2560));
        // down は IQ4_NL (slot 4) / Q2_0 (slot 5) も受ける (実モデルの down)。
        assert!(tc_shapes_ok(Some(1), Some(4), true, 2560, 1024, 1024, 2560));
        assert!(tc_shapes_ok(Some(1), Some(5), true, 2560, 1024, 1024, 2560));
        // gate/up が IQ4_NL / Q2_0 はこのカーネルの対象外。
        assert!(!tc_shapes_ok(Some(4), Some(3), true, 2560, 1024, 1024, 2560));
        assert!(!tc_shapes_ok(Some(5), Some(3), true, 2560, 1024, 1024, 2560));
        // k が 256 の倍数でない / n が 64 の倍数でない。
        assert!(!tc_shapes_ok(Some(1), Some(3), true, 2432, 1024, 1024, 2560));
        assert!(!tc_shapes_ok(Some(1), Some(3), true, 2560, 1024, 1000, 2560));
        assert!(!tc_shapes_ok(Some(1), Some(3), true, 2560, 1024, 1024, 2540));
        // 0 は不可。
        assert!(!tc_shapes_ok(Some(1), Some(3), true, 0, 1024, 1024, 2560));
    }

    /// `.cu` のタイル定数とホストの定数が一致すること (片方だけ直す事故を落とす)。
    #[test]
    fn tc_tile_constants_match_the_cu() {
        let p = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("kernels")
            .join("kernels_exp_iq_tc.cu");
        let src = std::fs::read_to_string(&p).expect("kernels_exp_iq_tc.cu が読める");
        let get = |name: &str| -> usize {
            let key = format!("#define {name} ");
            let line = src
                .lines()
                .find(|l| l.trim_start().starts_with(&key))
                .unwrap_or_else(|| panic!("{name} が .cu に無い"));
            line.trim_start()[key.len()..]
                .trim()
                .parse()
                .unwrap_or_else(|_| panic!("{name} の値が数値でない"))
        };
        assert_eq!(get("TC_BM"), EXTC_BM, "TC_BM");
        assert_eq!(get("TC_BN"), EXTC_BN, "TC_BN");
        assert_eq!(get("TC_THREADS"), EXTC_THREADS, "TC_THREADS");
        // 1 出力行は 16 列ずつ 4 warp で覆い、トークンは 32 本ずつ 2 段 + 16 本 × 2。
        assert_eq!(EXTC_BN, 4 * 16, "行タイルは wn 4 段 × 16 行");
        assert_eq!(EXTC_BM, 2 * 2 * 16, "トークンタイルは wm 2 段 × 2 断片 × 16");
    }

    /// PTX の引数の数え方がコミット済みの PTX (nvcc の実出力) で 9 になること。
    /// 合成文字列ではなく実物で確かめる (task 68 の ABI ゲートと同じ)。
    #[test]
    fn ptx_entry_params_counts_the_committed_pf_ptx() {
        let p = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("kernels")
            .join("kernels_exp_iq_pf.ptx");
        let Ok(text) = std::fs::read_to_string(&p) else {
            eprintln!("PTX が無いので省略: {}", p.display());
            return;
        };
        for name in ["dno_exp_pf_iq2s", "dno_exp_pf_iq3xxs", "dno_exp_pf_iq3s", "dno_exp_pf_iq4xs"] {
            assert_eq!(
                ptx_entry_params(&text, name),
                Some(9),
                "{name} の引数の数 (ptx パーサの前提)"
            );
        }
    }
}

#[cfg(test)]
mod pf_exp_k_tests {
    //! task 309: K 系 m 行カーネル (`kernels_exp_k_pf.cu`) の**索引**ミラー。
    //!
    //! カーネルの `kpf_w8_q4k` / `_q5k` / `_q6k` と、32 要素ブロックの
    //! `dno_exp_k_pf_q5_1` / `_q8_0` の索引算術を `.cu` の行から 1 対 1 で写し、
    //! CPU の参照 (`kquant::dequant_row_into`) と要素ごとに比べる。
    //! 丸め順の一致ではなく**索引の取り違え**を落とすためのテスト
    //! (型ごとに 1 行 512 要素 = Q4_K/Q5_K/Q6_K は 2 ブロック)。

    use super::*;
    use crate::kquant::{dequant_row_into, GgmlType};

    /// .cu の `kpf_f16` と同じ式 (IEEE の f16 → f32)。
    fn f16v(b: &[u8]) -> f32 {
        let h = b[0] as u32 | ((b[1] as u32) << 8);
        let sign = (h & 0x8000) << 16;
        let exp = (h >> 10) & 0x1f;
        let mut man = h & 0x3ff;
        let bits = if exp == 0 {
            if man == 0 {
                sign
            } else {
                let mut e: i32 = -14;
                while man & 0x400 == 0 {
                    man <<= 1;
                    e -= 1;
                }
                man &= 0x3ff;
                sign | (((e + 127) as u32) << 23) | (man << 13)
            }
        } else if exp == 31 {
            sign | 0x7f80_0000 | (man << 13)
        } else {
            sign | ((exp + 112) << 23) | (man << 13)
        };
        f32::from_bits(bits)
    }

    fn u32le(b: &[u8]) -> u32 {
        b[0] as u32 | ((b[1] as u32) << 8) | ((b[2] as u32) << 16) | ((b[3] as u32) << 24)
    }

    /// .cu の `kpf_scale_min_k4` と同じ式。
    fn scale_min_k4(q: &[u8], j: usize) -> (u32, u32) {
        if j < 4 {
            ((q[j] & 63) as u32, (q[j + 4] & 63) as u32)
        } else {
            (
                ((q[j + 4] & 0x0f) as u32) | (((q[j - 4] >> 6) as u32) << 4),
                ((q[j + 4] >> 4) as u32) | (((q[j] >> 6) as u32) << 4),
            )
        }
    }

    /// カーネルが要素 `k` をどうデコードするか (lane と i を k から引く)。
    fn mirror(ty: GgmlType, row: &[u8], k: usize) -> f32 {
        match ty {
            // 256 要素ブロック: lane = (k % 256) / 8、i = k % 8。
            GgmlType::Q4K => {
                let blk = &row[(k >> 8) * 144..];
                let d = f16v(blk);
                let dmin = f16v(&blk[2..]);
                let lane = (k & 255) >> 3;
                let i = k & 7;
                let sb = lane >> 2;
                let p = (lane & 3) << 3;
                let (sc, mn) = scale_min_k4(&blk[4..16], sb);
                let sh = if sb & 1 != 0 { 4 } else { 0 };
                let q = (blk[16 + (sb >> 1) * 32 + p + i] as u32 >> sh) & 0x0f;
                d * sc as f32 * q as f32 - dmin * mn as f32
            }
            GgmlType::Q5K => {
                let blk = &row[(k >> 8) * 176..];
                let d = f16v(blk);
                let dmin = f16v(&blk[2..]);
                let lane = (k & 255) >> 3;
                let i = k & 7;
                let sb = lane >> 2;
                let p = (lane & 3) << 3;
                let (sc, mn) = scale_min_k4(&blk[4..16], sb);
                let sh = if sb & 1 != 0 { 4 } else { 0 };
                let q = (blk[48 + (sb >> 1) * 32 + p + i] as u32 >> sh) & 0x0f;
                let hb = (blk[16 + p + i] as u32 >> sb) & 1;
                d * sc as f32 * (q + (hb << 4)) as f32 - dmin * mn as f32
            }
            GgmlType::Q6K => {
                let blk = &row[(k >> 8) * 210..];
                let d = f16v(&blk[208..]);
                let lane = (k & 255) >> 3;
                let i = k & 7;
                let half = lane >> 4;
                let o = (lane & 15) << 3;
                let ch = o >> 5;
                let l2 = o & 31;
                let ql = &blk[half * 64 + if ch & 1 != 0 { 32 } else { 0 } + l2..];
                let qh = &blk[128 + half * 32 + l2..];
                let sc = &blk[192 + half * 8..];
                let s = sc[2 * ch + if l2 >= 16 { 1 } else { 0 }] as i8 as f32;
                let sh = if ch >= 2 { 4 } else { 0 };
                let nib = (ql[i] as u32 >> sh) & 0x0f;
                let h2 = (qh[i] as u32 >> (2 * ch)) & 3;
                let q6 = (nib | (h2 << 4)) as i32 - 32;
                d * s * q6 as f32
            }
            // 32 要素ブロック: レーン 1 本 = 1 ブロック (k % 32 が要素)。
            GgmlType::Q5_1 => {
                let blk = &row[(k >> 5) * 24..];
                let d = f16v(blk);
                let m = f16v(&blk[2..]);
                let qh = u32le(&blk[4..]);
                let e = k & 31;
                let byte = blk[8 + (e & 15)] as u32;
                let q = if e < 16 { byte & 0x0f } else { byte >> 4 };
                let hb = (qh >> e) & 1;
                d * (q + (hb << 4)) as f32 + m
            }
            GgmlType::Q8_0 => {
                let blk = &row[(k >> 5) * 34..];
                let d = f16v(blk);
                d * (blk[2 + (k & 31)] as i8) as f32
            }
            _ => unreachable!("K 系 5 型だけ"),
        }
    }

    /// 決定的な擬似乱数で 1 行ぶんのバイト列を作る。スケール欄 (f16) だけは
    /// 有限の値に固定する (NaN/Inf を避ける。他は全ビット模様が有効)。
    fn make_row(ty: GgmlType, n: usize, seed: u64) -> Vec<u8> {
        let ts = ty.type_size();
        let bs = ty.blck_size();
        let mut v = vec![0u8; (n / bs) * ts];
        let mut s = seed.wrapping_mul(6364136223846793005).wrapping_add(1);
        for b in v.iter_mut() {
            s = s.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
            *b = (s >> 33) as u8;
        }
        // f16 の 1.0 = 0x3C00 / 0.5 = 0x3800 / 0.25 = 0x3400 (リトルエンディアン)。
        let put = |v: &mut [u8], off: usize, bytes: [u8; 2]| {
            v[off] = bytes[0];
            v[off + 1] = bytes[1];
        };
        for i in 0..(n / bs) {
            let b = i * ts;
            match ty {
                GgmlType::Q4K | GgmlType::Q5K => {
                    put(&mut v, b, [0x00, 0x3C]); // d = 1.0
                    put(&mut v, b + 2, [0x00, 0x38]); // dmin = 0.5
                }
                GgmlType::Q6K => put(&mut v, b + 208, [0x00, 0x3C]), // d = 1.0
                GgmlType::Q5_1 => {
                    put(&mut v, b, [0x00, 0x3C]); // d = 1.0
                    put(&mut v, b + 2, [0x00, 0x34]); // m = 0.25
                }
                GgmlType::Q8_0 => put(&mut v, b, [0x00, 0x3C]), // d = 1.0
                _ => {}
            }
        }
        v
    }

    /// 索引が参照と一致する (型ごとに 1 行 512 要素)。
    #[test]
    fn k_kernel_index_mirror_matches_cpu_reference() {
        for (ty, seed) in [
            (GgmlType::Q4K, 21u64),
            (GgmlType::Q5K, 22),
            (GgmlType::Q6K, 23),
            (GgmlType::Q5_1, 24),
            (GgmlType::Q8_0, 25),
        ] {
            let n = 512usize;
            let row = make_row(ty, n, seed);
            let mut r = vec![0.0f32; n];
            dequant_row_into(ty, &row, &mut r);
            let mut bad = 0usize;
            let mut worst = 0.0f32;
            for k in 0..n {
                let g = mirror(ty, &row, k);
                let d = (g - r[k]).abs();
                let rel = d / r[k].abs().max(1e-3);
                if !(rel <= 1e-6) {
                    bad += 1;
                    if bad <= 4 {
                        eprintln!("[pf-k-test] {ty:?} k={k} mirror={g} ref={} rel={rel}", r[k]);
                    }
                }
                worst = worst.max(rel);
            }
            assert_eq!(bad, 0, "{ty:?}: 索引が参照と違う要素 {bad} 個 (worst rel {worst})");
        }
    }

    /// コミット済みの K 系 PTX があれば、5 本とも引数 9 個で載っていること
    /// (ホストの起動形と ABI が合っていることの裏取り)。無いときは省略。
    #[test]
    fn ptx_entry_params_counts_the_committed_k_ptx() {
        let p = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("kernels")
            .join("kernels_exp_k_pf.ptx");
        let Ok(text) = std::fs::read_to_string(&p) else {
            eprintln!("PTX が無いので省略: {}", p.display());
            return;
        };
        for name in [
            "dno_exp_k_pf_q4k",
            "dno_exp_k_pf_q5k",
            "dno_exp_k_pf_q6k",
            "dno_exp_k_pf_q5_1",
            "dno_exp_k_pf_q8_0",
        ] {
            assert_eq!(
                ptx_entry_params(&text, name),
                Some(9),
                "{name} の引数の数 (ptx パーサの前提)"
            );
        }
    }
}

#[cfg(test)]
mod pf_stream_tests {
    //! task 162: ストリーミング経路の**契約**を GPU 無しで固定する。

    use super::*;
    use crate::kquant::GgmlType;

    /// task 239: 分割して写しても pinned の中身は 1 回写しと**同一**。
    ///
    /// 分割は「DMA(i) を写し(i+1) と重ねる」ためだけのもので、デバイスへ渡る
    /// バイト列を変えない (数値不変の根拠)。区間は整列の隙間をまたぐ形で切る。
    #[test]
    fn split_copy_into_pin_is_byte_identical() {
        // 96 バイトの転送元を 3 区間に分けて置く (間に整列の隙間がある形)。
        let src: Vec<u8> = (0..96u8).collect();
        let parts = vec![
            (
                0usize,
                PfHostRange {
                    ptr: src.as_ptr() as usize,
                    len: 16,
                    src: None,
                },
            ),
            (
                32usize,
                PfHostRange {
                    ptr: unsafe { src.as_ptr().add(16) } as usize,
                    len: 20,
                    src: None,
                },
            ),
            (
                64usize,
                PfHostRange {
                    ptr: unsafe { src.as_ptr().add(36) } as usize,
                    len: 12,
                    src: None,
                },
            ),
        ];
        let need = 80usize;
        // 従来: 1 回で全部写す。
        let mut one = vec![0xAAu8; need];
        pf_copy_into_pin(one.as_mut_ptr() as usize, &parts, false);
        // 分割: 24 バイトずつ (区間の境界と隙間をまたぐ)。
        let mut split = vec![0xAAu8; need];
        let mut off = 0usize;
        while off < need {
            let len = (need - off).min(24);
            pf_copy_into_pin_range(split.as_mut_ptr() as usize, &parts, off, len, false);
            off += len;
        }
        assert_eq!(one, split, "分割で pinned の中身が変わった");
        // 隙間は書かれない (0xAA のまま)。
        for gap in [16usize..32, 52..64] {
            for &b in &split[gap] {
                assert_eq!(b, 0xAA, "整列の隙間を書いてしまった");
            }
        }
        // 区間の中身は転送元のとおり。
        assert_eq!(&split[0..16], &src[0..16]);
        assert_eq!(&split[32..52], &src[16..36]);
        assert_eq!(&split[64..76], &src[36..48]);
    }

    /// task 481: 小さなバウンスへ**詰めて**写しても、1 回写しと中身が同じ。
    ///
    /// `pf_copy_into_pin_at` は分割 DMA (2 枚のバウンスを交互に使う) の写しで、
    /// オフセットを区間の先頭だけ詰める。区間をずらして繋ぐと 1 枚に写した
    /// ものと 1 バイトも変わらないこと = デバイスへ渡るバイト列が変わらない
    /// ことの根拠。
    #[test]
    fn split_at_copy_reassembles_to_the_same_bytes() {
        let src: Vec<u8> = (0..200u8).map(|i| i.wrapping_mul(7).wrapping_add(3)).collect();
        // 整列の隙間をまたぐ形の 4 区間 (0..20, 32..60, 60..61, 128..190)。
        let parts = vec![
            (
                0usize,
                PfHostRange {
                    ptr: src.as_ptr() as usize,
                    len: 20,
                    src: None,
                },
            ),
            (
                32usize,
                PfHostRange {
                    ptr: unsafe { src.as_ptr().add(20) } as usize,
                    len: 28,
                    src: None,
                },
            ),
            (
                60usize,
                PfHostRange {
                    ptr: unsafe { src.as_ptr().add(48) } as usize,
                    len: 1,
                    src: None,
                },
            ),
            (
                128usize,
                PfHostRange {
                    ptr: unsafe { src.as_ptr().add(49) } as usize,
                    len: 62,
                    src: None,
                },
            ),
        ];
        let need = 190usize;
        // 従来: 1 枚へ全部写す。
        let mut one = vec![0x5Au8; need];
        pf_copy_into_pin(one.as_mut_ptr() as usize, &parts, false);
        // 分割: 24 バイトずつ、2 枚のバウンスへ交互に詰めて繋ぎ直す。
        let chunk = 24usize;
        let mut got = vec![0x5Au8; need];
        let mut off = 0usize;
        let mut i = 0usize;
        while off < need {
            let n = chunk.min(need - off);
            let b = i % 2;
            assert_eq!(b, i % 2);
            pf_copy_into_pin_at(got.as_mut_ptr() as usize + off, &parts, off, n, false);
            off += n;
            i += 1;
        }
        assert_eq!(one, got, "分割で組み立てたバイト列が 1 回写しと違う");
        // 隙間は書かれない。
        for gap in [20usize..32, 61..128] {
            for &x in &got[gap] {
                assert_eq!(x, 0x5A, "整列の隙間を書いてしまった");
            }
        }
        assert_eq!(&got[0..20], &src[0..20]);
        assert_eq!(&got[32..60], &src[20..48]);
        assert_eq!(&got[60..61], &src[48..49]);
        assert_eq!(&got[128..190], &src[49..111]);
    }

    /// task 325: `DENNO_PF_PREAD` の写しが memcpy と 1 バイトも変わらないこと。
    ///
    /// 本物のファイルを 1 本作り、`read_at` 経路と memcpy 経路の出力を比べる。
    /// パートが開けない環境では read_at が false を返して memcpy へ落ちるので、
    /// このテストは「どちらの経路でも同じ」ことを保証する。
    #[test]
    fn pread_copy_is_byte_identical_to_memcpy() {
        use std::io::Write;
        let dir = std::env::temp_dir().join(format!("pf325_{}", std::process::id()));
        std::fs::create_dir_all(&dir).expect("temp dir");
        let path = dir.join("part.gguf");
        // 64 KiB + 端数の擬似乱数 (0 を含む)。
        let n = 64 * 1024 + 17;
        let src: Vec<u8> = (0..n).map(|i| (i * 31 + 7) as u8).collect();
        {
            let mut f = std::fs::File::create(&path).expect("create");
            f.write_all(&src).expect("write");
        }
        exp_pf::install_parts(vec![Some(path.clone())]);
        let opened = exp_pf::parts_open();
        // (pinned 内オフセット, 転送元) を 3 本。1 本はファイル無し (RAM tier 相当)。
        let a_off = 4096u64;
        let b_off = 20000u64;
        let c_off = 64000u64;
        let a_len = 8192usize;
        let b_len = 12345usize;
        let c_len = 1024usize;
        let local = vec![0x5Au8; 777];
        let parts = vec![
            (
                0usize,
                PfHostRange::of_src(&src[a_off as usize..a_off as usize + a_len], (0, a_off)),
            ),
            (
                a_len,
                PfHostRange::of_src(&src[b_off as usize..b_off as usize + b_len], (0, b_off)),
            ),
            (
                a_len + b_len,
                PfHostRange::of_src(&src[c_off as usize..c_off as usize + c_len], (0, c_off)),
            ),
            (a_len + b_len + c_len, PfHostRange::of(&local)),
        ];
        let need = a_len + b_len + c_len + local.len();
        let mut plain = vec![0xEEu8; need];
        pf_copy_into_pin(plain.as_mut_ptr() as usize, &parts, false);
        let mut pre = vec![0xEEu8; need];
        pf_copy_into_pin(pre.as_mut_ptr() as usize, &parts, true);
        assert_eq!(plain, pre, "pread と memcpy で pinned の中身が変わった");
        assert_eq!(&pre[..a_len], &src[a_off as usize..a_off as usize + a_len]);
        assert_eq!(
            &pre[a_len..a_len + b_len],
            &src[b_off as usize..b_off as usize + b_len]
        );
        assert_eq!(
            &pre[a_len + b_len..a_len + b_len + c_len],
            &src[c_off as usize..c_off as usize + c_len]
        );
        assert_eq!(&pre[a_len + b_len + c_len..], &local[..], "ファイル無しは memcpy");
        let _ = opened; // パートが開けなくてもフォールバックで一致する
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// GPU が無い (このコンテナ) ときは起動前に `Ok(None)` を返し、`out` を
    /// 1 要素も書かない (呼び出し側は従来経路をそのまま回せる)。
    #[test]
    fn stream_declines_without_gpu_and_leaves_out_untouched() {
        let host: Vec<u8> = vec![0u8; 256];
        let entries = vec![PfStreamEntry {
            expert: 3,
            dev: None,
            host: Some([host.as_slice(), host.as_slice(), host.as_slice()]),
            src: None,
        }];
        let seg = [1u32, 0, 0, 0];
        let rows = [0u32];
        let xs = vec![0.0f32; 8];
        let prow = [0u32];
        let wrow = [1.0f32];
        let mut out = vec![7.0f32; 4];
        let r = moe_experts_iq_pf_layer_stream(
            GgmlType::IQ3S,
            GgmlType::IQ3S,
            GgmlType::IQ3S,
            &entries,
            &seg,
            &rows,
            &xs,
            8,
            16,
            4,
            1,
            1,
            &prow,
            &wrow,
            32,
            &mut out,
            false,
        )
        .expect("GPU 無しでもエラーにしない");
        assert!(r.is_none(), "GPU が無いのに起動した");
        assert!(out.iter().all(|&v| v == 7.0), "out を書いてしまった: {out:?}");
        // 形が合わないときも同じ (fail closed)。
        let r2 = moe_experts_iq_pf_layer_stream(
            GgmlType::IQ3S,
            GgmlType::IQ3S,
            GgmlType::IQ3S,
            &entries,
            &[1u32, 0, 0],
            &rows,
            &xs,
            8,
            16,
            4,
            1,
            1,
            &prow,
            &wrow,
            32,
            &mut out,
            false,
        );
        assert!(r2.is_err() || r2.expect("shape").is_none());
    }

    /// task 162: GDN スキャンの分割は「単発の上限未満」「端数を出さない」
    /// 「連続・重複なし・合計 nt」を満たす。
    #[test]
    fn gdn_sub_bounds_cover_nt_without_tiny_tail() {
        let lim = gdn_sub_limit();
        let min = gdn_sig_min();
        for nt in [1usize, 19, 64, 512, 1024, 2047, 2048, 2049, 2100, 4096, 14018] {
            let b = gdn_sub_bounds(nt);
            assert!(!b.is_empty(), "nt={nt}");
            assert_eq!(b[0].0, 0, "nt={nt}");
            assert_eq!(b[b.len() - 1].1, nt, "nt={nt} の末尾");
            let mut prev = 0usize;
            for &(a, e) in b.iter() {
                assert_eq!(a, prev, "nt={nt} が連続でない");
                assert!(e > a, "nt={nt} に空の範囲");
                assert!(e - a < lim, "nt={nt} に上限以上の範囲 {}", e - a);
                if b.len() > 1 {
                    assert!(e - a >= min, "nt={nt} に小さすぎる範囲 {}", e - a);
                }
                prev = e;
            }
            assert_eq!(prev, nt, "nt={nt} の合計");
        }
        assert!(gdn_sub_bounds(0).is_empty());
        assert_eq!(gdn_sub_bounds(lim - 1), vec![(0, lim - 1)], "上限未満は 1 回");
    }

    /// ステージングは decode の LRU を追い出さない: 確保は `pf_stage_alloc`
    /// (cuMemAlloc 直) だけで、`DevBuffer::alloc_tagged` のフォールバックを
    /// 通らない。ここでは確保要求 0 で何も取らないことを固定する。
    #[test]
    fn stage_alloc_is_a_noop_for_zero() {
        assert!(pf_stage_alloc(0, 0).is_none());
    }

    /// task 254: 表の非同期 H2D のゲートは他のゲートと同じ解釈で、GPU が無い
    /// 環境では必ず `false` を返して同期版へ落ちる (fail closed)。
    #[test]
    fn tab_async_gate_parses_and_falls_back_without_gpu() {
        assert!(pf_tab::value_on(None));
        assert!(pf_tab::value_on(Some("1")));
        assert!(!pf_tab::value_on(Some("0")));
        assert!(!pf_tab::value_on(Some("false")));
        assert!(!pf_tab::value_on(Some("no")));
        // 分岐が呼ばれたことは数える (GPU 無し = false で同期版)。
        let before = pf_tab::counts();
        let data = [1u64, 2, 3];
        let bytes = unsafe {
            std::slice::from_raw_parts(data.as_ptr() as *const u8, std::mem::size_of_val(&data))
        };
        let ok = pf_tab::upload(&[(0u64, 0, bytes)]);
        let after = pf_tab::counts();
        if cuda_enabled() {
            // GPU のある環境では成功してよい (このコンテナでは起きない)。
            assert!(ok || after.0 > before.0, "呼び出しが数えられていない");
        } else {
            assert!(!ok, "GPU が無いのに非同期で積めた");
            assert_eq!(after.0, before.0 + 1, "呼び出しが数えられていない");
            assert_eq!(after.1, before.1, "成功数を増やしてしまった");
        }
    }

    /// task 254: 空の表は何もせず成功扱い (呼び出し側が同期版を選ばない)。
    #[test]
    fn tab_async_empty_upload_is_ok() {
        assert!(pf_tab::upload(&[]));
        let data: [u8; 0] = [];
        assert!(pf_tab::upload(&[(0u64, 0, &data)]));
    }

    /// task 248: ピーク記録 (`mem_audit::note_alloc` → `peak_note`) は prefill
    /// ステージングの確保中にも呼ばれる。ここで thread_local (PF_STREAM の
    /// RefCell) を読むと**二重借用で panic する** (lab t248b で踏んだ)。
    /// ピーク記録が thread_local を触らないことを、借用を持ったまま固定する。
    #[test]
    fn peak_note_runs_while_the_staging_refcell_is_borrowed() {
        crate::mem_audit::force_audit_for_test(Some(true));
        {
            let _w = crate::mem_audit::peak_window("t");
            PF_STREAM.with(|cell| {
                let _st = cell.borrow_mut();
                crate::mem_audit::note_alloc(crate::mem_audit::TAG_PF_STAGE, 1 << 20);
                crate::mem_audit::note_free(crate::mem_audit::TAG_PF_STAGE, 1 << 20);
            });
        }
        crate::mem_audit::force_audit_for_test(None);
    }

    /// task 165: グループ番号は層をまたいで単調 (連番) に増える。
    ///
    /// 層ごとに 0 へ戻すと、スロット (`g % 3`) の持ち主が前の層のグループと
    /// 重なり、前の層の完了イベントを「自分のグループの完了」と誤認する。
    /// ここでは 3 層ぶん確保して、番号が連続しスロットの持ち主が 3 つ前だけに
    /// なることを固定する。
    #[test]
    fn group_ids_are_monotonic_across_layers() {
        let sizes = [16usize, 7, 3];
        let mut next = 0u64;
        let mut bases = Vec::new();
        let mut all: Vec<u64> = Vec::new();
        for &n in sizes.iter() {
            let base = pf_take_group_ids(&mut next, n);
            bases.push(base);
            all.extend((0..n as u64).map(|i| base + i));
        }
        assert_eq!(bases, vec![0, 16, 23], "層の先頭が前の層の続きでない: {bases:?}");
        assert_eq!(all.len(), 26);
        for w in all.windows(2) {
            assert_eq!(w[1], w[0] + 1, "通し番号が連続でない: {all:?}");
        }
        // 同じスロットを共有するのは 3 グループ前だけ (番号が一意なので当然)。
        for (i, &g) in all.iter().enumerate() {
            assert_eq!(g as usize, i);
            assert_eq!((g % 3) as usize, i % 3);
        }
        // 0 本でも番号は進めない (空の層で番号が飛ばない)。
        let base = pf_take_group_ids(&mut next, 0);
        assert_eq!(base, 26);
        assert_eq!(next, 26);
    }

    /// task 165 / 554: 上げスレッドの進捗公開はグループ単位の旗で、エラーは
    /// 最初の 1 本を残す。
    #[test]
    fn up_progress_publishes_per_group() {
        let st = (
            std::sync::Mutex::new(PfUpState {
                done: Vec::new(),
                times: Vec::new(),
                probe: None,
                err: None,
            }),
            std::sync::Condvar::new(),
        );
        pf_up_publish(&st, 0, 10, 20, 30, Some((1_000, 5)), None);
        pf_up_publish(&st, 1, 11, 21, 31, None, None);
        {
            let s = st.0.lock().expect("poisoned");
            assert_eq!(s.done, vec![true, true], "2 グループとも記録済み");
            assert_eq!(s.times[0], (10, 20, 30));
            assert_eq!(s.times[1], (11, 21, 31));
            assert_eq!(s.probe, Some((1_000, 5)));
        }
        // 遅れて届いた小さい番号でも旗は戻らず、エラーは残る。
        pf_up_publish(&st, 0, 0, 0, 0, None, Some("最初のエラー".to_string()));
        pf_up_publish(&st, 2, 12, 22, 32, None, Some("2 本目".to_string()));
        let s = st.0.lock().expect("poisoned");
        assert_eq!(s.done, vec![true, true, true]);
        assert_eq!(s.err.as_deref(), Some("最初のエラー"), "エラーが上書きされた");
        assert_eq!(s.times[2], (12, 22, 32));
    }

    /// task 554: 上げスレッドが 2 本だと完了が**順不同**に届く。旗はグループ
    /// 単位なので、2 本目が先に届いても 1 本目の旗は立たない (= 古い `ev_up` で
    /// 計算側の待ちが満たされない)。空のグループ (依頼しない番号) があっても
    /// 他のグループの待ちは返る。
    #[test]
    fn up_progress_flags_do_not_leak_across_groups() {
        let st = (
            std::sync::Mutex::new(PfUpState {
                done: Vec::new(),
                times: Vec::new(),
                probe: None,
                err: None,
            }),
            std::sync::Condvar::new(),
        );
        // 2 本目が先に終わる (1 本目はまだ)。
        pf_up_publish(&st, 1, 11, 21, 31, None, None);
        {
            let s = st.0.lock().expect("poisoned");
            assert_eq!(s.done, vec![false, true], "1 本目の旗が立った");
        }
        pf_up_publish(&st, 0, 10, 20, 30, None, None);
        // 3 番目は依頼しない (空のグループ) まま 4 番目が届く。
        pf_up_publish(&st, 3, 13, 23, 33, None, None);
        let s = st.0.lock().expect("poisoned");
        assert_eq!(s.done, vec![true, true, false, true], "空の 2 番目は false のまま");
    }

    /// task 554/570: `DENNO_PF_UP_WORKERS` の解釈 (1..=3、既定 3、壊れた値は既定)。
    #[test]
    fn up_workers_values_round_and_default() {
        use crate::model::exp_pf::{up_workers_from_value, DEFAULT_UP_WORKERS};
        assert_eq!(
            DEFAULT_UP_WORKERS, 3,
            "既定は 3 本 (task 570 で 2 -> 3。lab t566a の 3,826 -4..-8% / 14k -5%)"
        );
        assert_eq!(up_workers_from_value(None), 3);
        assert_eq!(up_workers_from_value(Some("")), 3);
        assert_eq!(up_workers_from_value(Some("1")), 1, "切り戻し");
        assert_eq!(up_workers_from_value(Some(" 3 ")), 3);
        assert_eq!(up_workers_from_value(Some("0")), 1, "0 は 1 本へ");
        assert_eq!(up_workers_from_value(Some("9")), 3, "スロット 3 枚が上限");
        assert_eq!(up_workers_from_value(Some("x")), 3, "壊れた値は既定");
    }

    /// task 570: `DENNO_PF_STREAM_LOOKAHEAD_PREAD` の解釈と、実効の深さ。
    ///
    /// **pread の立つグループだけ深い**。既定モデル (非 pread) は base のまま
    /// (= P379 が +2.4% と測った深さへ動かさない)。
    #[test]
    fn lookahead_pread_gate_and_effective_depth() {
        use crate::model::exp_pf::{
            lookahead_for, stream_lookahead_pread_from_value,
            DEFAULT_STREAM_LOOKAHEAD, DEFAULT_STREAM_LOOKAHEAD_PREAD,
        };
        assert_eq!(DEFAULT_STREAM_LOOKAHEAD, 1, "base は 1 のまま (既定モデル)");
        assert_eq!(DEFAULT_STREAM_LOOKAHEAD_PREAD, 2, "pread は 2 (3 グループ)");
        assert_eq!(
            stream_lookahead_pread_from_value(None),
            DEFAULT_STREAM_LOOKAHEAD_PREAD
        );
        assert_eq!(stream_lookahead_pread_from_value(Some("")), 2);
        assert_eq!(stream_lookahead_pread_from_value(Some("0")), 0, "切り戻し");
        assert_eq!(stream_lookahead_pread_from_value(Some("1")), 1, "切り戻し");
        assert_eq!(stream_lookahead_pread_from_value(Some("2")), 2);
        assert_eq!(stream_lookahead_pread_from_value(Some("9")), 2, "上限は 2");
        assert_eq!(stream_lookahead_pread_from_value(Some("x")), 2);
        // 実効の深さ: pread のときだけ深い。非 pread は base のまま。
        assert_eq!(lookahead_for(false, 1, 2), 1, "既定モデルは 1 のまま");
        assert_eq!(lookahead_for(true, 1, 2), 2, "UD は 2");
        assert_eq!(lookahead_for(true, 0, 2), 2, "ut off は 0 だが pread なら 2");
        assert_eq!(lookahead_for(true, 1, 0), 1, "ゲートを 0 にすると base");
        assert_eq!(lookahead_for(true, 2, 1), 2, "小さい側へは動かさない");
        assert_eq!(lookahead_for(false, 2, 0), 2);
    }

    /// task 558: `DENNO_PF_PREAD_POOL_PER_UP` の解釈と、番号ごとのプールの割り当て。
    ///
    /// 既定 on (task 558 で採用、lab の 3,826 cold が -10.8% / -8.3%)。
    /// `0` で 1 本共有へ切り戻せる。プールは上げスレッドの番号ごとに別の実体を
    /// 返し、範囲外の番号は `None` (呼び出し側が共有プールへ落ちる)。
    #[test]
    fn pread_pool_per_up_gate_and_pools() {
        use crate::model::exp_pf::{pread_pool_per_up_from_value, DEFAULT_PREAD_POOL_PER_UP};
        assert!(DEFAULT_PREAD_POOL_PER_UP, "lab で採ったのに既定 off に戻っている");
        assert!(pread_pool_per_up_from_value(None), "未設定は既定 on");
        assert!(pread_pool_per_up_from_value(Some("")));
        assert!(!pread_pool_per_up_from_value(Some("0")), "切り戻し");
        assert!(!pread_pool_per_up_from_value(Some("off")));
        assert!(pread_pool_per_up_from_value(Some("1")));
        assert!(pread_pool_per_up_from_value(Some(" ON ")));
        // 計算スレッド (このテストスレッド) は番号を持たない = 共有プール。
        assert_eq!(pf_up_idx(), None, "計算スレッドに上げ番号が付いた");
        // 番号 0..2 はそれぞれ別のプール、3 以上は範囲外。
        let p0 = pf_pread_pool_up(2, 0);
        let p1 = pf_pread_pool_up(2, 1);
        assert!(p0.is_some() && p1.is_some(), "番号ごとのプールが作れない");
        assert!(
            !std::ptr::eq(p0.expect("確保済み"), p1.expect("確保済み")),
            "番号 0 と 1 が同じプールを共有している"
        );
        assert!(pf_pread_pool_up(2, 3).is_none(), "範囲外は共有プールへ");
    }

    /// task 558: 上げスレッド本体が自分の番号を焼くと、そのスレッドの
    /// `pf_copy_into_pin` だけが番号付きのプールを選ぶ (計算スレッドは None)。
    #[test]
    fn pread_pool_per_up_index_is_thread_local() {
        let seen = std::sync::Arc::new(std::sync::Mutex::new(Vec::new()));
        let s = std::sync::Arc::clone(&seen);
        std::thread::spawn(move || {
            // pf_up_worker と同じ焼き方をする。
            let _ = PF_UP_IDX.try_with(|c| c.set(Some(1usize)));
            s.lock().expect("poisoned").push(pf_up_idx());
        })
        .join()
        .expect("スレッドが落ちた");
        assert_eq!(*seen.lock().expect("poisoned"), vec![Some(1)]);
        assert_eq!(pf_up_idx(), None, "別スレッドの番号が漏れた");
    }

    /// task 227: 「1 回の DMA で流す塊」の切り方 (純関数)。
    ///
    /// 塊は parts の境界で切る (途中で切ると写しが半端になる)、長さは limit を
    /// 超えない、隙間 (整列の詰め物) は塊に含めてよい、1 本が limit より
    /// 大きければその 1 本だけ、を固定する。
    #[test]
    fn chunk_spans_follow_part_boundaries_and_limit() {
        // 隙間なしの 3 本 (100 B ずつ) → limit 250 は 2 本ずつ。
        let p = [(0usize, 100usize), (100, 100), (200, 100)];
        assert_eq!(pf_chunk_spans(&p, 0), vec![(0, 300)], "0 は全部で 1 回");
        assert_eq!(pf_chunk_spans(&p, 250), vec![(0, 200), (200, 300)]);
        assert_eq!(pf_chunk_spans(&p, 100), vec![(0, 100), (100, 200), (200, 300)]);
        // 整列の隙間 (16 B) は塊に含む (中身は読まれない)。
        let p = [(0usize, 100usize), (116, 100), (232, 100)];
        assert_eq!(pf_chunk_spans(&p, 250), vec![(0, 216), (232, 332)]);
        // 1 本が limit より大きいときは、その 1 本だけの塊になる。
        let p = [(0usize, 1000usize), (1000, 10)];
        assert_eq!(pf_chunk_spans(&p, 64), vec![(0, 1000), (1000, 1010)]);
        // 空は空。
        assert!(pf_chunk_spans(&[], 128).is_empty());
        // 塊は昇順・非重複で、全 parts を覆う。
        let p: Vec<(usize, usize)> = (0..40).map(|i| (i * 1000 + 16, 984)).collect();
        let spans = pf_chunk_spans(&p, 4096);
        let mut at = 0usize;
        for &(a, b) in &spans {
            assert!(a >= at, "塊が戻った");
            assert!(b > a);
            assert!(b - a <= 4096 + 984, "塊が大きすぎる {}", b - a);
            at = b;
        }
        assert_eq!(spans.last().map(|s| s.1), Some(39 * 1000 + 16 + 984));
    }
}

#[cfg(test)]
mod iq_overlap_tests {
    //! task 150: 重ね打ち経路の**契約**を GPU 無しで固定する。
    use super::*;
    use crate::kquant::GgmlType;

    /// task 164: プローブのホスト写しは**宛先が転送元より長い**ことを前提にする
    /// (pinned の bounce は 2 MB 固定、実スライスは 1 枚ぶん)。lab t164a では
    /// `copy_from_slice` の長さ不一致で panic した (tline / missup の 2 条件が
    /// 丸ごと落ちた)。ここで長さの扱いだけを固定する。
    #[test]
    fn probe_host_copy_accepts_short_source() {
        let mut dst = vec![0u8; 64];
        let src = vec![7u8; 10];
        let gbs = host_copy_gbs(&mut dst, &src, 4);
        assert!(gbs > 0.0, "写しのレートが 0");
        assert_eq!(&dst[..10], &src[..]);
        assert_eq!(dst[10], 0, "転送元より後ろは触らない");
    }

    /// task 164: prologue の非同期化は **既定 on**、明示的な偽値だけ切る。
    /// lab t164c で decode -3.0〜-3.6% / md5 SAME だったので既定を on にした。
    #[test]
    fn dec_pro_async_gate_defaults_on() {
        assert!(dec_pro_async_from_value(None));
        assert!(dec_pro_async_from_value(Some("1")));
        assert!(dec_pro_async_from_value(Some("ON")));
        assert!(!dec_pro_async_from_value(Some("0")));
        assert!(!dec_pro_async_from_value(Some("off")));
        assert!(!dec_pro_async_from_value(Some(" FALSE ")));
        assert!(!dec_pro_async_from_value(Some("no")));
    }

    /// task 164: prologue ステージングのレイアウトは 8 バイト整列で、各ブロックが
    /// 重ならないこと。`u64` の表を `u64` として読むので整列が要る。
    #[test]
    fn dec_stage_layout_is_aligned_and_disjoint() {
        let l = dec_stage_layout(2560, 10, 40, 40, 10, 0);
        assert_eq!(l.x, 0);
        assert_eq!(l.pg, 2560 * 4);
        assert_eq!(l.pu, l.pg + 80);
        assert_eq!(l.pd, l.pu + 80);
        assert_eq!(l.sgu, l.pd + 80);
        assert_eq!(l.sgd, l.sgu + 160);
        assert_eq!(l.w, l.sgd + 160);
        assert_eq!(l.total, l.w + 40);
        for off in [l.x, l.pg, l.pu, l.pd, l.sgu, l.sgd, l.w] {
            assert_eq!(off % 8, 0, "オフセット {off} が 8 バイト整列でない");
        }
        // ブロックの境界が重ならない (前の終わり <= 次の始まり)。
        assert!(l.x + 2560 * 4 <= l.pg);
        assert!(l.sgd + 40 * 4 <= l.w);
        assert!(l.w + 10 * 4 <= l.total);
    }

    /// task 164: ステージングへの書き込みは指定オフセットにだけ載る。
    #[test]
    fn dec_stage_put_writes_at_offset() {
        let l = dec_stage_layout(4, 1, 4, 4, 0, 0);
        let mut buf = vec![0u8; l.total];
        let x = [1.0f32, 2.0, 3.0, 4.0];
        unsafe {
            dec_stage_put(&mut buf, l.x, x.as_ptr() as *const u8, 16);
        }
        assert_eq!(&buf[l.x..l.x + 4], &1.0f32.to_ne_bytes());
        assert_eq!(&buf[l.x + 12..l.x + 16], &4.0f32.to_ne_bytes());
        assert!(buf[l.pg..].iter().all(|&b| b == 0), "後続のブロックを汚した");
    }

    /// task 164: ミス GPU 経路は**起動前に落ちるとき**必ず `Ok(false)` を返し、
    /// `out_h` を 1 要素も書かない (呼び出し側は従来経路へ戻せる)。
    /// GPU の無いテスト環境では毎回ここに落ちるので、契約だけを固定できる。
    #[test]
    fn miss_up_fails_closed_before_launching() {
        let x = vec![0.1f32; 8];
        let g = vec![0u8; 4];
        let mut out: Vec<f32> = vec![7.0f32; 3];
        let hit = [0u64];
        let ids_hit = [0u16];
        let ids_miss = [1u16];
        // ミス 0 本は「この経路ではやらない」。
        let r = moe_experts_iq_layer_miss_up(
            GgmlType::IQ2S,
            GgmlType::IQ2S,
            GgmlType::IQ2S,
            &hit,
            &hit,
            &hit,
            &ids_hit,
            &[],
            &[],
            &x,
            8,
            8,
            8,
            &mut out,
        );
        assert!(matches!(r, Ok(false)), "{r:?}");
        assert_eq!(out, vec![7.0f32; 3]);
        // 重みの長さが型・形と合わないミスは起動しない (型の取り違えを静かに
        // 通さないための最後の砦)。
        let miss = [MissExpertBytes {
            gate: &g,
            up: &g,
            down: &g,
        }];
        let r = moe_experts_iq_layer_miss_up(
            GgmlType::IQ2S,
            GgmlType::IQ2S,
            GgmlType::IQ2S,
            &hit,
            &hit,
            &hit,
            &ids_hit,
            &miss,
            &ids_miss,
            &x,
            8,
            8,
            8,
            &mut out,
        );
        assert!(matches!(r, Ok(false)), "{r:?}");
        assert_eq!(out, vec![7.0f32; 3]);
    }

    /// 形状が不正なら起動前に `Ok(false)` を返し、**CPU ミスのコールバックを
    /// 呼ばない** (呼び出し側は全 expert を CPU で計算し直せる)。呼んでしまうと
    /// 二重計算になるうえ、`out_h` が途中まで書かれた状態で CPU 経路へ戻すことになる。
    #[test]
    fn overlap_skips_cpu_miss_when_it_does_not_launch() {
        // task 388: `cpu_miss` は `Send` を要求される (`DENNO_DEC_MISS_SPAWN` で
        // プールへ渡せるようにするため) ので、数え役は atomic にする。
        let called = std::sync::atomic::AtomicU32::new(0);
        let mut out = vec![0.0f32; 4];
        // seg_gu の長さが 4 の倍数でない → 起動計画より前に落ちる。
        let r = moe_experts_iq_layer_overlap(
            GgmlType::IQ2S,
            GgmlType::IQ2S,
            GgmlType::IQ2S,
            &[0u64],
            &[0u64],
            &[0u64],
            &[0u32, 1, 0, 0, 0],
            &[0u32, 1, 0, 0, 0, 0, 0, 0],
            &[0.0f32; 8],
            8,
            16,
            4,
            &mut out,
            || {
                called.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                Ok(())
            },
        )
        .expect("形状検査は Err ではなく Ok(false)");
        assert!(!r, "不正な形状で GPU 経路を選んではいけない");
        assert_eq!(
            called.load(std::sync::atomic::Ordering::Relaxed),
            0,
            "起動しないのに CPU ミスを走らせた"
        );
        assert!(out.iter().all(|&v| v == 0.0), "out を書いてはいけない");
    }

    /// 逐次版と重ね打ち版は同じ入口 (`iq_layer_run`) を通る。GPU の無い環境では
    /// どちらも `Ok(false)` で、値は 1 つも書かれない。
    #[test]
    fn both_entries_fall_back_without_cuda() {
        let mut out_a = vec![7.0f32; 4];
        let mut out_b = vec![7.0f32; 4];
        let a = moe_experts_iq_layer(
            GgmlType::IQ2S,
            GgmlType::IQ2S,
            GgmlType::IQ2S,
            &[0u64],
            &[0u64],
            &[0u64],
            &[0u32, 0, 0, 0],
            &[0u32, 0, 0, 0],
            &[0.0f32; 8],
            8,
            16,
            4,
            &mut out_a,
        )
        .expect("逐次版");
        let b = moe_experts_iq_layer_overlap(
            GgmlType::IQ2S,
            GgmlType::IQ2S,
            GgmlType::IQ2S,
            &[0u64],
            &[0u64],
            &[0u64],
            &[0u32, 0, 0, 0],
            &[0u32, 0, 0, 0],
            &[0.0f32; 8],
            8,
            16,
            4,
            &mut out_b,
            || Ok(()),
        )
        .expect("重ね打ち版");
        assert_eq!(a, b, "同じ入口なのに戻り値が違う");
        assert_eq!(out_a, out_b, "out の扱いが違う");
    }
}

#[cfg(test)]
mod grouped_tests {
    //! P40: 起動形の純関数 (GPU 無しでも検証できる部分)。
    use super::*;

    #[test]
    fn launch_plan_sizes_smem_for_two_matrices() {
        // Q4_K (blkj=256) の gate+up: 16 行 × 256 × 4 B × 2 本 = 32 KiB
        let p = grouped_launch_plan(86, 60, 640, 256, 2)
            .expect("plan")
            .expect("some");
        assert_eq!(p.grid, (86, 40, 4)); // 640/16 = 40 行タイル、ceil(60/16) = 4
        assert_eq!(p.block, (16, 16, 1));
        assert_eq!(p.smem, 16 * 256 * 4 * 2);
        assert!(p.smem < 46_000, "48 KiB 既定を超えないこと");
        // Q5_1 (blkj=32) の down: 16 × 32 × 4 = 2 KiB
        let q = grouped_launch_plan(86, 60, 2560, 32, 1)
            .expect("plan")
            .expect("some");
        assert_eq!(q.grid, (86, 160, 4));
        assert_eq!(q.smem, 16 * 32 * 4);
    }

    #[test]
    fn launch_plan_rejects_oversized_smem_and_empty() {
        assert!(grouped_launch_plan(0, 10, 640, 256, 2)
            .expect("plan")
            .is_none());
        assert!(grouped_launch_plan(8, 0, 640, 256, 2)
            .expect("plan")
            .is_none());
        // 3 本同時 (Q4_K) は 48 KiB で既定を超える = 過去に全滅した形
        assert!(grouped_launch_plan(8, 10, 640, 256, 3)
            .expect("plan")
            .is_none());
        // 32 行タイル x 256 要素 x 4 B x 2 = 64 KiB も落ちる
        assert!(grouped_launch_plan(8, 10, 640, 512, 2)
            .expect("plan")
            .is_none());
    }

    #[test]
    fn env_value_parsing() {
        assert!(moe_grouped_gpu_from_value(Some("1")));
        assert!(moe_grouped_gpu_from_value(Some("on")));
        assert!(moe_grouped_gpu_from_value(Some("true")));
        assert!(!moe_grouped_gpu_from_value(None));
        assert!(!moe_grouped_gpu_from_value(Some("0")));
        assert!(!moe_grouped_gpu_from_value(Some("off")));
        assert!(!moe_grouped_gpu_from_value(Some("")));
    }
}

// ===========================================================================
// P17b: エンジン統合 (重み VRAM 常駐 + ピン留め/非同期パイプライン)
// ===========================================================================
//
// `quant::Linear` の int8 パス (apply_bt / apply_batch_bt / apply) から呼ばれ、
// `DENNO_CUDA=1` + feature `cuda` のとき int8 線形層を GPU にオフロードする。
// - 数値は CPU カーネルとビット一致 (同一カーネル = P17 の exactness 契約そのまま)
// - 重みは初回呼び出し時に VRAM へアップロードして常駐 (Quant8Linear のバッファ
//   ポインタをキーにしたレジストリ。ロード後の重みは不変であることが前提)
// - 固定オーバーヘッド削減: ピン留めホストメモリ + 非同期コピー/起動で
//   **1 線形層 = 1 同期** (P17 マイクロベンチでは起動+同期+コピーで約40µs/呼び出し)
// - 初期化失敗/実行時エラーは CPU パスへフォールバック (両者は同一仕様なので
//   出力は不変。実行時エラー後は二度と試さない)

/// ピン留めホストメモリ (非同期コピーの転送元/転送先)。
struct PinMem {
    ptr: *mut c_void,
    bytes: usize,
}

// 生ポインタを保持するだけ (スレッド局所で共有しない)
unsafe impl Send for PinMem {}

impl PinMem {
    fn alloc(bytes: usize) -> Result<Self> {
        Self::alloc_flags(bytes, false)
    }

    /// task 165: `write_combined` は書き込み結合の pinned にする。
    ///
    /// ストリーミングのバウンスは **CPU が書いて DMA が読むだけ**なので、
    /// write-combined にすると書き込みの read-for-ownership が消える
    /// (キャッシュには載らない。CPU から読み直さないので問題ない)。
    /// 確保に失敗したら通常の pinned へ落ちる (数値はどちらも同じ)。
    fn alloc_flags(bytes: usize, write_combined: bool) -> Result<Self> {
        let mut ptr: *mut c_void = std::ptr::null_mut();
        // PORTABLE: どのコンテキストからでも有効 (保険)
        const CU_MEMHOSTALLOC_PORTABLE: u32 = 0x01;
        const CU_MEMHOSTALLOC_WRITECOMBINED: u32 = 0x04;
        let bytes = bytes.max(1);
        let lib = lib()?;
        if write_combined {
            let flags = CU_MEMHOSTALLOC_PORTABLE | CU_MEMHOSTALLOC_WRITECOMBINED;
            let ok = unsafe {
                check((lib.mem_host_alloc)(&mut ptr, bytes, flags), "cuMemHostAlloc (wc)").is_ok()
            };
            if ok {
                return Ok(Self { ptr, bytes });
            }
        }
        unsafe {
            check(
                (lib.mem_host_alloc)(&mut ptr, bytes, CU_MEMHOSTALLOC_PORTABLE),
                "cuMemHostAlloc",
            )?;
        }
        Ok(Self { ptr, bytes })
    }

    fn as_slice<T>(&self) -> &[T] {
        unsafe { std::slice::from_raw_parts(self.ptr as *const T, self.bytes / std::mem::size_of::<T>()) }
    }

    fn as_mut_slice<T>(&mut self) -> &mut [T] {
        unsafe { std::slice::from_raw_parts_mut(self.ptr as *mut T, self.bytes / std::mem::size_of::<T>()) }
    }

    /// task 382: **device から直接見える** pinned (`CU_MEMHOSTALLOC_DEVICEMAP`)。
    ///
    /// 返り値の `CUdeviceptr` は同じホストメモリを指すので、カーネルは
    /// H2D 無しでこれを読み、D2H 無しでこれへ書ける (PCIe 越しの読み書きは
    /// ユニファイドアドレスで透過)。mix の鎖は 1 回 5.7 us の H2D と 2.6 us の
    /// D2H を払っていたので、そこを消すための器。
    ///
    /// DEVICEMAP が付かない環境 (古い driver / WSL など) では `Err` を返し、
    /// 呼び出し側は従来の H2D / D2H 経路へ落ちる (fail closed)。
    fn alloc_mapped(bytes: usize) -> Result<(Self, CUdeviceptr)> {
        const CU_MEMHOSTALLOC_PORTABLE: u32 = 0x01;
        const CU_MEMHOSTALLOC_DEVICEMAP: u32 = 0x02;
        let bytes = bytes.max(1);
        let lib = lib()?;
        let Some(get_dev) = lib.mem_host_get_device_ptr else {
            bail!("cuMemHostGetDevicePointer が無い");
        };
        let mut ptr: *mut c_void = std::ptr::null_mut();
        unsafe {
            check(
                (lib.mem_host_alloc)(
                    &mut ptr,
                    bytes,
                    CU_MEMHOSTALLOC_PORTABLE | CU_MEMHOSTALLOC_DEVICEMAP,
                ),
                "cuMemHostAlloc (devicemap)",
            )?;
        }
        let mut dev: CUdeviceptr = 0;
        unsafe {
            let rc = get_dev(&mut dev, ptr, 0);
            if rc != CUDA_SUCCESS {
                let _ = (lib.mem_host_free)(ptr);
                bail!("cuMemHostGetDevicePointer が失敗: {rc:?}");
            }
        }
        Ok((Self { ptr, bytes }, dev))
    }
}

/// task 382: device から直接読み書きできる pinned の組 (ホスト側の見え方と
/// device 側の見え方は同じ 1 本のメモリ)。
struct MapMem {
    pin: PinMem,
    dev: CUdeviceptr,
}

impl MapMem {
    /// 必要バイト数を満たすまで確保し直す (足りていれば何もしない)。
    fn ensure(slot: &mut Option<MapMem>, bytes: usize) -> Result<()> {
        if let Some(m) = slot.as_ref() {
            if m.pin.bytes >= bytes.max(1) {
                return Ok(());
            }
        }
        *slot = Some(MapMem::alloc(bytes)?);
        Ok(())
    }

    fn alloc(bytes: usize) -> Result<Self> {
        let (pin, dev) = PinMem::alloc_mapped(bytes)?;
        Ok(Self { pin, dev })
    }
}

/// task 318: `DENNO_PF_PIN_STAGE` の値の解釈 (純関数)。
///
/// `1` / `true` / `yes` / `on` (と未知の値) を on、`0` / `false` / `no` / `off` /
/// 空文字を off にする。既定は off (env が無いとき)。
pub fn pf_pin_stage_from_value(v: Option<&str>) -> bool {
    match v {
        None => false,
        Some(s) => {
            let t = s.trim().to_ascii_lowercase();
            !matches!(t.as_str(), "0" | "false" | "no" | "off" | "")
        }
    }
}

/// pinned バウンスを使う転送サイズの下限 (既定) / 上限 (1 MiB ..= 256 MiB)。
const PF_PIN_MIN_BYTES: usize = 1 << 20;
const PF_PIN_MAX_BYTES: usize = 256 << 20;

/// task 358: 下限を env で動かす (`DENNO_PF_PIN_MIN_KB`、既定 1024 KiB)。
///
/// 1 MiB の床は task 318 が「小さい転送は写しの固定費が勝つ」として置いたもの。
/// 共有バウンスにした今は、decode の 10 KB D2H (pageable で 11 us) も
/// 同じ 1 本で速くなる可能性があるので、床を下げた条件を 1 つの COND で測れる
/// ようにしておく。
pub const PF_PIN_MIN_KB_ENV: &str = "DENNO_PF_PIN_MIN_KB";

/// task 518: decode の**小さな往復** (層ごとの 4 KiB .. 1 MiB) を pinned バウンスへ。
///
/// # なぜ要るか (2026-11-21)
///
/// UD-Q4_K_XL の warm 短 decode (12.7 ms/tok) は 4 段すべてが GPU の帯域律速
/// (seg の実測 gbs: gate 466 / up 473 / down 346 GB/s) で、ホスト側に残っているのは
/// **層ごとの小さな同期コピー**だけだった。1 トークンあたりの回数は
/// seg experts の prologue H2D (10.8 KB) と結果 D2H (10 KB)、GDN の xba H2D
/// (10.3 KB) と out D2H (10 KB)、full attention の KV ミラー H2D (65 KB) で、
/// 実測 (t518b の `[pf-pin]`) は decode で 131 回/token、3,826 の prefill で
/// 12,572 回・134.8 MB。pageable の 10 KB コピーは 11 us/回 (task 358 の実測)。
///
/// task 318 の 1 MiB の床は「pinned の確保そのものが高い」時代のもの。task 358 で
/// 共有 1 本 (grow-only) になったので、床を外したときの損得を測り直したら
/// **3,826 cold prefill が 2 ラウンドとも -4.6%**、14k cold が -7.0 / -3.9%、
/// cold の深い decode が -17〜-24%、warm 短 decode は -0.7% (2 ラウンド同値)、
/// 既定モデルは md5 全 SAME だった (t518a / t518b / t518c)。既定 on。
/// ここでは **1 MiB 未満だけ**を対象にする (prefill の大きな転送は
/// `DENNO_PF_PIN_STAGE` の判定のまま = 既存の数字を動かさない)。
pub const DEC_PIN_SMALL_ENV: &str = "DENNO_DEC_PIN_SMALL";

/// [`DEC_PIN_SMALL_ENV`] の解釈 (純関数)。**既定 on** (t518a/t518b で採用)。
///
/// 未設定・空文字は on、明示的な偽値 (`0` / `false` / `no` / `off`) だけ切る
/// (切り戻しは `DENNO_DEC_PIN_SMALL=0`)。
pub fn dec_pin_small_from_value(v: Option<&str>) -> bool {
    match v.map(str::trim) {
        None | Some("") => true,
        Some(s) => !matches!(
            s.to_ascii_lowercase().as_str(),
            "0" | "false" | "no" | "off"
        ),
    }
}

/// [`DEC_PIN_SMALL_ENV`] が有効か (プロセスで 1 回だけ env を読む)。
fn dec_pin_small_on() -> bool {
    static ON: OnceLock<bool> = OnceLock::new();
    *ON.get_or_init(|| dec_pin_small_from_value(std::env::var(DEC_PIN_SMALL_ENV).ok().as_deref()))
}

/// task 518: 小さな往復の窓の下限 (4 KiB 未満は写しの固定費が勝つ)。上限は
/// 既存の 1 MiB の床 (= それ以上は `DENNO_PF_PIN_STAGE` の担当)。
const PF_PIN_SMALL_MIN_BYTES: usize = 4 << 10;

/// task 518: `bytes` が「小さな往復」の窓に入るか (純関数)。
fn pf_pin_small_window_from(small_on: bool, bytes: usize) -> bool {
    small_on && (PF_PIN_SMALL_MIN_BYTES..PF_PIN_MIN_BYTES).contains(&bytes)
}

/// [`PF_PIN_MIN_KB_ENV`] の解釈 (純関数)。1..=262144 KiB に丸める。未設定は既定。
fn pf_pin_min_kb_from_value(v: Option<&str>) -> usize {
    let Some(s) = v.map(str::trim).filter(|s| !s.is_empty()) else {
        return PF_PIN_MIN_BYTES >> 10;
    };
    match s.parse::<usize>() {
        Ok(kb) if kb > 0 => kb.min(262_144),
        _ => PF_PIN_MIN_BYTES >> 10,
    }
}

/// 下限 (バイト)。プロセスで 1 回だけ env を読む。
fn pf_pin_min_bytes() -> usize {
    static N: OnceLock<usize> = OnceLock::new();
    *N.get_or_init(|| {
        pf_pin_min_kb_from_value(std::env::var(PF_PIN_MIN_KB_ENV).ok().as_deref()) << 10
    })
}

/// task 358: `bytes` が pinned バウンスの窓に入るか (純関数)。
///
/// 小さい転送は写しの固定費が勝ち、大きすぎる転送は pinned を食い潰す。
fn pf_pin_window_from(min: usize, bytes: usize) -> bool {
    (min..=PF_PIN_MAX_BYTES).contains(&bytes)
}

/// task 565: どの転送を pinned バウンスに通すかの判定 (純関数)。
///
/// `force` は**全体ゲートだけ**を飛ばす (窓の判定は同じく効く)。残差の往復
/// (`DENNO_PF_RES_PIN`) のように「この転送だけ」を通したいときに使う。
fn pf_pin_admit(
    force: bool,
    stage_on: bool,
    small_on: bool,
    min: usize,
    bytes: usize,
) -> bool {
    let big = (force || stage_on) && pf_pin_window_from(min, bytes);
    big || pf_pin_small_window_from(small_on, bytes)
}

/// task 358: 共有バウンスを `want` へ育てる必要があるか (純関数)。
///
/// 育つときは **2 の冪へ切り上げる**。1.4 MB → 39 MB → 143 MB と昇順に来るので、
/// 毎回ちょうどの大きさで取り直すと `cuMemHostAlloc` (device を同期させる) が
/// 何度も走る。切り上げれば 1 プロセスで数回で済む。
fn pf_pin_need_grow(cur: usize, want: usize) -> Option<usize> {
    if cur >= want {
        return None;
    }
    let pow = want.next_power_of_two().min(PF_PIN_MAX_BYTES);
    Some(pow.max(want))
}

/// 層ループの同期 H2D / D2H を pinned バウンス経由にするか。
fn pf_pin_stage_on() -> bool {
    static ON: OnceLock<bool> = OnceLock::new();
    *ON.get_or_init(|| {
        pf_pin_stage_from_value(std::env::var("DENNO_PF_PIN_STAGE").ok().as_deref())
    })
}

/// task 358: pinned バウンスの実体 (**プロセスで 1 本**、grow-only)。
///
/// task 318 は `thread_local!` に持たせたため、rayon のワーカー 14 本が
/// それぞれ 143 MiB の pinned を `cuMemHostAlloc` で取りに行った
/// (lab t318a: 14k cold 34.8 -> 55.3 s = +59%、3,826 も +10%)。pinned の
/// 確保は device 全体を同期させるので、**回数を 1 回に固定する**のが要点。
/// ここでは共有 1 本 + ロックにし、サイズは「必要になったときだけ」育てる
/// (3,826 の 39 MiB -> 14k の 143 MiB で 2 回)。
struct PfPinShared {
    /// 転送先/転送元の pinned バッファ。
    buf: Option<PinMem>,
    /// 育ち直した回数 (診断: 1 プロセスで数回であること)。
    grows: u64,
    /// 他のスレッドがバウンスを使っていて待った回数と合計 ns (診断)。
    waits: u64,
    wait_ns: u64,
    /// バウンス経由で流したバイト数と回数 (診断: 発火の証拠)。
    bytes: u64,
    calls: u64,
}

/// 共有バウンス (プロセスで 1 本)。
fn pf_pin_shared() -> &'static std::sync::Mutex<PfPinShared> {
    static S: OnceLock<std::sync::Mutex<PfPinShared>> = OnceLock::new();
    S.get_or_init(|| {
        std::sync::Mutex::new(PfPinShared {
            buf: None,
            grows: 0,
            waits: 0,
            wait_ns: 0,
            bytes: 0,
            calls: 0,
        })
    })
}

/// task 358: 共有バウンスの台帳 (grows, waits, wait_ns, bytes, calls)。
pub fn pf_pin_stats() -> (u64, u64, u64, u64, u64) {
    match pf_pin_shared().lock() {
        Ok(g) => (g.grows, g.waits, g.wait_ns, g.bytes, g.calls),
        Err(p) => {
            let g = p.into_inner();
            (g.grows, g.waits, g.wait_ns, g.bytes, g.calls)
        }
    }
}

/// task 358: 台帳を 0 に戻す (リクエスト終端)。
pub fn pf_pin_reset() {
    let m = pf_pin_shared();
    let mut g = match m.lock() {
        Ok(g) => g,
        Err(p) => p.into_inner(),
    };
    g.grows = 0;
    g.waits = 0;
    g.wait_ns = 0;
    g.bytes = 0;
    g.calls = 0;
}

/// task 358: 1 行のレポート (発火が 0 なら `None` = 出力しない)。
pub fn pf_pin_line() -> Option<String> {
    let (grows, waits, wait_ns, bytes, calls) = pf_pin_stats();
    if calls == 0 {
        return None;
    }
    Some(format!(
        "[pf-pin] calls={calls} MB={:.1} grows={grows} waits={waits} wait_ms={:.1}",
        bytes as f64 / 1e6,
        wait_ns as f64 / 1e6
    ))
}

/// 共有バウンスを `bytes` 以上に育てて、ロックを持ったまま `f` を実行する。
///
/// - ゲート off / 窓の外: `Ok(None)` (呼び出し側は pageable 経路へ)。
/// - 確保できない (pinned 不足など): 1 回だけ記録して `Ok(None)` (数値は同じ)。
///
/// ロックは転送が終わるまで持つ。転送は葉 (この中で別の転送を呼ばない) なので
/// 再入は起きない。並行に来た転送は直列になるが、pinned の 1 本は pageable より
/// 桁で速いので損にならない (lab の数字で確認する)。
fn with_pf_pin<T>(
    bytes: usize,
    f: impl FnOnce(*mut c_void) -> Result<T>,
) -> Result<Option<T>> {
    with_pf_pin_gate(bytes, false, f)
}

/// task 565: 全体ゲート (`DENNO_PF_PIN_STAGE`) を無視して窓の判定だけ使う版。
///
/// 残差の往復 (`DENNO_PF_RES_PIN`) のように「この転送だけ pinned にしたい」
/// 呼び出しのためのもの。窓 (1 MiB ..= 256 MiB) の判定は同じく効く。
fn with_pf_pin_forced<T>(
    bytes: usize,
    f: impl FnOnce(*mut c_void) -> Result<T>,
) -> Result<Option<T>> {
    with_pf_pin_gate(bytes, true, f)
}

fn with_pf_pin_gate<T>(
    bytes: usize,
    force: bool,
    f: impl FnOnce(*mut c_void) -> Result<T>,
) -> Result<Option<T>> {
    if bytes == 0 {
        return Ok(None);
    }
    // task 518: decode の小さな往復は専用の窓 (`DENNO_DEC_PIN_SMALL`)。
    // prefill の大きな転送は従来どおり `DENNO_PF_PIN_STAGE` + 床 1 MiB の判定。
    if !pf_pin_admit(
        force,
        pf_pin_stage_on(),
        dec_pin_small_on(),
        pf_pin_min_bytes(),
        bytes,
    ) {
        return Ok(None);
    }
    let m = pf_pin_shared();
    let t0 = std::time::Instant::now();
    let mut g = match m.lock() {
        Ok(g) => g,
        Err(p) => p.into_inner(),
    };
    // ロック待ち (他のスレッドがバウンスを使っていた時間) を数える。
    // 200 us を超えたものだけ「待ち」として数える (通常は 0)。
    let lock_ns = t0.elapsed().as_nanos() as u64;
    if lock_ns > 200_000 {
        g.waits += 1;
        g.wait_ns += lock_ns;
    }
    let cur = g.buf.as_ref().map(|b| b.bytes).unwrap_or(0);
    if let Some(want) = pf_pin_need_grow(cur, bytes) {
        // 新しい 1 本を取る前に古い 1 本を落とす (pinned を二重に持たない)。
        g.buf = None;
        match PinMem::alloc(want) {
            Ok(p) => {
                g.buf = Some(p);
                g.grows += 1;
            }
            Err(e) => {
                static WARNED: std::sync::atomic::AtomicBool =
                    std::sync::atomic::AtomicBool::new(false);
                if !WARNED.swap(true, std::sync::atomic::Ordering::Relaxed) {
                    tracing::info!("[pf-pin] pinned バウンスを確保できない ({want} B): {e:#}");
                }
                return Ok(None);
            }
        }
    }
    let pin = g.buf.as_ref().expect("確保済み").ptr;
    g.calls += 1;
    g.bytes += bytes as u64;
    f(pin).map(Some)
}

impl Drop for PinMem {
    fn drop(&mut self) {
        unsafe {
            let _ = (lib().unwrap().mem_host_free)(self.ptr);
        }
    }
}

// ---------------------------------------------------------------------------
// task 260: ホスト RAM tier 用の pinned な塊
// ---------------------------------------------------------------------------
//
// `DENNO_EXPERT_RAM_MB` の常駐先。CUDA の `cuMemHostAlloc` で確保した
// **ページロック済み**のホストメモリで、次の 2 つが狙い:
//
// 1. どの大きな読みにも追い出されない (page cache との違いはここだけ)。production の
//    実測では、別モデルを回したあとに IQ3_S へ戻すと page cache が抜けていて、
//    最初のリクエストが 149 ms/tok (平常 26) になっていた。
// 2. H2D の転送元にできる (pinned 52.6 GB/s / pageable 19.6 GB/s)。expert の
//    上げ直しで bounce コピーを挟まない経路 [`crate::cuda::PinnedHost`] を
//    そのまま `cuMemcpyHtoD` に渡せる。
//
// 確保に失敗したら `None` を返す (呼び出し側はヒープの塊へ落ちる)。失敗で
// リクエストを落とさない。
pub struct PinnedHost {
    ptr: *mut c_void,
    bytes: usize,
}

// 生ポインタを保持するだけ (中身はページロックされたホストメモリで、
// CPU からも GPU からも見える。排他は呼び出し側の LRU が持つ)。
unsafe impl Send for PinnedHost {}
unsafe impl Sync for PinnedHost {}

impl PinnedHost {
    /// `bytes` バイトの pinned ホストメモリを確保する。0 バイトは失敗扱い。
    #[cfg(feature = "cuda")]
    pub fn alloc(bytes: usize) -> Option<Self> {
        if bytes == 0 {
            return None;
        }
        const CU_MEMHOSTALLOC_PORTABLE: u32 = 0x01;
        let mut ptr: *mut c_void = std::ptr::null_mut();
        let lib = lib().ok()?;
        let ok = unsafe {
            check(
                (lib.mem_host_alloc)(&mut ptr, bytes, CU_MEMHOSTALLOC_PORTABLE),
                "cuMemHostAlloc (RAM tier)",
            )
            .is_ok()
        };
        if !ok || ptr.is_null() {
            return None;
        }
        Some(Self { ptr, bytes })
    }

    /// GPU の無いビルドでは常に失敗する (ヒープへ落ちる)。
    #[cfg(not(feature = "cuda"))]
    pub fn alloc(_bytes: usize) -> Option<Self> {
        None
    }

    pub fn ptr(&self) -> *mut u8 {
        self.ptr as *mut u8
    }

    pub fn bytes(&self) -> usize {
        self.bytes
    }

    pub fn as_slice(&self) -> &[u8] {
        unsafe { std::slice::from_raw_parts(self.ptr as *const u8, self.bytes) }
    }

    pub fn as_mut_slice(&mut self) -> &mut [u8] {
        unsafe { std::slice::from_raw_parts_mut(self.ptr as *mut u8, self.bytes) }
    }
}

impl Drop for PinnedHost {
    fn drop(&mut self) {
        #[cfg(feature = "cuda")]
        {
            if let Ok(l) = lib() {
                unsafe {
                    let _ = (l.mem_host_free)(self.ptr);
                }
            }
        }
    }
}

thread_local! {
    /// task 144: expert の H2D 用の pinned staging (1 本ぶん。grow-only)。
    static EXPERT_PIN: std::cell::RefCell<Option<PinMem>> =
        const { std::cell::RefCell::new(None) };
    /// task 565: 戻し (`DENNO_PF_RESTORE_NOSYNC`) のリング。4 枠を使い回し、
    /// **使い回す枠の DMA だけ**待つ。枠は grow-only でプロセス寿命まで持つ。
    static UP_RING: std::cell::RefCell<UpPinRing> =
        const { std::cell::RefCell::new(UpPinRing::new()) };
}

/// task 565: 戻しの H2D のリング 1 枠 (pinned と、その枠を読む DMA のイベント)。
struct UpPinSlot {
    mem: PinMem,
    ev: CUevent,
}

/// task 565: 戻しの H2D のリング (スレッド局所)。
struct UpPinRing {
    slots: Vec<Option<UpPinSlot>>,
    /// 次に使う枠の通し番号 (枠は `idx % UP_RING_N`)。
    calls: usize,
}

impl UpPinRing {
    const fn new() -> Self {
        Self {
            slots: Vec::new(),
            calls: 0,
        }
    }
}

/// task 565: リングの枠数。1 本 2 MB の DMA (40 us) に対して、写し (0.2 ms) が
/// 支配的なので 2 枠でも足りる。余裕を見て 4。
const UP_RING_N: usize = 4;

/// task 565: 通し番号 → 枠の添字 (純関数)。
fn up_ring_index(calls: usize) -> usize {
    calls % UP_RING_N
}

/// task 565: 戻しの H2D を「1 本ごとに待たない」モードにする (プロセス全体)。
///
/// [`restore_defer_flush_thread`] を各スレッドで呼ぶまで、積んだ DMA は
/// 走ったままになる。デバイスへ渡るバイト列は 1 本ずつの経路と同一。
static RESTORE_DEFER: std::sync::atomic::AtomicBool = std::sync::atomic::AtomicBool::new(false);

/// task 565: 遅延モードの入口 (`DENNO_PF_RESTORE_NOSYNC`)。
pub fn restore_defer_begin() {
    RESTORE_DEFER.store(true, std::sync::atomic::Ordering::Relaxed);
}

/// task 565: 遅延モードの終端。呼んだスレッドのリングの DMA を全部待つ。
pub fn restore_defer_end() {
    restore_defer_flush_thread();
    RESTORE_DEFER.store(false, std::sync::atomic::Ordering::Relaxed);
}

/// task 565: このスレッドが積んだリングの DMA を全部待つ (枠は残す)。
pub fn restore_defer_flush_thread() {
    let Ok(l) = lib() else {
        return;
    };
    let Some(es) = l.event_sync else {
        return;
    };
    UP_RING.with(|cell| {
        let ring = cell.borrow();
        for s in ring.slots.iter().flatten() {
            // 失敗しても次の段は同期コピー/カーネルなので、ここでは握る。
            unsafe {
                let _ = es(s.ev);
            }
        }
    });
}

/// task 565: 遅延モードか (戻しの中だけ真)。
fn restore_defer_on() -> bool {
    RESTORE_DEFER.load(std::sync::atomic::Ordering::Relaxed)
}

/// `DENNO_EXPERT_PIN_H2D=1`: expert の H2D を pinned staging 経由にするか。
///
/// 既定 **off**。lab t144d の実測では、この環境の pageable `cuMemcpyHtoD` の方が
/// 速かった (1 本 2.05 MB で pinned 0.34〜0.42 ms / pageable 0.27〜0.30 ms。
/// driver が内部で staging を持つため、自前で pinned へ写すと memcpy が余分)。
/// 転送するバイト列はどちらも同じ (モデルの数値には触らない)。
pub fn expert_pin_h2d() -> bool {
    static ON: OnceLock<bool> = OnceLock::new();
    *ON.get_or_init(|| {
        matches!(
            std::env::var("DENNO_EXPERT_PIN_H2D").ok().as_deref(),
            Some("1") | Some("true") | Some("on")
        )
    })
}

/// pinned staging 経由でホストのスライスを VRAM へ上げる (task 144)。
///
/// ページャブルなメモリからの `cuMemcpyHtoD` は driver が内部で staging するため、
/// lab t144b の実測では **2.4 GB/s** しか出なかった (expert 1 本 2.05 MB で
/// 0.86 ms)。pinned メモリへ 1 回コピーしてから H2D すると速い。
/// デバイスへ渡るバイト列は [`DevBuffer::from_slice`] と同一 (1 bit も変えない)。
pub fn from_slice_pinned<T: Copy>(data: &[T]) -> Result<DevBuffer> {
    let bytes = std::mem::size_of_val(data);
    let buf = DevBuffer::alloc_tagged(bytes.max(1), crate::mem_audit::TAG_EXPERTS)?;
    if bytes == 0 {
        return Ok(buf);
    }
    EXPERT_PIN.with(|cell| -> Result<()> {
        let mut slot = cell.borrow_mut();
        if slot.as_ref().map(|p| p.bytes).unwrap_or(0) < bytes {
            *slot = Some(PinMem::alloc(bytes)?);
        }
        let pin = slot.as_ref().expect("確保済み");
        unsafe {
            // ホスト側の 1 回コピー (pinned は DMA 可能な常駐メモリ)。
            std::ptr::copy_nonoverlapping(data.as_ptr() as *const u8, pin.ptr as *mut u8, bytes);
            check(
                (lib()?.memcpy_htod)(buf.ptr, pin.ptr, bytes),
                "cuMemcpyHtoD (pinned)",
            )?;
        }
        dbg_htod(bytes);
        Ok(())
    })?;
    Ok(buf)
}

// ---------------------------------------------------------------------------
// task 209: prefill の活性バッファを pinned ホストメモリにする (`DENNO_PF_PIN`)
// ---------------------------------------------------------------------------
//
// 動機 (lab t203c の 14,018 トークン cold prefill の台帳): mix の D2H 13.78 GB が
// 785 ms (= 17.6 GB/s) かかっている。宛先は `vec![0.0f32; nt*e]` のページャブルな
// メモリで、driver が内部 staging を挟むためこの速さになる。このホストの実測は
// pinned 52.6 GB/s / pageable 19.6 GB/s なので、**宛先/元を pinned にするだけ**で
// 同じバイト列が 2.8 倍速く動く (値は 1 bit も変わらない)。
//
// `PfHostBuf` は「pinned が取れたら pinned、取れなければ Vec」の 1 本ぶんの
// ホストバッファ。API はスライスだけなので、呼び出し側は確保の仕方だけを変える。
// pinned は確保・解放が高いので、スレッド局所の空きリストで使い回す。

/// `DENNO_PF_PIN` の解釈 (純関数)。**既定 on** (lab t209a の pin で採用)、
/// 明示的な偽値だけ off。
pub(crate) fn pf_pin_from_value(v: Option<&str>) -> bool {
    match v.map(|s| s.trim().to_ascii_lowercase()) {
        None => true,
        Some(s) => !matches!(s.as_str(), "0" | "off" | "false" | "no" | ""),
    }
}

#[cfg(test)]
static PF_PIN_FORCE: std::sync::atomic::AtomicU8 = std::sync::atomic::AtomicU8::new(0);

/// テスト用: ゲートを強制する (0 = env に戻す)。
#[cfg(test)]
pub(crate) fn pf_pin_set_for_test(v: u8) {
    PF_PIN_FORCE.store(v, Ordering::Relaxed);
}

/// task 209: prefill の活性バッファを pinned ホストメモリにするか (`DENNO_PF_PIN`)。
///
/// **既定 on** (lab t209a の pin が 3,826 -3.9% / 14,018 -3.4%、both で
/// -4.8% / -4.0%。`=0` で切り戻し)。
pub(crate) fn pf_pin_on() -> bool {
    #[cfg(test)]
    {
        match PF_PIN_FORCE.load(Ordering::Relaxed) {
            1 => return false,
            2 => return true,
            _ => {}
        }
    }
    static ON: OnceLock<bool> = OnceLock::new();
    *ON.get_or_init(|| pf_pin_from_value(std::env::var("DENNO_PF_PIN").ok().as_deref()))
}

thread_local! {
    /// task 209: 使い終わった pinned ホスト領域 (スレッドごと。prefill は 1 本)。
    static PF_HOST_FREE: std::cell::RefCell<Vec<PinMem>> =
        const { std::cell::RefCell::new(Vec::new()) };
}

/// task 209: prefill の活性 1 本ぶんのホストバッファ。
///
/// pinned を確保できたらそちらを使い、できなければ `Vec` に落ちる。**中身は
/// 保証しない** — 読む前に全要素を書く経路 (D2H の宛先・GEMM の出力先) だけが
/// 使う。`Vec` に落ちたときは従来どおり 0 埋め。
pub struct PfHostBuf {
    mem: Option<PinMem>,
    v: Vec<f32>,
    len: usize,
}

impl PfHostBuf {
    /// 長さ `len` のバッファ (中身は不定)。pinned が取れなければ 0 埋めの `Vec`。
    pub fn new(len: usize) -> Self {
        if len > 0 && pf_pin_on() {
            // 空きリストから 1 本借りる (足りなければ新規に確保して差し替える)。
            let reused = PF_HOST_FREE.with(|c| {
                let mut q = c.borrow_mut();
                match q.pop() {
                    Some(m) if m.bytes >= len * 4 => Some(m),
                    Some(m) => {
                        q.push(m);
                        None
                    }
                    None => None,
                }
            });
            let mem = match reused {
                Some(m) => Some(m),
                None => match PinMem::alloc(len * 4) {
                    Ok(m) => Some(m),
                    Err(_) => {
                        tracing::info!("[pf-pin] pinned を確保できない → Vec に落ちる (len={len})");
                        None
                    }
                },
            };
            if let Some(mem) = mem {
                return Self {
                    mem: Some(mem),
                    v: Vec::new(),
                    len,
                };
            }
        }
        Self {
            mem: None,
            v: vec![0.0f32; len],
            len,
        }
    }

    pub fn len(&self) -> usize {
        self.len
    }

    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    /// pinned で確保できたか (台帳・テスト用)。
    pub fn is_pinned(&self) -> bool {
        self.mem.is_some()
    }

    pub fn as_slice(&self) -> &[f32] {
        match &self.mem {
            Some(m) => unsafe { std::slice::from_raw_parts(m.ptr as *const f32, self.len) },
            None => &self.v,
        }
    }

    pub fn as_mut_slice(&mut self) -> &mut [f32] {
        match &mut self.mem {
            Some(m) => unsafe { std::slice::from_raw_parts_mut(m.ptr as *mut f32, self.len) },
            None => &mut self.v,
        }
    }
}

impl Drop for PfHostBuf {
    fn drop(&mut self) {
        if let Some(m) = self.mem.take() {
            // 使い回す (スレッド局所)。コンテキスト破棄より先に drop される想定。
            PF_HOST_FREE.with(|c| c.borrow_mut().push(m));
        }
    }
}

#[cfg(test)]
mod pf_pin_tests {
    use super::*;

    /// task 209: `DENNO_PF_PIN` は **既定 on** (lab t209a の pin で採用)。
    #[test]
    fn pf_pin_gate_truth_table() {
        assert!(pf_pin_from_value(None), "未設定は既定 on");
        for v in ["0", "off", "false", "no", "", " off ", "FALSE"] {
            assert!(!pf_pin_from_value(Some(v)), "{v:?} が on になった");
        }
        for v in ["1", "on", "true", "yes", " ON "] {
            assert!(pf_pin_from_value(Some(v)), "{v:?} が off のまま");
        }
    }

    /// task 209: `DENNO_PF_MIXDEVIN` も **既定 on** (lab t209a の devin で採用)。
    #[test]
    fn pf_dev_in_gate_truth_table() {
        assert!(pf_dev_in_from_value(None), "未設定は既定 on");
        for v in ["0", "off", "false", "no", "", "FALSE"] {
            assert!(!pf_dev_in_from_value(Some(v)), "{v:?} が on になった");
        }
        for v in ["1", "on", "true", "yes"] {
            assert!(pf_dev_in_from_value(Some(v)), "{v:?} が off のまま");
        }
    }

    /// task 209: `PfHostBuf` はスライスとして読み書きでき、長さが要求どおり。
    /// pinned が取れる環境では pinned、取れない環境では `Vec` に落ちる (どちらも
    /// 値の経路は同じ)。
    #[test]
    fn pf_host_buf_round_trips_and_falls_back() {
        pf_pin_set_for_test(1); // 強制 off
        let mut b = PfHostBuf::new(37);
        assert_eq!(b.len(), 37);
        assert!(!b.is_pinned(), "強制 off で pinned になった");
        b.as_mut_slice()[0] = 1.5;
        b.as_mut_slice()[36] = -2.5;
        assert_eq!(b.as_slice()[0], 1.5);
        assert_eq!(b.as_slice()[36], -2.5);
        assert_eq!(b.as_slice().len(), 37);
        drop(b);

        pf_pin_set_for_test(2); // 強制 on (確保できなければ Vec に落ちる)
        let mut b = PfHostBuf::new(8);
        assert_eq!(b.len(), 8);
        b.as_mut_slice()[3] = 7.0;
        assert_eq!(b.as_slice()[3], 7.0);
        assert_eq!(b.as_slice().len(), 8);
        pf_pin_set_for_test(0);

        // 空でも安全。
        let b = PfHostBuf::new(0);
        assert_eq!(b.len(), 0);
        assert!(b.is_empty());
    }

    /// task 209: 記録は (ホストポインタ, nt, e) が全部一致したときだけ有効。
    #[test]
    fn pf_mixed_mark_requires_exact_match() {
        let a = [0.0f32; 4];
        let b = [0.0f32; 4];
        let mark = (a.as_ptr(), 2usize, 2usize);
        assert!(pf_mixed_mark_matches(mark, a.as_ptr(), 2, 2));
        assert!(!pf_mixed_mark_matches(mark, b.as_ptr(), 2, 2), "別ポインタ");
        assert!(!pf_mixed_mark_matches(mark, a.as_ptr(), 1, 2), "nt 違い");
        assert!(!pf_mixed_mark_matches(mark, a.as_ptr(), 2, 4), "e 違い");
        assert!(
            !pf_mixed_mark_matches((std::ptr::null(), 2, 2), a.as_ptr(), 2, 2),
            "未記録 (null) が一致扱いになった"
        );
    }

    /// task 230: `pf_mixed_keep_dev` は「デバイスだけが正」を立て、
    /// `pf_mixed_mark` / `pf_mixed_mark_clear` がそれを落とすこと。
    #[test]
    fn pf230_keep_dev_sets_dev_only() {
        let a = [0.0f32; 4];
        // 記録が無ければ dev-only ではない。
        pf_mixed_mark_clear();
        assert!(!pf_mixed_dev_only(a.as_ptr(), 2, 2));
        // keep_dev → dev-only。形が違えば一致しない。
        pf_mixed_keep_dev(a.as_ptr(), 2, 2);
        assert!(pf_mixed_dev_only(a.as_ptr(), 2, 2));
        assert!(!pf_mixed_dev_only(a.as_ptr(), 1, 2), "nt 違いが一致した");
        assert!(!pf_mixed_dev_only(a.as_ptr(), 2, 4), "e 違いが一致した");
        // 同一マークを打つと dev-only が落ちる (ホストが正に戻る)。
        pf_mixed_mark(a.as_ptr(), 2, 2);
        assert!(!pf_mixed_dev_only(a.as_ptr(), 2, 2));
        // clear でも落ちる。
        pf_mixed_keep_dev(a.as_ptr(), 2, 2);
        pf_mixed_mark_clear();
        assert!(!pf_mixed_dev_only(a.as_ptr(), 2, 2));
    }

    /// task 230/317: ゲートの解釈。v3 は task 244、MIXKEEP は task 317 で既定 on。
    #[test]
    fn pf230_gate_values() {
        // v3: 未指定は on (task 244 t244a で採択)、明示的な偽値で off。
        assert!(pf_attn_v3_from_value(None), "v3 の既定が on でない");
        for v in [Some("0"), Some("off"), Some("false"), Some("no"), Some("")] {
            assert!(!pf_attn_v3_from_value(v), "v3 が off でない: {v:?}");
        }
        for v in [Some("1"), Some("on"), Some("TRUE"), Some(" yes ")] {
            assert!(pf_attn_v3_from_value(v), "v3 が on でない: {v:?}");
        }
        // mixkeep: task 317 で既定 on (task 230/232 では off だった)。
        for v in [Some("0"), Some("off"), Some("false"), Some("no"), Some("")] {
            assert!(!pf_mix_keep_from_value(v), "mixkeep が off でない: {v:?}");
        }
        assert!(pf_mix_keep_from_value(None), "mixkeep の既定が on でない");
        for v in [Some("1"), Some("on"), Some("TRUE"), Some(" yes ")] {
            assert!(pf_mix_keep_from_value(v), "mixkeep が on でない: {v:?}");
        }
    }

    /// task 317: `DENNO_PF_MIXKEEP_SSM` は既定 on (明示的な偽値だけ off)。
    #[test]
    fn pf317_mixkeep_ssm_gate_values() {
        for v in [Some("0"), Some("off"), Some(""), Some("no")] {
            assert!(!pf_mix_keep_ssm_from_value(v), "ssm mixkeep が off でない: {v:?}");
        }
        assert!(pf_mix_keep_ssm_from_value(None), "ssm mixkeep の既定が on でない");
        for v in [Some("1"), Some("on"), Some("TRUE"), Some(" yes ")] {
            assert!(pf_mix_keep_ssm_from_value(v), "ssm mixkeep が on でない: {v:?}");
        }
        // 強制フラグは env より優先する (既定 = env)。
        pf_mix_keep_ssm_set_for_test(2);
        assert!(pf_mix_keep_ssm_on(), "強制 on が効いていない");
        pf_mix_keep_ssm_set_for_test(1);
        assert!(!pf_mix_keep_ssm_on(), "強制 off が効いていない");
        pf_mix_keep_ssm_set_for_test(0);
        crate::cuda::pf_reset_for_test();
    }

    /// task 317: 記録が合えばデバイスの `mixed` を指し、合わなければ `None`。
    /// `DENNO_PF_MIXDEVIN` (既定 on) が off なら常に `None`。
    #[test]
    fn pf317_dev_in_ptr_needs_matching_mark() {
        let a = [0.0f32; 8];
        let b = [0.0f32; 8];
        pf_dev_in_set_for_test(2);
        pf_mixed_keep_dev(a.as_ptr(), 2, 4);
        // 作業域が無いのでポインタは返らないが、記録の一致判定はここで効く。
        assert!(pf_mixed_dev_only(a.as_ptr(), 2, 4));
        assert!(!pf_mixed_dev_only(b.as_ptr(), 2, 4), "別ポインタが一致した");
        assert!(!pf_mixed_dev_only(a.as_ptr(), 1, 4), "nt 違いが一致した");
        pf_dev_in_set_for_test(1);
        assert!(pf_mixed_dev_in_ptr(a.as_ptr(), 2, 4).is_none(), "devin off で返った");
        pf_dev_in_set_for_test(0);
        pf_mixed_mark_clear();
        crate::cuda::pf_reset_for_test();
    }
}

// ---------------------------------------------------------------------------
// task 209: router / shared が mix の出力をデバイスから直接読む
// ---------------------------------------------------------------------------
//
// 層ループは mix の出力 (`mixed_flat`) を D2H したあと、同じバイト列を
// router (`gate_inp` の F32 GEMM) と shared expert の GEMM のために **もう一度
// H2D する** (台帳 14,018: 6.89 GB + 6.89 GB)。デバイスには `pf_mix` の出力が
// そのまま残っているので、そこを読めば転送 2 本が消える。値は同じバイト列。

/// `DENNO_PF_MIXDEVIN` の解釈 (純関数)。**既定 on** (lab t209a で採用)、
/// 明示的な偽値だけ off。
pub(crate) fn pf_dev_in_from_value(v: Option<&str>) -> bool {
    match v.map(|s| s.trim().to_ascii_lowercase()) {
        None => true,
        Some(s) => !matches!(s.as_str(), "0" | "off" | "false" | "no" | ""),
    }
}

#[cfg(test)]
