thread_local! {
    /// task 209: 「このホスト側ポインタの `mixed` はデバイスの `mixed` と同一」の記録。
    static PF_MIXED_CUR: std::cell::Cell<(*const f32, usize, usize)> =
        const { std::cell::Cell::new((std::ptr::null(), 0, 0)) };
    /// task 230: 直前の mix を D2H していない (ホスト側のバイト列は古い)。
    /// デバイスの `mixed` だけが正で、D2H する前にホスト経路へ落ちたら
    /// [`pf_mixed_restore_host`] で埋め直す。
    static PF_MIXED_DEV_ONLY: std::cell::Cell<bool> = const { std::cell::Cell::new(false) };
}

/// ホスト側の `mixed` がデバイスの `mixed` と同じ内容であることを記録する
/// (`pf_take_mixed` の直後に呼ぶ)。
pub fn pf_mixed_mark(host: *const f32, nt: usize, e: usize) {
    PF_MIXED_CUR.with(|c| c.set((host, nt, e)));
    PF_MIXED_DEV_ONLY.with(|c| c.set(false));
}

/// task 230: ホストへ降ろさずに「デバイスの `mixed` だけが正」と記録する。
///
/// 次の GEMM がデバイスから直接読める層 (full attention の qkv) だけで使う。
/// ホストのバイト列は古いままなので、ホスト経路に落ちるときは
/// [`pf_mixed_restore_host`] を必ず通すこと。
pub fn pf_mixed_keep_dev(host: *const f32, nt: usize, e: usize) {
    PF_MIXED_CUR.with(|c| c.set((host, nt, e)));
    PF_MIXED_DEV_ONLY.with(|c| c.set(true));
}

/// 記録を消す (非常駐経路へ落ちたとき・リクエストの終わり)。
pub fn pf_mixed_mark_clear() {
    PF_MIXED_CUR.with(|c| c.set((std::ptr::null(), 0, 0)));
    PF_MIXED_DEV_ONLY.with(|c| c.set(false));
}

/// このホスト配列が「D2H していない (デバイスだけが正)」か。
pub(crate) fn pf_mixed_dev_only(host: *const f32, nt: usize, e: usize) -> bool {
    let m = PF_MIXED_CUR.with(|c| c.get());
    pf_mixed_mark_matches(m, host, nt, e) && PF_MIXED_DEV_ONLY.with(|c| c.get())
}

/// D2H していない `mixed` をホストへ降ろし、記録を「同一」に戻す。
///
/// ホスト経路 (非常駐の qkv / ssM) へ落ちるときだけ呼ぶ。降ろせなければ false
/// (そのときは呼び出し側が失敗する = 古いバイト列で計算しない)。
pub(crate) fn pf_mixed_restore_host(host: *mut f32, nt: usize, e: usize) -> bool {
    if host.is_null() || nt == 0 || e == 0 {
        return false;
    }
    if !pf_mixed_dev_only(host as *const f32, nt, e) {
        return false;
    }
    let ok = PF_DEV.with(|c| {
        let d = c.borrow();
        match d.mixed.as_ref() {
            Some(b) if b.bytes() >= nt * e * 4 => unsafe {
                b.to_slice(std::slice::from_raw_parts_mut(host, nt * e)).is_ok()
            },
            _ => false,
        }
    });
    if ok {
        PF_MIXED_DEV_ONLY.with(|c| c.set(false));
    }
    ok
}

/// 記録が (host, nt, e) と一致するか (純関数・テスト用)。
pub(crate) fn pf_mixed_mark_matches(
    mark: (*const f32, usize, usize),
    host: *const f32,
    nt: usize,
    e: usize,
) -> bool {
    !mark.0.is_null() && std::ptr::eq(mark.0, host) && mark.1 == nt && mark.2 == e
}

/// この `xs` をデバイスの `mixed` から読んでよいなら、そのデバイスポインタ。
///
/// ゲート off・記録なし・ポインタ不一致・作業域の形違いはすべて `None`
/// (呼び出し側は従来どおりホストから上げる)。
pub(crate) fn pf_mixed_dev_in_ptr(host: *const f32, nt: usize, e: usize) -> Option<CUdeviceptr> {
    if !pf_dev_in_on() || nt == 0 || e == 0 {
        return None;
    }
    let m = PF_MIXED_CUR.with(|c| c.get());
    if !pf_mixed_mark_matches(m, host, nt, e) {
        return None;
    }
    PF_DEV.with(|c| {
        let d = c.borrow();
        let b = d.mixed.as_ref()?;
        (d.e == e && nt <= d.nt && b.bytes() >= nt * e * 4).then(|| b.ptr())
    })
}

/// s167 (P6): 専用コピーストリーム (h2 の D2H を qkv/z GEMM と重ねる)。
/// driver オブジェクトはコンテキストに属するので Drop で明示的に破棄する
/// (スレッド終了時に解放。`stream_destroy` が無い driver ではリークするだけで、
/// コンテキスト破棄時に回収される)。
struct CopyStream(CUstream);

impl Drop for CopyStream {
    fn drop(&mut self) {
        if let Ok(l) = lib() {
            if let Some(f) = l.stream_destroy {
                unsafe {
                    let _ = f(self.0);
                }
            }
        }
    }
}

/// s167 (P6): コピーストリームの順序付け/完了待ちに使うイベント (RAII)。
struct CopyEvent(CUevent);

impl Drop for CopyEvent {
    fn drop(&mut self) {
        if let Ok(l) = lib() {
            if let Some(f) = l.event_destroy {
                unsafe {
                    let _ = f(self.0);
                }
            }
        }
    }
}

thread_local! {
    /// task 155: 既定 (null) ストリームの完了待ちに使うイベント (スレッドごとに 1 本)。
    static DEF_EV: std::cell::RefCell<Option<CopyEvent>> = const { std::cell::RefCell::new(None) };
}

/// task 155: `cuEventCreate` の `CU_EVENT_DISABLE_TIMING`。
const CU_EVENT_DISABLE_TIMING: u32 = 0x02;

/// task 155: 既定 (null) ストリームの完了だけを**イベント 1 本**で待つ。
///
/// [`CudaCtx::sync`] の `cuCtxSynchronize` はコンテキスト**全体**を待つので、
/// 重ね打ち用のサイドストリーム (shared expert の gate/up) まで待ってしまう。
/// ホストがその結果を要るのは層のずっと後 (shared の join) なので、ここでは
/// null ストリームに打ったイベントだけを待つ。発行済みのカーネル・引数・順序は
/// 1 つも変えない (変わるのは待つ範囲だけ)。
///
/// 実測 (GPU ラボ t155a、swift15-abl IQ3_S、14T、plain = TLINE なし、全ゲート on と
/// off の A/B): decode 46 → 42 ms/tok (短い) / 44 → 38 (3,954) / 47 → 41 (14,139)、
/// prefill +1.1%、md5 は 6 本とも SAME、errors 0。14,139 の台帳は
/// router 4.09 → 1.61 ms/tok (48 層で 52 us/層の同期固定費が消えた)、
/// experts 10.37 → 10.18。**この待ちはモデルの値を 1 ビットも変えない。**
///
/// t155c (TLINE=1 / TLINE_K=1 を両条件に): token 47.06 → 42.29 (3,954) /
/// 49.83 → 44.50 (14,139)。host_wait 25.09 → 22.32 / 29.11 → 26.39 (router の
/// wait が 2.68 → 0.97 / 2.72 → 0.99)、gpu_idle 28.61 → 24.17 / 27.33 → 22.32、
/// gpu_busy は 18.44 → 18.12 / 22.50 → 22.18 で**動かない** (仕事量は同じ)。
///
/// 戻り値 `false` = イベントが使えない。呼び出し側は従来どおり `ctx.sync()` に
/// 落ちること (待たずに進んではいけない)。
pub fn sync_default_stream() -> bool {
    let Ok(l) = lib() else { return false };
    let (Some(create), Some(record), Some(esync)) =
        (l.event_create, l.event_record, l.event_sync)
    else {
        return false;
    };
    DEF_EV.with(|cell| {
        let mut slot = cell.borrow_mut();
        if slot.is_none() {
            let mut ev: CUevent = std::ptr::null_mut();
            if unsafe { create(&mut ev, CU_EVENT_DISABLE_TIMING) } != CUDA_SUCCESS {
                return false;
            }
            *slot = Some(CopyEvent(ev));
        }
        let ev = slot.as_ref().expect("直前に作った").0;
        let t = crate::model::q4ledger::stamp();
        let ok = unsafe { record(ev, std::ptr::null_mut()) } == CUDA_SUCCESS
            && unsafe { esync(ev) } == CUDA_SUCCESS;
        if ok {
            crate::model::q4ledger::note_sync(t);
        }
        ok
    })
}

/// [`sync_default_stream`] が使えない環境用の包み (失敗したら `ctx.sync()`)。
///
/// `scoped == false` (`DENNO_DEC_OVERLAP=0` / `DENNO_ROUTER_FUSED=0`) は従来どおり
/// コンテキスト全体を待つ。
fn sync_default_or_ctx(ctx: &CudaCtx, scoped: bool) -> Result<()> {
    if scoped && sync_default_stream() {
        return Ok(());
    }
    ctx.sync()
}

