/// task 307: 次の mix の鎖にルータ GEMV を載せるための控え。
struct RouterArm {
    uid: u64,
    /// ルータ重みのホスト生バイト (F32)。**同じ層・同じトークンの mix の中で
    /// 消費する** 前提で借りる (モデルの重みは mix の間ずっと生きている)。
    ptr: *const u8,
    len: usize,
    k: usize,
    n: usize,
    layer: usize,
    pos: u64,
}

thread_local! {
    static ROUTER_ARM: std::cell::RefCell<Option<RouterArm>> =
        const { std::cell::RefCell::new(None) };
    /// task 307: mix の鎖が作った logits の (uid, k, n)。0 = 無し。
    static ROUTER_FILLED: std::cell::Cell<(u64, usize, usize)> =
        const { std::cell::Cell::new((0, 0, 0)) };
    /// task 307: `ROUTER_FILLED` の中身はもう同期済みか (finish で待たない)。
    static ROUTER_SYNCED: std::cell::Cell<bool> = const { std::cell::Cell::new(false) };
}

/// task 307: この層の FFN mix の鎖にルータ GEMV を載せる (decode の層入口で呼ぶ)。
///
/// `false` = 載せない (ゲート off・形が合わない)。載らなかった場合は従来どおり
/// `maybe_gpu_router_gemv_begin` が H2D + 起動 + D2H を行う (数値は同じ).
pub fn router_in_mix_arm(uid: u64, bytes: &[u8], k: usize, n: usize) -> bool {
    if !router_in_mix_on() {
        return false;
    }
    if k == 0 || n == 0 || bytes.len() != k.saturating_mul(n).saturating_mul(4) {
        return false;
    }
    ROUTER_ARM.with(|c| {
        *c.borrow_mut() = Some(RouterArm {
            uid,
            ptr: bytes.as_ptr(),
            len: bytes.len(),
            k,
            n,
            layer: dec_kprof::cur_layer(),
            pos: dec_kprof::cur_pos(),
        })
    });
    true
}

/// task 307: トークンの入口でルータの控えを落とす (層 0 の入口で呼ぶ)。
///
/// 前のトークンの `ROUTER_FILLED` / 控えが残っていても、次のトークンでは
/// 必ず「mix の鎖が作った値」だけを使う。
pub fn router_in_mix_token_start() {
    if !router_in_mix_on() {
        return;
    }
    ROUTER_FILLED.with(|c| c.set((0, 0, 0)));
    ROUTER_SYNCED.with(|c| c.set(false));
    ROUTER_ARM.with(|c| {
        let _ = c.borrow_mut().take();
    });
}

/// task 364: 控え (`ROUTER_ARM`) がこの形・この層で消費できる状態か (**取らない**)。
///
/// [`router_in_mix_enqueue`] と同じ条件を読むだけの判定。qchain の入口で
/// 「載せにいく」回数を数えるのと、診断に使う。
#[cfg(test)]
fn router_in_mix_armed_for(k: usize) -> bool {
    ROUTER_ARM.with(|c| {
        c.borrow().as_ref().is_some_and(|job| {
            job.k == k && job.layer == dec_kprof::cur_layer() && job.pos == dec_kprof::cur_pos()
        })
    })
}

/// task 307: mix の鎖の末尾にルータ GEMV を 1 発積む (鎖の中から呼ぶ)。
///
/// 戻り値は積んだ出力行数 (0 = 積んでいない)。`x` は鎖の中間バッファ
/// (= `mixed` のデバイスコピー) で、`k` と一致するときだけ積む。
fn router_in_mix_enqueue(
    ctx: &CudaCtx,
    x_dev: CUdeviceptr,
    k: usize,
    w_keep: &mut Option<GgufWRef>,
) -> usize {
    let Some(job) = ROUTER_ARM.with(|c| c.borrow_mut().take()) else {
        return 0;
    };
    if job.k != k || job.layer != dec_kprof::cur_layer() || job.pos != dec_kprof::cur_pos() {
        return 0;
    }
    let bytes = unsafe { std::slice::from_raw_parts(job.ptr, job.len) };
    let w = match weights_for_f32(job.uid, bytes, job.k, job.n) {
        Ok(w) => w,
        Err(_) => return 0,
    };
    let f_seq = matvec_f32_fn(ctx);
    let f_red = matvec_f32_r_fn(ctx);
    let use_reduce = router_gpu_reduce_enabled() && router_use_reduce_kernel(job.k, job.n, f_red.is_some());
    let Some(f) = (if use_reduce { f_red } else { f_seq }) else {
        return 0;
    };
    let thr: u32 = if use_reduce { 256 } else { 1 };
    let Ok(l) = lib() else {
        return 0;
    };
    let r = ROUTER_SC.with(|cell| -> Result<()> {
        let mut s = cell.borrow_mut();
        let RouterScratch { out: dout, ho, .. } = &mut *s;
        Scratch::ensure(dout, job.n * 4)?;
        Scratch::ensure_pin(ho, job.n * 4)?;
        let dout = dout.as_ref().expect("ensure 済み");
        let mut po = dout.ptr();
        let mut pw = w.buf.ptr;
        let mut ph = x_dev;
        let (mut kc, mut nc) = (job.k as c_int, job.n as c_int);
        let mut args = [
            &mut ph as *mut _ as *mut c_void,
            &mut pw as *mut _ as *mut c_void,
            &mut po as *mut _ as *mut c_void,
            &mut kc as *mut _ as *mut c_void,
            &mut nc as *mut _ as *mut c_void,
        ];
        unsafe {
            ctx.launch_async(f, (job.n as u32, 1, 1), (thr, 1, 1), 0, &mut args)?;
            let ho = ho.as_ref().expect("ensure 済み");
            check(
                (l.memcpy_dtoh_async)(
                    ho.ptr,
                    dout.ptr(),
                    job.n * 4,
                    std::ptr::null_mut(),
                ),
                "cuMemcpyDtoHAsync (router in mix)",
            )?;
        }
        crate::prof::mark_d2h_src(crate::prof::D2H_SRC_LINEAR);
        Ok(())
    });
    match r {
        Ok(()) => {
            *w_keep = Some(w);
            ROUTER_FILLED.with(|c| c.set((job.uid, job.k, job.n)));
            job.n
        }
        Err(_) => 0,
    }
}

/// task 69 / 192: ルータ (f32・m=1) の GEMV を **同期せずに** 積む。
///
/// `maybe_gpu_router_gemv_into` の前半。`true` を返したら、呼び出し側は別の
/// ホスト仕事 (共有 expert の enqueue など) を挟んでから
/// [`maybe_gpu_router_gemv_finish`] で待つ。`false` = 従来経路で計算すること
/// (GPU 無効・PTX 未収録・予算外・実行時エラー)。
pub fn maybe_gpu_router_gemv_begin(
    uid: u64,
    bytes: &[u8],
    k: usize,
    n: usize,
    x: &[f32],
) -> bool {
    use std::sync::atomic::Ordering as AO;
    #[cfg(test)]
    ROUTER_GPU_ATTEMPTS.fetch_add(1, AO::Relaxed);
    if !cuda_enabled() || ROUTER_GPU_BROKEN.load(AO::Relaxed) {
        return false;
    }
    if k == 0
        || n == 0
        || x.len() != k
        || bytes.len() != k.saturating_mul(n).saturating_mul(4)
        || k > i32::MAX as usize
        || n > i32::MAX as usize
    {
        return false;
    }
    // task 307: mix の鎖 (`DENNO_ROUTER_IN_MIX`) がこの層の logits を既に作って
    // いて、鎖の同期でホストへ届いていれば、ここでは何も積まない。uid / k / n が
    // 違えば (別の層の残り) 捨てて従来経路へ。
    let filled = ROUTER_FILLED.with(|c| c.get());
    if filled.0 != 0 {
        if filled == (uid, k, n) {
            // 使い切り (次の層・次のトークンで古い logits を使わない)。
            ROUTER_FILLED.with(|c| c.set((0, 0, 0)));
            ROUTER_SYNCED.with(|c| c.set(true));
            ROUTER_PENDING_N.with(|c| c.set(n));
            return true;
        }
        ROUTER_FILLED.with(|c| c.set((0, 0, 0)));
        ROUTER_SYNCED.with(|c| c.set(false));
    } else {
        // 印が無い回は「鎖の値」を使わない (前回の SYNCED が残っていても無効)。
        ROUTER_SYNCED.with(|c| c.set(false));
    }
    let Some(ctx) = shared_ctx() else {
        return false;
    };
    if let Err(e) = ctx.make_current() {
        tracing::error!("CUDA cuCtxSetCurrent failed (router f32), using CPU: {e:#}");
        ROUTER_GPU_BROKEN.store(true, AO::Relaxed);
        return false;
    }
    // カーネルハンドル (未収録 PTX は None をキャッシュ = ラッチしない)。
    // task 127: ルータは k=2560 >= n=512 の長い行なので、`_r` (1 ブロック = 1 行・
    // block 256・固定木縮約) が選べるならそちらを使う。逐次版は 1 ブロック =
    // 1 スレッドで並列度が行数 n しかない (task 69 の却下はこの形だった)。
    // `_r` が未収録 / `DENNO_ROUTER_GPU_REDUCE=0` なら逐次版に落ちる (fail closed)。
    let f_seq = matvec_f32_fn(ctx);
    let f_red = matvec_f32_r_fn(ctx);
    let use_reduce = router_gpu_reduce_enabled() && router_use_reduce_kernel(k, n, f_red.is_some());
    if !use_reduce && f_seq.is_none() {
        return false;
    }
    let prof = crate::model::devprof::on();
    let up_before = if prof {
        crate::gpu_budget::weight_upload_bytes()
    } else {
        0
    };
    let w = match weights_for_f32(uid, bytes, k, n) {
        Ok(w) => w,
        Err(e) => {
            tracing::error!(
                "router f32 weight register failed (uid={uid}), using CPU permanently: {e:#}"
            );
            ROUTER_GPU_BROKEN.store(true, AO::Relaxed);
            return false;
        }
    };
    let lib = match lib() {
        Ok(l) => l,
        Err(e) => {
            tracing::error!("CUDA lib load failed (router f32), using CPU: {e:#}");
            ROUTER_GPU_BROKEN.store(true, AO::Relaxed);
            return false;
        }
    };
    let r = ROUTER_SC.with(|cell| -> Result<()> {
        let mut s = cell.borrow_mut();
        let RouterScratch {
            x: dx,
            out: dout,
            hx,
            ho,
        } = &mut *s;
        let bytes_x = k * 4;
        let bytes_out = n * 4;
        Scratch::ensure(dx, bytes_x)?;
        Scratch::ensure(dout, bytes_out)?;
        Scratch::ensure_pin(hx, bytes_x)?;
        Scratch::ensure_pin(ho, bytes_out)?;
        let (dx, dout) = (dx.as_ref().unwrap(), dout.as_ref().unwrap());
        let (hx, ho) = (hx.as_mut().unwrap(), ho.as_mut().unwrap());
        hx.as_mut_slice::<f32>()[..k].copy_from_slice(x);
        unsafe {
            check(
                (lib.memcpy_htod_async)(
                    dx.ptr(),
                    hx.ptr as *const c_void,
                    bytes_x,
                    std::ptr::null_mut(),
                ),
                "cuMemcpyHtoDAsync",
            )?;
            let (mut ph, mut pw, mut po) = (dx.ptr(), w.buf.ptr(), dout.ptr());
            let (mut kc, mut nc) = (k as c_int, n as c_int);
            let mut args = [
                &mut ph as *mut _ as *mut c_void,
                &mut pw as *mut _ as *mut c_void,
                &mut po as *mut _ as *mut c_void,
                &mut kc as *mut _ as *mut c_void,
                &mut nc as *mut _ as *mut c_void,
            ];
            // task 127: 長い行 (k >= n) は `_r` (1 ブロック = 1 行・block 256 で
            // k を分割し warp shuffle の固定木で縮約・決定論)、それ以外と
            // ゲート off は従来どおり逐次版 (カーネルが block 内全スレッドで
            // 同一計算するため block=(1,1,1))。grid.x は 2^31-1 まで合法。
            let (mv_fn, mv_thr): (CUfunction, u32) = if use_reduce {
                (f_red.expect("use_reduce は has_r=true を要求する"), 256)
            } else {
                (f_seq.expect("use_reduce=false は逐次版のハンドルを要求する"), 1)
            };
            if use_reduce && !ROUTER_GPU_REDUCE_LOGGED.swap(true, AO::Relaxed) {
                tracing::info!(
                    "[router-gpu] dno_matvec_f32_r を使用 (block 256・k={k} n={n})"
                );
            }
            ctx.launch_async(mv_fn, (n as u32, 1, 1), (mv_thr, 1, 1), 0, &mut args)?;
            check(
                (lib.memcpy_dtoh_async)(ho.ptr, dout.ptr(), bytes_out, std::ptr::null_mut()),
                "cuMemcpyDtoHAsync",
            )?;
            crate::prof::mark_d2h_src(crate::prof::D2H_SRC_LINEAR);
        }
        // task 192: 待たずに返す (待ちは `maybe_gpu_router_gemv_finish`)。
        ROUTER_PENDING_N.with(|c| c.set(n));
        Ok(())
    });
    match r {
        Ok(()) => {
            set_last_linear_ran_on_gpu(true);
            if prof {
                let up_w = crate::gpu_budget::weight_upload_bytes().saturating_sub(up_before);
                crate::model::devprof::note_bytes(k as u64 * 4 + up_w, n as u64 * 4);
            }
            true
        }
        Err(e) => {
            tracing::error!("CUDA router f32 gemv failed, using CPU permanently: {e:#}");
            ROUTER_GPU_BROKEN.store(true, AO::Relaxed);
            false
        }
    }
}

/// task 192: [`maybe_gpu_router_gemv_begin`] の後半 (同期 + ホストへの写し)。
///
/// `false` = 待ちに失敗した (呼び出し側は CPU 経路で計算し直す)。
pub fn maybe_gpu_router_gemv_finish(out: &mut [f32]) -> bool {
    use std::sync::atomic::Ordering as AO;
    let n = ROUTER_PENDING_N.with(|c| c.replace(0));
    if n == 0 || out.len() != n {
        return false;
    }
    // task 307: mix の鎖が積んで、その同期で既に届いている場合 (待たない)。
    if ROUTER_SYNCED.with(|c| c.replace(false)) {
        ROUTER_FILLED.with(|c| c.set((0, 0, 0)));
        let r = ROUTER_SC.with(|cell| -> Result<()> {
            let s = cell.borrow();
            let ho = s
                .ho
                .as_ref()
                .ok_or_else(|| anyhow!("router scratch が無い (mix の鎖を飛ばした)"))?;
            out.copy_from_slice(&ho.as_slice::<f32>()[..n]);
            Ok(())
        });
        if r.is_ok() {
            set_last_linear_ran_on_gpu(true);
            return true;
        }
        return false;
    }
    let Some(ctx) = shared_ctx() else {
        return false;
    };
    let r = (|| -> Result<()> {
        // task 155: 待つのは null ストリームのぶんだけ (重ね打ち中の shared
        // expert のサイドストリームは待たない)。イベントが無ければ従来どおり。
        sync_default_or_ctx(ctx, router_fused_enabled())?;
        ROUTER_SC.with(|cell| -> Result<()> {
            let s = cell.borrow();
            let ho = s
                .ho
                .as_ref()
                .ok_or_else(|| anyhow!("router scratch が無い (begin を飛ばした)"))?;
            out.copy_from_slice(&ho.as_slice::<f32>()[..n]);
            Ok(())
        })
    })();
    match r {
        Ok(()) => {
            set_last_linear_ran_on_gpu(true);
            true
        }
        Err(e) => {
            tracing::error!("CUDA router f32 gemv (finish) failed, using CPU permanently: {e:#}");
            ROUTER_GPU_BROKEN.store(true, AO::Relaxed);
            false
        }
    }
}

/// task 69: ルータ (f32・m=1) を GPU で計算して `out` に書く (begin + finish)。
///
/// `false` = 呼び出し側は CPU 参照で計算すること (GPU 無効・PTX 未収録・予算外・
/// 実行時エラー)。逐次版 `dno_matvec_f32` のときは CPU 経路とビット一致するので
/// どちらに落ちても出力は変わらない。task 127 で既定は並列リダクション版
/// `dno_matvec_f32_r` (丸め順が違う = ビット一致しない・決定論は保つ)。
pub fn maybe_gpu_router_gemv_into(
    uid: u64,
    bytes: &[u8],
    k: usize,
    n: usize,
    x: &[f32],
    out: &mut [f32],
) -> bool {
    maybe_gpu_router_gemv_begin(uid, bytes, k, n, x) && maybe_gpu_router_gemv_finish(out)
}

// ===========================================================================
// task 110: hc mix (hc_down / hc_up) の BF16 GEMV を GPU へ (decode 96 回/token)
// ===========================================================================
// 実測 (メインセッション 2026-11-02、swift15 IQ3_S、DENNO_MIX_KPROF=1): decode
// mix 47.1 ms/tok の 91% が hc_down / hc_up の BF16 GEMV。down = [10240->320] /
// up = [320->10240]、48 層 x 2 = 96 回/token、重み 630 MB/token を CPU が読む
// 帯域律速 (316 MMAC/token で 42.9 ms = 7.4 GMAC/s)。
//
// カーネルは新規に作らず、s49 / task 69 と同じ `dno_matvec_f32` を流用する
// (.cu / PTX は 1 バイトも変えない。BF16 を直接読むカーネルは現行 PTX に無い):
//   - 1 行 = 1 ブロック (grid=(n,1,1)・block=(1,1,1))・k 昇順の直列加算。
//     PTX は `mul.rn.f32` + `add.rn.f32` のみ (fma.rn 0 個・.ftz 0 個)。
//   - CPU 参照は `kquant::dequant_row_into` (BF16 -> f32 は上位 16bit 複製 =
//     情報落ちなし) + 1 行の `acc += row[i] * x[i]` (i 昇順・積と加算の丸め分離)。
//     同じ演算列なので**ビット一致**する (task 92 の AVX2 融合カーネルも
//     「積を i 昇順で逐次加算・FMA 無し」で classic とビット一致済み)。
//   - BF16 のまま VRAM に載せられない (カーネルは f32 を読む) ため f32 に展開
//     して常駐する (630 MB BF16 -> 1,260 MB f32。BF16 -> f32 は情報落ちなしで
//     値は不変)。展開は初回の GPU 呼び出しで 1 回だけ。
//   - 常駐は s49 (LMV32_W) と同じ**専用レジストリ** (eviction 無し・uid key)。
//     gguf_registry (DENNO_GPU_WEIGHT_MB) にも expert LRU (DENNO_EXPERT_VRAM_MB)
//     にも乗らないので、ルータ / lm_head / expert と枠を奪い合わない。
//   - 失敗時 (VRAM 足りない等) は CPU へフォールバックして warning を 1 行だけ
//     出す (MIX_GPU_BROKEN ラッチ。2 回目以降は warn 無しで静かに CPU に落ちる)。
//     cuda_enabled() が false (GPU 無し・DENNO_CUDA 未設定) は正常フォール
//     バックなので warn を出さない。

/// task 110: hc mix BF16 経路のスコープド恒久ラッチ (s49 / task 69 とは独立。
/// 本経路の失敗で他の GPU 経路を落とさない)。
static MIX_GPU_BROKEN: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// task 110: hc mix BF16 経路の入口に入った回数 (テスト専用)。
/// 「ゲートを足したが分岐が通っていない」を GPU 無しで検出するために、
/// `cuda_enabled()` の判定より**前**で数える (task 69 の ROUTER_GPU_ATTEMPTS
/// と同じ流儀)。
#[cfg(test)]
static MIX_GPU_ATTEMPTS: std::sync::atomic::AtomicUsize =
    std::sync::atomic::AtomicUsize::new(0);

/// task 110: [`MIX_GPU_ATTEMPTS`] を読む (テスト専用)。
#[cfg(test)]
pub(crate) fn mix_gpu_attempts() -> usize {
    MIX_GPU_ATTEMPTS.load(std::sync::atomic::Ordering::Relaxed)
}

/// task 110: hc mix BF16 経路の失敗 warning (1 行だけ。ラッチは swap で 1 回保証)。
fn mix_gpu_broken_once(msg: &str) {
    let prev = MIX_GPU_BROKEN.swap(true, std::sync::atomic::Ordering::Relaxed);
    if !prev {
        tracing::warn!("CUDA hc mix BF16 GPU disabled, using CPU: {msg}");
    }
}

/// task 110: BF16 重みを f32 に展開する (行ごとに [`crate::kquant::dequant_row_into`]
/// を通す = BF16 -> f32 変換の定義を 1 か所に保つ。BF16 は f32 の上位 16bit なので
/// 情報落ちは無い)。
fn mix_expand_bf16(bytes: &[u8], k: usize, n: usize) -> Vec<f32> {
    let rb = k * 2;
    let mut out = vec![0f32; k * n];
    let mut row = vec![0f32; k];
    for r in 0..n {
        crate::kquant::dequant_row_into(
            crate::kquant::GgmlType::Bf16,
            &bytes[r * rb..(r + 1) * rb],
            &mut row,
        );
        out[r * k..(r + 1) * k].copy_from_slice(&row);
    }
    out
}

/// task 110: 展開済み f32 重みの常駐エントリ (s49 の LMV32_W と同じ方針:
/// eviction 無し・uid key。解放は [`mix_gpu_unregister`] が `GgufLinear::drop` から)。
///
/// task 152: `bf16 == true` のときは `buf` が **BF16 の生バイト** (k*n*2 B) で、
/// カーネルは `dno_matvec_bf16*` / `dno_gemm_bf16_mt` を使う。f32 展開しないので
/// 常駐が半分になる (lab t149c の w:mix_f32 2,425 MiB のうち約 1,200 MiB が戻る)。
struct MixGpuW {
    buf: DevBuffer,
    k: usize,
    n: usize,
    bf16: bool,
}

/// task 152: 常駐重みのポインタ (モードは呼び出し側が先に決めている)。
#[derive(Clone, Copy)]
struct MixW {
    ptr: CUdeviceptr,
}

/// task 152: `DENNO_MIX_BF16` の解釈 (純関数)。明示的な真値だけ on。
/// 既定は [`MIX_BF16_DEFAULT`] (lab の採否で決める)。
fn mix_bf16_from_value(v: Option<&str>, default_on: bool) -> bool {
    match v.map(|s| s.trim().to_ascii_lowercase()) {
        Some(s) if matches!(s.as_str(), "1" | "true" | "on" | "yes") => true,
        Some(s) if matches!(s.as_str(), "0" | "false" | "off" | "no") => false,
        _ => default_on,
    }
}

/// task 152: BF16 のまま読むカーネルを使うか (`DENNO_MIX_BF16`)。
fn mix_bf16_enabled() -> bool {
    static ON: OnceLock<bool> = OnceLock::new();
    *ON.get_or_init(|| {
        mix_bf16_from_value(std::env::var("DENNO_MIX_BF16").ok().as_deref(), MIX_BF16_DEFAULT)
    })
}

static MIX_GPU_W: OnceLock<std::sync::Mutex<std::collections::HashMap<u64, MixGpuW>>> =
    OnceLock::new();

/// task 110: hc mix 用スクラッチ。ルータの RouterScratch と分ける (mix down は
/// x=41KB/out=1.3KB、up は x=1.3KB/out=41KB と交互に来るが grow-only なので
/// 41KB x 2 で固定)。decode は 1 スレッド直列だが thread_local にする理由は同じ。
struct MixGpuScratch {
    x: Option<DevBuffer>,
    /// task 138: チェーン経路の down 出力 (lo_apply 済み) を device に置く場所。
    lo: Option<DevBuffer>,
    out: Option<DevBuffer>,
    /// task 150: chain2 の hc_mixed 出力 ([e]) を device に置く場所。
    mixed: Option<DevBuffer>,
    hx: Option<PinMem>,
    ho: Option<PinMem>,
    /// task 282: 量子 chain の高速 GEMV 用の前置き
    /// (`[wptr_d][wptr_u][seg_d][seg_u][xn]` を 1 本の H2D で送る)。
    stage: Option<DevBuffer>,
    hstage: Option<PinMem>,
    /// task 382: `DENNO_MIX_ZC` 用。device から直接見える pinned。
    /// `xmap` = down の入力 (`xn`、H2D を消す)、`omap` = `mixed` の行き先
    /// (hc_mixed に直接書かせて D2H を消す)。`None` の間は従来経路。
    xmap: Option<MapMem>,
    omap: Option<MapMem>,
    /// task 382: `DENNO_MIX_UPQ8=check` の比較用 (融合版の出力 / その受け皿)。
    chk: Option<DevBuffer>,
    hchk: Option<PinMem>,
    /// task 431: `DENNO_MIX_ZC=stream` の H2D 専用ストリーム + 完了イベント。
    /// 鎖のカーネルは null ストリームのまま (発行順も同期点も変えない)。
    cstream: Option<CopyStream>,
    cev: Option<CopyEvent>,
}

thread_local! {
    static MIX_GPU_SC: std::cell::RefCell<MixGpuScratch> =
        std::cell::RefCell::new(MixGpuScratch {
            x: None,
            lo: None,
            out: None,
            mixed: None,
            hx: None,
            ho: None,
            stage: None,
            hstage: None,
            xmap: None,
            omap: None,
            chk: None,
            hchk: None,
            cstream: None,
            cev: None,
        });
}

/// task 431: H2D 専用の非ブロッキングストリーム + 完了イベントを用意する
/// (`DENNO_MIX_ZC=stream` のときだけ呼ばれる)。作れなければ `None` = 従来経路。
fn mix_h2s_ensure(s: &mut MixGpuScratch) -> Option<(CUstream, CUevent)> {
    if let (Some(st), Some(ev)) = (s.cstream.as_ref(), s.cev.as_ref()) {
        return Some((st.0, ev.0));
    }
    const CU_STREAM_NON_BLOCKING: u32 = 0x01;
    const CU_EVENT_DISABLE_TIMING: u32 = 0x02;
    let l = lib().ok()?;
    let (Some(stream_create), Some(event_create)) = (l.stream_create, l.event_create) else {
        return None;
    };
    let mut st: CUstream = std::ptr::null_mut();
    if unsafe { stream_create(&mut st, CU_STREAM_NON_BLOCKING) } != CUDA_SUCCESS {
        return None;
    }
    let mut ev: CUevent = std::ptr::null_mut();
    if unsafe { event_create(&mut ev, CU_EVENT_DISABLE_TIMING) } != CUDA_SUCCESS {
        unsafe {
            if let Some(f) = l.stream_destroy {
                let _ = f(st);
            }
        }
        return None;
    }
    s.cstream = Some(CopyStream(st));
    s.cev = Some(CopyEvent(ev));
    Some((st, ev))
}

/// task 121: mix GPU で並列リダクション版 (`dno_matvec_f32_r`) に切り替える
/// 「長い行」の閾値 (k >= n × この比)。実測 (swift15-abl IQ3_S・128 tok・main) では
/// down (k=10240, n=320) が 281 us/行列とほぼ直列 (1 ブロック = 1 行で k を 1
/// スレッドが舐めるため並列度が n しかない) で、up (k=320, n=10240) は 55
/// us/行列と n 側に並列度が足りている。比 1.0 = k が n 以上なら `_r` を使う。
const MIX_REDUCE_MIN_RATIO: f64 = 1.0;

/// task 121: mix GPU matvec のカーネル選択 (純関数・GPU 無しで検証可)。
/// true = `dno_matvec_f32_r` (block 256・k をスレッド分割して warp shuffle の
/// 固定木で縮約・決定論) / false = `dno_matvec_f32` (block 1・k 逐次)。
/// 長い行 (k >= n × [`MIX_REDUCE_MIN_RATIO`]) だけ `_r` にする。短い行は並列度が
/// 行数 n 側にあり逐次版で十分 (これを `_r` に変えると up が遅くなる)。
/// 縮退形 (n == 0) は安全側で逐次版 (実際は呼び出し側の形状検査が先に弾く)。
/// `has_r` は PTX に `_r` が無いとき false となり逐次版に落ちる (fail closed・
/// エラーにはしない)。[`fast_reduce_enabled`] (DENNO_FAST_REDUCE) には依存しない
/// (mix の長い行はオペレーター方針で bit 一致契約の外 = 速度優先・決定論のみ)。
fn mix_use_reduce_kernel(k: usize, n: usize, has_r: bool) -> bool {
    has_r && n > 0 && (k as f64) >= (n as f64) * MIX_REDUCE_MIN_RATIO
}

/// task 110 (task 121 で長い行を並列リダクション版に): hc mix BF16 (m==1) の
/// GEMV を GPU で実行する。
///
/// 戻り値 false = CPU パスを使うこと (GPU 無効・PTX 未収録・形状不一致・確保失敗・
/// 実行エラー)。数値は短い行 (k < n) が CPU 経路とビット一致するので、そちらは
/// どちらに落ちても出力は変わらない。長い行 (k >= n、[`mix_use_reduce_kernel`])
/// は s169 の並列リダクション版 `dno_matvec_f32_r` (block 256・warp shuffle の
/// 固定木) を使い、丸め順が CPU の逐次累積と違うためビット一致は**しない**
/// (実行ごとの決定論は保つ。オペレーター方針: 速度優先)。uid は `GgufLinear` の
/// もの (モデルロード毎に一意) で、そのまま常駐レジストリの key にする。bytes は
/// BF16 の生バイト (k * n * 2)。
///
/// ゲート (`DENNO_MIX_GPU`、既定 off) の判定は呼び出し側 (qwen4exp の
/// hc_mix_quant_fast) が持つ。
pub fn maybe_gpu_mix_bf16_into(
    uid: u64,
    bytes: &[u8],
    k: usize,
    n: usize,
    x: &[f32],
    out: &mut [f32],
) -> bool {
    use std::sync::atomic::Ordering as AO;
    #[cfg(test)]
    MIX_GPU_ATTEMPTS.fetch_add(1, AO::Relaxed);
    if !cuda_enabled() {
        return false;
    }
    if MIX_GPU_BROKEN.load(AO::Relaxed) {
        return false;
    }
    if k == 0
        || n == 0
        || x.len() != k
        || out.len() != n
        || bytes.len() != k.saturating_mul(n).saturating_mul(2)
        || k > i32::MAX as usize
        || n > i32::MAX as usize
    {
        mix_gpu_broken_once(&format!(
            "shape mismatch (k={k}, n={n}, bytes={} / want {})",
            bytes.len(),
            k.saturating_mul(n).saturating_mul(2)
        ));
        return false;
    }
    let Some(ctx) = shared_ctx() else {
        mix_gpu_broken_once("shared_ctx() is None");
        return false;
    };
    if let Err(e) = ctx.make_current() {
        mix_gpu_broken_once(&format!("cuCtxSetCurrent: {e:#}"));
        return false;
    }
    // カーネルハンドル (lazy fetch)。未収録 PTX は 1 行 warn して CPU に落とす。
    // task 152: `DENNO_MIX_BF16=1` かつ BF16 カーネルが PTX にあれば、重みを f32 に
    // 展開せず BF16 のまま読む (常駐が半分)。無ければ従来の f32 展開経路。
    let want_bf16 = mix_bf16_enabled() && matvec_bf16_fn(ctx).is_some();
    let (f_seq, f_red) = if want_bf16 {
        (matvec_bf16_fn(ctx), matvec_bf16_r_fn(ctx))
    } else {
        (matvec_f32_fn(ctx), matvec_f32_r_fn(ctx))
    };
    let Some(f) = f_seq else {
        mix_gpu_broken_once("kernels_elem.ptx に dno_matvec_f32 が無い (PTX 再生成が必要)");
        return false;
    };
    // task 121: 長い行 (k >= n) は s169 の並列リダクション版 (`dno_matvec_f32_r`)
    // を使う。逐次版は 1 ブロック = 1 行で k を 1 スレッドが舐めるため、down
    // (k=10240, n=320) のような形で並列度が足りない (実測 281 us/行列・ほぼ DRAM
    // 律速に達しない)。`_r` は DENNO_FAST_REDUCE と無関係にこの経路だけで選ぶ
    // (mix の長い行はオペレーター方針で bit 一致契約の外)。PTX に `_r` が無ければ
    // (Option が None) 逐次版に落ちる = 失敗にはしない (fail closed)。
    let fr = f_red;
    let use_reduce = mix_use_reduce_kernel(k, n, fr.is_some());
    // 重みの展開 + 常駐 (初回 1 回・同期 H2D)。ロック内で二重アップロード防止。
    let wp = match mix_gpu_weight(uid, bytes, k, n, want_bf16) {
        Ok(w) => w.ptr,
        Err(e) => {
            mix_gpu_broken_once(&format!("hc mix 重みの常駐に失敗: {e:#}"));
            return false;
        }
    };
    let lib = match lib() {
        Ok(l) => l,
        Err(e) => {
            mix_gpu_broken_once(&format!("CUDA lib load failed: {e:#}"));
            return false;
        }
    };
    let r = MIX_GPU_SC.with(|cell| -> Result<()> {
        let mut s = cell.borrow_mut();
        let MixGpuScratch {
            x: dx,
            out: dout,
            hx,
            ho,
            ..
        } = &mut *s;
        let bytes_x = k * 4;
        let bytes_out = n * 4;
        Scratch::ensure(dx, bytes_x)?;
        Scratch::ensure(dout, bytes_out)?;
        Scratch::ensure_pin(hx, bytes_x)?;
        Scratch::ensure_pin(ho, bytes_out)?;
        let (dx, dout) = (dx.as_ref().unwrap(), dout.as_ref().unwrap());
        let (hx, ho) = (hx.as_mut().unwrap(), ho.as_mut().unwrap());
        // task 177: mix 1 回の操作別内訳 (`DENNO_GDN_DEC_KPROF`・既定 off)。
        let _kp_win = dec_kprof::window(
            dec_kprof::MIX,
            dec_kprof::cur_layer(),
            dec_kprof::cur_pos(),
            0,
        );
        hx.as_mut_slice::<f32>()[..k].copy_from_slice(x);
        unsafe {
            check(
                (lib.memcpy_htod_async)(
                    dx.ptr(),
                    hx.ptr as *const c_void,
                    bytes_x,
                    std::ptr::null_mut(),
                ),
                "cuMemcpyHtoDAsync",
            )?;
            let (mut ph, mut pw, mut po) = (dx.ptr(), wp, dout.ptr());
            let (mut kc, mut nc) = (k as c_int, n as c_int);
            let mut args = [
                &mut ph as *mut _ as *mut c_void,
                &mut pw as *mut _ as *mut c_void,
                &mut po as *mut _ as *mut c_void,
                &mut kc as *mut _ as *mut c_void,
                &mut nc as *mut _ as *mut c_void,
            ];
            // task 121: 長い行は `_r` (1 ブロック = 1 行・block 256 で k を分割し
            // warp shuffle の固定木で縮約・決定論)、短い行は従来どおり逐次版
            // (カーネルが block 内全スレッドで同一計算するため block=(1,1,1)。
            // grid.x は 2^31-1 まで合法)。
            let (mv_fn, mv_thr): (CUfunction, u32) = if use_reduce {
                (fr.expect("use_reduce は has_r=true を要求する"), 256)
            } else {
                (f, 1)
            };
            ctx.launch_async(mv_fn, (n as u32, 1, 1), (mv_thr, 1, 1), 0, &mut args)?;
            check(
                (lib.memcpy_dtoh_async)(ho.ptr, dout.ptr(), bytes_out, std::ptr::null_mut()),
                "cuMemcpyDtoHAsync",
            )?;
            crate::prof::mark_d2h_src(crate::prof::D2H_SRC_LINEAR);
        }
        ctx.sync()?;
        out.copy_from_slice(&ho.as_slice::<f32>()[..n]);
        Ok(())
    });
    match r {
        Ok(()) => {
            set_last_linear_ran_on_gpu(true);
            true
        }
        Err(e) => {
            mix_gpu_broken_once(&format!("hc mix BF16 matvec failed: {e:#}"));
            false
        }
    }
}

/// task 145: `dno_gemm_f32_mt` (f32 重み × m トークンの GEMM) のハンドル。
///
/// kernels_elem.ptx に未収録なら None をキャッシュする (呼び出し側は CPU の
/// バッチ経路へ落ちるだけで、失敗にはしない = fail closed)。
#[derive(Clone, Copy)]
struct LgemmMtFn(CUfunction);
unsafe impl Send for LgemmMtFn {}
unsafe impl Sync for LgemmMtFn {}

static GEMM_F32_MT_FNS: OnceLock<Option<LgemmMtFn>> = OnceLock::new();

fn gemm_f32_mt_fn(ctx: &CudaCtx) -> Option<CUfunction> {
    GEMM_F32_MT_FNS
        .get_or_init(|| {
            let lib = lib().ok()?;
            let mut f: CUfunction = std::ptr::null_mut();
            let r = unsafe {
                (lib.module_get_function)(
                    &mut f,
                    ctx.module_elem,
                    b"dno_gemm_f32_mt\0".as_ptr() as *const c_char,
                )
            };
            if r != 0 {
                None
            } else {
                Some(LgemmMtFn(f))
            }
        })
        .as_ref()
        .map(|h| h.0)
}

/// task 145 のカーネル幾何 (kernels_elem.cu の `dno_gemm_f32_mt` と 1:1)。
pub const GEMM_MT_ROWS: usize = 16;
/// 1 ブロックが担当するトークン数。
pub const GEMM_MT_TOKS: usize = 32;

/// task 145: prefill の hc mix (BF16 重み) を **m トークンまとめて** GPU で回す。
///
/// `out[t * n + r] = dot(bf16 を f32 展開した行 r, xs[t])`。
/// 重みは decode の mix GPU 経路と**同じ常駐バッファ** ([`mix_gpu_weight`]) を
/// 使うので、既に載っていれば転送は起きない。1 呼び出し = H2D 1 回 + 起動 1 回 +
/// 同期 1 回 + D2H 1 回。数値は FMA + タイル順なので CPU の mul+add 逐次とは
/// ビット一致しない (prefill のバッチ行列積は速度優先の契約)。
///
/// `false` = GPU でやらなかった (呼び出し側は CPU バッチへ)。
pub fn maybe_gpu_mix_bf16_batch_into(
    uid: u64,
    bytes: &[u8],
    k: usize,
    n: usize,
    xs: &[f32],
    nt: usize,
    out: &mut [f32],
) -> bool {
    if !cuda_enabled() || MIX_GPU_BROKEN.load(std::sync::atomic::Ordering::Relaxed) {
        return false;
    }
    if k == 0
        || n == 0
        || nt < 2
        || xs.len() != nt * k
        || out.len() != nt * n
        || bytes.len() != k.saturating_mul(n).saturating_mul(2)
        || k > i32::MAX as usize
        || n > i32::MAX as usize
        || nt > i32::MAX as usize
    {
        return false;
    }
    let Some(ctx) = shared_ctx() else {
        return false;
    };
    if let Err(e) = ctx.make_current() {
        mix_gpu_broken_once(&format!("cuCtxSetCurrent (batch): {e:#}"));
        return false;
    }
    // task 152: BF16 カーネルがあれば重みを BF16 のまま置く (常駐が半分)。
    let want_bf16 = mix_bf16_enabled() && gemm_bf16_mt_fn(ctx).is_some();
    let f = if want_bf16 {
        gemm_bf16_mt_fn(ctx)
    } else {
        gemm_f32_mt_fn(ctx)
    };
    let Some(f) = f else {
        // PTX 未収録 (PTX=elem の再生成待ち)。ラッチはしない。
        return false;
    };
    let wp = match mix_gpu_weight(uid, bytes, k, n, want_bf16) {
        Ok(w) => w.ptr,
        Err(e) => {
            mix_gpu_broken_once(&format!("batch の重み常駐に失敗: {e:#}"));
            return false;
        }
    };
    let lib = match lib() {
        Ok(l) => l,
        Err(e) => {
            mix_gpu_broken_once(&format!("CUDA lib load failed (batch): {e:#}"));
            return false;
        }
    };
    let r = MIX_GPU_SC.with(|cell| -> Result<()> {
        let mut s = cell.borrow_mut();
        let MixGpuScratch {
            x: dx, out: dout, ..
        } = &mut *s;
        let bytes_x = nt * k * 4;
        let bytes_out = nt * n * 4;
        Scratch::ensure(dx, bytes_x)?;
        Scratch::ensure(dout, bytes_out)?;
        let (dx, dout) = (dx.as_ref().unwrap(), dout.as_ref().unwrap());
        // s68 の実測 (pinned 経由 + memcpy は pageable 直の 4 倍遅い) に従い、
        // ホスト側のコピーを挟まず呼び出し元のスライス / 出力先へ直接発行する。
        dx.copy_from(xs)?;
        unsafe {
            let (mut pw, mut px, mut po) = (wp, dx.ptr(), dout.ptr());
            let (mut nt_c, mut k_c, mut n_c) = (nt as c_int, k as c_int, n as c_int);
            let mut args = [
                &mut pw as *mut _ as *mut c_void,
                &mut px as *mut _ as *mut c_void,
                &mut po as *mut _ as *mut c_void,
                &mut nt_c as *mut _ as *mut c_void,
                &mut k_c as *mut _ as *mut c_void,
                &mut n_c as *mut _ as *mut c_void,
            ];
            let grid = (
                ((n + GEMM_MT_ROWS - 1) / GEMM_MT_ROWS) as u32,
                ((nt + GEMM_MT_TOKS - 1) / GEMM_MT_TOKS) as u32,
                1,
            );
            ctx.launch_async(f, grid, (GEMM_MT_ROWS as u32, 16, 1), 0, &mut args)?;
            ctx.sync()?;
            // D2H は同期コピーで `out` へ直接 (中間 Vec / pinned を作らない)。
            check(
                (lib.memcpy_dtoh)(
                    out.as_mut_ptr() as *mut c_void,
                    dout.ptr(),
                    bytes_out,
                ),
                "cuMemcpyDtoH (mix batch)",
            )?;
            crate::prof::mark_d2h_src(crate::prof::D2H_SRC_LINEAR);
        }
        Ok(())
    });
    match r {
        Ok(()) => {
            set_last_linear_ran_on_gpu(true);
            true
        }
        Err(e) => {
            mix_gpu_broken_once(&format!("hc mix BF16 batch GEMM failed: {e:#}"));
            false
        }
    }
}

// ---------------------------------------------------------------------------
// task 182: prefill の router / PLE 射影 (F32 重み × m トークン) を GPU で回す
// ---------------------------------------------------------------------------
//
// task 170 (br170) が層優先 prefill 用に書いたものと同じ経路。ここでは通常の
// チャンク順 prefill から、層ごと・チャンクごとに 1 回ずつ呼ぶ:
//   - router (`ffn_gate_inp`、実形 2,560 x 512 の F32) は 14k の prefill で 2.8 s
//   - PLE の key / value 射影 (F32、`blk.1.ple_key/value`) は合わせて約 1.3 s
// どちらも CPU の行バッチで回っていた。重みは `weights_for_f32` の常駐
// (decode のルータ GEMV と同じ uid 表) に載せ、既存の `dno_gemm_f32_mt` で
// m トークンをまとめて回す (.cu / PTX の変更なし)。
//
// 数値は FMA + タイル順なので CPU の `mul + add` 逐次とはビット一致しない
// (prefill の行列積は速度優先の契約)。`false` = CPU のバッチ経路へ。

struct F32GemmBatchSc {
    x: Option<DevBuffer>,
    out: Option<DevBuffer>,
    /// task 296: 大きい D2H 用の pinned 置き場 (grow-only)。
    pin: Option<PinMem>,
}

thread_local! {
    static F32_GEMM_BATCH_SC: std::cell::RefCell<F32GemmBatchSc> = const {
        std::cell::RefCell::new(F32GemmBatchSc { x: None, out: None, pin: None })
    };
}

/// `DENNO_F32_GEMM_PIN_D2H`: 1 MiB 以上の D2H を pinned 経由の非同期コピーに
/// する (task 296、既定 **off**)。
///
/// 層優先 prefill ではこの関数の D2H が毎層・毎チャンク走る:
/// router (3,826 x 512 = 7.8 MB/層) と PLE の key/value
/// (3,826 x 320 + 3,826 x 2560 = 22 MB/チャンク x 96)。pageable の
/// `cuMemcpyDtoH` は 1 枚 6 GB/s 前後しか出ないので、pinned へ非同期で落として
/// からホストへ写す (デバイスから出るバイト列は同じ = 値は不変)。
///
/// lab t296c: 3,826 cold は base 3.41 / 既定 (両方 on) 3.24 で、内訳では
/// `other` が -170 ms。ただしこの差は同時に on にした [`PIN_GROW_ENV`] の
/// ぶんで、このゲート単独の差は見えていない (`ple` は 154 → 160 ms で不変)。
/// 効いた証拠が無いので既定 off。
pub const F32_GEMM_PIN_D2H_ENV: &str = "DENNO_F32_GEMM_PIN_D2H";

/// この関数で pinned D2H を使う下限 (これ未満は従来の pageable)。
pub(crate) const F32_GEMM_PIN_D2H_MIN: usize = 1 << 20;

/// [`F32_GEMM_PIN_D2H_ENV`] の解釈 (明示的な真値だけ on)。
pub(crate) fn f32_gemm_pin_d2h_from_value(v: Option<&str>) -> bool {
    let low = v.map(|s| s.trim().to_ascii_lowercase());
    matches!(
        low.as_deref(),
        Some("1") | Some("on") | Some("true") | Some("yes")
    )
}

/// 大きい D2H を pinned 経由にするか (既定 off)。
fn f32_gemm_pin_d2h_on() -> bool {
    static ON: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *ON.get_or_init(|| {
        f32_gemm_pin_d2h_from_value(std::env::var(F32_GEMM_PIN_D2H_ENV).ok().as_deref())
    })
}

/// task 182: `maybe_gpu_f32_gemm_batch_into` の入口に入った回数 (テスト専用)。
///
/// このコンテナに GPU は無いので、計算は `cuda_enabled()` の所で CPU へ落ちる。
/// ゲートと配線が生きていることを「入口の回数」で数える (decode の
/// `router_gpu_attempts` と同じ規約)。
#[cfg(test)]
static F32_GEMM_BATCH_ATTEMPTS: std::sync::atomic::AtomicUsize =
    std::sync::atomic::AtomicUsize::new(0);

#[cfg(test)]
pub(crate) fn f32_gemm_batch_attempts() -> usize {
    F32_GEMM_BATCH_ATTEMPTS.load(std::sync::atomic::Ordering::Relaxed)
}

#[cfg(test)]
pub(crate) fn f32_gemm_batch_attempts_reset() {
    F32_GEMM_BATCH_ATTEMPTS.store(0, std::sync::atomic::Ordering::Relaxed);
}

/// task 182: `out[t * n + r] = dot(row r, xs[t])` を GPU の f32 GEMM で回す。
///
/// 重みは [`weights_for_f32`] の常駐 (router の 1 行 GEMV と同じ uid 表) を使う。
/// `nt < 2`・形の不一致・GPU 無し・予算外・PTX 未収録はすべて `false` を返して
/// CPU 経路へ落とす (panic しない)。
pub fn maybe_gpu_f32_gemm_batch_into(
    uid: u64,
    bytes: &[u8],
    k: usize,
    n: usize,
    xs: &[f32],
    nt: usize,
    out: &mut [f32],
    src_ty: crate::kquant::GgmlType,
) -> bool {
    #[cfg(test)]
    F32_GEMM_BATCH_ATTEMPTS.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    if xs.len() != nt * k {
        return false;
    }
    f32_gemm_batch_run(uid, bytes, k, n, BatchIn::Host(xs), nt, out, src_ty)
}

/// task 209: `xs` が既にデバイスにある版 (ホストからの H2D をしない)。
///
/// `dev_x` は `[nt][k]` f32 のデバイス領域。router が `pf_mix` の出力
/// (`mixed`) をそのまま読むために使う。ホスト版と**同じカーネル・同じ入力
/// バイト列**なので値は変わらない。
pub fn maybe_gpu_f32_gemm_batch_dev_into(
    uid: u64,
    bytes: &[u8],
    k: usize,
    n: usize,
    dev_x: CUdeviceptr,
    nt: usize,
    out: &mut [f32],
    src_ty: crate::kquant::GgmlType,
) -> bool {
    #[cfg(test)]
    F32_GEMM_BATCH_ATTEMPTS.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    if dev_x == 0 {
        return false;
    }
    f32_gemm_batch_run(uid, bytes, k, n, BatchIn::Dev(dev_x), nt, out, src_ty)
}

/// 入力の置き場所 (ホストのスライス / 既にデバイスにある領域)。
enum BatchIn<'a> {
    Host(&'a [f32]),
    Dev(CUdeviceptr),
}

/// [`maybe_gpu_f32_gemm_batch_into`] と [`maybe_gpu_f32_gemm_batch_dev_into`] の本体。
fn f32_gemm_batch_run(
    uid: u64,
    bytes: &[u8],
    k: usize,
    n: usize,
    src: BatchIn<'_>,
    nt: usize,
    out: &mut [f32],
    src_ty: crate::kquant::GgmlType,
) -> bool {
    if !cuda_enabled() {
        return false;
    }
    let bpp = match src_ty {
        crate::kquant::GgmlType::F32 => 4usize,
        crate::kquant::GgmlType::Bf16 | crate::kquant::GgmlType::F16 => 2,
        _ => return false,
    };
    if k == 0
        || n == 0
        || nt < 2
        || out.len() != nt * n
        || bytes.len() != k.saturating_mul(n).saturating_mul(bpp)
        || k > i32::MAX as usize
        || n > i32::MAX as usize
        || nt > i32::MAX as usize
    {
        return false;
    }
    let Some(ctx) = shared_ctx() else {
        return false;
    };
    if ctx.make_current().is_err() {
        return false;
    }
    let Some(f) = gemm_f32_mt_fn(ctx) else {
        return false;
    };
    let w = match weights_for_gemm_f32(uid, bytes, k, n, src_ty) {
        Ok(w) => w,
        Err(_) => return false,
    };
    let lib = match lib() {
        Ok(l) => l,
        Err(_) => return false,
    };
    let r = F32_GEMM_BATCH_SC.with(|cell| -> Result<()> {
        let mut s = cell.borrow_mut();
        let F32GemmBatchSc { x: dx, out: dout, pin } = &mut *s;
        // task 209: デバイス入力のときは `x` の作業域 (と H2D) を丸ごと省く。
        let xp = match src {
            BatchIn::Host(xs) => {
                Scratch::ensure(dx, nt * k * 4)?;
                let dx = dx.as_ref().unwrap();
                dx.copy_from(xs)?;
                dx.ptr()
            }
            BatchIn::Dev(p) => p,
        };
        Scratch::ensure(dout, nt * n * 4)?;
        let dout = dout.as_ref().unwrap();
        let wp = w.buf.ptr();
        unsafe {
            let (mut pw, mut px, mut po) = (wp, xp, dout.ptr());
            let (mut nt_c, mut k_c, mut n_c) = (nt as c_int, k as c_int, n as c_int);
            let mut args = [
                &mut pw as *mut _ as *mut c_void,
                &mut px as *mut _ as *mut c_void,
                &mut po as *mut _ as *mut c_void,
                &mut nt_c as *mut _ as *mut c_void,
                &mut k_c as *mut _ as *mut c_void,
                &mut n_c as *mut _ as *mut c_void,
            ];
            let grid = (
                ((n + GEMM_MT_ROWS - 1) / GEMM_MT_ROWS) as u32,
                ((nt + GEMM_MT_TOKS - 1) / GEMM_MT_TOKS) as u32,
                1,
            );
            ctx.launch_async(f, grid, (GEMM_MT_ROWS as u32, 16, 1), 0, &mut args)?;
            let bytes = nt * n * 4;
            // task 296: 大きい D2H は pinned へ非同期で落として 1 回の同期で待つ
            // (pageable の同期コピーは 6 GB/s 前後しか出ない)。
            if bytes >= F32_GEMM_PIN_D2H_MIN && f32_gemm_pin_d2h_on() {
                Scratch::ensure_pin(pin, bytes)?;
                let p = pin.as_ref().expect("ensure 済み");
                check(
                    (lib.memcpy_dtoh_async)(p.ptr, dout.ptr(), bytes, std::ptr::null_mut()),
                    "cuMemcpyDtoHAsync (f32 batch pin)",
                )?;
                ctx.sync()?;
                // pinned → `out` (デバイスから出たバイト列は従来と同じ)。
                std::ptr::copy_nonoverlapping(
                    p.ptr as *const u8,
                    out.as_mut_ptr() as *mut u8,
                    bytes,
                );
            } else {
                ctx.sync()?;
                // D2H は同期コピーで `out` へ直接 (中間 Vec / pinned を作らない)。
                check(
                    (lib.memcpy_dtoh)(
                        out.as_mut_ptr() as *mut c_void,
                        dout.ptr(),
                        bytes,
                    ),
                    "cuMemcpyDtoH (f32 batch)",
                )?;
            }
            crate::prof::mark_d2h_src(crate::prof::D2H_SRC_LINEAR);
        }
        Ok(())
    });
    r.is_ok()
}

#[cfg(test)]
mod f32_d2h_pin_tests {
    use super::*;

    /// task 296: 1 MiB 以上の D2H を pinned 経由にするゲートの真理値表。
    #[test]
    fn f32_gemm_pin_d2h_gate_truth_table() {
        assert!(!f32_gemm_pin_d2h_from_value(None), "未設定は既定 off");
        assert!(!f32_gemm_pin_d2h_from_value(Some("")));
        assert!(f32_gemm_pin_d2h_from_value(Some("1")));
        assert!(f32_gemm_pin_d2h_from_value(Some(" on ")));
        assert!(f32_gemm_pin_d2h_from_value(Some("True")));
        assert!(!f32_gemm_pin_d2h_from_value(Some("0")));
        assert!(!f32_gemm_pin_d2h_from_value(Some("off")));
        assert!(!f32_gemm_pin_d2h_from_value(Some("no")));
        // しきい値は 1 MiB (decode の小さい D2H は従来のまま = 挙動を変えない)。
        assert_eq!(F32_GEMM_PIN_D2H_MIN, 1 << 20);
        // 3,826 トークンの router (3,826 x 512) と PLE の value (3,826 x 2560) が
        // しきい値を超えること (= prefill の主な D2H が pinned 経路に入る)。
        assert!(3826 * 512 * 4 >= F32_GEMM_PIN_D2H_MIN);
        assert!(3826 * 2560 * 4 >= F32_GEMM_PIN_D2H_MIN);
        // decode (1 トークン x 512) は入らない。
        assert!(512 * 4 < F32_GEMM_PIN_D2H_MIN);
    }
}



// ---------------------------------------------------------------------------
// task 154: prefill のデバイス常駐 mix 連鎖 (`DENNO_PF_RESIDENT`)
// ---------------------------------------------------------------------------
//
// 狙い: hc mix 1 回ごとの往復 (res H2D → down GEMM → lo D2H → lo H2D → up GEMM →
// gate D2H → ホストで norm/silu/gating) を、デバイス上の 1 連鎖に置き換える。
// 入力 `res` はチャンク開始時に 1 回だけ上げ、以後は層をまたいでデバイスに置く
// (`pf_upload_res` / `pf_download_res` は呼び出し側が層の境界でだけ使う)。
//
// 使うカーネル:
//   dno_pf_rmsgroup / dno_pf_lo / dno_pf_mixed / dno_pf_inj / dno_pf_combine
//   (kernels_pf.cu、PTX は `bash build_ptx.sh pf`) と、既存の
//   dno_gemm_bf16_mt (k=hc_dim→low_rank と low_rank→hc_dim と hc_dim→hc)。
//
// 数値: 要素演算は CPU 参照と 1 演算 1 丸めで一致するように書いてある
// (二乗和は i 昇順の逐次)。GEMM は task 145 のバッチ mix と同じ
// `dno_gemm_bf16_mt` なので、`DENNO_MIX_BATCH_GPU=1` のときの値と一致する。

struct PfKernels {
    #[allow(dead_code)]
    module: CUmodule,
    rmsgroup: CUfunction,
    lo: CUfunction,
    mixed: CUfunction,
    inj: CUfunction,
    combine: CUfunction,
}

// 生ハンドル (CudaCtx / MoeBatchKernels と同じ規約)。
unsafe impl Send for PfKernels {}
unsafe impl Sync for PfKernels {}

const PF_NAMES: [&[u8]; 5] = [
    b"dno_pf_rmsgroup\0",
    b"dno_pf_lo\0",
    b"dno_pf_mixed\0",
    b"dno_pf_inj\0",
    b"dno_pf_combine\0",
];

/// task 154: 常駐連鎖の PTX。lab t154e が `PTX=pf` で `kernels_pf.cu` から
/// 再生成したものをそのまま収録した (5 本の entry を含む)。
///
/// `include_bytes!` にする理由: 既定 on の経路なので、実行時にクレート配下の
/// `kernels/` が無い配置でも黙って CPU へ落ちないようにする (task 151 の
/// `kernels_exp_iq_pf.ptx` はファイル読みだが、あちらは既定 on の判断が後追い)。
const PTX_PF: &[u8] = include_bytes!("../kernels/kernels_pf.ptx");

/// `DENNO_PF_PTX` があればそのイメージ、無ければコミット済みの [`PTX_PF`]。
fn pf_ptx_image() -> Option<Vec<u8>> {
    match std::env::var("DENNO_PF_PTX") {
        Ok(p) if !p.is_empty() => {
            let path = std::path::Path::new(&p);
            match std::fs::read(path) {
                Ok(b) => Some(b),
                Err(e) => {
                    tracing::info!(
                        "[pf] PTX が読めない ({}): {e} → CPU 経路",
                        path.display()
                    );
                    None
                }
            }
        }
        _ => Some(PTX_PF.to_vec()),
    }
}

/// カーネル一式を読む (初回だけ。失敗は None を焼き付ける = 二度と試さない)。
fn pf_kernels() -> Option<&'static PfKernels> {
    static K: OnceLock<Option<PfKernels>> = OnceLock::new();
    K.get_or_init(|| {
        let mut image = pf_ptx_image()?;
        image.push(0);
        let lib = lib().ok()?;
        let mut module: CUmodule = std::ptr::null_mut();
        unsafe {
            if (lib.module_load_data)(&mut module, image.as_ptr() as *const c_void) != CUDA_SUCCESS {
                tracing::info!("[pf] cuModuleLoadData 失敗 → CPU 経路");
                return None;
            }
        }
        let mut fns: [CUfunction; 5] = [std::ptr::null_mut(); 5];
        for (i, name) in PF_NAMES.iter().enumerate() {
            unsafe {
                if (lib.module_get_function)(&mut fns[i], module, name.as_ptr() as *const c_char)
                    != CUDA_SUCCESS
                {
                    tracing::info!(
                        "[pf] PTX に {} が無い → CPU 経路",
                        String::from_utf8_lossy(&name[..name.len() - 1])
                    );
                    return None;
                }
            }
        }
        Some(PfKernels {
            module,
            rmsgroup: fns[0],
            lo: fns[1],
            mixed: fns[2],
            inj: fns[3],
            combine: fns[4],
        })
    })
    .as_ref()
}

/// 連鎖 1 回ぶんの失敗を 1 度だけ記録する (以降は CPU 経路に固定)。
static PF_BROKEN: std::sync::atomic::AtomicBool = std::sync::atomic::AtomicBool::new(false);

// ---------------------------------------------------------------------------
// task 186: prefill hc mix の down / up 用 GEMM (`kernels_mix_pf.cu`、既定 off)
// ---------------------------------------------------------------------------
//
// 既存 `dno_gemm_bf16_mt` は 1 ブロック = 16 行 x 32 トークンで、k タイル 32 ごとに
// `__syncthreads` を 2 回打つ (barrier あたりの FMA が 64)。lab t183a の 14k
// prefill で mix の down + up は 4.2 GFLOP を 1.27 ms = 3.1 TFLOP/s (fp32 山の 3%)
// で回っており、同じホストの隣の GEMM は 70-75 TFLOP/s。mix の 146 MB / 1.34 ms は
// 109 GB/s なので帯域律速でもない ([REPORT_P186.md] 0.1 の表)。
//
// 新しい `dno_mix_pf_gemm` は 32 トークン x 64 行 x k タイル 16 で、barrier あたりの
// FMA が 256。**値は既存カーネルとビット一致** (1 出力 1 アキュムレータ・k 昇順の
// `__fmaf_rn`、BF16 -> f32 は上位 16 bit の複製で CPU の dequant と同一) なので、
// 採否は速度だけで決まる。
//
// PTX はクレートの `kernels/kernels_mix_pf.ptx` (lab が `bash build_ptx.sh mix_pf`
// で生成) を実行時に読む。無い・読めない・entry が無いときは従来カーネルへ
// fail closed (ゲート on でも既定 off と同じ経路・同じ値)。

/// 1 ブロックの出力行数 (カーネルの MIXP_BN)。
pub(crate) const MIX_PF_BN: usize = 64;
/// 1 ブロックのトークン数 (カーネルの MIXP_BM)。
pub(crate) const MIX_PF_BM: usize = 32;
/// スレッド数 (カーネルの MIXP_THREADS)。
pub(crate) const MIX_PF_THREADS: usize = 128;
/// 新しいカーネルを使う最小トークン数 (それ未満は既存カーネルのほうが速い)。
pub const MIX_PF_MIN_TOK: usize = 64;

/// task 186: `kernels_mix_pf.cu` の関数一式。
struct MixPfKernels {
    #[allow(dead_code)]
    module: CUmodule,
    gemm: CUfunction,
}

// 生ハンドル (PfKernels と同じ規約)。
