/// 非同期の k/v 書き戻しの置き場 (スレッド局所・grow-only)。
///
/// task 553: 待ちを後ろへずらすときは 2 枚を交互に使う (1 枚だと次の
/// `begin` がまだ読んでいない転送を上書きしてしまう)。`seq` は古い順に
/// 流すための通し番号。
struct KvWbSlot {
    pin: Option<PinMem>,
    ev: Option<CUevent>,
    /// 保留中のバイト数 (k, v)。(0, 0) で保留なし。
    bytes: (usize, usize),
    /// 保留の持ち主 (層, 行数)。
    owner: (usize, usize),
    /// 積んだ順 (0 = 空)。
    seq: u64,
}

impl KvWbSlot {
    const fn new() -> Self {
        Self {
            pin: None,
            ev: None,
            bytes: (0, 0),
            owner: (0, 0),
            seq: 0,
        }
    }

    fn pending(&self) -> bool {
        self.bytes.0 > 0
    }
}

struct KvWbSc {
    slots: [KvWbSlot; 2],
    /// 次に `begin` が書くスロット (`defer` のときだけ交互に進める)。
    next: usize,
    /// `begin` の通し番号。
    seq: u64,
}

thread_local! {
    static KV_WB_SC: std::cell::RefCell<KvWbSc> = const {
        std::cell::RefCell::new(KvWbSc {
            slots: [KvWbSlot::new(), KvWbSlot::new()],
            next: 0,
            seq: 0,
        })
    };
}

/// 次に `begin` が使うスロットを選ぶ (純関数。テストで固定する)。
///
/// `defer` のときは空いている枚を選ぶ (2 枚交互)。そうでなければ 1 枚しか
/// 使わない (従来と同じく、保留があるうちは積まない)。
fn kv_wb_pick_slot(pending: [bool; 2], next: usize, defer: bool) -> Option<usize> {
    if !defer {
        return if pending[0] || pending[1] { None } else { Some(0) };
    }
    let a = next % 2;
    if !pending[a] {
        return Some(a);
    }
    let b = (next + 1) % 2;
    if !pending[b] {
        return Some(b);
    }
    None
}

/// 一番古い保留スロット。
fn kv_wb_oldest(s: &KvWbSc) -> Option<usize> {
    let mut best: Option<usize> = None;
    for (i, sl) in s.slots.iter().enumerate() {
        if !sl.pending() {
            continue;
        }
        match best {
            None => best = Some(i),
            Some(j) if sl.seq < s.slots[j].seq => best = Some(i),
            _ => {}
        }
    }
    best
}

/// 保留中の k/v 書き戻しがあるか。
pub fn pf_kv_wb_pending() -> bool {
    KV_WB_SC.with(|c| c.borrow().slots.iter().any(KvWbSlot::pending))
}

/// 一番古い保留の持ち主 `(層, 行数)`。無ければ `None`。
///
/// task 553: `DENNO_PF_KV_DEFER` では呼び出し側が「この層チャンクの分が
/// 保留に載ったか」をこれで確かめてから積むのを後ろへ回す。
pub fn pf_kv_wb_peek() -> Option<(usize, usize)> {
    KV_WB_SC.with(|c| {
        let s = c.borrow();
        kv_wb_oldest(&s).map(|i| s.slots[i].owner)
    })
}

/// 一番古い保留の長さ (k, v の要素数)。無ければ `None`。
pub fn pf_kv_wb_len() -> Option<(usize, usize)> {
    KV_WB_SC.with(|c| {
        let s = c.borrow();
        kv_wb_oldest(&s).map(|i| (s.slots[i].bytes.0 / 4, s.slots[i].bytes.1 / 4))
    })
}

/// `begin` の通し番号 (積むたびに増える)。
///
/// task 553: 呼び出し側は「この層チャンクの D2H を実際に積めたか」を前後の値で
/// 判定する (積めていないのに積むのを省くと、その層チャンクの KV が永久に
/// ホストへ降りず、長さと値がずれる)。持ち主だけの判定では、同じ層の同じ行数の
/// 保留と区別できない。
pub fn pf_kv_wb_seq() -> u64 {
    KV_WB_SC.with(|c| c.borrow().seq)
}

/// k/v を pinned へ非同期で積む (ストリーム順序。待たない)。
///
/// `Ok(false)` = 積まなかった (ゲート off / イベントが取れない / 空きが無い)。
fn pf_kv_wb_begin(
    kptr: CUdeviceptr,
    vptr: CUdeviceptr,
    k_bytes: usize,
    v_bytes: usize,
    layer: usize,
    rows: usize,
) -> Result<bool> {
    if !pf_kv_async_on() || k_bytes == 0 || v_bytes == 0 {
        return Ok(false);
    }
    let lib = lib()?;
    let (Some(create), Some(record)) = (lib.event_create, lib.event_record) else {
        return Ok(false);
    };
    let defer = pf_kv_defer_on();
    KV_WB_SC.with(|cell| -> Result<bool> {
        let mut s = cell.borrow_mut();
        let pending = [s.slots[0].pending(), s.slots[1].pending()];
        let Some(i) = kv_wb_pick_slot(pending, s.next, defer) else {
            return Ok(false);
        };
        let total = k_bytes + v_bytes;
        let need = !matches!(&s.slots[i].pin, Some(p) if p.bytes >= total);
        if need {
            s.slots[i].pin = Some(PinMem::alloc(total)?);
        }
        let base = s.slots[i].pin.as_ref().expect("確保済み").ptr as usize;
        unsafe {
            check(
                (lib.memcpy_dtoh_async)(base as *mut c_void, kptr, k_bytes, std::ptr::null_mut()),
                "cuMemcpyDtoHAsync (full k)",
            )?;
            check(
                (lib.memcpy_dtoh_async)(
                    (base + k_bytes) as *mut c_void,
                    vptr,
                    v_bytes,
                    std::ptr::null_mut(),
                ),
                "cuMemcpyDtoHAsync (full v)",
            )?;
        }
        if s.slots[i].ev.is_none() {
            let mut ev: CUevent = std::ptr::null_mut();
            if unsafe { create(&mut ev, CU_EVENT_DISABLE_TIMING) } != CUDA_SUCCESS {
                return Ok(false);
            }
            s.slots[i].ev = Some(ev);
        }
        let ev = s.slots[i].ev.expect("作成済み");
        if unsafe { record(ev, std::ptr::null_mut()) } != CUDA_SUCCESS {
            return Ok(false);
        }
        s.seq += 1;
        let seq = s.seq;
        {
            let sl = &mut s.slots[i];
            sl.bytes = (k_bytes, v_bytes);
            sl.owner = (layer, rows);
            sl.seq = seq;
        }
        if defer {
            s.next = (i + 1) % 2;
        }
        Ok(true)
    })
}

/// 保留中の転送を待って `k_out` / `v_out` へ写す。`false` = 保留なし。
pub fn pf_kv_wb_copy_into(k_out: &mut [f32], v_out: &mut [f32]) -> bool {
    KV_WB_SC.with(|cell| {
        let mut s = cell.borrow_mut();
        let Some(i) = kv_wb_oldest(&s) else {
            return false;
        };
        let (kb, vb) = s.slots[i].bytes;
        let (kf, vf) = (kb / 4, vb / 4);
        let Some(pin) = s.slots[i].pin.as_ref() else {
            s.slots[i].bytes = (0, 0);
            return false;
        };
        let base = pin.ptr as usize;
        {
            // task 505: 待ちを台帳に載せる (`full` 段の cpu 列の中身を割る)。
            let _s = crate::model::q4ledger::sub(crate::model::q4ledger::SUB_PF_KVWAIT);
            if let (Some(ev), Some(esync)) = (s.slots[i].ev, lib().ok().and_then(|l| l.event_sync)) {
                unsafe {
                    let _ = (esync)(ev);
                }
            }
        }
        s.slots[i].bytes = (0, 0);
        if k_out.len() < kf || v_out.len() < vf {
            return false;
        }
        unsafe {
            std::ptr::copy_nonoverlapping(base as *const u8, k_out.as_mut_ptr() as *mut u8, kb);
            std::ptr::copy_nonoverlapping(
                (base + kb) as *const u8,
                v_out.as_mut_ptr() as *mut u8,
                vb,
            );
        }
        true
    })
}

/// `DENNO_PF_KV_PUSH`: 保留中の k/v を **pinned のまま** `AttnCache::push` に
/// 渡す (`ks`/`vs` への写しをしない)。既定 off。
///
/// pinned から `ks`/`vs` へ写す経路は 14k で 304 ms (689 MB、約 2.3 GB/s)、
/// 3,826 で 89 ms (188 MB) のホスト時間を使っていた (lab t369a の `full` の
/// cpu 列: 239 -> 543 ms / 55 -> 144 ms。うち大半は初回タッチのページフォルト)。
/// 直接 push すれば写しは 1 回 (pinned -> キャッシュ) で済む。
/// デバイスから出るバイト列は同じなので値は不変。
pub const PF_KV_PUSH_ENV: &str = "DENNO_PF_KV_PUSH";

/// [`PF_KV_PUSH_ENV`] の解釈 (明示的な真値だけ on)。
pub(crate) fn pf_kv_push_from_value(v: Option<&str>) -> bool {
    matches!(
        v.map(|s| s.trim().to_ascii_lowercase()).as_deref(),
        Some("1") | Some("on") | Some("true") | Some("yes")
    )
}

#[cfg(test)]
static PF_KV_PUSH_FORCE: std::sync::atomic::AtomicU8 = std::sync::atomic::AtomicU8::new(0);

#[cfg(test)]
pub(crate) fn set_pf_kv_push_for_test(v: Option<bool>) {
    PF_KV_PUSH_FORCE.store(
        match v {
            None => 0,
            Some(false) => 1,
            Some(true) => 2,
        },
        std::sync::atomic::Ordering::Relaxed,
    );
}

/// pinned から直接 push するか (既定 off)。
pub fn pf_kv_push_on() -> bool {
    #[cfg(test)]
    {
        match PF_KV_PUSH_FORCE.load(std::sync::atomic::Ordering::Relaxed) {
            1 => return false,
            2 => return true,
            _ => {}
        }
    }
    static ON: OnceLock<bool> = OnceLock::new();
    *ON.get_or_init(|| pf_kv_push_from_value(std::env::var(PF_KV_PUSH_ENV).ok().as_deref()))
}

/// 保留中の k/v を **pinned のまま** `f` に渡す (コピーしない)。
///
/// `false` = 保留なし (呼び出し側は従来の `ks`/`vs` 経路へ)。
pub fn pf_kv_wb_with<F: FnOnce(&[f32], &[f32])>(f: F) -> bool {
    KV_WB_SC.with(|cell| {
        let mut s = cell.borrow_mut();
        let Some(i) = kv_wb_oldest(&s) else {
            return false;
        };
        let (kb, vb) = s.slots[i].bytes;
        let Some(pin) = s.slots[i].pin.as_ref() else {
            s.slots[i].bytes = (0, 0);
            return false;
        };
        let base = pin.ptr as usize;
        // task 505: 待ちを台帳に載せる (`full` 段の cpu 列の中身を割る)。
        {
            let _s = crate::model::q4ledger::sub(crate::model::q4ledger::SUB_PF_KVWAIT);
            if let (Some(ev), Some(esync)) = (s.slots[i].ev, lib().ok().and_then(|l| l.event_sync)) {
                unsafe {
                    let _ = (esync)(ev);
                }
            }
        }
        s.slots[i].bytes = (0, 0);
        // SAFETY: pinned は `kb + vb` バイト以上あり、転送はイベントで完了済み。
        let k = unsafe { std::slice::from_raw_parts(base as *const f32, kb / 4) };
        let v = unsafe { std::slice::from_raw_parts((base + kb) as *const f32, vb / 4) };
        f(k, v);
        true
    })
}

/// 保留を捨てる (デバイスのコピー完了は待つ)。`false` = 保留なし。
pub fn pf_kv_wb_discard() -> bool {
    KV_WB_SC.with(|cell| {
        let mut s = cell.borrow_mut();
        let mut any = false;
        for i in 0..s.slots.len() {
            if !s.slots[i].pending() {
                continue;
            }
            any = true;
            if let (Some(ev), Some(esync)) = (s.slots[i].ev, lib().ok().and_then(|l| l.event_sync)) {
                unsafe {
                    let _ = (esync)(ev);
                }
            }
            s.slots[i].bytes = (0, 0);
        }
        any
    })
}

/// `pf_full_out` がミラーから読める状態か (= ホスト KV を読まない)。
///
/// `pf_full_qkv` が記録した `mir` が一致し、かつミラーが生きているときだけ
/// `true`。呼び出し側はこのときだけ `AttnCache::push` を後ろへ回してよい。
/// 偽を返したときは従来どおり「ホスト KV を先に積む」経路へ戻る (安全側)。
pub fn pf_full_mirror_direct(
    cache_id: u64,
    layer: usize,
    gen: u64,
    t_total: usize,
    kv_dim: usize,
) -> bool {
    if !pf_kv_async_on() {
        return false;
    }
    let staged = PF2_DEV.with(|c| c.borrow().mir);
    let direct = matches!(
        staged,
        Some((cid, li, g, tt)) if cid == cache_id && li == layer && g == gen && tt == t_total
    );
    direct && q4_attn_mirror_ready(cache_id, kv_dim, layer, gen, t_total).is_some()
}

/// task 172: full 層 1 チャンクの後半 (attention → 出力ゲート → 出力投影)。
///
/// `pf_full_qkv` がデバイスに残した q / qg を使う。K/V はミラーから読む
/// (`k_cpu` / `v_cpu` は台帳を進めるためだけに渡す。既に積んであるので転送は起きない)。
/// 前提の形。`keep_dev` のときは `out` を書かない (`out` は空でよい)。
#[allow(clippy::too_many_arguments)]
pub fn pf_full_out(
    cache_id: u64,
    n_layer: usize,
    layer: usize,
    gen: u64,
    t_total: usize,
    pos0: usize,
    nt: usize,
    heads: usize,
    group: usize,
    dh: usize,
    kv_dim: usize,
    scale: f32,
    k_cpu: &[f32],
    v_cpu: &[f32],
    wo: PfLin<'_>,
    e: usize,
    // task 183: 融合 qkv 経路のとき true。gate を `d.qkv` の
    // `gate_off` 行から `gate_ld` ストライドで読む (pf3 のカーネル)。
    fused_gate: bool,
    gate_off: usize,
    gate_ld: usize,
    // task 308: 層出力をデバイスに残す (D2H しない)。直後の combine が
    // `pf_attn_dev_store` の記録を読む (`DENNO_PF_FULL_DEVRES`)。
    keep_dev: bool,
    out: &mut [f32],
) -> bool {
    pf2_set_nt(nt);
    let qd = heads * dh;
    // task 369: ミラーへ直書きできていればここでホスト KV を読まない。
    // `DENNO_PF_KV_ASYNC` は k/v の D2H を `AttnCache::push` の直前まで遅らせる
    // ので、そのときはホスト KV の長さを要求しない (`k_cpu` はまだ短い)。
    let staged_mir = PF2_DEV.with(|c| c.borrow().mir);
    let mirror_direct = matches!(
        staged_mir,
        Some((cid, li, g, tt)) if cid == cache_id && li == layer && g == gen && tt == t_total
    );
    let ok_shape = nt >= PF2_MIN_ROWS
        && dh >= ATTN_PF_BQ
        && dh <= 1024
        && heads > 0
        && group > 0
        && heads % group == 0
        && kv_dim == (heads / group) * dh
        && pos0 + nt == t_total
        && (mirror_direct || k_cpu.len() >= t_total * kv_dim)
        && (mirror_direct || v_cpu.len() >= t_total * kv_dim)
        && wo.k == qd
        && wo.n == e
        && (keep_dev || out.len() == nt * e);
    if !ok_shape {
        pf2_note(1);
        return false;
    }
    if !attn_prefill_shape_ok(nt, dh, t_total, ATTN_Q4_PF_MIN_ROWS) {
        pf2_note(1);
        return false;
    }
    let Some(kr) = pf2_kernels() else {
        pf2_note(1);
        return false;
    };
    let Some(ctx) = shared_ctx() else {
        pf2_note(1);
        return false;
    };
    if ctx.make_current().is_err() {
        pf2_note(1);
        return false;
    }
    let Some((pw, pw_k)) = pf_weight(wo, false) else {
        pf2_note(1);
        return false;
    };
    let r = (|| -> Result<()> {
        // task 181: `pf_full_qkv` がミラーへ直接書いていれば H2D をしない
        // (`DENNO_PF_MIRROR_DELTA`)。台帳が一致しないときは従来の差分 H2D。
        // task 369: 判定は `ok_shape` の前へ出した (上の `mirror_direct`)。
        let (kptr, vptr) = match mirror_direct {
            true => match q4_attn_mirror_ready(cache_id, kv_dim, layer, gen, t_total) {
                Some(p) => p,
                // 台帳は合うがバッファが無い (LRU で落ちた等) → 従来経路で作り直す。
                None => {
                    // task 369: `DENNO_PF_KV_ASYNC` で push を後ろへ回している
                    // ときはホスト KV がまだ短い。短いままで作り直すと足りない
                    // 行を積むので、ここで諦めて呼び出し側を従来経路へ戻す
                    // (`ok_shape` の長さ検査はミラー直書きのとき外している)。
                    if k_cpu.len() < t_total * kv_dim || v_cpu.len() < t_total * kv_dim {
                        bail!("full out: ミラーが落ちた (ホスト KV も未確定)");
                    }
                    q4_attn_mirror_prepare(
                        cache_id, n_layer, kv_dim, layer, gen, t_total, k_cpu, v_cpu, true,
                    )?
                }
            },
            false => q4_attn_mirror_prepare(
                cache_id, n_layer, kv_dim, layer, gen, t_total, k_cpu, v_cpu, true,
            )?,
        };
        PF2_DEV.with(|cell| -> Result<()> {
            let mut d = cell.borrow_mut();
            pf2_ensure(&mut d.att, nt * qd * 4)?;
            pf2_ensure(&mut d.o, nt * e * 4)?;
            // task 183: 融合 qkv 経路では gate が `d.qkv` の中にあるので、qg は
            // 要らない (q は norm+rope 済みの詰めたバッファ)。
            let qb = d.q.as_ref().ok_or_else(|| anyhow!("q が無い"))?;
            if fused_gate {
                let qkvb = d.qkv.as_ref().ok_or_else(|| anyhow!("qkv が無い"))?;
                if qkvb.bytes() < nt * gate_ld * 4 || qb.bytes() < nt * qd * 4 {
                    bail!("q / qkv の作業域が小さい (融合 qkv を先に呼ぶこと)");
                }
            } else {
                let qgb = d.qg.as_ref().ok_or_else(|| anyhow!("qg が無い"))?;
                if qgb.bytes() < nt * 2 * qd * 4 || qb.bytes() < nt * qd * 4 {
                    bail!("q / qg の作業域が小さい (qkv を先に呼ぶこと)");
                }
            }
            let attb = d.att.as_ref().expect("ensure 済み");
            let ob = d.o.as_ref().expect("ensure 済み");
            // 1. attention (K/V はミラー、q はデバイス)
            {
                // task 222: v2 カーネル (スコアを bf16 mma) が使える形ならそちら。
                // 形は dh == 256 固定 (スレッド配置)・PTX があること・ゲート on。
                // task 230: v3 (PV も bf16 mma・head 優先グリッド) が使えるなら
                // 最優先。どれも使えなければ従来 (v1) へ fail closed。
                let use_v3 = pf_attn_v3_on()
                    && dh == ATTN_PF3_DH
                    && qd == heads * dh
                    && !ctx.f_attn_pf3.is_null();
                let use_v2 = !use_v3
                    && pf_attn_tc_on()
                    && dh == ATTN_PF2_DH
                    && qd == heads * dh
                    && !ctx.f_attn_pf2.is_null();
                let (mut qp, mut kp, mut vp, mut ap) =
                    (qb.ptr(), kptr, vptr, attb.ptr());
                // task 465: K/V を bf16 にした v4 が撃てるなら最優先。撃てなければ
                // v3 -> v2 -> 従来へ fail closed (値はどれも同じ丸め順)。
                let v4kv = if dh == ATTN_PF4_DH && qd == heads * dh && nt >= ATTN_PF4_BQ {
                    pf_attn_v4_kv_prepare(kptr, vptr, pos0, nt, t_total, kv_dim)
                } else {
                    None
                };
                if let Some((kb, vb)) = v4kv {
                    kp = kb;
                    vp = vb;
                }
                let (mut heads_c, mut n_c, mut pos0_c) =
                    (heads as c_int, nt as c_int, pos0 as c_int);
                let (mut kvd_c, mut t_c, mut group_c, mut dh_c) = (
                    kv_dim as c_int,
                    t_total as c_int,
                    group as c_int,
                    dh as c_int,
                );
                let mut scale_c = scale;
                let mut args = [
                    &mut qp as *mut _ as *mut c_void,
                    &mut kp as *mut _ as *mut c_void,
                    &mut vp as *mut _ as *mut c_void,
                    &mut ap as *mut _ as *mut c_void,
                    &mut heads_c as *mut _ as *mut c_void,
                    &mut n_c as *mut _ as *mut c_void,
                    &mut pos0_c as *mut _ as *mut c_void,
                    &mut kvd_c as *mut _ as *mut c_void,
                    &mut t_c as *mut _ as *mut c_void,
                    &mut group_c as *mut _ as *mut c_void,
                    &mut dh_c as *mut _ as *mut c_void,
                    &mut scale_c as *mut _ as *mut c_void,
                ];
                let v4f = if v4kv.is_some() { pf_attn_pf4_kernels() } else { None };
                if let Some(fns) = v4f {
                    unsafe {
                        ctx.launch_async(
                            fns.attn,
                            (heads as u32, nt.div_ceil(ATTN_PF4_BQ) as u32, 1),
                            (ATTN_PF4_THREADS as u32, 1, 1),
                            ATTN_PF4_SMEM_BYTES as u32,
                            &mut args,
                        )?;
                    }
                } else if use_v3 {
                    unsafe {
                        ctx.launch_async(
                            ctx.f_attn_pf3,
                            (heads as u32, nt.div_ceil(ATTN_PF3_BQ) as u32, 1),
                            (dh as u32, 1, 1),
                            ATTN_PF3_SMEM_BYTES as u32,
                            &mut args,
                        )?;
                    }
                } else if use_v2 {
                    unsafe {
                        ctx.launch_async(
                            ctx.f_attn_pf2,
                            (nt.div_ceil(ATTN_PF2_BQ) as u32, heads as u32, 1),
                            (dh as u32, 1, 1),
                            ATTN_PF2_SMEM_BYTES as u32,
                            &mut args,
                        )?;
                    }
                } else {
                    unsafe {
                        ctx.launch_async(
                            ctx.f_attn_pf,
                            (nt.div_ceil(ATTN_PF_BQ) as u32, heads as u32, 1),
                            (dh as u32, 1, 1),
                            (attn_pf_sh_f(dh) * 4) as u32,
                            &mut args,
                        )?;
                    }
                }
            }
            // 2. 出力ゲート (att *= sigmoid(gate))
            if fused_gate {
                // task 183: 融合バッファ (ld = 融合 1 本の行数) から読む。
                let kr3 = pf3_kernels().ok_or_else(|| anyhow!("pf3 のカーネルが無い"))?;
                let qkvb = d.qkv.as_ref().ok_or_else(|| anyhow!("qkv が無い"))?;
                let (mut ap, mut gptr) =
                    (attb.ptr(), qkvb.ptr() + (gate_off * 4) as CUdeviceptr);
                let (mut h_c, mut dh_c, mut ld_c) =
                    (heads as c_int, dh as c_int, gate_ld as c_int);
                let mut args = [
                    &mut ap as *mut _ as *mut c_void,
                    &mut gptr as *mut _ as *mut c_void,
                    &mut h_c as *mut _ as *mut c_void,
                    &mut dh_c as *mut _ as *mut c_void,
                    &mut ld_c as *mut _ as *mut c_void,
                ];
                unsafe {
                    ctx.launch_async(
                        kr3.gate_mul,
                        (nt as u32, heads as u32, 1),
                        (dh as u32, 1, 1),
                        0,
                        &mut args,
                    )?;
                }
            } else {
                let qgb = d.qg.as_ref().ok_or_else(|| anyhow!("qg が無い"))?;
                let (mut ap, mut gptr) = (attb.ptr(), qgb.ptr());
                let (mut h_c, mut dh_c) = (heads as c_int, dh as c_int);
                let mut args = [
                    &mut ap as *mut _ as *mut c_void,
                    &mut gptr as *mut _ as *mut c_void,
                    &mut h_c as *mut _ as *mut c_void,
                    &mut dh_c as *mut _ as *mut c_void,
                ];
                unsafe {
                    ctx.launch_async(
                        kr.gate_mul,
                        (nt as u32, heads as u32, 1),
                        (dh as u32, 1, 1),
                        0,
                        &mut args,
                    )?;
                }
            }
            // 3. 出力投影 (同期しない) → 最後に 1 回だけ待って 1 回で戻す
            pf2_gemm(ctx, pw, pw_k, attb.ptr(), ob.ptr(), nt, qd, e)?;
            // task 334: `DENNO_PF_ATTN_NOSYNC` なら待たない (直後の D2H / combine は
            // 同じストリーム)。
            pf_chain_sync(ctx)?;
            // task 308: 層出力をデバイスに残す。直後の combine が同じポインタを
            // 読むので、D2H (層出力) と combine の H2D が 1 往復ぶん消える
            // (`DENNO_PF_FULL_DEVRES`。呼び出し側が keep_dev を立てたときだけ)。
            if keep_dev {
                pf_attn_dev_store(ob.ptr(), nt, e);
                return Ok(());
            }
            // task 181: `DENNO_PF_D2H_DIRECT` は中間 Vec を作らない (値は同じ)。
            if pf_d2h_direct_on() {
                ob.to_slice(&mut out[..nt * e])?;
            } else {
                let got: Vec<f32> = ob.to_vec(nt * e)?;
                out.copy_from_slice(&got);
            }
            Ok(())
        })
    })();
    // task 181: 直接書きの印は 1 チャンク限り (次のチャンクへ持ち越さない)。
    PF2_DEV.with(|c| c.borrow_mut().mir = None);
    match r {
        Ok(()) => {
            pf2_note(0);
            true
        }
        Err(e) => {
            pf2_warn(&format!("full out: {e:#}"));
            pf2_note(1);
            false
        }
    }
}

// ---------------------------------------------------------------------------
// shared expert (gate → silu*up → down) をデバイスで閉じる
// ---------------------------------------------------------------------------

/// task 172: shared expert の 3 射影を 1 チャンクぶんまとめてデバイスで回す。
///
/// `out` には `down_shexp(silu(gate_shexp(x)) * up_shexp(x))` を書く。ゲート
/// (`gate_inp_shexp`) と sigmoid の足し込みは呼び出し側が従来どおり CPU でやる
/// (重みが 1 行なので GPU に載せる意味が無い)。
#[allow(clippy::too_many_arguments)]
pub fn pf_shared(
    x: &[f32],
    nt: usize,
    e: usize,
    sff: usize,
    gate: PfLin<'_>,
    up: PfLin<'_>,
    down: PfLin<'_>,
    out: &mut [f32],
) -> bool {
    if x.len() != nt.saturating_mul(e) {
        pf2_note(3);
        return false;
    }
    pf_shared_impl(SharedIn::Host(x), nt, e, sff, gate, up, down, SharedOut::Host(out))
}

/// task 209: 入力 `x` が既にデバイスにある版 (`[nt][e]` f32)。
///
/// router と同じく、`pf_mix` の出力 (`mixed`) をそのまま読む。ホスト版と
/// **同じカーネル・同じ入力バイト列**なので値は変わらない。
pub fn pf_shared_dev(
    dev_x: CUdeviceptr,
    nt: usize,
    e: usize,
    sff: usize,
    gate: PfLin<'_>,
    up: PfLin<'_>,
    down: PfLin<'_>,
    out: &mut [f32],
) -> bool {
    if dev_x == 0 {
        pf2_note(3);
        return false;
    }
    pf_shared_impl(SharedIn::Dev(dev_x), nt, e, sff, gate, up, down, SharedOut::Host(out))
}

/// task 233: 入力も出力もデバイスにある版 (層優先 prefill の shared expert)。
///
/// 出力は `[nt][e]` f32。MoE の作業域の「共有 expert の行」へ直接書く
/// (呼び出し側は [`pf_moe_shared_tail`] のポインタを渡す)。
#[allow(clippy::too_many_arguments)]
pub fn pf_shared_dev_to(
    dev_x: CUdeviceptr,
    nt: usize,
    e: usize,
    sff: usize,
    gate: PfLin<'_>,
    up: PfLin<'_>,
    down: PfLin<'_>,
    out_dev: CUdeviceptr,
) -> bool {
    if dev_x == 0 || out_dev == 0 {
        pf2_note(3);
        return false;
    }
    pf_shared_impl(
        SharedIn::Dev(dev_x),
        nt,
        e,
        sff,
        gate,
        up,
        down,
        SharedOut::Dev(out_dev),
    )
}

/// shared 連鎖の入力の置き場所。
enum SharedIn<'a> {
    Host(&'a [f32]),
    Dev(CUdeviceptr),
}

/// shared 連鎖の出力の置き場所。
enum SharedOut<'a> {
    Host(&'a mut [f32]),
    Dev(CUdeviceptr),
}

impl SharedOut<'_> {
    fn host_len(&self) -> Option<usize> {
        match self {
            SharedOut::Host(o) => Some(o.len()),
            SharedOut::Dev(_) => None,
        }
    }
}

#[allow(clippy::too_many_arguments)]
fn pf_shared_impl(
    src: SharedIn<'_>,
    nt: usize,
    e: usize,
    sff: usize,
    gate: PfLin<'_>,
    up: PfLin<'_>,
    down: PfLin<'_>,
    out: SharedOut<'_>,
) -> bool {
    pf2_set_nt(nt);
    let ok_shape = nt >= PF2_MIN_ROWS
        && e > 0
        && sff > 0
        && out.host_len().map_or(true, |n| n == nt * e)
        && gate.k == e
        && gate.n == sff
        && up.k == e
        && up.n == sff
        && down.k == sff
        && down.n == e;
    if !ok_shape {
        pf2_note(3);
        return false;
    }
    let Some(ctx) = shared_ctx() else {
        pf2_note(3);
        return false;
    };
    if ctx.make_current().is_err() {
        pf2_note(3);
        return false;
    }
    let (Some((pg, pg_k)), Some((pu, pu_k)), Some((pd, pd_k))) =
        (pf_weight(gate, false), pf_weight(up, false), pf_weight(down, false))
    else {
        pf2_note(3);
        return false;
    };
    let r = PF2_DEV.with(|cell| -> Result<()> {
        let mut d = cell.borrow_mut();
        // task 257: shared expert の作業域もプールから (タイルの行数で足りる)。
        ensure_region(&mut d.x, crate::model::pf_pool::R::ShX, 0, nt * e * 4)?;
        ensure_region(&mut d.ga, crate::model::pf_pool::R::ShGa, 0, nt * sff * 4)?;
        ensure_region(&mut d.gu, crate::model::pf_pool::R::ShGu, 0, nt * sff * 4)?;
        // task 233: デバイス出力のときは `sh` (ホストへ戻すための中間) を確保しない。
        if matches!(out, SharedOut::Host(_)) {
            ensure_region(&mut d.sh, crate::model::pf_pool::R::ShSh, 0, nt * e * 4)?;
        }
        // swiglu の出力は x の領域へ (gate/up を撃ったあとの x はもう不要。
        // ga を in-place で上書きすると別名になるので避ける)。
        let xb = d.x.as_ref().expect("ensure 済み");
        let gab = d.ga.as_ref().expect("ensure 済み");
        let gub = d.gu.as_ref().expect("ensure 済み");
        let swb = d.x.as_ref().expect("ensure 済み");
        // task 209: デバイス入力のときは H2D をせず、その領域を直接読む
        // (swiglu の出力は別の `d.x` に書くので入力は壊れない)。
        let xp = match src {
            SharedIn::Host(x) => {
                xb.copy_from(x)?;
                xb.ptr()
            }
            SharedIn::Dev(p) => p,
        };
        // task 183: `DENNO_PF_TC_SHARED2` が on なら BM=64 のカーネルで撃つ。
        pf2_gemm_shared(ctx, pg, pg_k, xp, gab.ptr(), nt, e, sff)?;
        pf2_gemm_shared(ctx, pu, pu_k, xp, gub.ptr(), nt, e, sff)?;
        // swiglu: x = silu(ga) * gu (elem の既存カーネル。CPU と同じ式)
        {
            let (mut gp, mut up_p, mut op) = (gab.ptr(), gub.ptr(), swb.ptr());
            let mut total = (nt * sff) as c_int;
            let grid = ((nt * sff).div_ceil(256)) as u32;
            let mut args = [
                &mut gp as *mut _ as *mut c_void,
                &mut up_p as *mut _ as *mut c_void,
                &mut op as *mut _ as *mut c_void,
                &mut total as *mut _ as *mut c_void,
            ];
            unsafe {
                ctx.launch_async(ctx.f_swiglu, (grid, 1, 1), (256, 1, 1), 0, &mut args)?;
            }
        }
        // task 233: デバイス出力のときは down の結果を**そのまま**宛先へ書く
        // (置き場へ D2D で写し直さない)。ホスト出力は従来どおり `d.sh` 経由。
        let dst = match &out {
            SharedOut::Host(_) => d.sh.as_ref().expect("ensure 済み").ptr(),
            SharedOut::Dev(p) => *p,
        };
        pf2_gemm_shared(ctx, pd, pd_k, swb.ptr(), dst, nt, sff, e)?;
        // task 334: `DENNO_PF_ATTN_NOSYNC` なら待たない (ホスト出力は同期 D2H、
        // デバイス出力は同じストリームの後続が読む)。
        pf_chain_sync(ctx)?;
        if let SharedOut::Host(o) = out {
            let shb = d.sh.as_ref().expect("ensure 済み");
            // task 181: ホストへは**呼び出し側のバッファへ直接**戻す
            // (`DENNO_PF_D2H_DIRECT`)。`to_vec` + `copy_from_slice` は毎層 5 MB の
            // Vec 確保 (= ページフォルト) と memcpy をもう 1 回する。
            if pf_d2h_direct_on() {
                shb.to_slice(&mut o[..nt * e])?;
            } else {
                let got: Vec<f32> = shb.to_vec(nt * e)?;
                o.copy_from_slice(&got);
            }
        }
        Ok(())
    });
    match r {
        Ok(()) => {
            pf2_note(2);
            true
        }
        Err(e) => {
            pf2_warn(&format!("shared: {e:#}"));
            pf2_note(3);
            false
        }
    }
}

// ---------------------------------------------------------------------------
// PLE の key / value 射影をデバイスで回す
// ---------------------------------------------------------------------------

/// task 172: PLE の key / value 射影 (層 1 の 1 チャンク) を GPU で回す。
///
/// 表の pread は SSD なので CPU のまま (gather は呼び出し側)。ここは
/// `gemv_batch_cpu` を置き換えるだけで、値は gemv_batch_cpu と同じ行独立の和。
pub fn pf_ple_proj(
    x: &[f32],
    nt: usize,
    e: usize,
    key: PfLin<'_>,
    value: PfLin<'_>,
    key_out: &mut [f32],
    value_out: &mut [f32],
) -> bool {
    pf2_set_nt(nt);
    let ok_shape = nt > 0
        && e > 0
        && x.len() == nt * e
        && key.k == e
        && key_out.len() == nt * key.n
        && value.k == e
        && value_out.len() == nt * value.n;
    if !ok_shape {
        pf2_note(5);
        return false;
    }
    let Some(ctx) = shared_ctx() else {
        pf2_note(5);
        return false;
    };
    if ctx.make_current().is_err() {
        pf2_note(5);
        return false;
    }
    // 量子型 (Q8_0 など) だけを受ける。F32 / BF16 は pf_weight が VRAM に
    // 載せてしまうので、形の段階で断る (このモデルの ple_key/ple_value は F32)。
    if !matches!(key.ty, crate::kquant::GgmlType::Q8_0 | crate::kquant::GgmlType::Q5_1 | crate::kquant::GgmlType::Q4K | crate::kquant::GgmlType::Q5K)
        || !matches!(value.ty, crate::kquant::GgmlType::Q8_0 | crate::kquant::GgmlType::Q5_1 | crate::kquant::GgmlType::Q4K | crate::kquant::GgmlType::Q5K)
    {
        pf2_note(5);
        return false;
    }
    let (Some((pk, pk_k)), Some((pv, pv_k))) =
        (pf_weight(key, false), pf_weight(value, false))
    else {
        pf2_note(5);
        return false;
    };
    let r = PF2_DEV.with(|cell| -> Result<()> {
        let mut d = cell.borrow_mut();
        pf2_ensure(&mut d.x, nt * e * 4)?;
        pf2_ensure(&mut d.o, nt * (key.n + value.n) * 4)?;
        let xb = d.x.as_ref().expect("ensure 済み");
        let ob = d.o.as_ref().expect("ensure 済み");
        xb.copy_from(x)?;
        pf2_gemm(ctx, pk, pk_k, xb.ptr(), ob.ptr(), nt, e, key.n)?;
        let kn = key.n;
        pf2_gemm(ctx, pv, pv_k, xb.ptr(), ob.ptr() + (nt * kn * 4) as CUdeviceptr, nt, e, value.n)?;
        ctx.sync()?;
        let kk: Vec<f32> = ob.to_vec(nt * kn)?;
        key_out.copy_from_slice(&kk);
        let vv: Vec<f32> = ob.view_at(nt * kn * 4, nt * value.n * 4).to_vec(nt * value.n)?;
        value_out.copy_from_slice(&vv);
        Ok(())
    });
    match r {
        Ok(()) => {
            pf2_note(4);
            true
        }
        Err(e) => {
            pf2_warn(&format!("ple proj: {e:#}"));
            pf2_note(5);
            false
        }
    }
}

/// task 138: `DENNO_MIX_UP_REDUCE` の値を解釈する (純関数・テスト用)。
/// **既定 on** で、明示的な偽値だけ切る (切ると逐次版 = 従来の丸め順)。
fn mix_up_reduce_from_value(v: Option<&str>) -> bool {
    match v {
        Some(s) => !matches!(
            s.trim().to_ascii_lowercase().as_str(),
            "0" | "off" | "false" | "no"
        ),
        None => true,
    }
}

/// task 138: チェーン経路の up GEMV に並列リダクション版 (`dno_matvec_f32_r`)
/// を使う (`DENNO_MIX_UP_REDUCE`、**既定 on**。`=0` で逐次版に戻る)。
/// up の形は k < n (320 x 5120) で、逐次版は 1 ブロック 1 スレッドのため
/// 並列度が n 側にしか無い。lab t138b の実測で mix の同期待ちが
/// 6.42 → 4.65 ms/tok になった (丸め順が変わるが決定論は保つ)。
fn mix_up_reduce_enabled() -> bool {
    static ON: OnceLock<bool> = OnceLock::new();
    *ON.get_or_init(|| {
        mix_up_reduce_from_value(std::env::var("DENNO_MIX_UP_REDUCE").ok().as_deref())
    })
}

/// task 138: hc mix (BF16) の **down → lo_apply → up を 1 回の同期に畳む**。
///
/// 従来は down GEMV (H2D + kernel + D2H + sync)、ホストで `hc_lo_apply`、
/// up GEMV (H2D + kernel + D2H + sync) の 2 往復だった。down の出力
/// (`low_rank` 本) はそのまま lo_apply の入力なので、silu を畳んだ
/// [`matvec_f32_r_silu`] (`dno_matvec_f32_r_silu`) で down を書き、その出力を
/// デバイス上で up に渡す。丸めは GPU 経路の現行と同じ (dno_expf は glibc expf
/// のビット一致実装) なので logits は従来経路とビット一致する。
///
/// 戻り値 `false` = 従来の 2 往復経路を使うこと (GPU 無効・PTX 未収録・形状不一致・
/// 確保失敗・実行エラー)。`x` は `[k1]`、`out` は `[n2]`。
#[allow(clippy::too_many_arguments)]
pub fn maybe_gpu_mix_bf16_chain_into(
    down_uid: u64,
    down_bytes: &[u8],
    k1: usize,
    n1: usize,
    up_uid: u64,
    up_bytes: &[u8],
    _k2: usize,
    n2: usize,
    inv_hc: f32,
    x: &[f32],
    out: &mut [f32],
) -> bool {
    use std::sync::atomic::Ordering as AO;
    if !cuda_enabled() || MIX_GPU_BROKEN.load(AO::Relaxed) {
        return false;
    }
    if k1 == 0
        || n1 == 0
        || n2 == 0
        || n1 != _k2
        || x.len() != k1
        || out.len() != n2
        || k1 < n1
        || down_bytes.len() != k1.saturating_mul(n1).saturating_mul(2)
        || up_bytes.len() != n1.saturating_mul(n2).saturating_mul(2)
        || k1 > i32::MAX as usize
        || n1 > i32::MAX as usize
        || n2 > i32::MAX as usize
    {
        return false;
    }
    let Some(ctx) = shared_ctx() else {
        return false;
    };
    if let Err(e) = ctx.make_current() {
        mix_gpu_broken_once(&format!("cuCtxSetCurrent: {e:#}"));
        return false;
    }
    // down は silu 込みの並列リダクション版。未収録 PTX は従来経路へ (ラッチしない)。
    // task 152: BF16 カーネルがあれば重みは BF16 のまま (常駐が半分)。
    let want_bf16 = mix_bf16_enabled() && matvec_bf16_r_silu_fn(ctx).is_some();
    let f_down = if want_bf16 {
        matvec_bf16_r_silu_fn(ctx)
    } else {
        matvec_f32_r_silu_fn(ctx)
    };
    let Some(f_down) = f_down else {
        return false;
    };
    let up_reduce = mix_up_reduce_enabled();
    let f_up = if up_reduce {
        if want_bf16 {
            matvec_bf16_r_fn(ctx)
        } else {
            matvec_f32_r_fn(ctx)
        }
    } else if want_bf16 {
        matvec_bf16_fn(ctx)
    } else {
        matvec_f32_fn(ctx)
    };
    let Some(f_up) = f_up else {
        return false;
    };
    let up_thr: u32 = if up_reduce { 256 } else { 1 };
    let wp1 = match mix_gpu_weight(down_uid, down_bytes, k1, n1, want_bf16) {
        Ok(w) => w.ptr,
        Err(e) => {
            mix_gpu_broken_once(&format!("down 重みの常駐に失敗: {e:#}"));
            return false;
        }
    };
    let wp2 = match mix_gpu_weight(up_uid, up_bytes, n1, n2, want_bf16) {
        Ok(w) => w.ptr,
        Err(e) => {
            mix_gpu_broken_once(&format!("up 重みの常駐に失敗: {e:#}"));
            return false;
        }
    };
    let lib = match lib() {
        Ok(l) => l,
        Err(e) => {
            mix_gpu_broken_once(&format!("CUDA lib load failed: {e:#}"));
            return false;
        }
    };
    let r = MIX_GPU_SC.with(|cell| -> Result<()> {
        let mut s = cell.borrow_mut();
        let MixGpuScratch {
            x: dx,
            lo: dlo,
            out: dout,
            mixed: _,
            hx,
            ho,
            ..
        } = &mut *s;
        let bytes_x = k1 * 4;
        let bytes_lo = n1 * 4;
        let bytes_out = n2 * 4;
        Scratch::ensure(dx, bytes_x)?;
        Scratch::ensure(dlo, bytes_lo)?;
        Scratch::ensure(dout, bytes_out)?;
        Scratch::ensure_pin(hx, bytes_x)?;
        Scratch::ensure_pin(ho, bytes_out)?;
        let (dx, dlo, dout) = (
            dx.as_ref().unwrap(),
            dlo.as_ref().unwrap(),
            dout.as_ref().unwrap(),
        );
        let (hx, ho) = (hx.as_mut().unwrap(), ho.as_mut().unwrap());
        hx.as_mut_slice::<f32>()[..k1].copy_from_slice(x);
        unsafe {
            check(
                (lib.memcpy_htod_async)(
                    dx.ptr(),
                    hx.ptr as *const c_void,
                    bytes_x,
                    std::ptr::null_mut(),
                ),
                "cuMemcpyHtoDAsync (mix chain)",
            )?;
            // down + lo_apply (silu 込み) → lo はデバイスに残る。
            let (mut ph, mut pw, mut po) = (dx.ptr(), wp1, dlo.ptr());
            let (mut kc, mut nc) = (k1 as c_int, n1 as c_int);
            let mut invc = inv_hc;
            let mut args = [
                &mut ph as *mut _ as *mut c_void,
                &mut pw as *mut _ as *mut c_void,
                &mut po as *mut _ as *mut c_void,
                &mut kc as *mut _ as *mut c_void,
                &mut nc as *mut _ as *mut c_void,
                &mut invc as *mut _ as *mut c_void,
            ];
            ctx.launch_async(f_down, (n1 as u32, 1, 1), (256, 1, 1), 0, &mut args)?;
            // up: 入力は lo_apply 済みの lo (同じ既定ストリームなので順序保証)。
            let (mut ph2, mut pw2, mut po2) = (dlo.ptr(), wp2, dout.ptr());
            let (mut kc2, mut nc2) = (n1 as c_int, n2 as c_int);
            let mut args2 = [
                &mut ph2 as *mut _ as *mut c_void,
                &mut pw2 as *mut _ as *mut c_void,
                &mut po2 as *mut _ as *mut c_void,
                &mut kc2 as *mut _ as *mut c_void,
                &mut nc2 as *mut _ as *mut c_void,
            ];
            ctx.launch_async(
                f_up,
                (n2 as u32, 1, 1),
                (up_thr, 1, 1),
                0,
                &mut args2,
            )?;
            check(
                (lib.memcpy_dtoh_async)(ho.ptr, dout.ptr(), bytes_out, std::ptr::null_mut()),
                "cuMemcpyDtoHAsync (mix chain)",
            )?;
            crate::prof::mark_d2h_src(crate::prof::D2H_SRC_LINEAR);
        }
        ctx.sync()?;
        out.copy_from_slice(&ho.as_slice::<f32>()[..n2]);
        Ok(())
    });
    match r {
        Ok(()) => {
            set_last_linear_ran_on_gpu(true);
            true
        }
        Err(e) => {
            mix_gpu_broken_once(&format!("hc mix chain failed: {e:#}"));
            false
        }
    }
}

/// task 150: `dno_hc_mixed_f32` (hc_mixed の device 版) を PTX から取る。
/// 未収録 (旧 PTX) は `None` を返し、呼び出し側は従来経路へ落ちる (ラッチしない)。
fn hc_mixed_f32_fn(ctx: &CudaCtx) -> Option<CUfunction> {
    struct HcMixedFn(CUfunction);
    unsafe impl Send for HcMixedFn {}
    unsafe impl Sync for HcMixedFn {}
    static FN: OnceLock<Option<HcMixedFn>> = OnceLock::new();
    FN.get_or_init(|| {
        let lib = lib().ok()?;
        let mut f: CUfunction = std::ptr::null_mut();
        let r = unsafe {
            (lib.module_get_function)(
                &mut f,
                ctx.module_elem,
                b"dno_hc_mixed_f32\0".as_ptr() as *const c_char,
            )
        };
        if r != 0 {
            None
        } else {
            Some(HcMixedFn(f))
        }
    })
    .as_ref()
    .map(|h| h.0)
}

/// task 150: hc mix の **down → lo_apply → up → hc_mixed** を 1 回の同期に畳む。
///
/// task 138 の [`maybe_gpu_mix_bf16_chain_into`] は up までを GPU で閉じ、`hc_mixed`
/// (ストリームごとの sigmoid と加算) はホストで計算していた。ここでは `hc_mixed` も
/// device の `dno_hc_mixed_f32` で閉じ、ホストへ返すのは `mixed[e]` だけにする
/// (従来は `gate[hc*e]` を返してホストで計算 = D2H も 4 倍)。
///
/// 丸めは CPU の `hyper::hc_mixed_into_par` と同一 (dno_expf + `__f*_rn`・要素独立)
/// なので値はビット一致する。戻り値 `false` = 従来経路を使うこと (GPU 無効・PTX
/// 未収録・形状不一致・確保失敗・実行エラー)。
///
/// `x` は `[k1]` (= `[hc][e]`)、`out` は `[e]`。
#[allow(clippy::too_many_arguments)]
pub fn maybe_gpu_mix_bf16_chain2_into(
    down_uid: u64,
    down_bytes: &[u8],
    k1: usize,
    n1: usize,
    up_uid: u64,
    up_bytes: &[u8],
    k2: usize,
    n2: usize,
    inv_hc: f32,
    e: usize,
    x: &[f32],
    out: &mut [f32],
) -> bool {
    use std::sync::atomic::Ordering as AO;
    if !cuda_enabled() || MIX_GPU_BROKEN.load(AO::Relaxed) {
        return false;
    }
    if k1 == 0
        || n1 == 0
        || n2 == 0
        || e == 0
        || k2 != n1
        || n2 % e != 0
        || n2 / e > 64
        || x.len() != k1
        || out.len() != e
        || n2 != k1
        || k1 < n1
        || down_bytes.len() != k1.saturating_mul(n1).saturating_mul(2)
        || up_bytes.len() != n1.saturating_mul(n2).saturating_mul(2)
        || k1 > i32::MAX as usize
        || n1 > i32::MAX as usize
        || n2 > i32::MAX as usize
        || e > i32::MAX as usize
    {
        return false;
    }
    let hc = n2 / e;
    let Some(ctx) = shared_ctx() else {
        return false;
    };
    if let Err(e) = ctx.make_current() {
        mix_gpu_broken_once(&format!("cuCtxSetCurrent: {e:#}"));
        return false;
    }
    let Some(f_mixed) = hc_mixed_f32_fn(ctx) else {
        return false;
    };
    // task 152: BF16 カーネルがあれば重みは BF16 のまま (常駐が半分)。
    let want_bf16 = mix_bf16_enabled() && matvec_bf16_r_silu_fn(ctx).is_some();
    let f_down = if want_bf16 {
        matvec_bf16_r_silu_fn(ctx)
    } else {
        matvec_f32_r_silu_fn(ctx)
    };
    let Some(f_down) = f_down else {
        return false;
    };
    let up_reduce = mix_up_reduce_enabled();
    let f_up = if up_reduce {
        if want_bf16 {
            matvec_bf16_r_fn(ctx)
        } else {
            matvec_f32_r_fn(ctx)
        }
    } else if want_bf16 {
        matvec_bf16_fn(ctx)
    } else {
        matvec_f32_fn(ctx)
    };
    let Some(f_up) = f_up else {
        return false;
    };
    let up_thr: u32 = if up_reduce { 256 } else { 1 };
    let wp1 = match mix_gpu_weight(down_uid, down_bytes, k1, n1, want_bf16) {
        Ok(w) => w.ptr,
        Err(e) => {
            mix_gpu_broken_once(&format!("down 重みの常駐に失敗: {e:#}"));
            return false;
        }
    };
    let wp2 = match mix_gpu_weight(up_uid, up_bytes, n1, n2, want_bf16) {
        Ok(w) => w.ptr,
        Err(e) => {
            mix_gpu_broken_once(&format!("up 重みの常駐に失敗: {e:#}"));
            return false;
        }
    };
    let lib = match lib() {
        Ok(l) => l,
        Err(e) => {
            mix_gpu_broken_once(&format!("CUDA lib load failed: {e:#}"));
            return false;
        }
    };
    const MIXED_THREADS: usize = 256;
    let r = MIX_GPU_SC.with(|cell| -> Result<()> {
        // task 177: mix 1 回の操作別内訳 (`DENNO_GDN_DEC_KPROF`・既定 off)。
        // decode の mix 本線はこの chain2 経路 (down + lo_apply → up → hc_mixed)。
        let _kp_win = dec_kprof::window(
            dec_kprof::MIX,
            dec_kprof::cur_layer(),
            dec_kprof::cur_pos(),
            1,
        );
        let mut s = cell.borrow_mut();
        // task 307: 鎖の末尾に積むルータ GEMV の重み (同期の後まで生かす)。
        let mut router_w: Option<GgufWRef> = None;
        let MixGpuScratch {
            x: dx,
            lo: dlo,
            out: dout,
            mixed: dm,
            hx,
            ho,
            ..
        } = &mut *s;
        Scratch::ensure(dx, k1 * 4)?;
        Scratch::ensure(dlo, n1 * 4)?;
        Scratch::ensure(dout, n2 * 4)?;
        Scratch::ensure(dm, e * 4)?;
        Scratch::ensure_pin(hx, k1 * 4)?;
        Scratch::ensure_pin(ho, e * 4)?;
        let (dx, dlo, dout, dm) = (
            dx.as_ref().unwrap(),
            dlo.as_ref().unwrap(),
            dout.as_ref().unwrap(),
            dm.as_ref().unwrap(),
        );
        let (hx, ho) = (hx.as_mut().unwrap(), ho.as_mut().unwrap());
        dec_kprof::step("mix_h2d_pack", || {
            hx.as_mut_slice::<f32>()[..k1].copy_from_slice(x)
        });
        let kp_cp = dec_kprof::op_begin(
            || "H2D@a".to_string(),
            (0, 0, 0),
            (0, 0, 0),
            0,
            k1 * 4,
        );
        unsafe {
            check(
                (lib.memcpy_htod_async)(
                    dx.ptr(),
                    hx.ptr as *const c_void,
                    k1 * 4,
                    std::ptr::null_mut(),
                ),
                "cuMemcpyHtoDAsync (mix chain2)",
            )?;
            // down + lo_apply (silu 込み) → lo はデバイスに残る。
            let (mut ph, mut pw, mut po) = (dx.ptr(), wp1, dlo.ptr());
            let (mut kc, mut nc) = (k1 as c_int, n1 as c_int);
            let mut invc = inv_hc;
            let mut args = [
                &mut ph as *mut _ as *mut c_void,
                &mut pw as *mut _ as *mut c_void,
                &mut po as *mut _ as *mut c_void,
                &mut kc as *mut _ as *mut c_void,
                &mut nc as *mut _ as *mut c_void,
                &mut invc as *mut _ as *mut c_void,
            ];
            ctx.launch_async(f_down, (n1 as u32, 1, 1), (256, 1, 1), 0, &mut args)?;
            // up: 入力は lo_apply 済みの lo (同じ既定ストリームなので順序保証)。
            let (mut ph2, mut pw2, mut po2) = (dlo.ptr(), wp2, dout.ptr());
            let (mut kc2, mut nc2) = (n1 as c_int, n2 as c_int);
            let mut args2 = [
                &mut ph2 as *mut _ as *mut c_void,
                &mut pw2 as *mut _ as *mut c_void,
                &mut po2 as *mut _ as *mut c_void,
                &mut kc2 as *mut _ as *mut c_void,
                &mut nc2 as *mut _ as *mut c_void,
            ];
            ctx.launch_async(f_up, (n2 as u32, 1, 1), (up_thr, 1, 1), 0, &mut args2)?;
            // hc_mixed: xn (= dx) と gate (= dout) から mixed を作る。
            let (mut px, mut pg, mut pm) = (dx.ptr(), dout.ptr(), dm.ptr());
            let (mut ec, mut hcc) = (e as c_int, hc as c_int);
            let mut invc2 = inv_hc;
            let mut args3 = [
                &mut px as *mut _ as *mut c_void,
                &mut pg as *mut _ as *mut c_void,
                &mut pm as *mut _ as *mut c_void,
                &mut ec as *mut _ as *mut c_void,
                &mut hcc as *mut _ as *mut c_void,
                &mut invc2 as *mut _ as *mut c_void,
            ];
            let grid = (e.div_ceil(MIXED_THREADS).max(1) as u32, 1, 1);
            ctx.launch_async(
                f_mixed,
                grid,
                (MIXED_THREADS as u32, 1, 1),
                0,
                &mut args3,
            )?;
            // task 307: ルータ GEMV を鎖の末尾に 1 発積む (D2H は下の mixed と
            // 同じ 1 回の同期でまとめる)。載らなければ 0 = 従来経路。
            let _ = router_in_mix_enqueue(ctx, dm.ptr(), e, &mut router_w);
            let kp_cp = dec_kprof::op_begin(
                || "D2H@a".to_string(),
                (0, 0, 0),
                (0, 0, 0),
                0,
                e * 4,
            );
            check(
                (lib.memcpy_dtoh_async)(ho.ptr, dm.ptr(), e * 4, std::ptr::null_mut()),
                "cuMemcpyDtoHAsync (mix chain2)",
            )?;
            dec_kprof::op_end(kp_cp);
            crate::prof::mark_d2h_src(crate::prof::D2H_SRC_LINEAR);
        }
        ctx.sync()?;
        drop(router_w);
        dec_kprof::step("mix_pack", || {
            out.copy_from_slice(&ho.as_slice::<f32>()[..e])
        });
        Ok(())
    });
    match r {
        Ok(()) => {
            set_last_linear_ran_on_gpu(true);
            true
        }
        Err(e) => {
            mix_gpu_broken_once(&format!("hc mix chain2 failed: {e:#}"));
            false
        }
    }
}

/// task 282: `DENNO_MIX_QK` — 量子型 mix の fused chain (task 266) の中で
/// **1 行 = 1 warp の高速 GEMV** (`kernels_seg_k.ptx`) を使う。
///
/// なぜ要るか: chain の GEMV は `plan_moe_gemv` の v2 形 (1 行 = 1 スレッドの
/// 直列累積) で、UD-Q4_K_XL の mix (down 10240→320 / up 320→10240) は
/// **1 呼び出し 0.14 ms** かかっていた (lab t266r1b の `[q4prof]` mix=0.279 ms/層、
/// 1 トークン 96 呼び出しで 13.4 ms)。
///
/// 値は `both` (既定) / `0` / `down` / `up`。**向きごとに切り替えられる**のは、
/// lab t282a で「両方 seg_k」が旧 GEMV より遅かったため (mix の up は
/// 1 行 320 要素 = warp が 10 反復しかせず、行数 10240 の割に 1 warp の仕事が
/// 小さすぎる)。down (行数 320 / k 10240) と up を別々に A/B できるようにする。
/// 丸め順が変わる (warp の木) ので切り戻しは `DENNO_MIX_QK=0`。
pub const MIX_QK_ENV: &str = "DENNO_MIX_QK";

/// task 282: mix の GEMV 種別。`Old` = 従来の `plan_moe_gemv` (v3 形)、
/// `Seg` = `kernels_seg_k.cu` の 1 行 1 warp、`Blk` = 同ファイルの 1 行 1 ブロック
/// (行数が少ない down 用)、`R8` = 同ファイルの 1 warp 8 行 (行数が多い up 用)。
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum MixGemv {
    /// 従来 (`plan_moe_gemv` の v3 形。lab t282b の実測で 1 行列 54 us)。
    Old,
    /// 1 行 = 1 warp (`dno_seg_gemv_k_q8_0`)。
    Seg,
    /// 1 行 = 1 ブロック 256 スレッド (`dno_mix_gemv_q8_0_rowblk`)。
    Blk,
    /// 1 warp = 8 行 (`dno_mix_gemv_q8_0_r8`)。
    R8,
    /// task 286: 既存の `dno_gemv_q8_0_v5` (`kernels_moe_v5.ptx`、GDN の
    /// decode GEMV と同じ形)。**2 ブロック = 68 B を 17 ワードで読み**、
    /// 次の対を先読みし、アキュムレータを 4 本に分ける。
    ///
    /// lab t286a の `[dec-kprof-avg]` (採否前の既定) で mix の GEMV は
    /// down `rowblk` 31.8 us / up `r8` 39.8 us だった (3.48 MB を 109 / 87 GB/s)。
    /// 同じ 3.48 MB を v5 形 (GDN の qkv) は 374 GB/s で読んでいる。
    /// PTX は既にコミット済みなので、この経路は**ホスト側の切り替えだけ**。
    V5,
    /// task 418: 1 ブロック = 1 行・1 レーン = 1 対 (`kernels_mix_dn5.cu`)。
    /// down 専用 (n_in = 10,240 / n_out = 320 の形)。v5 の 160 ブロック
    /// x 64 スレッドに対し 320 ブロック x 160 スレッド = 5 倍のスレッドで、
    /// ループも先読みも無い。合計順が v5 と違う (丸めだけ)。
    Dn5,
    /// task 422: 1 ブロック = rows 行・1 レーン = 1 対 (`kernels_mix_dn6.cu`)。
    /// dn5 を「複数行」に一般化した形で、x の 64 要素をレジスタに 1 回だけ
    /// 載せて rows 行で使い回す。行ごとの積和と縮約順は dn5 と同一なので、
    /// **値は dn5 と 1 ビットも変わらない**。
    Dn6,
    /// task 431: 1 対 = 4 レーン (`kernels_mix_dn7.cu`)。1 レーン = 1 対では
    /// スレッド数が n_out * n_pairs で頭打ちになり 9.4 warp/SM しか出ないため、
    /// 16 要素ずつ 4 レーンに割って 4 倍のスレッドを出す (丸め順が変わる)。
    Dn7,
}

/// [`MIX_QK_ENV`] の解釈 (純関数)。返り値は `(down, up)` の種別。
///
/// - 未設定 / 未知: `(Dn5, V5)` = 既定 (task 418。down だけ dn5 の新カーネル)
/// - `0` / `off` / `false` : `(Old, Old)` = 切り戻し (task 266 より前)
/// - `blk`                : `(Blk, R8)` = task 282 の形 (採否前の既定)
/// - `down`               : `(Blk, Old)`
/// - `up`                 : `(Old, R8)`
/// - `seg`                : `(Seg, Seg)` = task 278 の seg_k をそのまま
/// - `v5d` / `v5u`        : 片方向だけ v5 (A/B 用)
/// - `ups`                : `(Blk, Seg)` = down は task 282 のまま、up だけ
///   1 行 1 warp の A/B 用
/// - `dn5` / `d5`         : `(Dn5, V5)` = task 418 の down (1 ブロック 1 行)
/// - `v5` / `1` / `both`  : `(V5, V5)` = task 286 の形 (task 418 の切り戻し)
pub fn mix_qk_from_value(v: Option<&str>) -> (MixGemv, MixGemv) {
    match v.map(str::trim).map(str::to_ascii_lowercase).as_deref() {
        Some("0") | Some("off") | Some("false") | Some("no") => (MixGemv::Old, MixGemv::Old),
        Some("blk") | Some("r8") => (MixGemv::Blk, MixGemv::R8),
        Some("down") => (MixGemv::Blk, MixGemv::Old),
        Some("up") => (MixGemv::Old, MixGemv::R8),
        Some("seg") => (MixGemv::Seg, MixGemv::Seg),
        Some("v5d") => (MixGemv::V5, MixGemv::R8),
        Some("v5u") => (MixGemv::Blk, MixGemv::V5),
        Some("ups") => (MixGemv::Blk, MixGemv::Seg),
        // task 418: down だけ 1 ブロック 1 行・1 レーン 1 対の新カーネル。
        Some("dn5") | Some("d5") => (MixGemv::Dn5, MixGemv::V5),
        // task 431: 1 対 = 4 レーンの dn7 (丸め順が変わる)。
        Some("dn7") | Some("d7") => (MixGemv::Dn7, MixGemv::V5),
        // task 422: down を「1 ブロック rows 行」に一般化した dn6
        // (`mix_dn6_rows_from_value` が rows を決める。値は dn5 と同一)。
        Some("dn6") | Some("d6") | Some("dn6r1") | Some("dn6r2") | Some("dn6r4")
        | Some("dn6r6") | Some("dn6r8") | Some("d6r1") | Some("d6r2") | Some("d6r4")
        | Some("d6r6") | Some("d6r8") => {
            (MixGemv::Dn6, MixGemv::V5)
        }
        // task 286 の形へ明示的に戻す逃げ道 (task 418 の切り戻し)。
        Some("1") | Some("both") | Some("v5") => (MixGemv::V5, MixGemv::V5),
        // task 422: lab t422b で短い decode 12.9 -> 12.5 (-3.1%)、14k 後 -4.1%、
        // mix 段 -6.7%、md5 全 SAME (rows=2 が rows=4 より全点で良かった) なので
        // **down の既定を dn6 (rows=2) にした**。
        // task 431: lab t431c で 1 対 4 レーンの dn7 が mix 段 -5〜-7%
        // (8 リクエスト中 7 本。最初の 1 本だけは新カーネルの初回ロードで +13%)、
        // 短い decode -1.0%、14k 後 -2.3%、prefill +0.9%、md5 全 SAME、
        // errors 0 だったので **既定を dn7 にした**。形が合わない型・k
        // (np が 8 の倍数でない / 1 行 1024 超) や PTX 欠けは `mix_dn7_plan` の
        // 門番で dn6 へ落ちる。
        // 切り戻しは `DENNO_MIX_QK=dn6` / `dn5` (task 418) / `v5` (task 286)。
        _ => (MixGemv::Dn7, MixGemv::V5),
    }
}

/// [`MIX_QK_ENV`] をプロセスで 1 回だけ読む。`(down, up)` の種別。
pub fn mix_qk_enabled() -> (MixGemv, MixGemv) {
    static ON: OnceLock<(MixGemv, MixGemv)> = OnceLock::new();
    *ON.get_or_init(|| mix_qk_from_value(std::env::var(MIX_QK_ENV).ok().as_deref()))
}

/// gate_audit の台帳用 (既定 on のゲート)。どちらかが seg_k 系なら true。
pub fn mix_qk_gate_on() -> bool {
    mix_qk_enabled() != (MixGemv::Old, MixGemv::Old)
}

/// task 422: dn6 が選ばれているか (gate_audit の台帳用)。
/// mix の down (`DENNO_MIX_QK=dn6`) か GDN (`DENNO_GDN_DEC_GEMV=dn6`) の
/// どちらかで選ばれたら true。
pub fn mix_dn6_gate_on() -> bool {
    matches!(mix_qk_enabled().0, MixGemv::Dn6 | MixGemv::Dn7) || gdn_dec_gemv_dn6_on()
}

/// task 282: 高速 GEMV が実際に撃たれた回数 (診断用。プロセス通算)。
static MIX_QK_HITS: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);

/// task 282: 高速 GEMV 用の前置きバッファのレイアウト (純関数)。
///
/// 1 本の H2D で「重みポインタ 2 本 + segment 表 2 枚 + xn」を送る。
/// 返り値は `(wptr_down, wptr_up, seg_down, seg_up, x)` のバイトオフセット。
/// segment 表は 4 語 (`kernels_seg_k.cu` の規約: id / m / x_off / out_off) で、
/// どちらも `m=1, x_off=0, out_off=0`。`x` は 16 バイト整列。
pub fn mix_qk_layout() -> (usize, usize, usize, usize, usize) {
    (0, 8, 16, 32, 48)
}

/// task 282: 高速 GEMV の前置き (`[wptr_d][wptr_u][seg_d][seg_u]`) のバイト数。
const MIX_QK_PROLOGUE: usize = 48;

/// task 286: [`mix_v5_plan`] の形の部分だけを取り出した純関数。
/// 返り値は `(lanes, rows_per_block, grid)`。形が合わなければ `None`。
pub fn mix_v5_shape(n_in: usize, n_out: usize) -> Option<(usize, usize, u32)> {
    if n_in == 0 || n_out == 0 || n_in % 32 != 0 {
        return None;
    }
    let nb = n_in / 32;
    if nb < 2 || nb % 2 != 0 {
        return None;
    }
    let np = nb / 2;
    let lanes = v5_lanes_div(np, 32);
    if lanes == 0 {
        return None;
    }
    let rows = if lanes >= 16 {
        2
    } else if lanes >= 8 {
        4
    } else {
        (128 / lanes).max(1)
    };
    let block_dim = rows * lanes;
    if block_dim == 0 || block_dim > 1024 {
        return None;
    }
    Some((lanes, rows, n_out.div_ceil(rows) as u32))
}

/// task 286: mix の Q8_0 GEMV を v5 形 (`dno_gemv_q8_0_v5`) で回すときの
/// 起動計画。形が合わない / PTX が無いときは `None` (呼び出し側は Blk/R8 へ)。
///
/// v5 の制約:
/// - Q8_0 のみ。`nb = n_in / 32` が 2 以上かつ偶数 (2 ブロック = 68 B の対で読む)。
/// - `lanes` は 2 の冪で `np = nb / 2` を割り切ること (レーンの担当区間が
///   等分できること)。`lanes` は 1 も許す (`dno_v5_reduce` が空ループになる)。
///
/// 形の選び方 (lab の実測で決める): レーンが多いほど 1 行を 1 warp で読むので
/// 行数が少ない down (n_out=320) は `lanes=32` / 2 行 1 ブロック (grid=n_out/2)。
/// 行数が多い up (n_out=10,240) は `lanes=1` / 128 行 1 ブロック (grid=n_out/128)。
pub fn mix_v5_plan(
    ty: crate::kquant::GgmlType,
    n_in: usize,
    n_out: usize,
) -> Option<MoeGemvPlan> {
    use crate::kquant::GgmlType as T;
    if ty != T::Q8_0 {
        return None;
    }
    let (lanes, rows, grid) = mix_v5_shape(n_in, n_out)?;
    let rb = gguf_row_bytes(ty, n_in)?;
    Some(MoeGemvPlan {
        f: gemv_v5_kernels()?.f[0],
        rows_per_block: rows,
        block_dim: (rows * lanes) as u32,
        shmem: 0,
        lanes,
        rb,
        grid,
    })
}

/// task 286: [`mix_v5_plan`] の計画を 1 本積む (v5 は引数 8 本。`lanes=1` でも
/// `rows_per_block` / `lanes` を渡す = 6 本で撃つと未定義値になる)。
fn launch_mix_v5(
    ctx: &CudaCtx,
    plan: &MoeGemvPlan,
    w: CUdeviceptr,
    x: CUdeviceptr,
    o: CUdeviceptr,
    n_in: usize,
    n_out: usize,
) -> Result<()> {
    let (mut pw, mut px, mut po) = (w, x, o);
    let (mut ni, mut no, mut rb) = (n_in as c_int, n_out as c_int, plan.rb as c_int);
    let (mut rows, mut lanes) = (plan.rows_per_block as c_int, plan.lanes as c_int);
    let mut args = [
        &mut pw as *mut _ as *mut c_void,
        &mut px as *mut _ as *mut c_void,
        &mut po as *mut _ as *mut c_void,
        &mut ni as *mut _ as *mut c_void,
        &mut no as *mut _ as *mut c_void,
        &mut rb as *mut _ as *mut c_void,
        &mut rows as *mut _ as *mut c_void,
        &mut lanes as *mut _ as *mut c_void,
    ];
    unsafe {
        ctx.launch_async(
            plan.f,
            (plan.grid, 1, 1),
            (plan.block_dim, 1, 1),
            plan.shmem,
            &mut args,
        )
    }
}

// ===========================================================================
// task 418: mix の down (Q8_0) を 1 ブロック 1 行・1 レーン 1 対で読む
// (`DENNO_MIX_QK=dn5`)
// ===========================================================================
//
// 実形 (n_in = 10,240 = 160 対、n_out = 320、3.48 MB) を v5 は
// `lanes=32 / rows=2` = **160 ブロック x 64 スレッド**で撃つ (1 レーンが 5 対を
// 逐次ループ)。lab t418a の `[dec-kprof-avg]` (band 0) で down は
// **19.4 us = 180 GB/s** で、同じ band の inject (`dno_matvec_f32_r`、
// 512 ブロック x 256 スレッド、13 MB) は 7.1 us だった。差は並列度。
//
// 新カーネルは 1 ブロック = 1 行、block = 32 * (n_in / 64 / 32) = 160 スレッド
// (1 レーン = 1 対 = 68 B を 1 回だけ読む)。ループも先読みも無い。
// 縮約は warp 内の木 -> warp ごとの部分和を共有メモリ -> スレッド 0 が固定順。
// 合計順が v5 と違う (丸めだけ) ので既定 off。値はゲートで切り戻せる。

/// 新カーネルの名前。
const MIX_DN5_KERNEL_NAME: &str = "dno_mix_gemv_q8_0_dn5";

/// 新カーネルの引数の数 (w, x, out, n_in, n_out, row_bytes)。
const MIX_DN5_NARGS: usize = 6;

/// `.cu` の `part[8]` (warp の部分和の上限)。
const MIX_DN5_MAX_WARPS: usize = 8;

struct MixDn5Kernels {
    #[allow(dead_code)]
    module: CUmodule,
    f: CUfunction,
}

unsafe impl Send for MixDn5Kernels {}
unsafe impl Sync for MixDn5Kernels {}

static MIX_DN5_KERNELS: OnceLock<Option<MixDn5Kernels>> = OnceLock::new();

fn mix_dn5_ptx_path() -> std::path::PathBuf {
    match std::env::var("DENNO_MIX_DN5_PTX") {
        Ok(p) if !p.is_empty() => std::path::PathBuf::from(p),
        _ => std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("kernels")
            .join("kernels_mix_dn5.ptx"),
    }
}

/// 新カーネルを取得する (初回だけ PTX を読む。失敗は `None` を焼き付ける)。
fn mix_dn5_kernels() -> Option<&'static MixDn5Kernels> {
    MIX_DN5_KERNELS
        .get_or_init(|| {
            let path = mix_dn5_ptx_path();
            let mut image = match std::fs::read(&path) {
                Ok(b) => b,
                Err(_) => return None,
            };
            let text = String::from_utf8_lossy(&image).to_string();
            if ptx_entry_params(&text, MIX_DN5_KERNEL_NAME) != Some(MIX_DN5_NARGS) {
                eprintln!(
                    "[mix-dn5] PTX の引数が {MIX_DN5_NARGS} 本でない → v5 の down へ。\
                     `bash build_ptx.sh mix_dn5` で再生成する"
                );
                return None;
            }
            image.push(0);
            let lib = lib().ok()?;
            unsafe {
                let mut module: CUmodule = std::ptr::null_mut();
                if (lib.module_load_data)(&mut module, image.as_ptr() as *const c_void)
                    != CUDA_SUCCESS
                {
                    return None;
                }
                let mut cname = MIX_DN5_KERNEL_NAME.as_bytes().to_vec();
                cname.push(0);
                let mut f: CUfunction = std::ptr::null_mut();
                if (lib.module_get_function)(&mut f, module, cname.as_ptr() as *const c_char)
                    != CUDA_SUCCESS
                {
                    eprintln!("[mix-dn5] PTX に {MIX_DN5_KERNEL_NAME} が無い → v5 の down へ");
                    return None;
                }
                Some(MixDn5Kernels { module, f })
            }
        })
        .as_ref()
}

/// 新カーネルが載っているか (テスト / 診断用)。
pub fn mix_dn5_loaded() -> bool {
    mix_dn5_kernels().is_some()
}

/// 形の門番 (純関数)。`.cu` の前提は
/// 「Q8_0 / n_in % 64 == 0 / 対の数 np = n_in / 64 が 32 の倍数 / np/32 <= 8」。
/// 返り値は 1 ブロックの warp 数 (= np / 32)。
pub fn mix_dn5_warps(n_in: usize) -> Option<usize> {
    if n_in == 0 || n_in % 64 != 0 {
        return None;
    }
    let np = n_in / 64;
    if np % 32 != 0 {
        return None;
    }
    let warps = np / 32;
    if warps == 0 || warps > MIX_DN5_MAX_WARPS {
        return None;
    }
    Some(warps)
}

/// 新カーネルを 1 本積む (grid = n_out、block = 32 * warps)。
fn launch_mix_dn5(
    ctx: &CudaCtx,
    w: CUdeviceptr,
    x: CUdeviceptr,
    o: CUdeviceptr,
    n_in: usize,
    n_out: usize,
    row_bytes: usize,
    warps: usize,
) -> Result<()> {
    let k = mix_dn5_kernels().ok_or_else(|| anyhow::anyhow!("dn5 のカーネルが無い"))?;
    let (mut pw, mut px, mut po) = (w, x, o);
    let (mut ni, mut no, mut rb) = (n_in as c_int, n_out as c_int, row_bytes as c_int);
    let mut args = [
        &mut pw as *mut _ as *mut c_void,
        &mut px as *mut _ as *mut c_void,
        &mut po as *mut _ as *mut c_void,
        &mut ni as *mut _ as *mut c_void,
        &mut no as *mut _ as *mut c_void,
        &mut rb as *mut _ as *mut c_void,
    ];
    unsafe {
        ctx.launch_async(
            k.f,
            (n_out.max(1) as u32, 1, 1),
            ((32 * warps) as u32, 1, 1),
            0,
            &mut args,
        )
    }
}

/// task 418: dn5 の down を撃った回数 (診断。`[mix-qchain]` の `dn5=` に出る)。
static MIX_DN5_HITS: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);

/// task 418: dn5 の down を撃った回数。
pub fn mix_dn5_hits() -> u64 {
    MIX_DN5_HITS.load(std::sync::atomic::Ordering::Relaxed)
}

/// task 418: 集計を 0 に戻す (リクエスト終端)。
pub fn mix_dn5_reset() {
    MIX_DN5_HITS.store(0, std::sync::atomic::Ordering::Relaxed);
}

// ===========================================================================
// task 422: `dno_mix_gemv_q8_0_dn6` — dn5 を「1 ブロック = rows 行」に一般化
// (`DENNO_MIX_QK=dn6` / `DENNO_GDN_DEC_GEMV=dn6`)
// ===========================================================================
//
// lab t422a の `[dec-kprof-avg]` (band 0、既定モデル) で、Q8_0 の GEMV は 2 か所が
// 残っていた:
//   - mix の down (`dn5`): 320 x 160 = 15.4 us。重み 3.48 MB + **x 13.1 MB**
//     (320 ブロックが同じ 41 KB を読む) = 16.6 MB を 1.08 TB/s。
//   - GDN の qkv/out (`dno_gemv_q8_0_v5`): 320 x 256 が 2 本/層で 35.4 us ずつ。
//     v5 は 8 行 1 ブロック・1 レーンが 5 対を逐次ループ (重み 27.9 MB を 787 GB/s)。
// dn6 は 1 レーン = 1 対のまま、**1 ブロックが rows 行を持つ**ので
//   (a) 1 レーンの逐次ループが無くなる (v5 の 5 対 -> 1 対)
//   (b) x の 64 要素をレジスタに 1 回だけ載せて rows 行で使い回す (x が 1/rows)
// を行う。行ごとの積和と縮約の順は dn5 と同一なので、**値は dn5 と 1 ビットも
// 変わらない** (v5 から切り替えたときだけ合計順が変わる = 丸めだけ)。

/// 新カーネルの名前。
const MIX_DN6_KERNEL_NAME: &str = "dno_mix_gemv_q8_0_dn6";

/// 新カーネルの引数の数 (w, x, out, n_in, n_out, row_bytes, rows)。
const MIX_DN6_NARGS: usize = 7;

/// `.cu` の `part[8][8]` (warp の部分和 / 行の上限)。
const MIX_DN6_MAX_WARPS: usize = 8;
const MIX_DN6_MAX_ROWS: usize = 8;

/// 1 ブロックのスレッド上限 (rows * 32 * warps)。
const MIX_DN6_MAX_THREADS: usize = 1024;

struct MixDn6Kernels {
    #[allow(dead_code)]
    module: CUmodule,
    f: CUfunction,
}

unsafe impl Send for MixDn6Kernels {}
unsafe impl Sync for MixDn6Kernels {}

static MIX_DN6_KERNELS: OnceLock<Option<MixDn6Kernels>> = OnceLock::new();

fn mix_dn6_ptx_path() -> std::path::PathBuf {
    match std::env::var("DENNO_MIX_DN6_PTX") {
        Ok(p) if !p.is_empty() => std::path::PathBuf::from(p),
        _ => std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("kernels")
            .join("kernels_mix_dn6.ptx"),
    }
}

/// 新カーネルを取得する (初回だけ PTX を読む。失敗は `None` を焼き付ける)。
fn mix_dn6_kernels() -> Option<&'static MixDn6Kernels> {
    MIX_DN6_KERNELS
        .get_or_init(|| {
            let path = mix_dn6_ptx_path();
            let mut image = match std::fs::read(&path) {
                Ok(b) => b,
                Err(_) => return None,
            };
            let text = String::from_utf8_lossy(&image).to_string();
            if ptx_entry_params(&text, MIX_DN6_KERNEL_NAME) != Some(MIX_DN6_NARGS) {
                eprintln!(
                    "[mix-dn6] PTX の引数が {MIX_DN6_NARGS} 本でない → dn5 / v5 へ。\
                     `bash build_ptx.sh mix_dn6` で再生成する"
                );
                return None;
            }
            image.push(0);
            let lib = lib().ok()?;
            unsafe {
                let mut module: CUmodule = std::ptr::null_mut();
                if (lib.module_load_data)(&mut module, image.as_ptr() as *const c_void)
                    != CUDA_SUCCESS
                {
                    return None;
                }
                let mut cname = MIX_DN6_KERNEL_NAME.as_bytes().to_vec();
                cname.push(0);
                let mut f: CUfunction = std::ptr::null_mut();
                if (lib.module_get_function)(&mut f, module, cname.as_ptr() as *const c_char)
                    != CUDA_SUCCESS
                {
                    eprintln!("[mix-dn6] PTX に {MIX_DN6_KERNEL_NAME} が無い → dn5 / v5 へ");
                    return None;
                }
                Some(MixDn6Kernels { module, f })
            }
        })
        .as_ref()
}

/// 新カーネルが載っているか (テスト / 診断用)。
pub fn mix_dn6_loaded() -> bool {
    mix_dn6_kernels().is_some()
}

/// 形の門番 (純関数)。`.cu` の前提は
/// 「Q8_0 / n_in % 64 == 0 / 対の数 np = n_in / 64 が 1 以上 /
///   warps = ceil(np / 32) が 8 以下」。返り値は 1 行あたりの warp 数。
pub fn mix_dn6_warps(n_in: usize) -> Option<usize> {
    if n_in == 0 || n_in % 64 != 0 {
        return None;
    }
    let np = n_in / 64;
    if np == 0 {
        return None;
    }
    let warps = np.div_ceil(32);
    if warps == 0 || warps > MIX_DN6_MAX_WARPS {
        return None;
    }
    Some(warps)
}

/// 起動形 (純関数)。`Some((warps, rows))` なら撃てる。
///
/// `want_rows` は 1 ブロックが持つ行数の希望。`rows * 32 * warps <= 1024` と
/// `rows <= 8` に丸める (丸めた結果が 1 未満なら撃たない)。
pub fn mix_dn6_plan(n_in: usize, n_out: usize, want_rows: usize) -> Option<(usize, usize)> {
    if n_out == 0 {
        return None;
    }
    let warps = mix_dn6_warps(n_in)?;
    let fit = MIX_DN6_MAX_THREADS / (32 * warps);
    let rows = want_rows.clamp(1, fit.min(MIX_DN6_MAX_ROWS));
    if rows == 0 {
        return None;
    }
    let grid = n_out.div_ceil(rows);
    if grid == 0 || grid > u32::MAX as usize {
        return None;
    }
    Some((warps, rows))
}

/// 新カーネルを 1 本積む (grid = ceil(n_out / rows)、block = 32 * warps * rows)。
fn launch_mix_dn6(
    ctx: &CudaCtx,
    w: CUdeviceptr,
    x: CUdeviceptr,
    o: CUdeviceptr,
    n_in: usize,
    n_out: usize,
    row_bytes: usize,
    warps: usize,
    rows: usize,
) -> Result<()> {
    let k = mix_dn6_kernels().ok_or_else(|| anyhow::anyhow!("dn6 のカーネルが無い"))?;
    let (mut pw, mut px, mut po) = (w, x, o);
    let (mut ni, mut no, mut rb) = (n_in as c_int, n_out as c_int, row_bytes as c_int);
    let mut rw = rows as c_int;
    let mut args = [
        &mut pw as *mut _ as *mut c_void,
        &mut px as *mut _ as *mut c_void,
        &mut po as *mut _ as *mut c_void,
        &mut ni as *mut _ as *mut c_void,
        &mut no as *mut _ as *mut c_void,
        &mut rb as *mut _ as *mut c_void,
        &mut rw as *mut _ as *mut c_void,
    ];
    let grid = n_out.div_ceil(rows).max(1) as u32;
    let block = (32 * warps * rows) as u32;
    unsafe { ctx.launch_async(k.f, (grid, 1, 1), (block, 1, 1), 0, &mut args) }
}

/// task 427: mix 以外の呼び出し点 (full 層の qkv/wo、head) から dn6 を撃つ門番。
///
/// カーネル・値は mix の down と同一 (`dno_mix_gemv_q8_0_dn6`。rows は行の割り当て
/// だけを変えるので dn5 とビット一致)。Q8_0 で、形 (`mix_dn6_plan`) と PTX が
/// 揃うときだけ `Some((warps, rows))`。`want_rows == 0` は「撃たない」。
pub(crate) fn dn6_gemv_plan(
    ty: crate::kquant::GgmlType,
    n_in: usize,
    n_out: usize,
    want_rows: usize,
) -> Option<(usize, usize)> {
    if want_rows == 0 || ty != crate::kquant::GgmlType::Q8_0 {
        return None;
    }
    if mix_dn6_kernels().is_none() {
        return None;
    }
    mix_dn6_plan(n_in, n_out, want_rows)
}

/// task 427: [`dn6_gemv_plan`] の計画を 1 本積む (生ポインタの重み)。
#[allow(clippy::too_many_arguments)]
pub(crate) fn launch_dn6_gemv(
    ctx: &CudaCtx,
    w: CUdeviceptr,
    x: CUdeviceptr,
    o: CUdeviceptr,
    n_in: usize,
    n_out: usize,
    row_bytes: usize,
    warps: usize,
    rows: usize,
) -> Result<()> {
    launch_mix_dn6(ctx, w, x, o, n_in, n_out, row_bytes, warps, rows)
}

/// task 427: full 層の qkv/wo を dn6 で撃った回数 (1 プロセス通算)。
static DN6_FULL_HITS: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);

/// task 427: head の GEMV を dn6 で撃った回数 (1 プロセス通算)。
static DN6_HEAD_HITS: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);

/// task 427: 発火の証拠 (`[mix-qchain]` の `f6=` / `h6=`)。
pub fn dn6_dec_hits() -> (u64, u64) {
    (
        DN6_FULL_HITS.load(std::sync::atomic::Ordering::Relaxed),
        DN6_HEAD_HITS.load(std::sync::atomic::Ordering::Relaxed),
    )
}

/// task 427: 集計を 0 に戻す。
pub fn dn6_dec_reset() {
    DN6_FULL_HITS.store(0, std::sync::atomic::Ordering::Relaxed);
    DN6_HEAD_HITS.store(0, std::sync::atomic::Ordering::Relaxed);
}

/// task 427: full 層の 1 本を撃ったことを数える (full_dec から)。
pub(crate) fn note_dn6_full_hit() {
    DN6_FULL_HITS.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
}

/// task 427: head の 1 本を撃ったことを数える。
pub(crate) fn note_dn6_head_hit() {
    DN6_HEAD_HITS.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
}

/// task 422: dn6 を撃った回数 (診断。`[mix-qchain]` の `dn6=` に出る)。
static MIX_DN6_HITS: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);

/// task 422: dn6 を撃った回数。
pub fn mix_dn6_hits() -> u64 {
    MIX_DN6_HITS.load(std::sync::atomic::Ordering::Relaxed)
}

/// task 422: 集計を 0 に戻す。
pub fn mix_dn6_reset() {
    MIX_DN6_HITS.store(0, std::sync::atomic::Ordering::Relaxed);
}

/// `DENNO_MIX_QK` / `DENNO_GDN_DEC_GEMV` の値から dn6 の rows を決める (純関数)。
///
/// `dn6` / `d6` = 4 行 (実測で選ぶ)、`dn6r2` = 2 行、`dn6r6` = 6 行
/// (GDN の qkv/out は 6 行 = block 960)。それ以外は既定 4。
pub fn mix_dn6_rows_from_value(v: Option<&str>) -> usize {
    match v.map(str::trim).map(str::to_ascii_lowercase).as_deref() {
        Some("dn6r1") | Some("d6r1") => 1,
        Some("dn6r4") | Some("d6r4") => 4,
        Some("dn6r6") | Some("d6r6") => 6,
        Some("dn6r8") | Some("d6r8") => 8,
        // task 422: 既定 (未設定 / dn6 / d6 / それ以外) は 2 行。
        // lab t422b で rows=2 が rows=4 より短い decode・14k 後とも良かった。
        _ => 2,
    }
}

/// dn6 の rows (mix の down 用。env から 1 回だけ読む)。
fn mix_dn6_rows() -> usize {
    static R: OnceLock<usize> = OnceLock::new();
    *R.get_or_init(|| {
        mix_dn6_rows_from_value(std::env::var(MIX_QK_ENV).ok().as_deref())
    })
}

// ===========================================================================
// task 496: dn6 の**レーン詰め**版 (`dno_mix_gemv_q8_0_dn8`、`DENNO_GDN_DEC_GEMV=dn8`)
// ===========================================================================
//
// dn6 は 1 レーン = 1 対 (64 要素) なので、レーン数 = 32 * ceil(np / 32) に固定される
// (np = n_in / 64)。既定モデルの GDN qkv は n_in = 2,560 / n_out = 16,384 で
// **np = 40** = 64 レーン中 24 レーンが遊ぶ (埋まり 62.5%)。t492c の ssm 段
// (3.03 ms/token) のうち最大の 1 本がこの qkv で、実測は約 1.27 TB/s
// (ピーク 1.79 TB/s の 71%)。
//
// dn8 は行の割り当てを「1 ブロック rows 行」から「1 ブロック = rows * np 個の
// (行, 対)」へ変え、レーンを (行, 対) で埋める (items = rows * np)。x は shared に
// 1 回だけ置いて rows 本で使い回す。**1 対の積和は dn6 と同一**で、変わるのは
// 対の部分和の足し方だけ (dn6 = warp 木 + warp の逐次、dn8 = 対の昇順 1 本)。
// 行ごとに独立で決定的。np が 32 の倍数の形 (GDN の out = np 96 など) では
// dn6 が既に 100% なので dn8 は使わない (dn6 のまま)。

/// 新カーネルの名前。
const MIX_DN8_KERNEL_NAME: &str = "dno_mix_gemv_q8_0_dn8";

/// 新カーネルの引数の数 (w, x, out, n_in, n_out, row_bytes, rows)。
const MIX_DN8_NARGS: usize = 7;

/// 1 ブロックのスレッド上限 (items = rows * np)。
const MIX_DN8_MAX_THREADS: usize = 1024;

/// 1 ブロックが持つ行数の上限 (`.cu` は rows を引数で受けるだけなので自由。
/// t496a で rows 2 -> 4 -> 8 が単調に良かったので 16 まで試せるようにする)。
const MIX_DN8_MAX_ROWS: usize = 16;

/// 1 ブロックのスレッド数上限 (レジスタの都合)。
///
/// `.cu` は 1 レーンが x の 64 要素をレジスタに持つので ~100 レジスタ/スレッド
/// 使う。t496b の `d8a8` (out を block 768 で撃った回) は
/// `cuLaunchKernel が失敗: error 701` = LAUNCH_OUT_OF_RESOURCES で落ちた
/// (768 x 100 > 65,536)。640 は t496b の `d8a16` (qkv を block 640 で撃った回)
/// で通っているので、それを上限にする。
const MIX_DN8_MAX_BLOCK: usize = 640;

/// shared の上限 (x の詰め物込み。48 KiB を超える形は dn6 へ)。
const MIX_DN8_MAX_SHMEM: usize = 48 * 1024;

/// dn8 の起動形 (純関数 [`mix_dn8_plan`] の結果)。
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct MixDn8Plan {
    /// 1 行あたりの対の数 (n_in / 64)。
    pub np: usize,
    /// 1 ブロックが持つ行数。
    pub rows: usize,
    /// 1 ブロックのスレッド数 (32 の倍数)。
    pub block: usize,
    /// 動的 shared のバイト数。
    pub shmem: usize,
    /// grid (= ceil(n_out / rows))。
    pub grid: usize,
}

struct MixDn8Kernels {
    #[allow(dead_code)]
    module: CUmodule,
    f: CUfunction,
}

unsafe impl Send for MixDn8Kernels {}
unsafe impl Sync for MixDn8Kernels {}

static MIX_DN8_KERNELS: OnceLock<Option<MixDn8Kernels>> = OnceLock::new();

fn mix_dn8_ptx_path() -> std::path::PathBuf {
    match std::env::var("DENNO_MIX_DN8_PTX") {
        Ok(p) if !p.is_empty() => std::path::PathBuf::from(p),
        _ => std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("kernels")
            .join("kernels_mix_dn8.ptx"),
    }
}

/// 新カーネルを取得する (初回だけ PTX を読む。失敗は `None` を焼き付ける)。
fn mix_dn8_kernels() -> Option<&'static MixDn8Kernels> {
    MIX_DN8_KERNELS
        .get_or_init(|| {
            let path = mix_dn8_ptx_path();
            let mut image = match std::fs::read(&path) {
                Ok(b) => b,
                Err(_) => return None,
            };
            let text = String::from_utf8_lossy(&image).to_string();
            if ptx_entry_params(&text, MIX_DN8_KERNEL_NAME) != Some(MIX_DN8_NARGS) {
                eprintln!(
                    "[mix-dn8] PTX の引数が {MIX_DN8_NARGS} 本でない → dn6 / v5 へ。\
                     `bash build_ptx.sh mix_dn8` で再生成する"
                );
                return None;
            }
            image.push(0);
            let lib = lib().ok()?;
            unsafe {
                let mut module: CUmodule = std::ptr::null_mut();
                if (lib.module_load_data)(&mut module, image.as_ptr() as *const c_void)
                    != CUDA_SUCCESS
                {
                    return None;
                }
                let mut cname = MIX_DN8_KERNEL_NAME.as_bytes().to_vec();
                cname.push(0);
                let mut f: CUfunction = std::ptr::null_mut();
                if (lib.module_get_function)(&mut f, module, cname.as_ptr() as *const c_char)
                    != CUDA_SUCCESS
                {
                    eprintln!("[mix-dn8] PTX に {MIX_DN8_KERNEL_NAME} が無い → dn6 / v5 へ");
                    return None;
                }
                Some(MixDn8Kernels { module, f })
            }
        })
        .as_ref()
}

/// 新カーネルが載っているか (テスト / 診断用)。
pub fn mix_dn8_loaded() -> bool {
    mix_dn8_kernels().is_some()
}

/// レーンの埋まり具合 (`np` 対を `lanes` レーンへ割るときの比)。
fn dn8_fill(np: usize, lanes: usize) -> f64 {
    if lanes == 0 {
        return 0.0;
    }
    np as f64 / lanes as f64
}

/// 形の門番 (純関数)。dn6 よりレーンが埋まる形だけを受ける。
///
/// 前提: `np = n_in / 64` が 1 以上 / `np % 32 != 0` (32 の倍数なら dn6 で十分) /
/// `items = rows * np <= 1024` / `shared = (np * 65 + items) * 4 <= 48 KiB`。
pub fn mix_dn8_plan(n_in: usize, n_out: usize, want_rows: usize) -> Option<MixDn8Plan> {
    mix_dn8_plan_with(n_in, n_out, want_rows, false)
}

/// [`mix_dn8_plan`] の本体。`allow_full` は「np が 32 の倍数の形 (dn6 で既に
/// レーンが 100% 埋まる形) でも dn8 を使う」か。
///
/// その形でも dn8 は **x を shared に 1 回だけ置いて rows 本で使い回す**ので、
/// x のグローバル読み (1 ブロックあたり n_in 本) が 1/rows になる
/// (GDN の out は n_in = 6,144 で、rows=2 の dn6 は 1,280 ブロック x 24 KB を
/// 読む)。レーンの詰まりは dn6 と同じなので、埋まりの比較は課さない。
pub fn mix_dn8_plan_with(
    n_in: usize,
    n_out: usize,
    want_rows: usize,
    allow_full: bool,
) -> Option<MixDn8Plan> {
    if n_in == 0 || n_in % 64 != 0 || n_out == 0 {
        return None;
    }
    let np = n_in / 64;
    if np == 0 {
        return None;
    }
    let lane_gain = np % 32 != 0;
    if !lane_gain && !allow_full {
        // dn6 が既に 100% 埋まる (qkv の out 側や mix down はこちら)。
        return None;
    }
    let rows = want_rows.clamp(1, MIX_DN8_MAX_ROWS);
    let items = np.checked_mul(rows)?;
    if items == 0 || items > MIX_DN8_MAX_THREADS {
        return None;
    }
    let block = 32 * items.div_ceil(32);
    if block > MIX_DN8_MAX_BLOCK {
        return None;
    }
    if lane_gain {
        // dn6 の埋まり (32 * ceil(np / 32) レーン) より 5 ポイント以上良いときだけ。
        let dn6_lanes = 32 * np.div_ceil(32);
        if dn8_fill(items, block) <= dn8_fill(np, dn6_lanes) + 0.05 {
            return None;
        }
    }
    let shmem = (np * 65 + items).checked_mul(4)?;
    if shmem > MIX_DN8_MAX_SHMEM {
        return None;
    }
    let grid = n_out.div_ceil(rows);
    if grid == 0 || grid > u32::MAX as usize {
        return None;
    }
    Some(MixDn8Plan {
        np,
        rows,
        block,
        shmem,
        grid,
    })
}

/// dn8 を 1 本積む (grid = plan.grid、block = plan.block、shmem = plan.shmem)。
fn launch_mix_dn8(
    ctx: &CudaCtx,
    plan: &MixDn8Plan,
    w: CUdeviceptr,
    x: CUdeviceptr,
    o: CUdeviceptr,
    n_in: usize,
    n_out: usize,
    row_bytes: usize,
) -> Result<()> {
    let k = mix_dn8_kernels().ok_or_else(|| anyhow::anyhow!("dn8 のカーネルが無い"))?;
    let (mut pw, mut px, mut po) = (w, x, o);
    let (mut ni, mut no, mut rb) = (n_in as c_int, n_out as c_int, row_bytes as c_int);
    let mut rw = plan.rows as c_int;
    let mut args = [
        &mut pw as *mut _ as *mut c_void,
        &mut px as *mut _ as *mut c_void,
        &mut po as *mut _ as *mut c_void,
        &mut ni as *mut _ as *mut c_void,
        &mut no as *mut _ as *mut c_void,
        &mut rb as *mut _ as *mut c_void,
        &mut rw as *mut _ as *mut c_void,
    ];
    unsafe {
        ctx.launch_async(
            k.f,
            (plan.grid as u32, 1, 1),
            (plan.block as u32, 1, 1),
            plan.shmem as u32,
            &mut args,
        )
    }
}

/// task 496: dn8 を撃った回数 (診断。`[mix-qchain]` の `dn8=` に出る)。
static MIX_DN8_HITS: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);

/// task 496: dn8 を撃った回数。
pub fn mix_dn8_hits() -> u64 {
    MIX_DN8_HITS.load(std::sync::atomic::Ordering::Relaxed)
}

/// task 496: 集計を 0 に戻す。
pub fn mix_dn8_reset() {
    MIX_DN8_HITS.store(0, std::sync::atomic::Ordering::Relaxed);
}

// ===========================================================================
// task 431: mix の down を 1 対 = 4 レーンで回す (`DENNO_MIX_QK=dn7`)
// ===========================================================================
//
// lab t431a の mix band (`[dec-kprof-avg]`、1 呼び出しあたり) は
//   H2D@a 10.3 / down 14.0 / up 10.8 / router 6.9 / D2H@a 5.4 us
// で、down は 3.48 MB を 245 GB/s。**同じ dn6 の PTX を GDN の qkv
// (grid 1,280 x 192) で撃つと 962 GB/s** 出るので、差はカーネルの中身ではなく
// 同時に走る warp 数 (mix down は 9.4 warp/SM)。1 レーン = 1 対のままだと
// スレッド数が n_out * n_pairs で固定されるため、dn7 は 1 対を 4 レーンに割る
// (`kernels_mix_dn7.cu`)。実形で 204,800 スレッド = 37.6 warp/SM。
//
// 値は丸め順だけが変わる (1 行の和を 16 要素ずつ 4 レーンに分けて足す)。
// ゲートは既存 env の新しい値 `DENNO_MIX_QK=dn7`。形が合わなければ dn6 へ落ちる。

/// 新カーネル名 (`kernels_mix_dn7.cu`)。
const MIX_DN7_KERNEL_NAME: &str = "dno_mix_gemv_q8_0_dn7";
/// 引数の数 (w, x, out, n_in, n_out, row_bytes, rows)。
const MIX_DN7_NARGS: usize = 7;
/// 1 ブロックのスレッド上限。
const MIX_DN7_MAX_THREADS: usize = 1024;
/// 1 レーンが担当する要素数 (`.cu` の `16 * sub`)。
const MIX_DN7_LANES: usize = 4;

struct MixDn7Kernels {
    #[allow(dead_code)]
    module: CUmodule,
    f: CUfunction,
}

unsafe impl Send for MixDn7Kernels {}
unsafe impl Sync for MixDn7Kernels {}

static MIX_DN7_KERNELS: OnceLock<Option<MixDn7Kernels>> = OnceLock::new();

fn mix_dn7_ptx_path() -> std::path::PathBuf {
    match std::env::var("DENNO_MIX_DN7_PTX") {
        Ok(p) if !p.is_empty() => std::path::PathBuf::from(p),
        _ => std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("kernels")
            .join("kernels_mix_dn7.ptx"),
    }
}

/// 新カーネルを取得する (初回だけ PTX を読む。失敗は `None` を焼き付ける)。
fn mix_dn7_kernels() -> Option<&'static MixDn7Kernels> {
    MIX_DN7_KERNELS
        .get_or_init(|| {
            let path = mix_dn7_ptx_path();
            let mut image = match std::fs::read(&path) {
                Ok(b) => b,
                Err(_) => return None,
            };
            let text = String::from_utf8_lossy(&image).to_string();
            if ptx_entry_params(&text, MIX_DN7_KERNEL_NAME) != Some(MIX_DN7_NARGS) {
                eprintln!(
                    "[mix-dn7] PTX の引数が {MIX_DN7_NARGS} 本でない → dn6 / dn5 / v5 へ。\
                     `bash build_ptx.sh mix_dn7` で再生成する"
                );
                return None;
            }
            image.push(0);
            let lib = lib().ok()?;
            unsafe {
                let mut module: CUmodule = std::ptr::null_mut();
                if (lib.module_load_data)(&mut module, image.as_ptr() as *const c_void)
                    != CUDA_SUCCESS
                {
                    return None;
                }
                let mut cname = MIX_DN7_KERNEL_NAME.as_bytes().to_vec();
                cname.push(0);
                let mut f: CUfunction = std::ptr::null_mut();
                if (lib.module_get_function)(&mut f, module, cname.as_ptr() as *const c_char)
                    != CUDA_SUCCESS
                {
                    eprintln!("[mix-dn7] PTX に {MIX_DN7_KERNEL_NAME} が無い → dn6 / dn5 / v5 へ");
                    return None;
                }
                Some(MixDn7Kernels { module, f })
            }
        })
        .as_ref()
}

/// 新カーネルが載っているか (テスト / 診断用)。
pub fn mix_dn7_loaded() -> bool {
    mix_dn7_kernels().is_some()
}

/// 起動形 (純関数)。`Some((rows, threads))` なら撃てる。
///
/// `.cu` の前提は「Q8_0 / n_in % 64 == 0 / 1 行あたり np*4 スレッド
/// (np = n_in/64) が 32 の倍数 = np % 8 == 0 / np*4 <= 1024 / warp 数 <= 32」。
/// 実形 (n_in = 10,240) は np = 160 で 1 行 640 スレッド・20 warp。
pub fn mix_dn7_plan(n_in: usize, n_out: usize) -> Option<(usize, usize)> {
    if n_in == 0 || n_out == 0 || n_in % 64 != 0 {
        return None;
    }
    let np = n_in / 64;
    if np == 0 || np % 8 != 0 {
        return None;
    }
    let per_row = np * MIX_DN7_LANES;
    if per_row > MIX_DN7_MAX_THREADS || per_row / 32 > 32 {
        return None;
    }
    // 1 ブロックは 1 行 (rows=1)。2 行にすると per_row*2 が上限を超える実形がある。
    let rows = 1;
    if n_out.div_ceil(rows) > u32::MAX as usize {
        return None;
    }
    Some((rows, per_row))
}

/// 新カーネルを 1 本積む (grid = ceil(n_out / rows)、block = rows * np * 4)。
fn launch_mix_dn7(
    ctx: &CudaCtx,
    w: CUdeviceptr,
    x: CUdeviceptr,
    o: CUdeviceptr,
    n_in: usize,
    n_out: usize,
    row_bytes: usize,
    rows: usize,
    threads: usize,
) -> Result<()> {
    let k = mix_dn7_kernels().ok_or_else(|| anyhow::anyhow!("dn7 のカーネルが無い"))?;
    let (mut pw, mut px, mut po) = (w, x, o);
    let (mut ni, mut no, mut rb) = (n_in as c_int, n_out as c_int, row_bytes as c_int);
    let mut rw = rows as c_int;
    let mut args = [
        &mut pw as *mut _ as *mut c_void,
        &mut px as *mut _ as *mut c_void,
        &mut po as *mut _ as *mut c_void,
        &mut ni as *mut _ as *mut c_void,
        &mut no as *mut _ as *mut c_void,
        &mut rb as *mut _ as *mut c_void,
        &mut rw as *mut _ as *mut c_void,
    ];
    // block = rows (1) * threads。grid は行数。
    unsafe {
        ctx.launch_async(
            k.f,
            (n_out.div_ceil(rows) as u32, 1, 1),
            (threads as u32, 1, 1),
            0,
            &mut args,
        )
    }
}

/// dn7 を撃った回数 (診断。`[mix-qchain]` の `dn7=` に出る)。
static MIX_DN7_HITS: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);

/// dn7 を撃った回数。
pub fn mix_dn7_hits() -> u64 {
    MIX_DN7_HITS.load(std::sync::atomic::Ordering::Relaxed)
}

/// 集計を 0 に戻す。
pub fn mix_dn7_reset() {
    MIX_DN7_HITS.store(0, std::sync::atomic::Ordering::Relaxed);
}

// ---------------------------------------------------------------------------
// task 504: dn7 を mix の down 以外 (GDN の out 投影 / full 層の qkv・wo) へ
// ---------------------------------------------------------------------------
//
// P500 の profile: ssm の out 投影 (n_in 6,144 / n_out 2,560) は dn8 で 16.7 MB
// を 24.8 us = 673 GB/s、full 層の qkv/wo は dn6 で 6.96 MB を 23.4 us =
// 298 GB/s しか出ない。どちらも np が 96 / 40 で、dn8/dn6 は **1 行の和を 1
// レーンが np 本直列**に足す形 (依存鎖 96 / 40 段) なので、latency で止まる。
// dn7 (`kernels_mix_dn7.cu`) は 1 対を 4 レーンに割って 16 要素ずつ積むので
// 依存鎖が 1/4 になる (mix の down では 14.0 -> 12.1 us)。同じ PTX をそのまま
// 撃つだけで、新しい `.cu` は要らない。
//
// 値は丸め順だけが変わる (16 要素ずつ 4 レーンに分けて足す)。ゲート:
//   - GDN の out: `DENNO_GDN_DEC_GEMV=dn8ao7` (qkv は dn8 のまま)
//   - full 層:    `DENNO_FULL_DEC_FAST=dn7` (qkv と wo の両方)
// 既定はどちらも従来どおり (off)。

/// GDN の out 投影だけ dn7 で撃つか (純関数)。
///
/// task 504 (lab t504b で採否): **未設定が既定 on** (ssm 2.93 -> 2.87 = -2.1%、
/// 2 ラウンド同じ、md5 SAME)。
/// - 未設定: true = out を dn7
/// - `dn8ao7` / `dn8o7` / `d8o7` / `d8ao7`: true (明示 on)
/// - それ以外の明示値 (`dn8ar4` / `dn8a` / `dn8` / `dn6` / `v5` / ...): false
///   = その値が決める従来のカーネル。**厳密な切り戻しは `dn8ar4`**
///   (out = dn8 rows 4、t496c の既定)。
pub fn gdn_out_dn7_from_value(v: Option<&str>) -> bool {
    match v.map(str::trim).map(str::to_ascii_lowercase) {
        Some(s) => s.ends_with("o7"),
        None => true,
    }
}

/// [`gdn_out_dn7_from_value`] をプロセスで 1 回だけ読む。
fn gdn_out_dn7_on() -> bool {
    static ON: OnceLock<bool> = OnceLock::new();
    *ON.get_or_init(|| {
        gdn_out_dn7_from_value(std::env::var("DENNO_GDN_DEC_GEMV").ok().as_deref())
    })
}

/// full 層の qkv/wo を dn7 で撃つか (純関数)。`DENNO_FULL_DEC_FAST=dn7` / `d7`。
pub(crate) fn full_dec_dn7_from_value(raw: Option<&str>) -> bool {
    matches!(
        raw.map(|s| s.trim().to_ascii_lowercase()).as_deref(),
        Some("dn7") | Some("d7")
    )
}

/// [`full_dec_dn7_from_value`] をプロセスで 1 回だけ読む。
fn full_dec_dn7_on() -> bool {
    static ON: OnceLock<bool> = OnceLock::new();
    *ON.get_or_init(|| {
        full_dec_dn7_from_value(std::env::var("DENNO_FULL_DEC_FAST").ok().as_deref())
    })
}

/// task 504: dn7 の形で撃ってよいか (型 Q8_0 + 起動形 + PTX)。
fn dn7_dec_plan(ty: crate::kquant::GgmlType, k: usize, n: usize) -> Option<(usize, usize)> {
    if ty != crate::kquant::GgmlType::Q8_0 || mix_dn7_kernels().is_none() {
        return None;
    }
    mix_dn7_plan(k, n)
}

