/// flash decoding を使うか (`DENNO_ATTN_FLASHDEC`)。
pub(crate) fn attn_flashdec_enabled() -> bool {
    #[cfg(test)]
    {
        let f = ATTN_FDEC_FORCE.load(std::sync::atomic::Ordering::Relaxed);
        if f >= 0 {
            return f == 1;
        }
    }
    static ON: OnceLock<bool> = OnceLock::new();
    *ON.get_or_init(|| parse_attn_flashdec(std::env::var("DENNO_ATTN_FLASHDEC").ok().as_deref()))
}

/// この KV 本数未満では flash decoding を使わない (`DENNO_ATTN_FLASHDEC_MIN_CTX`)。
fn attn_flashdec_min_ctx() -> usize {
    #[cfg(test)]
    {
        let f = ATTN_FDEC_MIN_CTX_FORCE.load(std::sync::atomic::Ordering::Relaxed);
        if f != usize::MAX {
            return f;
        }
    }
    static N: OnceLock<usize> = OnceLock::new();
    *N.get_or_init(|| {
        parse_attn_flashdec_min_ctx(std::env::var("DENNO_ATTN_FLASHDEC_MIN_CTX").ok().as_deref())
    })
}

/// 1 分割あたりの key 数 (`DENNO_ATTN_FLASHDEC_CHUNK`)。
fn attn_flashdec_chunk() -> usize {
    #[cfg(test)]
    {
        let f = ATTN_FDEC_CHUNK_FORCE.load(std::sync::atomic::Ordering::Relaxed);
        if f != usize::MAX {
            return f;
        }
    }
    static N: OnceLock<usize> = OnceLock::new();
    *N.get_or_init(|| {
        parse_attn_flashdec_chunk(std::env::var("DENNO_ATTN_FLASHDEC_CHUNK").ok().as_deref())
    })
}

/// この文脈長で使う 1 分割の key 数 (task 460)。
///
//   既定 (未設定・空) と `auto` のときは文脈長で変える ([`q4_fdec_chunk_auto`])。
/// 数値を書いたときだけ [`attn_flashdec_chunk`] の固定値 (切り戻し)。
fn attn_flashdec_chunk_for(t_total: usize) -> usize {
    #[cfg(test)]
    {
        let f = ATTN_FDEC_CHUNK_FORCE.load(std::sync::atomic::Ordering::Relaxed);
        if f != usize::MAX {
            return f;
        }
    }
    static AUTO: OnceLock<bool> = OnceLock::new();
    let auto = *AUTO.get_or_init(|| {
        attn_fdec_chunk_is_auto(std::env::var("DENNO_ATTN_FLASHDEC_CHUNK").ok().as_deref())
    });
    if auto {
        q4_fdec_chunk_auto(t_total)
    } else {
        attn_flashdec_chunk()
    }
}

/// 文脈長から分割数を決める (純関数)。カーネル側の
/// `chunk = ceil(t_total / n_split)` と同じ式で、ホストとカーネルが同じ分割を見る。
///
/// block 数は `n_split x n_kv`。n_kv = 4 のモデルなら 256 key 分割で
/// 14,139 -> 56 分割 = 224 block (SM 170) になり、全 SM が働く。
pub(crate) fn q4_fdec_split(t_total: usize, chunk_keys: usize) -> (usize, usize) {
    if t_total == 0 {
        return (1, 1);
    }
    let keys = chunk_keys.max(ATTN_FLASHDEC_CHUNK_MIN);
    let n = t_total.div_ceil(keys).clamp(1, ATTN_FDEC_SPLIT_MAX);
    let chunk = t_total.div_ceil(n).max(1);
    (t_total.div_ceil(chunk).max(1), chunk)
}

/// 分割数を 1 回だけログる (task 160 の "log it")。len は毎トークン変わるので
/// 分割数が変わったときだけ出す (14k でも数十トークンに 1 行)。
fn fdec_log(len: usize, n_split: usize, chunk: usize, kv_dim: usize, dh: usize, group: usize) {
    static LAST: std::sync::atomic::AtomicUsize =
        std::sync::atomic::AtomicUsize::new(usize::MAX);
    if LAST.load(std::sync::atomic::Ordering::Relaxed) == n_split {
        return;
    }
    if LAST.swap(n_split, std::sync::atomic::Ordering::Relaxed) != n_split {
        eprintln!(
            "[attn-fdec] len={len} n_split={n_split} chunk={chunk} kv_dim={kv_dim} dh={dh} \
             group={group} kv_bytes={:.1}MB",
            (len * kv_dim * 4 * 2) as f64 / (1024.0 * 1024.0)
        );
    }
}

/// flash decoding の PTX (`kernels_attn_dec.ptx`)。`DENNO_ATTN_FLASHDEC_PTX` で
/// 差し替え可 (lab は再生成した PTX をツリーに置いてから測る)。
fn fdec_ptx_path() -> std::path::PathBuf {
    match std::env::var("DENNO_ATTN_FLASHDEC_PTX") {
        Ok(p) if !p.is_empty() => std::path::PathBuf::from(p),
        _ => std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("kernels")
            .join("kernels_attn_dec.ptx"),
    }
}

/// flash decoding のカーネル 2 本。
///
/// `include_bytes!` せず実行時に 1 回だけ読む (このコンテナには nvcc が無く、
/// PTX を先に置かないとビルドが通らないため。exp_iq / gemm_grouped と同じ方針)。
/// 読めない・entry が無い場合は None を焼き付け、呼び出し側は従来カーネルへ落ちる。
struct FdecKernels {
    /// モジュールはプロセス終了まで保持する (unload しない)。
    _module: CUmodule,
    f_dec: CUfunction,
    f_cb: CUfunction,
}

// 生ハンドル (module / function)。CudaCtx と同じ規約。
unsafe impl Send for FdecKernels {}
unsafe impl Sync for FdecKernels {}

fn fdec_kernels() -> Option<&'static FdecKernels> {
    static K: OnceLock<Option<FdecKernels>> = OnceLock::new();
    K.get_or_init(|| {
        let path = fdec_ptx_path();
        let mut image = match std::fs::read(&path) {
            Ok(b) => b,
            Err(e) => {
                eprintln!(
                    "[attn-fdec] PTX が読めない ({}) : {e} → 従来カーネルへ",
                    path.display()
                );
                return None;
            }
        };
        image.push(0);
        let lib = lib().ok()?;
        let mut module: CUmodule = std::ptr::null_mut();
        unsafe {
            if (lib.module_load_data)(&mut module, image.as_ptr() as *const c_void) != CUDA_SUCCESS {
                eprintln!("[attn-fdec] cuModuleLoadData 失敗 → 従来カーネルへ");
                return None;
            }
        }
        let mut f_dec: CUfunction = std::ptr::null_mut();
        let mut f_cb: CUfunction = std::ptr::null_mut();
        unsafe {
            if (lib.module_get_function)(
                &mut f_dec,
                module,
                b"dno_attn_flashdec\0".as_ptr() as *const c_char,
            ) != CUDA_SUCCESS
                || (lib.module_get_function)(
                    &mut f_cb,
                    module,
                    b"dno_attn_flashdec_combine\0".as_ptr() as *const c_char,
                ) != CUDA_SUCCESS
            {
                eprintln!("[attn-fdec] PTX にカーネルが無い (再生成が必要) → 従来カーネルへ");
                return None;
            }
        }
        Some(FdecKernels {
            _module: module,
            f_dec,
            f_cb,
        })
    })
    .as_ref()
}

// ---- task 448: flash decoding 第 2 版 (K/V を shared のタイルへ協調ロード) ----

/// タイル版の PTX (`kernels_attn_dec2.ptx`)。
/// `DENNO_ATTN_FLASHDEC2_PTX` で差し替え可 (lab は再生成した PTX をツリーに置く)。
fn fdt_ptx_path() -> std::path::PathBuf {
    match std::env::var("DENNO_ATTN_FLASHDEC2_PTX") {
        Ok(p) if !p.is_empty() => std::path::PathBuf::from(p),
        _ => std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("kernels")
            .join("kernels_attn_dec2.ptx"),
    }
}

/// タイル版カーネルの引数の個数 (`.cu` と一致させる。kernel_invariants が見る)。
pub(crate) const FDT_NARGS: usize = 11;

/// タイル版の動的 shared の上限 (これを超える形では v1 へ落とす)。
/// 48 KiB は cuLaunchKernel が opt-in 無しで受け付ける上限。
pub(crate) const FDT_SMEM_MAX: usize = 48 * 1024;

/// タイル版の tile 行数の既定 (`DENNO_ATTN_FLASHDEC_TILE`、4..=64)。
const ATTN_FD_TILE_DEFAULT: usize = 16;

/// タイル版の 1 block あたりの動的 shared (バイト)。`.cu` の
/// `2 * tile * dh * sizeof(float)` と一致させること。
pub(crate) fn fdt_smem_bytes(tile: usize, dh: usize) -> usize {
    2 * tile * dh * 4
}

/// タイル版の形の門番 (純関数)。
///
/// `.cu` の前提は「dh が 4 の倍数」「dh <= DNO_FDT_MAXB * 128」「smem <= 48 KiB」。
/// 1 つでも外れたら v1 へ落とす (v1 はこの形をすべて満たしている)。
pub(crate) fn fdt_shape_ok(dh: usize, tile: usize) -> bool {
    dh >= 4
        && dh % 4 == 0
        && dh <= ATTN_FDEC_MAXB * 128
        && (1..=64).contains(&tile)
        && fdt_smem_bytes(tile, dh) <= FDT_SMEM_MAX
}

/// `DENNO_ATTN_FLASHDEC_TILE` の解釈 (純関数)。4..=64 に丸める。
fn parse_attn_fdec_tile(v: Option<&str>) -> usize {
    match v.and_then(|s| s.trim().parse::<usize>().ok()) {
        Some(n) => n.clamp(4, 64),
        None => ATTN_FD_TILE_DEFAULT,
    }
}

/// タイル版の tile 行数 (`DENNO_ATTN_FLASHDEC_TILE`)。
fn attn_fdec_tile() -> usize {
    #[cfg(test)]
    {
        let f = FD_TILE_FORCE.load(std::sync::atomic::Ordering::Relaxed);
        if f != usize::MAX {
            return f.clamp(4, 64);
        }
    }
    static N: OnceLock<usize> = OnceLock::new();
    *N.get_or_init(|| parse_attn_fdec_tile(std::env::var("DENNO_ATTN_FLASHDEC_TILE").ok().as_deref()))
}

#[cfg(test)]
static FD_TILE_FORCE: std::sync::atomic::AtomicUsize =
    std::sync::atomic::AtomicUsize::new(usize::MAX);

/// テスト用: tile 行数を差し替える (`None` で env の解釈に戻す)。
#[cfg(test)]
#[doc(hidden)]
pub fn set_attn_fdec_tile_for_test(n: Option<usize>) {
    FD_TILE_FORCE.store(n.unwrap_or(usize::MAX), std::sync::atomic::Ordering::Relaxed);
}

/// カーネル選択からタイル版の on/off を決める (純関数)。
///
/// `tile` / `fdec2` で on、`fdec1` で off、それ以外 (`split` / `decode` / `pf` /
/// 未設定) は [`ATTN_FLASHDEC_TILE_DEFAULT`] に従う。
pub(crate) fn fdec_tile_from_kernel(k: Q4AttnKernel) -> bool {
    match k {
        Q4AttnKernel::Tile => true,
        Q4AttnKernel::Fdec1 => false,
        _ => ATTN_FLASHDEC_TILE_DEFAULT,
    }
}

/// task 448: タイル版の on/off の **新しい env** (`DENNO_ATTN_FLASHDEC2`)。
///
/// 純関数。未設定・空は `None` (カーネル選択に委ねる)。lab の COND は新しい env 名
/// でも届くが、既存名 (`DENNO_Q4_GPU_ATTN_KERNEL`) の上書きは届かない回があった
/// (t448a では `tile` が効かず v1 が走った) ので、A/B はこちらで取る。
pub(crate) fn fdec_tile_from_env(v: Option<&str>) -> Option<bool> {
    let t = v?.trim().to_ascii_lowercase();
    if t.is_empty() {
        return None;
    }
    match t.as_str() {
        "1" | "on" | "tile" | "true" | "yes" => Some(true),
        _ => Some(false),
    }
}

/// task 448: `DENNO_ATTN_FLASHDEC_TILE` を on/off の門としても使う (純関数)。
///
/// - 未設定・空: `None` (既定 [`ATTN_FLASHDEC_TILE_DEFAULT`] に従う)
/// - `0` / `off` / `false` / `no`: `Some(false)` = タイル版を使わない (v1)
/// - それ以外 (数値・`on` など): `Some(true)` = タイル版。行数は
///   [`parse_attn_fdec_tile`] が 4..=64 に丸める
///
/// lab の COND は **名前に数字を含む env を落とす** 回がある (t448a の
/// `DENNO_Q4_GPU_ATTN_KERNEL=tile` と t448b の `DENNO_ATTN_FLASHDEC2=1` は
/// どちらも届かず v1 が走った。同じ COND の `DENNO_ATTN_FLASHDEC_TILE=24` は
/// 届いた) ので、A/B は数字を含まないこの名前で取る。
pub(crate) fn attn_fdec_tile_ctl(v: Option<&str>) -> Option<bool> {
    let t = v?.trim().to_ascii_lowercase();
    if t.is_empty() {
        return None;
    }
    match t.as_str() {
        "0" | "off" | "false" | "no" => Some(false),
        _ => Some(true),
    }
}

/// `DENNO_ATTN_FLASHDEC_TILE` / `DENNO_ATTN_FLASHDEC2` の実値 (1 回だけ読む)。
fn attn_fdec_tile_env() -> Option<bool> {
    static V: OnceLock<Option<bool>> = OnceLock::new();
    *V.get_or_init(|| {
        attn_fdec_tile_ctl(std::env::var("DENNO_ATTN_FLASHDEC_TILE").ok().as_deref())
            .or_else(|| {
                fdec_tile_from_env(std::env::var("DENNO_ATTN_FLASHDEC2").ok().as_deref())
            })
    })
}

/// task 448: タイル版で回すか (`DENNO_ATTN_FLASHDEC_TILE` が優先、
/// 次に `DENNO_ATTN_FLASHDEC2`、未設定なら `DENNO_Q4_GPU_ATTN_KERNEL`)。
fn attn_fdec_tile_on() -> bool {
    match attn_fdec_tile_env() {
        Some(b) => b,
        None => fdec_tile_from_kernel(q4_gpu_attn_kernel()),
    }
}

/// task 448: 起動時の 1 行 (診断)。lab の COND で env が届いたか、測った
/// バイナリが新しいかをログだけで判別できるようにする。数値経路には触らない。
pub fn attn_fdec_boot_line() -> String {
    let tile_on = attn_fdec_tile_on();
    let k = match q4_gpu_attn_kernel() {
        Q4AttnKernel::Decode => "decode",
        Q4AttnKernel::Prefill => "pf",
        Q4AttnKernel::Split => "split",
        Q4AttnKernel::Tile => "tile",
        Q4AttnKernel::Fdec1 => "fdec1",
    };
    format!(
        "[attn-fdec] kernel={k} fdt_on={tile_on} tile={} ilp={} khx={} fdtv=5 (task 520)",
        attn_fdec_tile(),
        attn_fdec_ilp_on(),
        attn_fdec_khx_on()
    )
}

/// 門の判定を 1 回だけログる (発火しなかった回の原因を lab の log で見るため)。
fn fdt_gate_log(tile_on: bool) {
    static ONCE: std::sync::Once = std::sync::Once::new();
    ONCE.call_once(|| {
        eprintln!(
            "[attn-fdec2] gate tile_on={tile_on} tile={} min_ctx={} \
             (DENNO_ATTN_FLASHDEC_TILE / DENNO_Q4_GPU_ATTN_KERNEL)",
            attn_fdec_tile(),
            attn_flashdec_min_ctx()
        );
    });
}

/// タイル版のカーネル 1 本。読み込み失敗は `None` を焼き付ける (v1 へ落ちる)。
struct FdtKernels {
    /// モジュールはプロセス終了まで保持する (unload しない)。
    _module: CUmodule,
    f_t: CUfunction,
}

unsafe impl Send for FdtKernels {}
unsafe impl Sync for FdtKernels {}

fn fdt_kernels() -> Option<&'static FdtKernels> {
    static K: OnceLock<Option<FdtKernels>> = OnceLock::new();
    K.get_or_init(|| {
        let path = fdt_ptx_path();
        let mut image = match std::fs::read(&path) {
            Ok(b) => b,
            Err(e) => {
                eprintln!(
                    "[attn-fdec2] PTX が読めない ({}) : {e} → v1 の flashdec へ",
                    path.display()
                );
                return None;
            }
        };
        // ABI: 引数の個数が違う PTX を起動すると、足りない引数は不定のまま読まれる。
        // モジュールを載せる前に数えられないと分からないので、ここで弾く。
        let text = String::from_utf8_lossy(&image).into_owned();
        if ptx_entry_params(&text, "dno_attn_flashdec_t") != Some(FDT_NARGS) {
            eprintln!(
                "[attn-fdec2] PTX の dno_attn_flashdec_t が {FDT_NARGS} 引数でない \
                 (再生成が必要) → v1 の flashdec へ"
            );
            return None;
        }
        image.push(0);
        let lib = lib().ok()?;
        let mut module: CUmodule = std::ptr::null_mut();
        unsafe {
            if (lib.module_load_data)(&mut module, image.as_ptr() as *const c_void) != CUDA_SUCCESS {
                eprintln!("[attn-fdec2] cuModuleLoadData 失敗 → v1 の flashdec へ");
                return None;
            }
        }
        let mut f_t: CUfunction = std::ptr::null_mut();
        unsafe {
            if (lib.module_get_function)(
                &mut f_t,
                module,
                b"dno_attn_flashdec_t\0".as_ptr() as *const c_char,
            ) != CUDA_SUCCESS
            {
                eprintln!("[attn-fdec2] PTX に dno_attn_flashdec_t が無い → v1 の flashdec へ");
                return None;
            }
        }
        let k = FdtKernels { _module: module, f_t };
        fdt_loaded_log();
        Some(k)
    })
    .as_ref()
}

/// モジュールが載ったことを 1 回だけログる (発火の証拠。tile 行数と env も出す)。
fn fdt_loaded_log() {
    static ONCE: std::sync::Once = std::sync::Once::new();
    ONCE.call_once(|| {
        eprintln!(
            "[attn-fdec2] PTX ok: dno_attn_flashdec_t nargs={} tile={} (DENNO_ATTN_FLASHDEC2)",
            FDT_NARGS,
            attn_fdec_tile()
        );
    });
}

/// タイル版の分割・tile を 1 回だけログる (発火の証拠。tile か n_split が
/// 変わったときだけ出す)。
fn fdt_log(len: usize, n_split: usize, chunk: usize, dh: usize, tile: usize) {
    static LAST: std::sync::atomic::AtomicUsize =
        std::sync::atomic::AtomicUsize::new(usize::MAX);
    let key = n_split.wrapping_mul(1024).wrapping_add(tile);
    if LAST.load(std::sync::atomic::Ordering::Relaxed) == key {
        return;
    }
    if LAST.swap(key, std::sync::atomic::Ordering::Relaxed) != key {
        eprintln!(
            "[attn-fdec2] len={len} n_split={n_split} chunk={chunk} dh={dh} tile={tile} \
             smem={}KiB",
            fdt_smem_bytes(tile, dh) / 1024
        );
    }
}

// ---- task 520: flash decoding 第 3 版 (2 key 同時、`kernels_attn_dec5.cu`) -----
//
// 動機 (t520a の `[dec-kprof-avg]`): `dno_attn_flashdec_t` は 14k で 66.4 us/層、
// 2k で 29.3 us/層。key 数が 7 倍でも時間は 2.3 倍 = **1 key の単価がほぼ一定**
// (458 -> 519 ns) で、帯域ではなく命令発行と依存鎖で決まっている。第 3 版は
// 「2 key の内積と shfl 縮約を交互に出す」+「max が動かない key では acc の
// 乗算を省く」。どちらも算術の列を変えないので **値は第 2 版とビット一致**。

/// 第 3 版の引数の個数 (`.cu` と一致。第 2 版の 11 本 + grid 入れ替えの 1 本)。
pub(crate) const FDT2_NARGS: usize = 12;

/// `DENNO_ATTN_FLASHDEC_ILP` の解釈 (純関数)。**既定 on**。
/// 明示的な偽値 (`0` / `off` / `false` / `no`) のときだけ第 2 版へ戻す。
pub(crate) fn parse_attn_fdec_ilp(v: Option<&str>) -> bool {
    match v {
        Some(s) => !matches!(
            s.trim().to_ascii_lowercase().as_str(),
            "0" | "off" | "false" | "no"
        ),
        None => true,
    }
}

