/// カーネルの前提 (k <= 32 / ne <= 1024)。純関数。
pub(crate) fn pf_router_dev_ok(nt: usize, ne: usize, k: usize) -> bool {
    nt >= 1 && (1..=32).contains(&k) && (1..=1024).contains(&ne)
}

struct RouterDevSc {
    x: Option<DevBuffer>,
    logits: Option<DevBuffer>,
    sels: Option<DevBuffer>,
    wts: Option<DevBuffer>,
    rowsum: Option<DevBuffer>,
}

thread_local! {
    static ROUTER_DEV_SC: std::cell::RefCell<RouterDevSc> = const {
        std::cell::RefCell::new(RouterDevSc {
            x: None,
            logits: None,
            sels: None,
            wts: None,
            rowsum: None,
        })
    };
}

/// task 225: logits をデバイスに残したまま softmax → top-k → 再正規化まで回す。
///
/// `dev_x` が `Some` なら入力は既にデバイスにある (`DENNO_PF_MIXDEVIN` の
/// `mixed`)、`None` ならホストの `xs` を上げる。`sels` / `wts` は `nt * k`、
/// `rowsum` は `nt` 要素。`false` = デバイスでやらなかった (呼び出し側は
/// 従来のホスト経路へ)。
#[allow(clippy::too_many_arguments)]
pub fn pf_router_dev_topk(
    uid: u64,
    bytes: &[u8],
    k_in: usize,
    n: usize,
    dev_x: Option<CUdeviceptr>,
    xs: Option<&[f32]>,
    nt: usize,
    k: usize,
    sels: &mut [u32],
    wts: &mut [f32],
    rowsum: &mut [f32],
    src_ty: crate::kquant::GgmlType,
) -> bool {
    let bpp = match src_ty {
        crate::kquant::GgmlType::F32 => 4usize,
        crate::kquant::GgmlType::Bf16 | crate::kquant::GgmlType::F16 => 2,
        _ => return false,
    };
    if !cuda_enabled()
        || !pf_router_dev_ok(nt, n, k)
        || sels.len() != nt * k
        || wts.len() != nt * k
        || rowsum.len() != nt
        || k_in == 0
        || bytes.len() != k_in.saturating_mul(n).saturating_mul(bpp)
        || match (dev_x, xs) {
            (Some(p), _) => p == 0,
            (None, Some(x)) => x.len() != nt * k_in,
            (None, None) => true,
        }
    {
        return false;
    }
    let Some(ctx) = shared_ctx() else {
        return false;
    };
    if ctx.make_current().is_err() {
        return false;
    }
    // logits の GEMM は専用カーネル (`dno_gemm_f32_ba`) が使えればそちら。
    // 使えないときだけ `dno_gemm_f32_mt` を要求する。
    let f_gemm = gemm_f32_mt_fn(ctx);
    let Some(f_rt) = router_dev_fns(ctx) else {
        return false;
    };
    let f_rt = f_rt.kernel;
    let w = match weights_for_gemm_f32(uid, bytes, k_in, n, src_ty) {
        Ok(w) => w,
        Err(_) => return false,
    };
    let Ok(lib) = lib() else {
        return false;
    };
    let r = ROUTER_DEV_SC.with(|cell| -> Result<()> {
        let mut s = cell.borrow_mut();
        let RouterDevSc {
            x: dx,
            logits: dlogit,
            sels: dsel,
            wts: dwt,
            rowsum: drs,
        } = &mut *s;
        let xp = match (dev_x, xs) {
            (Some(p), _) => p,
            (None, Some(host)) => {
                Scratch::ensure(dx, nt * k_in * 4)?;
                let dx = dx.as_ref().unwrap();
                dx.copy_from(host)?;
                dx.ptr()
            }
            (None, None) => return Ok(()),
        };
        Scratch::ensure(dlogit, nt * n * 4)?;
        Scratch::ensure(dsel, nt * k * 4)?;
        Scratch::ensure(dwt, nt * k * 4)?;
        Scratch::ensure(drs, nt * 4)?;
        let (dlogit, dsel, dwt, drs) = (
            dlogit.as_ref().unwrap(),
            dsel.as_ref().unwrap(),
            dwt.as_ref().unwrap(),
            drs.as_ref().unwrap(),
        );
        let wp = w.buf.ptr();
        unsafe {
            // 1) logits = W @ x^T (デバイスに残す)。task 225: 専用 GEMM
            // (`dno_gemm_f32_ba`) が使えればそちら (累積順は同じ k 昇順なので値は
            // ビット一致)。使えなければ従来の `dno_gemm_f32_mt`。
            let fast = pf_ba_gemm_dev_launch(ctx, wp, xp, dlogit.ptr(), nt, k_in, n)?;
            if !fast {
                let Some(f_gemm) = f_gemm else {
                    return Ok(());
                };
                let (mut pw, mut px, mut po) = (wp, xp, dlogit.ptr());
                let (mut nt_c, mut k_c, mut n_c) = (nt as c_int, k_in as c_int, n as c_int);
                let mut args = [
                    &mut pw as *mut _ as *mut c_void,
                    &mut px as *mut _ as *mut c_void,
                    &mut po as *mut _ as *mut c_void,
                    &mut nt_c as *mut _ as *mut c_void,
                    &mut k_c as *mut _ as *mut c_void,
                    &mut n_c as *mut _ as *mut c_void,
                ];
                let grid = (
                    n.div_ceil(GEMM_MT_ROWS) as u32,
                    nt.div_ceil(GEMM_MT_TOKS) as u32,
                    1,
                );
                ctx.launch_async(f_gemm, grid, (GEMM_MT_ROWS as u32, 16, 1), 0, &mut args)?;
            }
            // 2) softmax + top-k + 再正規化
            let (mut pl, mut ps, mut pwt, mut prs) =
                (dlogit.ptr(), dsel.ptr(), dwt.ptr(), drs.ptr());
            let (mut nt_c, mut ne_c, mut k_c) = (nt as c_int, n as c_int, k as c_int);
            let mut args = [
                &mut pl as *mut _ as *mut c_void,
                &mut ps as *mut _ as *mut c_void,
                &mut pwt as *mut _ as *mut c_void,
                &mut prs as *mut _ as *mut c_void,
                &mut nt_c as *mut _ as *mut c_void,
                &mut ne_c as *mut _ as *mut c_void,
                &mut k_c as *mut _ as *mut c_void,
            ];
            let grid = (nt.div_ceil(4) as u32, 1, 1);
            ctx.launch_async(f_rt, grid, (128, 1, 1), 0, &mut args)?;
            ctx.sync()?;
            // 3) 選んだ k 個と重みだけ降ろす
            check(
                (lib.memcpy_dtoh)(
                    sels.as_mut_ptr() as *mut c_void,
                    dsel.ptr(),
                    nt * k * 4,
                ),
                "cuMemcpyDtoH (router sels)",
            )?;
            check(
                (lib.memcpy_dtoh)(wts.as_mut_ptr() as *mut c_void, dwt.ptr(), nt * k * 4),
                "cuMemcpyDtoH (router wts)",
            )?;
            check(
                (lib.memcpy_dtoh)(
                    rowsum.as_mut_ptr() as *mut c_void,
                    drs.ptr(),
                    nt * 4,
                ),
                "cuMemcpyDtoH (router rowsum)",
            )?;
        }
        Ok(())
    });
    r.is_ok()
}

// ---------------------------------------------------------------------------
// task 173: prefill の GDN スキャンを「状態レジスタ常駐 + 4 レーン分割」へ
// ---------------------------------------------------------------------------
//
// 既存 `dno_gdn_scan_sig` (gdn.cu) は 1 ブロック = dk スレッドで、状態の列
// (dk = 128 float = 1 KiB) をスレッドローカルの配列に持つ。作業集合 128 KiB が
// L1 に収まらず毎トークン L2 へ落ちるため、lab t169b の実測は 10.7 us/token
// (1 層 1 チャンク 512 トークンで 5.5 ms = 14k prefill の 5.5 s)。
//
// `kernels_gdn_pf.cu` の `dno_gdn_pf_scan128` は同じ演算を 512 スレッド
// (128 列 × 4 レーン) で回し、状態をレジスタに置く (ローカルメモリ往復なし)。
// 要素ごとの更新は同一の丸め、縮約 (q/k ノルム・skv・o・出力 RMS) だけが
// 4 本の部分和の結合になる (丸め順の差のみ)。
//
// PTX: `bash build_ptx.sh gdn_pf` (lab は `PTX=gdn_pf` で再生成する)。
// このコンテナには nvcc が無いので生成は GPU 側。

/// 新カーネルの 1 ヘッド次元 (`kernels_gdn_pf.cu` の PF_DK と一致)。
const GDN_PF_DK: usize = 128;
/// 新カーネルのスレッド数 (`PF_DK * PF_LANES` = 128 * 4)。
const GDN_PF_SCAN_THREADS: usize = 512;

/// `DENNO_GDN_PF_FAST` の値の解釈 (純関数)。`0`/`off`/`false`/`no`/空だけが off。
///
/// 既定 on: lab t174b (SHA 99807fa7d、新ホスト、SCENARIO=depth8k、PROFILE=1) で採用。
/// cold prefill 3,826 tok 20.55 -> 19.74 s (-4.0%)、14,018 tok 71.70 -> 66.80 s (-6.8%)、
/// decode は 1 トークンあたりの合計で -0.4 〜 +0.4% (median の ±1 ms は量子化)、
/// base COND は errors 0 のまま。md5 DIFF は縮約順の差 (仕様)。
pub(crate) fn gdn_pf_fast_from_value(v: Option<&str>) -> bool {
    match v.map(|s| s.trim().to_ascii_lowercase()) {
        None => true,
        Some(s) => !matches!(s.as_str(), "0" | "off" | "false" | "no" | ""),
    }
}

/// 新しいスキャンカーネルを使うか (既定 on)。
pub(crate) fn gdn_pf_fast_on() -> bool {
    #[cfg(test)]
    {
        match PF_FAST_FORCE.load(Ordering::Relaxed) {
            1 => return false,
            2 => return true,
            _ => {}
        }
    }
    static ON: OnceLock<bool> = OnceLock::new();
    *ON.get_or_init(|| gdn_pf_fast_from_value(std::env::var("DENNO_GDN_PF_FAST").ok().as_deref()))
}

#[cfg(test)]
static PF_FAST_FORCE: std::sync::atomic::AtomicU8 = std::sync::atomic::AtomicU8::new(0);

/// テスト用にゲートを固定する (`None` で env に戻す)。
#[cfg(test)]
pub(crate) fn set_gdn_pf_fast_for_test(v: Option<bool>) {
    PF_FAST_FORCE.store(
        match v {
            None => 0,
            Some(false) => 1,
            Some(true) => 2,
        },
        Ordering::Relaxed,
    );
}

/// 新しいスキャンカーネルが受ける形か (純関数。カーネルの前提と同じ)。
pub(crate) fn gdn_pf_fast_eligible(
    nt: usize,
    nk: usize,
    nv: usize,
    dk: usize,
    dv: usize,
    d_conv: usize,
    conv_dim: usize,
) -> bool {
    nt >= 1
        && nk >= 1
        && nv >= 1
        && dk == GDN_PF_DK
        && dv == GDN_PF_DK
        && d_conv == 4
        && conv_dim == 2 * nk * dk + nv * dv
}

#[cfg(test)]
mod gdn_pf_fast_tests {
    use super::*;

    /// ゲートの真理値表 (既定は on。lab t174b で採用)。
    #[test]
    fn gate_truth_table() {
        assert!(gdn_pf_fast_from_value(None), "未設定は既定 on");
        for v in ["0", "off", "false", "no", "", " OFF "] {
            assert!(!gdn_pf_fast_from_value(Some(v)), "{v}");
        }
        for v in ["1", "on", "true", "yes", "anything"] {
            assert!(gdn_pf_fast_from_value(Some(v)), "{v}");
        }
    }

    /// 形のゲート: 実モデル (nk=16 / nv=48 / dk=dv=128) だけを受ける。
    #[test]
    fn shape_gate() {
        let conv_dim = 2 * 16 * 128 + 48 * 128;
        assert_eq!(conv_dim, 10240);
        assert!(gdn_pf_fast_eligible(1, 16, 48, 128, 128, 4, conv_dim));
        assert!(gdn_pf_fast_eligible(512, 16, 48, 128, 128, 4, conv_dim));
        assert!(gdn_pf_fast_eligible(2048, 16, 48, 128, 128, 4, conv_dim));
        // dk != 128 / d_conv != 4 / conv_dim 不一致 / nt=0 は受けない。
        assert!(!gdn_pf_fast_eligible(512, 16, 48, 64, 64, 4, 2 * 16 * 64 + 48 * 64));
        assert!(!gdn_pf_fast_eligible(512, 16, 48, 128, 128, 3, conv_dim));
        assert!(!gdn_pf_fast_eligible(512, 16, 48, 128, 128, 4, conv_dim + 1));
        assert!(!gdn_pf_fast_eligible(0, 16, 48, 128, 128, 4, conv_dim));
        assert!(!gdn_pf_fast_eligible(512, 0, 48, 128, 128, 4, conv_dim));
    }

    /// テスト用の強制スイッチが env 解決を上書きする (戻し忘れない)。
    #[test]
    fn force_switch_overrides_env() {
        set_gdn_pf_fast_for_test(Some(true));
        assert!(gdn_pf_fast_on());
        set_gdn_pf_fast_for_test(Some(false));
        assert!(!gdn_pf_fast_on());
        set_gdn_pf_fast_for_test(None);
    }
}

/// 新しいスキャンカーネルのモジュール (PTX は実行時読み込み)。
struct GdnPfKernels {
    #[allow(dead_code)]
    module: CUmodule,
    scan128: CUfunction,
}

unsafe impl Send for GdnPfKernels {}
unsafe impl Sync for GdnPfKernels {}

static GDN_PF_K: OnceLock<Option<GdnPfKernels>> = OnceLock::new();

/// PTX の置き場所。`DENNO_GDN_PF_PTX` があればそれ、無ければクレートの
/// `kernels/kernels_gdn_pf.ptx`。
fn gdn_pf_ptx_path() -> std::path::PathBuf {
    match std::env::var("DENNO_GDN_PF_PTX") {
        Ok(p) if !p.is_empty() => std::path::PathBuf::from(p),
        _ => std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("kernels")
            .join("kernels_gdn_pf.ptx"),
    }
}

/// カーネルを取得する (初回だけ PTX を読む)。失敗は None を焼き付ける。
/// **current context を張った後に呼ぶこと**。
fn gdn_pf_kernels() -> Option<&'static GdnPfKernels> {
    GDN_PF_K
        .get_or_init(|| {
            let path = gdn_pf_ptx_path();
            let mut image = match std::fs::read(&path) {
                Ok(b) => b,
                Err(e) => {
                    eprintln!(
                        "[gdn-pf] PTX が読めない ({}) : {e} → 従来のスキャンへ",
                        path.display()
                    );
                    return None;
                }
            };
            image.push(0);
            let lib = lib().ok()?;
            let mut module: CUmodule = std::ptr::null_mut();
            unsafe {
                if (lib.module_load_data)(&mut module, image.as_ptr() as *const c_void)
                    != CUDA_SUCCESS
                {
                    eprintln!("[gdn-pf] cuModuleLoadData 失敗 → 従来のスキャンへ");
                    return None;
                }
                let mut scan128: CUfunction = std::ptr::null_mut();
                if (lib.module_get_function)(
                    &mut scan128,
                    module,
                    b"dno_gdn_pf_scan128\0".as_ptr() as *const c_char,
                ) != CUDA_SUCCESS
                {
                    eprintln!("[gdn-pf] PTX に dno_gdn_pf_scan128 が無い → 従来のスキャンへ");
                    return None;
                }
                log_kernel_attr(lib, scan128, "dno_gdn_pf_scan128");
                Some(GdnPfKernels { module, scan128 })
            }
        })
        .as_ref()
}

/// task 173: レジスタ常駐スキャンを 1 回撃つ (引数はカーネルの並び)。
///
/// 起動サイトは `fns.scan128` なので、kernel_invariants の起動サイト表が
/// カーネル名 (`dno_gdn_pf_scan128`) と block 形状 (512) に解決できる。
#[allow(clippy::too_many_arguments)]
fn gdn_pf_scan128_launch(
    ctx: &CudaCtx,
    fns: &GdnPfKernels,
    qkv: CUdeviceptr,
    z: CUdeviceptr,
    beta: CUdeviceptr,
    alpha: CUdeviceptr,
    conv_st_in: CUdeviceptr,
    ssm_in: CUdeviceptr,
    wconv: CUdeviceptr,
    wa: CUdeviceptr,
    wdt: CUdeviceptr,
    wnorm: CUdeviceptr,
    y_out: CUdeviceptr,
    conv_st_out: CUdeviceptr,
    ssm_out: CUdeviceptr,
    n: usize,
    nk: usize,
    nv: usize,
    conv_dim: usize,
    eps: f32,
    q_scale: f32,
) -> Result<()> {
    let (mut pq, mut pzz, mut pbb, mut paa) = (qkv, z, beta, alpha);
    let (mut pci, mut psi) = (conv_st_in, ssm_in);
    let (mut pwc, mut pwa, mut pwd, mut pwn) = (wconv, wa, wdt, wnorm);
    let (mut pyy, mut pco, mut pso) = (y_out, conv_st_out, ssm_out);
    let (mut ni, mut nki, mut nvi) = (n as c_int, nk as c_int, nv as c_int);
    let (mut cdi, mut epsi, mut qsi) = (conv_dim as c_int, eps, q_scale);
    let mut args = [
        &mut pq as *mut _ as *mut c_void,
        &mut pzz as *mut _ as *mut c_void,
        &mut pbb as *mut _ as *mut c_void,
        &mut paa as *mut _ as *mut c_void,
        &mut pci as *mut _ as *mut c_void,
        &mut psi as *mut _ as *mut c_void,
        &mut pwc as *mut _ as *mut c_void,
        &mut pwa as *mut _ as *mut c_void,
        &mut pwd as *mut _ as *mut c_void,
        &mut pwn as *mut _ as *mut c_void,
        &mut pyy as *mut _ as *mut c_void,
        &mut pco as *mut _ as *mut c_void,
        &mut pso as *mut _ as *mut c_void,
        &mut ni as *mut _ as *mut c_void,
        &mut nki as *mut _ as *mut c_void,
        &mut nvi as *mut _ as *mut c_void,
        &mut cdi as *mut _ as *mut c_void,
        &mut epsi as *mut _ as *mut c_void,
        &mut qsi as *mut _ as *mut c_void,
    ];
    unsafe {
        ctx.launch_async(
            fns.scan128,
            (nv as u32, 1, 1),
            (GDN_PF_SCAN_THREADS as u32, 1, 1),
            0,
            &mut args,
        )
    }
}

// ---------------------------------------------------------------------------
// task 186: カーネル属性の診断 (DENNO_KERNEL_ATTR=1 のとき 1 行)
// ---------------------------------------------------------------------------
//
// PTX の仮想レジスタ数 (`%f<1161>` など) は NVVM の SSA 形なので実際の割り当ては
// 分からない。JIT 後の実体を `cuFuncGetAttribute` で読むと、ptxas が割り当てた
// レジスタ数とローカルメモリ (スピル) のバイト数が読める。scan が「レジスタに
// 載っていない」疑いを潰すための計測 (既定 off)。
fn log_kernel_attr(lib: &CudaLib, f: CUfunction, name: &str) {
    static ON: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    if !*ON.get_or_init(|| std::env::var_os("DENNO_KERNEL_ATTR").is_some()) {
        return;
    }
    let Some(g) = lib.func_get_attribute else {
        return;
    };
    // CU_FUNC_ATTRIBUTE_MAX_THREADS_PER_BLOCK=0 / SHARED_SIZE_BYTES=1 /
    // LOCAL_SIZE_BYTES=3 / NUM_REGS=4。
    let (mut regs, mut local, mut smem, mut maxthr) = (-1i32, -1i32, -1i32, -1i32);
    unsafe {
        if g(&mut regs, 4, f) != CUDA_SUCCESS {
            regs = -1;
        }
        if g(&mut local, 3, f) != CUDA_SUCCESS {
            local = -1;
        }
        if g(&mut smem, 1, f) != CUDA_SUCCESS {
            smem = -1;
        }
        if g(&mut maxthr, 0, f) != CUDA_SUCCESS {
            maxthr = -1;
        }
    }
    eprintln!(
        "[kattr] {name}: num_regs={regs} local_bytes={local} shared_bytes={smem} max_threads={maxthr}"
    );
}

// ---------------------------------------------------------------------------
// task 186: prefill GDN スキャン v2 (`kernels_gdn_pf2.cu`、DENNO_PF_SCAN_FAST)
// ---------------------------------------------------------------------------
//
// `dno_gdn_pf_scan128` は 1 ブロック = 1 ヘッド (128 列) で 48 ブロックしかなく、
// 1 トークンあたり barrier 3 回と単一スレッドの超越関数を払う。lab t183a の実測は
// 5.53 us/トークン (16.3 GB/s, 0.85 TFLOP/s)。v2 は
//   - 1 ブロック = 64 列 (2 ブロックで 1 ヘッド) → 96 ブロック
//   - conv の窓をレーンごとに 1 チャネルずつ分散し、3 段リングで 2 トークン先を
//     先に埋める (barrier は 1 トークン 1 回)
//   - 出力の gated RMS norm は別カーネル `dno_gdn_pf_norm128`
// で回す。値は `dno_gdn_pf_scan128` とビット一致 (同じ状態の持ち方・同じ縮約の木・
// 同じ式) なので、採否は速度だけで決まる。PTX は
// `kernels/kernels_gdn_pf2.ptx` を実行時に読む (無ければ従来へ fail closed)。

/// v2 スキャンのスレッド数 (カーネルの PF2_THREADS)。
pub(crate) const GDN_PF2_THREADS: usize = 256;
/// v2 スキャンの 1 ブロックあたりの列数 (カーネルの PF2_COLS)。
pub(crate) const GDN_PF2_COLS: usize = 64;
/// RMS norm カーネルのスレッド数 (カーネルの PF2_NORM_THREADS)。
pub(crate) const GDN_PF2_NORM_THREADS: usize = 128;

/// task 186: `kernels_gdn_pf2.cu` の関数一式。
struct GdnPf2Kernels {
    #[allow(dead_code)]
    module: CUmodule,
    scan64: CUfunction,
    norm: CUfunction,
}

// 生ハンドル (GdnPfKernels と同じ規約)。
unsafe impl Send for GdnPf2Kernels {}
unsafe impl Sync for GdnPf2Kernels {}

/// PTX の置き場所。`DENNO_GDN_PF2_PTX` があればそれ、無ければクレートの
/// `kernels/kernels_gdn_pf2.ptx`。
fn gdn_pf2_ptx_path() -> std::path::PathBuf {
    match std::env::var("DENNO_GDN_PF2_PTX") {
        Ok(p) if !p.is_empty() => std::path::PathBuf::from(p),
        _ => std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("kernels")
            .join("kernels_gdn_pf2.ptx"),
    }
}

/// カーネルを取得する (初回だけ PTX を読む)。失敗は None を焼き付ける。
/// **current context を張った後に呼ぶこと**。
fn gdn_pf2_kernels() -> Option<&'static GdnPf2Kernels> {
    static K: OnceLock<Option<GdnPf2Kernels>> = OnceLock::new();
    K.get_or_init(|| {
        let path = gdn_pf2_ptx_path();
        let mut image = match std::fs::read(&path) {
            Ok(b) => b,
            Err(e) => {
                eprintln!(
                    "[gdn-pf2] PTX が読めない ({}) : {e} → 従来のスキャンへ",
                    path.display()
                );
                return None;
            }
        };
        image.push(0);
        let lib = lib().ok()?;
        let mut module: CUmodule = std::ptr::null_mut();
        unsafe {
            if (lib.module_load_data)(&mut module, image.as_ptr() as *const c_void) != CUDA_SUCCESS {
                eprintln!("[gdn-pf2] cuModuleLoadData 失敗 → 従来のスキャンへ");
                return None;
            }
            let mut scan64: CUfunction = std::ptr::null_mut();
            if (lib.module_get_function)(
                &mut scan64,
                module,
                b"dno_gdn_pf_scan64\0".as_ptr() as *const c_char,
            ) != CUDA_SUCCESS
            {
                eprintln!("[gdn-pf2] PTX に dno_gdn_pf_scan64 が無い → 従来のスキャンへ");
                return None;
            }
            let mut norm: CUfunction = std::ptr::null_mut();
            if (lib.module_get_function)(
                &mut norm,
                module,
                b"dno_gdn_pf_norm128\0".as_ptr() as *const c_char,
            ) != CUDA_SUCCESS
            {
                eprintln!("[gdn-pf2] PTX に dno_gdn_pf_norm128 が無い → 従来のスキャンへ");
                return None;
            }
            log_kernel_attr(lib, scan64, "dno_gdn_pf_scan64");
            log_kernel_attr(lib, norm, "dno_gdn_pf_norm128");
            Some(GdnPf2Kernels {
                module,
                scan64,
                norm,
            })
        }
    })
    .as_ref()
}

/// `DENNO_PF_SCAN_FAST` の解釈 (純関数)。`0`/`off`/`false`/`no`/空だけが off。
///
/// task 189: **既定 on**。lab t187c で scan_pf 2,853 -> 1,295 ms (md5 SAME)、
/// wall -3.2% を確認済み (task 186 では目標未達だったため off のままだった)。
/// `DENNO_PF_SCAN_FAST=0` で従来の `gdn_pf` スキャンに戻る。
pub(crate) fn gdn_pf2_from_value(v: Option<&str>) -> bool {
    match v {
        None => true,
        Some(s) => !matches!(s.trim(), "0" | "off" | "false" | "no" | ""),
    }
}

#[cfg(test)]
static PF2_FORCE: std::sync::atomic::AtomicU8 = std::sync::atomic::AtomicU8::new(0);

/// テスト用にゲートを固定する (`None` で env に戻す)。
#[cfg(test)]
pub(crate) fn set_gdn_pf2_for_test(v: Option<bool>) {
    PF2_FORCE.store(
        match v {
            None => 0,
            Some(false) => 1,
            Some(true) => 2,
        },
        Ordering::Relaxed,
    );
}

/// v2 スキャンを使うか (既定 on。`DENNO_PF_SCAN_FAST=0` で off)。
pub(crate) fn gdn_pf2_on() -> bool {
    #[cfg(test)]
    {
        match PF2_FORCE.load(Ordering::Relaxed) {
            1 => return false,
            2 => return true,
            _ => {}
        }
    }
    static ON: OnceLock<bool> = OnceLock::new();
    *ON.get_or_init(|| gdn_pf2_from_value(std::env::var("DENNO_PF_SCAN_FAST").ok().as_deref()))
}

/// v2 スキャンが受ける形か (純関数。カーネルの前提と同じ)。
pub(crate) fn gdn_pf2_ok(
    nt: usize,
    nk: usize,
    nv: usize,
    dk: usize,
    dv: usize,
    d_conv: usize,
    conv_dim: usize,
) -> bool {
    nt >= 1
        && nk >= 1
        && nv >= 1
        && dk == GDN_PF_DK
        && dv == GDN_PF_DK
        && d_conv == 4
        && conv_dim == 2 * nk * dk + nv * dv
}

/// task 186: v2 スキャンを撃つ (scan64 → norm128 の 2 起動)。引数の並びは
/// カーネルの宣言順。`o_out` と `y_out` は同じバッファでよい (norm は in-place)。
#[allow(clippy::too_many_arguments)]
fn gdn_pf2_launch(
    ctx: &CudaCtx,
    fns: &GdnPf2Kernels,
    qkv: CUdeviceptr,
    z: CUdeviceptr,
    beta: CUdeviceptr,
    alpha: CUdeviceptr,
    conv_st_in: CUdeviceptr,
    ssm_in: CUdeviceptr,
    wconv: CUdeviceptr,
    wa: CUdeviceptr,
    wdt: CUdeviceptr,
    wnorm: CUdeviceptr,
    y_out: CUdeviceptr,
    conv_st_out: CUdeviceptr,
    ssm_out: CUdeviceptr,
    n: usize,
    nk: usize,
    nv: usize,
    conv_dim: usize,
    eps: f32,
    q_scale: f32,
) -> Result<()> {
    {
        let (mut pq, mut pb, mut pa) = (qkv, beta, alpha);
        let (mut pci, mut psi) = (conv_st_in, ssm_in);
        let (mut pwc, mut pwa, mut pwd) = (wconv, wa, wdt);
        let (mut py, mut pco, mut pso) = (y_out, conv_st_out, ssm_out);
        let (mut ni, mut nki, mut nvi) = (n as c_int, nk as c_int, nv as c_int);
        let (mut cdi, mut epsi, mut qsi) = (conv_dim as c_int, eps, q_scale);
        let mut args = [
            &mut pq as *mut _ as *mut c_void,
            &mut pb as *mut _ as *mut c_void,
            &mut pa as *mut _ as *mut c_void,
            &mut pci as *mut _ as *mut c_void,
            &mut psi as *mut _ as *mut c_void,
            &mut pwc as *mut _ as *mut c_void,
            &mut pwa as *mut _ as *mut c_void,
            &mut pwd as *mut _ as *mut c_void,
            &mut py as *mut _ as *mut c_void,
            &mut pco as *mut _ as *mut c_void,
            &mut pso as *mut _ as *mut c_void,
            &mut ni as *mut _ as *mut c_void,
            &mut nki as *mut _ as *mut c_void,
            &mut nvi as *mut _ as *mut c_void,
            &mut cdi as *mut _ as *mut c_void,
            &mut epsi as *mut _ as *mut c_void,
            &mut qsi as *mut _ as *mut c_void,
        ];
        // 1 ヘッドを 2 ブロックが分担する (64 列ずつ)。
        unsafe {
            ctx.launch_async(
                fns.scan64,
                (nv as u32, 2, 1),
                (GDN_PF2_THREADS as u32, 1, 1),
                0,
                &mut args,
            )?;
        }
    }
    {
        let (mut py, mut pz, mut pwn) = (y_out, z, wnorm);
        let (mut ni, mut nvi) = (n as c_int, nv as c_int);
        let mut epsi = eps;
        let mut args = [
            &mut py as *mut _ as *mut c_void,
            &mut pz as *mut _ as *mut c_void,
            &mut pwn as *mut _ as *mut c_void,
            &mut ni as *mut _ as *mut c_void,
            &mut nvi as *mut _ as *mut c_void,
            &mut epsi as *mut _ as *mut c_void,
        ];
        let groups = n.saturating_mul(nv);
        let per_block = GDN_PF2_NORM_THREADS / 4;
        let grid = (groups.div_ceil(per_block)) as u32;
        unsafe {
            ctx.launch_async(
                fns.norm,
                (grid, 1, 1),
                (GDN_PF2_NORM_THREADS as u32, 1, 1),
                0,
                &mut args,
            )?;
        }
    }
    Ok(())
}

// ---------------------------------------------------------------------------
// task 186: ssm の beta/alpha 射影 (F32 重み) をデバイスで回す
// (`DENNO_PF_SSM_GEMM_GPU`、既定 off)
// ---------------------------------------------------------------------------
//
// lab t183a の 14k prefill で `beta_pf` は 712 ms (1008 呼び出し = 0.71 ms/回)。
// CPU の `gemv_batch_split` は 0.25 GFLOP/回 を 16 スレッドで回しており、
// 実効 0.36 TFLOP/s。同じ層の隣の qkv GEMM は 74.8 TFLOP/s なので 200 倍の差。
// 入力 (x) は連鎖が既にデバイスへ上げており、出力 (beta/alpha) も連鎖がデバイスで
// 使うので、**ホストを経由せずに** `dno_gemm_f32_mt` で作れる (転送 0)。
// 丸めは FMA + タイル順なので CPU の mul+add 逐次とは一致しない (丸めだけの差)。

/// task 186: beta/alpha 射影をデバイスで回すための指定 (連結済みの F32 重み)。
#[derive(Clone)]
pub struct PfBetaAlpha<'a> {
    /// beta の重み (`k = n_embd`)。連結済みなら beta 行 + alpha 行を持つ。
    pub w: PfChainW<'a>,
    /// beta の行範囲。
    pub beta_rows: std::ops::Range<usize>,
    /// alpha の行範囲 (`w` の中。`alpha_w` が Some なら未使用)。
    pub alpha_rows: std::ops::Range<usize>,
    /// task 225: alpha が別の行列のとき (`Some` なら `w` は beta 専用で、
    /// alpha はこの行列の `alpha_rows` 行)。連結されていない実モデル用。
    pub alpha_w: Option<PfChainW<'a>>,
}

/// `DENNO_PF_SSM_GEMM_GPU` の解釈 (純関数)。`0`/`off`/`false`/`no`/空だけが off。
pub(crate) fn pf_ssm_gemm_gpu_from_value(v: Option<&str>) -> bool {
    match v {
        None => false,
        Some(s) => !matches!(s.trim(), "0" | "off" | "false" | "no" | ""),
    }
}

#[cfg(test)]
static SSM_GEMM_GPU_FORCE: std::sync::atomic::AtomicU8 = std::sync::atomic::AtomicU8::new(0);

/// テスト用にゲートを固定する (`None` で env に戻す)。
#[cfg(test)]
pub(crate) fn set_pf_ssm_gemm_gpu_for_test(v: Option<bool>) {
    SSM_GEMM_GPU_FORCE.store(
        match v {
            None => 0,
            Some(false) => 1,
            Some(true) => 2,
        },
        Ordering::Relaxed,
    );
}

/// beta/alpha をデバイスで回すか (既定 off。lab の結果で決める)。
pub(crate) fn pf_ssm_gemm_gpu_on() -> bool {
    #[cfg(test)]
    {
        match SSM_GEMM_GPU_FORCE.load(Ordering::Relaxed) {
            1 => return false,
            2 => return true,
            _ => {}
        }
    }
    static ON: OnceLock<bool> = OnceLock::new();
    *ON.get_or_init(|| {
        pf_ssm_gemm_gpu_from_value(std::env::var("DENNO_PF_SSM_GEMM_GPU").ok().as_deref())
    })
}

/// F32 重みをデバイスへ常駐させてポインタを返す (`PF_F32_W` の表を使う)。
/// **current context を張った後に呼ぶこと**。形が合わなければ `None`。
pub fn pf_f32_weight_dev(uid: u64, blocks: &[u8], k: usize, n: usize) -> Option<CUdeviceptr> {
    let want = k.checked_mul(n)?.checked_mul(4)?;
    if k == 0 || n == 0 || blocks.len() != want {
        return None;
    }
    let reg = PF_F32_W.get_or_init(|| Mutex::new(std::collections::HashMap::new()));
    let mut m = match reg.lock() {
        Ok(g) => g,
        Err(_) => return None,
    };
    if let Some(b) = m.get(&uid) {
        return Some(b.ptr());
    }
    let b = DevBuffer::from_slice_tagged(blocks, crate::mem_audit::TAG_OTHER).ok()?;
    let p = b.ptr();
    m.insert(uid, b);
    Some(p)
}

// ---------------------------------------------------------------------------
// task 228: beta/alpha の重みを「型を問わず」デバイスへ常駐させる
// ---------------------------------------------------------------------------
//
// task 225 までの入口 (`pf_f32_weight_dev`) は **元の型が F32** のときだけ受けた。
// 実モデルの `ssm_beta` / `ssm_alpha` は GGUF によって F32 / BF16 / F16 / 量子型が
// 混在する (ローダ側 `f32_tensor` の 2026-10-31 コメント: Swift 1.5 は
// `ssm_alpha` などが BF16) ので、`DENNO_PF_BA_FAST=1` でも `ba_dev` が None に
// なり、`gdn_pf_chain` が **連鎖ごと諦めて**いた (lab t225a: ssm 2.98 -> 27.8 s)。
//
// ここでは非 F32 をホストで 1 回だけ f32 へ展開し (`dequant_row_into` =
// ホスト GEMV と同じ関数)、デバイスには f32 として置く。値が変わるのは
// 「ホストの mul+add 逐次和」と「f32 GEMM の k 昇順 fma」の丸め差だけ。
// 常駐量は 1 本あたり n*k*4 B (実モデル 48x5120 で 983 KB、層あたり beta+alpha で
// 2 MB 未満)。形・型が合わないときは None (呼び出し側はホスト経路へ)。

static PF_BA_W: OnceLock<Mutex<std::collections::HashMap<u64, DevBuffer>>> = OnceLock::new();

/// beta/alpha の重み 1 本を f32 でデバイスへ常駐させる。
/// **current context を張った後に呼ぶこと**。
///
/// 戻り値は (先頭ポインタ, f32 の行バイト数)。`blocks` の長さが
/// `n * row_bytes(ty, k)` と違う / `k` がブロックサイズの倍数でない / 型が
/// 展開できないときは `None`。
pub fn pf_ba_weight_dev(
    uid: u64,
    ty: crate::kquant::GgmlType,
    blocks: &[u8],
    k: usize,
    n: usize,
) -> Option<(CUdeviceptr, usize)> {
    let host = pf_ba_host_f32(ty, blocks, k, n)?;
    let reg = PF_BA_W.get_or_init(|| Mutex::new(std::collections::HashMap::new()));
    let mut m = match reg.lock() {
        Ok(g) => g,
        Err(_) => return None,
    };
    if let Some(b) = m.get(&uid) {
        return Some((b.ptr(), k * 4));
    }
    let b = DevBuffer::from_slice_tagged(&host, crate::mem_audit::TAG_OTHER).ok()?;
    let p = b.ptr();
    m.insert(uid, b);
    Some((p, k * 4))
}

/// beta/alpha の重みを f32 の行優先 (`n` 行 × `k` 列) に展開する。GPU を触らない。
///
/// 1 行ずつ [`crate::kquant::dequant_row_into`] (ホスト GEMV が使うのと同じ関数)
/// で展開するので、出来上がる `f32` はホスト経路が内積に使う値と**ビット一致**する。
/// 形が合わない (`k` がブロックサイズの倍数でない / バイト数が違う) ときは `None`。
pub(crate) fn pf_ba_host_f32(
    ty: crate::kquant::GgmlType,
    blocks: &[u8],
    k: usize,
    n: usize,
) -> Option<Vec<f32>> {
    let bs = ty.blck_size();
    let ts = ty.type_size();
    if k == 0 || n == 0 || bs == 0 || k % bs != 0 || !crate::kquant::dequant_supported(ty) {
        return None;
    }
    let rb = (k / bs) * ts;
    if blocks.len() != n.checked_mul(rb)? {
        return None;
    }
    let mut host = vec![0f32; k.checked_mul(n)?];
    let mut row = vec![0f32; k];
    for r in 0..n {
        crate::kquant::dequant_row_into(ty, &blocks[r * rb..(r + 1) * rb], &mut row);
        host[r * k..(r + 1) * k].copy_from_slice(&row);
    }
    Some(host)
}

/// beta/alpha の 1 本がデバイス経路に載せられるか。載せられない理由を返す
/// (載せられるときは `None`)。GPU を触らない純関数。
///
/// 呼び出し側 (`forward_batch_chain`) と `gdn_pf_chain` が**同じ判定**を使うので、
/// 入口を開けてから連鎖が諦める (層ごと従来経路へ落ちる) ことが起きない。
pub(crate) fn pf_ba_w_check(
    ty: crate::kquant::GgmlType,
    k: usize,
    n: usize,
    rows: &std::ops::Range<usize>,
    nv: usize,
    e: usize,
) -> Option<String> {
    if !crate::kquant::dequant_supported(ty) {
        return Some(format!("型 {ty:?} は f32 へ展開できない"));
    }
    if k != e {
        return Some(format!("k={k} が n_embd={e} と違う"));
    }
    if rows.len() != nv {
        return Some(format!("行数 {} が n_v_heads={nv} と違う", rows.len()));
    }
    if n == 0 || rows.is_empty() || rows.end > n {
        return Some(format!("行範囲 {rows:?} が n={n} を超える"));
    }
    None
}

/// [`pf_ba_w_check`] の真偽版。
pub(crate) fn pf_ba_w_ok(
    ty: crate::kquant::GgmlType,
    k: usize,
    n: usize,
    rows: &std::ops::Range<usize>,
    nv: usize,
    e: usize,
) -> bool {
    pf_ba_w_check(ty, k, n, rows, nv, e).is_none()
}

/// task 228: 入口 (`DENNO_PF_SSM_GEMM_GPU` / `DENNO_PF_BA_FAST`) を開けたのに
/// beta/alpha のデバイス記述を作れなかった理由を **1 回だけ** warn に出す。
///
/// task 225 ではこれが無く、「開けたつもりが層ごとに従来経路へ落ちる」を
/// lab の ssm 時間 (+79%) から逆算するしかなかった。
pub(crate) fn pf_ba_diag_warn(why: &str) {
    static ONCE: std::sync::atomic::AtomicBool = std::sync::atomic::AtomicBool::new(false);
    if !ONCE.swap(true, Ordering::Relaxed) {
        tracing::warn!("ssm beta/alpha のデバイス入口を閉じた: {why}");
    }
}

#[cfg(test)]
mod ssm_gemm_gpu_tests {
    use super::*;

    #[test]
    fn ssm_gemm_gpu_gate_truth_table() {
        assert!(!pf_ssm_gemm_gpu_from_value(None), "未設定は既定 off");
        for v in ["0", "off", "false", "no", "", " off "] {
            assert!(!pf_ssm_gemm_gpu_from_value(Some(v)), "{v:?} が on になった");
        }
        for v in ["1", "on", "true", "yes", "2"] {
            assert!(pf_ssm_gemm_gpu_from_value(Some(v)), "{v:?} が off のまま");
        }
    }

    #[test]
    fn ssm_gemm_gpu_force_switch() {
        set_pf_ssm_gemm_gpu_for_test(Some(true));
        assert!(pf_ssm_gemm_gpu_on());
        set_pf_ssm_gemm_gpu_for_test(Some(false));
        assert!(!pf_ssm_gemm_gpu_on());
        set_pf_ssm_gemm_gpu_for_test(None);
        assert!(!pf_ssm_gemm_gpu_on(), "env 未設定の既定は off");
    }
}

#[cfg(test)]
mod ba228_tests {
    //! task 228: beta/alpha のデバイス入口 (型を問わず f32 へ展開) の検査。
    use super::*;
    use crate::kquant::{dequant_row, GgmlType as T};

    /// `n` 行 × `k` 列の生ブロックを型ごとの正しいバイト数で作る。
    fn raw(ty: T, k: usize, n: usize, seed: u32) -> Vec<u8> {
        let bs = ty.blck_size();
        let ts = ty.type_size();
        assert_eq!(k % bs, 0, "{ty:?}: k がブロック倍数でない");
        let nb = k / bs;
        let mut out = Vec::with_capacity(n * nb * ts);
        for r in 0..n {
            for b in 0..nb {
                let base = seed.wrapping_add((r * 131 + b * 17) as u32);
                match ty {
                    T::F32 => {
                        for i in 0..bs {
                            let v = ((base + i as u32) % 97) as f32 / 97.0 - 0.5;
                            out.extend_from_slice(&v.to_le_bytes());
                        }
                    }
                    T::Bf16 => {
                        for i in 0..bs {
                            let v = ((base + i as u32) % 97) as f32 / 97.0 - 0.5;
                            out.extend_from_slice(&((v.to_bits() >> 16) as u16).to_le_bytes());
                        }
                    }
                    T::F16 => {
                        for i in 0..bs {
                            // 0.5 + (0..63)/... の正規化数の範囲 (0x3800 = 0.5)
                            let bits: u16 = 0x3800 + ((base + i as u32) % 64) as u16;
                            out.extend_from_slice(&bits.to_le_bytes());
                        }
                    }
                    T::Q8_0 => {
                        out.extend_from_slice(&0x3C00u16.to_le_bytes()); // d = 1.0
                        for i in 0..32 {
                            let v = (((base + i) % 251) as i32 - 125) as i8;
                            out.push(v as u8);
                        }
                    }
                    other => panic!("テスト用の生成器が無い型 {other:?}"),
                }
            }
        }
        out
    }

    /// 展開した f32 は `dequant_row` (ホスト GEMV が使う関数) と行ごとにビット一致。
    #[test]
    fn pf228_ba_host_f32_matches_dequant_row() {
        for ty in [T::F32, T::F16, T::Bf16, T::Q8_0] {
            let (k, n) = (256usize, 7usize);
            let bytes = raw(ty, k, n, 11);
            let flat = pf_ba_host_f32(ty, &bytes, k, n).expect("展開できる");
            assert_eq!(flat.len(), k * n, "{ty:?}: 要素数");
            let rb = bytes.len() / n;
            for r in 0..n {
                let row = dequant_row(ty, &bytes[r * rb..(r + 1) * rb], k);
                assert_eq!(
                    &flat[r * k..(r + 1) * k],
                    &row[..],
                    "{ty:?}: 行 {r} が dequant_row と違う"
                );
            }
            // バイト数が 1 足りない / k が形と合わない → None (黙って別物を作らない)。
            assert!(pf_ba_host_f32(ty, &bytes[..bytes.len() - 1], k, n).is_none());
            assert!(pf_ba_host_f32(ty, &bytes, k + 1, n).is_none());
            assert!(pf_ba_host_f32(ty, &bytes, k, n + 1).is_none());
        }
    }

    /// ホスト GEMV (BF16/F16 の展開経路) は「展開済み f32 の k 昇順 mul+add」と
    /// **ビット一致**する。デバイス f32 GEMM との差が fma の丸めだけである根拠。
    #[test]
    fn pf228_ba_host_f32_host_gemv_bits() {
        use crate::model::linear_gguf::GgufLinear;
        let (k, n, nt) = (256usize, 5usize, 3usize);
        let xs: Vec<f32> = (0..nt * k)
            .map(|i| ((i * 37 % 101) as f32) / 101.0 - 0.5)
            .collect();
        for ty in [T::F16, T::Bf16] {
            let bytes = raw(ty, k, n, 3);
            let w = GgufLinear::from_slice(ty, k, n, &bytes).expect("GgufLinear");
            let mut out = vec![0f32; nt * n];
            crate::model::qwen4exp::gemv_batch_cpu(&w, &xs, nt, &mut out).expect("gemv_batch_cpu");
            let flat = pf_ba_host_f32(ty, &bytes, k, n).expect("展開");
            for t in 0..nt {
                for r in 0..n {
                    let mut acc = 0f32;
                    for i in 0..k {
                        acc += flat[r * k + i] * xs[t * k + i];
                    }
                    assert_eq!(
                        out[t * n + r].to_bits(),
                        acc.to_bits(),
                        "{ty:?}: t={t} r={r}"
                    );
                }
            }
        }
    }

    /// 入口の判定: 実モデルの形 (k = n_embd, 行 = n_v_heads) を型を問わず受け、
    /// 形が違えば理由付きで閉じる。
    #[test]
    fn pf228_ba_w_check_truth_table() {
        let (e, nv) = (2560usize, 48usize);
        for ty in [T::F32, T::F16, T::Bf16, T::Q8_0, T::Q2K, T::IQ3S] {
            assert!(
                pf_ba_w_ok(ty, e, 2 * nv, &(0..nv), nv, e),
                "{ty:?}: 連結 (beta 行) を受けない"
            );
            assert!(
                pf_ba_w_ok(ty, e, 2 * nv, &(nv..2 * nv), nv, e),
                "{ty:?}: 連結 (alpha 行) を受けない"
            );
            assert!(
                pf_ba_w_ok(ty, e, nv, &(0..nv), nv, e),
                "{ty:?}: 未連結 (alpha_w) を受けない"
            );
            assert!(
                !pf_ba_w_ok(ty, e + 8, 2 * nv, &(0..nv), nv, e),
                "{ty:?}: k 違いを受けた"
            );
            assert!(
                !pf_ba_w_ok(ty, e, 2 * nv, &(0..nv + 1), nv, e),
                "{ty:?}: 行数違いを受けた"
            );
            assert!(
                !pf_ba_w_ok(ty, e, nv, &(1..nv + 1), nv, e),
                "{ty:?}: n を超える行範囲を受けた"
            );
            assert!(
                !pf_ba_w_ok(ty, e, nv, &(nv..nv), nv, e),
                "{ty:?}: 空の行範囲を受けた"
            );
        }
        let why = pf_ba_w_check(T::Bf16, e + 8, 2 * nv, &(0..nv), nv, e).expect("閉じる");
        assert!(why.contains("n_embd"), "理由に k の食い違いが出ていない: {why}");
        let why = pf_ba_w_check(T::Bf16, e, 2 * nv, &(0..nv + 1), nv, e).expect("閉じる");
        assert!(
            why.contains("n_v_heads"),
            "理由に行数の食い違いが出ていない: {why}"
        );
    }
}

#[cfg(test)]
mod gdn_pf2_tests {
    use super::*;

    /// ゲートの真理値表 (既定 off。lab の結果で on にする)。
    #[test]
    fn gdn_pf2_gate_truth_table() {
        assert!(gdn_pf2_from_value(None), "未設定は既定 on (task 189)");
        for v in ["0", "off", "false", "no", "", " off "] {
            assert!(!gdn_pf2_from_value(Some(v)), "{v:?} が on になった");
        }
        for v in ["1", "on", "true", "yes", "2"] {
            assert!(gdn_pf2_from_value(Some(v)), "{v:?} が off のまま");
        }
    }

    /// 形のゲートは scan128 と同じ前提 (dk=dv=128 / d_conv=4 / conv_dim 一致)。
    #[test]
    fn gdn_pf2_ok_checks_shape() {
        let conv_dim = 2 * 16 * 128 + 48 * 128;
        assert!(gdn_pf2_ok(1, 16, 48, 128, 128, 4, conv_dim));
        assert!(gdn_pf2_ok(512, 16, 48, 128, 128, 4, conv_dim));
        assert!(!gdn_pf2_ok(512, 16, 48, 64, 64, 4, 2 * 16 * 64 + 48 * 64));
        assert!(!gdn_pf2_ok(512, 16, 48, 128, 128, 3, conv_dim));
        assert!(!gdn_pf2_ok(512, 16, 48, 128, 128, 4, conv_dim + 1));
        assert!(!gdn_pf2_ok(0, 16, 48, 128, 128, 4, conv_dim));
        assert!(!gdn_pf2_ok(512, 0, 48, 128, 128, 4, conv_dim));
    }

    /// 強制スイッチ (テスト用) が効く。
    #[test]
    fn gdn_pf2_force_switch() {
        set_gdn_pf2_for_test(Some(true));
        assert!(gdn_pf2_on());
        set_gdn_pf2_for_test(Some(false));
        assert!(!gdn_pf2_on());
        set_gdn_pf2_for_test(None);
        // task 189: 既定を on に反転した (lab t187c: scan_pf 2,853 -> 1,295 ms)。
        assert!(gdn_pf2_on(), "env 未設定の既定は on");
    }
}

// ---------------------------------------------------------------------------
// task 225: prefill GDN スキャン v3 (ヘッドあたり 4 ブロック x 8 レーン)
// (`DENNO_PF_SCAN3`、task 228 から既定 on)
// ---------------------------------------------------------------------------
//
// lab t222c: `ssm scan_pf` は 1,470.3 ms = 2.9 us/トークン。v2
// (`dno_gdn_pf_scan64`) は 1 ブロック = 64 列で 96 ブロックしかなく (170 SM)、
// 8 ワープ/ブロックなので 4.5 ワープ/SM。1 トークンの依存鎖 (32 行の skv 和 →
// 32 行の更新 + o 和) が latency にそのまま出る。
// v3 は 1 ブロック = 32 列 x 8 レーン = 256 スレッド (1 レーン 16 行) で
// 192 ブロック。リングを 4 段にして t+3 のグローバル読みを t の計算の前に発行し、
// silu とリング書きを計算の後に回す。値は v2 と丸め順だけが違う (縮約の木が
// 8 レーン)。

/// v3 スキャンの 1 ブロックあたりの列数 (カーネルの PF3_COLS)。
pub(crate) const GDN_PF3_COLS: usize = 32;
/// v3 スキャンのスレッド数 (カーネルの PF3_THREADS)。
pub(crate) const GDN_PF3_THREADS: usize = 256;
/// v3 スキャンが 1 ヘッドを割るブロック数 (128 列 / 32 列)。
pub(crate) const GDN_PF3_BLOCKS: u32 = 4;

struct GdnPf3Kernels {
    #[allow(dead_code)]
    module: CUmodule,
    scan32: CUfunction,
    /// 出力の gated RMS norm は v2 の PTX のものを使う (同じ演算列)。
    norm: CUfunction,
}

unsafe impl Send for GdnPf3Kernels {}
unsafe impl Sync for GdnPf3Kernels {}

/// PTX の置き場所 (`DENNO_GDN_PF3_PTX` があればそれ)。
fn gdn_pf3_ptx_path() -> std::path::PathBuf {
    match std::env::var("DENNO_GDN_PF3_PTX") {
        Ok(p) if !p.is_empty() => std::path::PathBuf::from(p),
        _ => std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("kernels")
            .join("kernels_gdn_pf3.ptx"),
    }
}

/// カーネルを取得する (初回だけ PTX を読む)。norm は v2 の PTX から取る。
fn gdn_pf3_kernels() -> Option<&'static GdnPf3Kernels> {
    static K: OnceLock<Option<GdnPf3Kernels>> = OnceLock::new();
    K.get_or_init(|| {
        let path = gdn_pf3_ptx_path();
        let mut image = match std::fs::read(&path) {
            Ok(b) => b,
            Err(e) => {
                eprintln!(
                    "[gdn-pf3] PTX が読めない ({}) : {e} → v2 のスキャンへ",
                    path.display()
                );
                return None;
            }
        };
        image.push(0);
        let lib = lib().ok()?;
        let mut module: CUmodule = std::ptr::null_mut();
        unsafe {
            if (lib.module_load_data)(&mut module, image.as_ptr() as *const c_void) != CUDA_SUCCESS {
                eprintln!("[gdn-pf3] cuModuleLoadData 失敗 → v2 のスキャンへ");
                return None;
            }
            let mut scan32: CUfunction = std::ptr::null_mut();
            if (lib.module_get_function)(
                &mut scan32,
                module,
                b"dno_gdn_pf_scan32\0".as_ptr() as *const c_char,
            ) != CUDA_SUCCESS
            {
                eprintln!("[gdn-pf3] PTX に dno_gdn_pf_scan32 が無い → v2 のスキャンへ");
                return None;
            }
            log_kernel_attr(lib, scan32, "dno_gdn_pf_scan32");
            // 出力の norm は v2 の PTX (同じ演算列) をそのまま使う。
            let norm = gdn_pf2_kernels()?.norm;
            Some(GdnPf3Kernels {
                module,
                scan32,
                norm,
            })
        }
    })
    .as_ref()
}

/// `DENNO_PF_SCAN3` の解釈 (純関数)。`0`/`off`/`false`/`no`/空だけが off。
pub(crate) fn gdn_pf3_from_value(v: Option<&str>) -> bool {
    match v.map(|s| s.trim().to_ascii_lowercase()) {
        // task 228: task 225 の lab t225c で scan_pf 1,469.8 → 1,310.4 ms (14k) /
        // decode・text 無影響の実測が出たので既定 on。切り戻しは `DENNO_PF_SCAN3=0`。
        None => true,
        Some(s) => !matches!(s.as_str(), "0" | "off" | "false" | "no" | ""),
    }
}

#[cfg(test)]
static PF3_FORCE: std::sync::atomic::AtomicU8 = std::sync::atomic::AtomicU8::new(0);

/// テスト用にゲートを固定する (`None` で env に戻す)。
#[cfg(test)]
pub(crate) fn set_gdn_pf3_for_test(v: Option<bool>) {
    PF3_FORCE.store(
        match v {
            None => 0,
            Some(false) => 1,
            Some(true) => 2,
        },
        Ordering::Relaxed,
    );
}

/// v3 スキャンを使うか (task 228 から既定 on)。
pub(crate) fn gdn_pf3_on() -> bool {
    #[cfg(test)]
    {
        match PF3_FORCE.load(Ordering::Relaxed) {
            1 => return false,
            2 => return true,
            _ => {}
        }
    }
    static ON: OnceLock<bool> = OnceLock::new();
    *ON.get_or_init(|| gdn_pf3_from_value(std::env::var("DENNO_PF_SCAN3").ok().as_deref()))
}

/// v3 スキャンが受ける形か (純関数。カーネルの前提と同じ)。
pub(crate) fn gdn_pf3_ok(
    nt: usize,
    nk: usize,
    nv: usize,
    dk: usize,
    dv: usize,
    d_conv: usize,
    conv_dim: usize,
) -> bool {
    gdn_pf2_ok(nt, nk, nv, dk, dv, d_conv, conv_dim)
}

/// task 225: v3 スキャンを撃つ (scan32 → v2 の norm の 2 起動)。引数の並びは
/// カーネルの宣言順で、v2 の [`gdn_pf2_launch`] と同じ。
#[allow(clippy::too_many_arguments)]
fn gdn_pf3_launch(
    ctx: &CudaCtx,
    fns: &GdnPf3Kernels,
    qkv: CUdeviceptr,
    z: CUdeviceptr,
    beta: CUdeviceptr,
    alpha: CUdeviceptr,
    conv_st_in: CUdeviceptr,
    ssm_in: CUdeviceptr,
    wconv: CUdeviceptr,
    wa: CUdeviceptr,
    wdt: CUdeviceptr,
    wnorm: CUdeviceptr,
    y_out: CUdeviceptr,
    conv_st_out: CUdeviceptr,
    ssm_out: CUdeviceptr,
    n: usize,
    nk: usize,
    nv: usize,
    conv_dim: usize,
    eps: f32,
    q_scale: f32,
) -> Result<()> {
    {
        let (mut pq, mut pb, mut pa) = (qkv, beta, alpha);
        let (mut pci, mut psi) = (conv_st_in, ssm_in);
        let (mut pwc, mut pwa, mut pwd) = (wconv, wa, wdt);
        let (mut py, mut pco, mut pso) = (y_out, conv_st_out, ssm_out);
        let (mut ni, mut nki, mut nvi) = (n as c_int, nk as c_int, nv as c_int);
        let (mut cdi, mut epsi, mut qsi) = (conv_dim as c_int, eps, q_scale);
        let mut args = [
            &mut pq as *mut _ as *mut c_void,
            &mut pb as *mut _ as *mut c_void,
            &mut pa as *mut _ as *mut c_void,
            &mut pci as *mut _ as *mut c_void,
            &mut psi as *mut _ as *mut c_void,
            &mut pwc as *mut _ as *mut c_void,
            &mut pwa as *mut _ as *mut c_void,
            &mut pwd as *mut _ as *mut c_void,
            &mut py as *mut _ as *mut c_void,
            &mut pco as *mut _ as *mut c_void,
            &mut pso as *mut _ as *mut c_void,
            &mut ni as *mut _ as *mut c_void,
            &mut nki as *mut _ as *mut c_void,
            &mut nvi as *mut _ as *mut c_void,
            &mut cdi as *mut _ as *mut c_void,
            &mut epsi as *mut _ as *mut c_void,
            &mut qsi as *mut _ as *mut c_void,
        ];
        // 1 ヘッドを 4 ブロックが分担する (32 列ずつ)。
        unsafe {
            ctx.launch_async(
                fns.scan32,
                (nv as u32, GDN_PF3_BLOCKS, 1),
                (GDN_PF3_THREADS as u32, 1, 1),
                0,
                &mut args,
            )?;
        }
    }
    {
        let (mut py, mut pz, mut pwn) = (y_out, z, wnorm);
        let (mut ni, mut nvi) = (n as c_int, nv as c_int);
        let mut epsi = eps;
        let mut args = [
            &mut py as *mut _ as *mut c_void,
            &mut pz as *mut _ as *mut c_void,
            &mut pwn as *mut _ as *mut c_void,
            &mut ni as *mut _ as *mut c_void,
            &mut nvi as *mut _ as *mut c_void,
            &mut epsi as *mut _ as *mut c_void,
        ];
        let groups = n.saturating_mul(nv);
        let per_block = GDN_PF2_NORM_THREADS / 4;
        let grid = (groups.div_ceil(per_block)) as u32;
        unsafe {
            ctx.launch_async(
                fns.norm,
                (grid, 1, 1),
                (GDN_PF2_NORM_THREADS as u32, 1, 1),
                0,
                &mut args,
            )?;
        }
    }
    Ok(())
}

// ---------------------------------------------------------------------------
// task 228: prefill の GDN スキャン WY (UT) 形式チャンク版
// (`DENNO_PF_SCAN_WY`、既定 off。初回ラウンドは PTX= で生成)
// ---------------------------------------------------------------------------
//
// 1 ブロック = 1 ヘッド。32 トークンを 1 チャンクにして、チャンク内を
//    A[t][j] = (k_t·k_j) * Π_{m=j+1..t} eg_m
//    D_t = b_t (v_t - Λ_t (k_tᵀ S_0) - Σ_{j<t} A[t][j] D_j)
//    o_t = Λ_t (q_tᵀ S_0) + Σ_{j≤t} (q_t·k_j) Π_{m=j+1..t} eg_m D_j
//    S_new = Λ_last S_0 + Σ_j (Λ_last/Λ_j) k_j ⊗ D_j
// の行列積 + 前進代入で回す (直列なのはチャンク間だけ)。
// CPU 参照は `crate::gdn::wy::wy_head_scan`、値の裏付けはそこのテスト。
//
// 共有メモリは 91,012 B (状態 64 KB + 作業域 C = 8 本ぶん) なので、
// cuFuncSetAttribute で opt-in してから起動する。lab t228a の実機 (RTX 5090,
// sm_120) の opt-in 上限は 99 KB で、C = 32 のときの 176,644 B は通らず
// v3 へ落ちていた (t228a の wy COND は v3 を測っていた)。上限は
// `attn_pf_dynamic_smem_limit()` (CudaCtx 生成時のデバイス問い合わせ) を使い、
// 足りないときはカーネルを掴まない (v3 → v2 → v1 → CPU へ fail closed)。

pub(crate) const GDN_PF_WY_THREADS: usize = 512;
/// カーネルの動的共有メモリ (float 数。`kernels_gdn_pf_wy.cu` の WY_TOTAL)。
pub(crate) const GDN_PF_WY_SMEM_FLOATS: usize = 22753;
pub(crate) const GDN_PF_WY_SMEM_BYTES: usize = GDN_PF_WY_SMEM_FLOATS * 4;
/// lab t228a の実機が許した opt-in 上限 (99 KB)。これ以上は起動できない。
pub(crate) const GDN_PF_WY_SMEM_LIMIT: usize = 99 * 1024;

struct GdnPfWyKernels {
    #[allow(dead_code)]
    module: CUmodule,
    scan: CUfunction,
    norm: CUfunction,
}

unsafe impl Send for GdnPfWyKernels {}
unsafe impl Sync for GdnPfWyKernels {}

fn gdn_pf_wy_ptx_path() -> std::path::PathBuf {
    match std::env::var("DENNO_PF_SCAN_WY_PTX") {
        Ok(p) if !p.is_empty() => std::path::PathBuf::from(p),
        _ => std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("kernels")
            .join("kernels_gdn_pf_wy.ptx"),
    }
}

fn gdn_pf_wy_kernels() -> Option<&'static GdnPfWyKernels> {
    static K: OnceLock<Option<GdnPfWyKernels>> = OnceLock::new();
    K.get_or_init(|| {
        let path = gdn_pf_wy_ptx_path();
        let mut image = match std::fs::read(&path) {
            Ok(b) => b,
            Err(e) => {
                eprintln!(
                    "[gdn-pf-wy] PTX が読めない ({}) : {e} → v3 のスキャンへ",
                    path.display()
                );
                return None;
            }
        };
        image.push(0);
        let lib = lib().ok()?;
        let mut module: CUmodule = std::ptr::null_mut();
        unsafe {
            if (lib.module_load_data)(&mut module, image.as_ptr() as *const c_void) != CUDA_SUCCESS {
                eprintln!("[gdn-pf-wy] cuModuleLoadData 失敗 → v3 のスキャンへ");
                return None;
            }
            let mut scan: CUfunction = std::ptr::null_mut();
            if (lib.module_get_function)(
                &mut scan,
                module,
                b"dno_gdn_pf_wy32\0".as_ptr() as *const c_char,
            ) != CUDA_SUCCESS
            {
                eprintln!("[gdn-pf-wy] PTX に dno_gdn_pf_wy32 が無い → v3 のスキャンへ");
                return None;
            }
            // 動的 smem の opt-in (48 KB 既定を超えるため必須)。デバイスの
            // opt-in 上限 (CudaCtx 生成時に問い合わせ済み) を先に見て、
            // 足りないときは理由を出して掴まない (t228a: 176,644 B が 99 KB の
            // 上限に弾かれて、黙って v3 が測られていた)。
            let limit = attn_pf_dynamic_smem_limit().min(GDN_PF_WY_SMEM_LIMIT);
            if GDN_PF_WY_SMEM_BYTES > limit {
                eprintln!(
                    "[gdn-pf-wy] 動的 smem {} B がデバイスの上限 {limit} B を超える → v3 のスキャンへ",
                    GDN_PF_WY_SMEM_BYTES
                );
                return None;
            }
            let ok = match lib.func_set_attribute {
                Some(fn_attr) => {
                    (fn_attr)(
                        scan,
                        CU_FUNC_ATTR_MAX_DYNAMIC_SHARED_SIZE_BYTES,
                        GDN_PF_WY_SMEM_BYTES as c_int,
                    ) == 0
                }
                None => false,
            };
            if !ok {
                eprintln!(
                    "[gdn-pf-wy] 動的 smem {GDN_PF_WY_SMEM_BYTES} B の opt-in に失敗 → v3 のスキャンへ"
                );
                return None;
            }
            log_kernel_attr(lib, scan, "dno_gdn_pf_wy32");
            // 出力の gated RMS norm は v2 の PTX (同じ演算列) をそのまま使う。
            let norm = gdn_pf2_kernels()?.norm;
            Some(GdnPfWyKernels { module, scan, norm })
        }
    })
    .as_ref()
}

// ---------------------------------------------------------------------------
// task 311: WY スキャンの v 列 4 分割版 (`DENNO_PF_SCAN_WY4`)
// ---------------------------------------------------------------------------
//
// `dno_gdn_pf_wy32` は 1 ブロック = 1 ヘッドなので 48 ブロックしか立たず
// (170 SM)、C = 8 では v3 より 11% 遅かった (t231a: scan_pf 392.8 vs 357.0 ms)。
// `dno_gdn_pf_wy4` は v 列を 4 分割して 192 ブロックにする。状態は
// dk x 32 列 = 16 KB で、共有メモリは 29,572 B (48 KB 既定の内側なので opt-in
// 不要だが、実機の上限は念のため見る)。数値は wy32 と要素ごとに同じ順序。
pub(crate) const GDN_PF_WY4_THREADS: usize = 256;
/// v 列の分割数 (`blockIdx.y`)。dk = 128 を 32 列ずつに切る。
pub(crate) const GDN_PF_WY4_BLOCKS: usize = 4;
/// 1 ブロックが持つ v 列数 (カーネルの `WY4_DV`)。
pub(crate) const GDN_PF_WY4_DV: usize = 32;
/// カーネルの動的共有メモリ (float 数。`kernels_gdn_pf_wy4.cu` の WY4_TOTAL)。
pub(crate) const GDN_PF_WY4_SMEM_FLOATS: usize = 7393;
pub(crate) const GDN_PF_WY4_SMEM_BYTES: usize = GDN_PF_WY4_SMEM_FLOATS * 4;

/// WY 系スキャン (wy32 / wy4) の PTX を読んでカーネルを掴む。
///
/// 3 本とも同じ 17 引数なので、ホストの起動 (`gdn_pf_wy_launch`) と norm を
/// 共有する。違うのは PTX のパス・entry 名・動的共有メモリ・起動形状だけ。
/// `require_attr` は「`func_set_attribute` が無い/失敗したら降りる」か
/// (wy32 = true、48 KB 既定を超えるため必須。wy4 = false)。
fn gdn_wy_load(
    path: std::path::PathBuf,
    entry: &'static [u8],
    smem_bytes: usize,
    tag: &'static str,
    smem_limit: usize,
    require_attr: bool,
) -> Option<GdnPfWyKernels> {
    let mut image = match std::fs::read(&path) {
        Ok(b) => b,
        Err(e) => {
            eprintln!(
                "{tag} PTX が読めない ({}) : {e} → v3 のスキャンへ",
                path.display()
            );
            return None;
        }
    };
    image.push(0);
    let lib = lib().ok()?;
    let mut module: CUmodule = std::ptr::null_mut();
    unsafe {
        if (lib.module_load_data)(&mut module, image.as_ptr() as *const c_void) != CUDA_SUCCESS {
            eprintln!("{tag} cuModuleLoadData 失敗 → v3 のスキャンへ");
            return None;
        }
        let name = String::from_utf8_lossy(&entry[..entry.len() - 1]).to_string();
        let mut scan: CUfunction = std::ptr::null_mut();
        if (lib.module_get_function)(&mut scan, module, entry.as_ptr() as *const c_char)
            != CUDA_SUCCESS
        {
            eprintln!("{tag} PTX に {name} が無い → v3 のスキャンへ");
            return None;
        }
        // 実機の opt-in 上限 (CudaCtx 生成時に問い合わせ済み) を先に見る。
        let limit = attn_pf_dynamic_smem_limit().min(smem_limit);
        if smem_bytes > limit {
            eprintln!(
                "{tag} 動的 smem {smem_bytes} B がデバイスの上限 {limit} B を超える → v3 のスキャンへ"
            );
            return None;
        }
        match lib.func_set_attribute {
            Some(fn_attr) => {
                if (fn_attr)(
                    scan,
                    CU_FUNC_ATTR_MAX_DYNAMIC_SHARED_SIZE_BYTES,
                    smem_bytes as c_int,
                ) != 0
                {
                    eprintln!("{tag} 動的 smem {smem_bytes} B の opt-in に失敗 → v3 のスキャンへ");
                    return None;
                }
            }
            None => {
                if require_attr {
                    eprintln!("{tag} func_set_attribute が無い → v3 のスキャンへ");
                    return None;
                }
            }
        }
        log_kernel_attr(lib, scan, &name);
        // 出力の gated RMS norm は v2 の PTX (同じ演算列) をそのまま使う。
        let norm = gdn_pf2_kernels()?.norm;
        Some(GdnPfWyKernels { module, scan, norm })
    }
}

fn gdn_pf_wy4_ptx_path() -> std::path::PathBuf {
    match std::env::var("DENNO_PF_SCAN_WY4_PTX") {
        Ok(p) if !p.is_empty() => std::path::PathBuf::from(p),
        _ => std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("kernels")
            .join("kernels_gdn_pf_wy4.ptx"),
    }
}

fn gdn_pf_wy4_kernels() -> Option<&'static GdnPfWyKernels> {
    static K: OnceLock<Option<GdnPfWyKernels>> = OnceLock::new();
    K.get_or_init(|| {
        gdn_wy_load(
            gdn_pf_wy4_ptx_path(),
            b"dno_gdn_pf_wy4\0",
            GDN_PF_WY4_SMEM_BYTES,
            "[gdn-pf-wy4]",
            GDN_PF_WY_SMEM_LIMIT,
            false,
        )
    })
    .as_ref()
}

