/// task 173: レジスタ常駐スキャンを「ホスト入力 → ホスト出力」で 1 回だけ回す
/// (検算用。prefill の本線は連鎖 [`gdn_pf_chain`] の中から呼ぶ)。
///
/// 戻り値 `None` は「GPU・PTX・形の前提が無い」(呼び出し側はスキップしてよい)。
#[allow(clippy::too_many_arguments)]
pub fn gdn_pf_scan128_host(
    qkv: &[f32],
    z: &[f32],
    beta: &[f32],
    alpha: &[f32],
    conv_st: &mut [f32],
    ssm_st: &mut [f32],
    wconv: &[f32],
    wa: &[f32],
    wdt: &[f32],
    wnorm: &[f32],
    n: usize,
    nk: usize,
    nv: usize,
    dk: usize,
    dv: usize,
    d_conv: usize,
    eps: f32,
    q_scale: f32,
) -> Option<Vec<f32>> {
    let cs = d_conv - 1;
    let conv_dim = 2 * nk * dk + nv * dv;
    let vd = nv * dv;
    if !gdn_pf_fast_eligible(n, nk, nv, dk, dv, d_conv, conv_dim)
        || qkv.len() != n * conv_dim
        || z.len() != n * vd
        || beta.len() != n * nv
        || alpha.len() != n * nv
        || conv_st.len() != conv_dim * cs
        || ssm_st.len() != nv * dk * dv
        || wconv.len() != conv_dim * d_conv
        || wa.len() != nv
        || wdt.len() != nv
        || wnorm.len() != dv
    {
        return None;
    }
    if !cuda_enabled() {
        return None;
    }
    let ctx = shared_ctx()?;
    if ctx.make_current().is_err() {
        return None;
    }
    let fns = gdn_pf_kernels()?;
    let d_qkv = DevBuffer::from_slice(qkv).ok()?;
    let d_z = DevBuffer::from_slice(z).ok()?;
    let d_beta = DevBuffer::from_slice(beta).ok()?;
    let d_alpha = DevBuffer::from_slice(alpha).ok()?;
    let d_cst = DevBuffer::from_slice(conv_st).ok()?;
    let d_sst = DevBuffer::from_slice(ssm_st).ok()?;
    let d_wc = DevBuffer::from_slice(wconv).ok()?;
    let d_wa = DevBuffer::from_slice(wa).ok()?;
    let d_wd = DevBuffer::from_slice(wdt).ok()?;
    let d_wn = DevBuffer::from_slice(wnorm).ok()?;
    let d_y = DevBuffer::alloc(n * vd * 4).ok()?;
    let d_co = DevBuffer::alloc(conv_dim * cs * 4).ok()?;
    let d_so = DevBuffer::alloc(nv * dk * dv * 4).ok()?;
    gdn_pf_scan128_launch(
        &ctx,
        fns,
        d_qkv.ptr(),
        d_z.ptr(),
        d_beta.ptr(),
        d_alpha.ptr(),
        d_cst.ptr(),
        d_sst.ptr(),
        d_wc.ptr(),
        d_wa.ptr(),
        d_wd.ptr(),
        d_wn.ptr(),
        d_y.ptr(),
        d_co.ptr(),
        d_so.ptr(),
        n,
        nk,
        nv,
        conv_dim,
        eps,
        q_scale,
    )
    .ok()?;
    ctx.sync().ok()?;
    let y = d_y.to_vec::<f32>(n * vd).ok()?;
    let co = d_co.to_vec::<f32>(conv_dim * cs).ok()?;
    let so = d_so.to_vec::<f32>(nv * dk * dv).ok()?;
    conv_st.copy_from_slice(&co);
    ssm_st.copy_from_slice(&so);
    Some(y)
}

// ---------------------------------------------------------------------------
// task 173: 連鎖の段ごとの GPU 時間 (`DENNO_GDN_PF_KPROF=1`・既定 off)
// ---------------------------------------------------------------------------
//
// 台帳の段 (`qkv_pf` / `scan_pf` / `out_pf`) は「発行 + 同期の待ち」を含む壁時計
// なので、**待ち**が混ざると中身が読めない (expert の別ストリームが走っている
// 間の `cuCtxSynchronize` はその完了も待つ)。ここでは段の前後に CUDA イベントを
// 打ち、`cuEventElapsedTime` で「その段の GPU 時間」だけを積む。段の壁時計との
// 差が「他人の仕事を待っていた時間」になる。
pub mod gdn_pf_kprof {
    use super::*;

    /// 段の番号 (この順で 1 行に出す)。
    pub const X_H2D: usize = 0;
    pub const QKV_GEMM: usize = 1;
    pub const Z_GEMM: usize = 2;
    pub const SCAN: usize = 3;
    pub const OUT_GEMM: usize = 4;
    pub const OUT_D2H: usize = 5;
    pub const ST_D2H: usize = 6;
    /// task 225: beta/alpha 射影 (デバイス版)。
    pub const BA_GEMM: usize = 7;
    pub const N: usize = 8;
    pub const NAMES: [&str; N] = [
        "x_h2d", "qkv_gemm", "z_gemm", "scan", "out_gemm", "out_d2h", "st_d2h", "ba_gemm",
    ];

    static NS: [AtomicU64; N] = [const { AtomicU64::new(0) }; N];
    static CNT: [AtomicU64; N] = [const { AtomicU64::new(0) }; N];

    /// 計測するか (`DENNO_GDN_PF_KPROF` があるとき)。
    pub fn on() -> bool {
        static ON: OnceLock<bool> = OnceLock::new();
        *ON.get_or_init(|| std::env::var_os("DENNO_GDN_PF_KPROF").is_some())
    }

    /// 積算を 0 に戻す。
    pub fn reset() {
        for i in 0..N {
            NS[i].store(0, Ordering::Relaxed);
            CNT[i].store(0, Ordering::Relaxed);
        }
        open_reset();
    }

    /// 1 行にまとめる (1 本も打っていなければ `None`)。
    pub fn lines() -> Vec<String> {
        if !on() {
            return Vec::new();
        }
        let cnt: u64 = CNT.iter().map(|c| c.load(Ordering::Relaxed)).sum();
        if cnt == 0 {
            return Vec::new();
        }
        let mut s = String::from("[gdn-pf-kprof] 段ごとの GPU 時間 (イベント計測)");
        for i in 0..N {
            let ns = NS[i].load(Ordering::Relaxed);
            let n = CNT[i].load(Ordering::Relaxed);
            if n == 0 {
                continue;
            }
            s.push_str(&format!(
                " | {} {:.1}ms/{}",
                NAMES[i],
                ns as f64 / 1e6,
                n
            ));
        }
        vec![s]
    }

    fn add_ns(i: usize, ns: u64) {
        if i >= N {
            return;
        }
        NS[i].fetch_add(ns, Ordering::Relaxed);
        CNT[i].fetch_add(1, Ordering::Relaxed);
    }

    /// イベントのプール (スレッドローカル)。収集のたびに先頭から使い直す。
    struct Pool {
        evs: Vec<CUevent>,
        used: usize,
        dead: bool,
    }

    thread_local! {
        static P: std::cell::RefCell<Pool> = const {
            std::cell::RefCell::new(Pool { evs: Vec::new(), used: 0, dead: false })
        };
        /// 段ごとの入口イベント番号。
        static OPEN: std::cell::RefCell<[Option<u32>; N]> = const {
            std::cell::RefCell::new([None; N])
        };
        /// 収集待ちの (段, 入口, 出口)。
        static PEND: std::cell::RefCell<Vec<(u8, u32, u32)>> =
            const { std::cell::RefCell::new(Vec::new()) };
    }

    fn mark() -> Option<u32> {
        P.with(|c| {
            let mut p = c.borrow_mut();
            if p.dead {
                return None;
            }
            if p.used >= p.evs.len() {
                let Some(create) = lib().ok().and_then(|l| l.event_create) else {
                    p.dead = true;
                    return None;
                };
                let mut ev: CUevent = std::ptr::null_mut();
                // CU_EVENT_DEFAULT (0) = 計時有効。
                if unsafe { create(&mut ev, 0) } != CUDA_SUCCESS || ev.is_null() {
                    p.dead = true;
                    return None;
                }
                p.evs.push(ev);
            }
            let Some(rec) = lib().ok().and_then(|l| l.event_record) else {
                p.dead = true;
                return None;
            };
            let ev = p.evs[p.used];
            if unsafe { rec(ev, std::ptr::null_mut()) } != CUDA_SUCCESS {
                p.dead = true;
                return None;
            }
            let i = p.used as u32;
            p.used += 1;
            Some(i)
        })
    }

    fn open_reset() {
        OPEN.with(|c| {
            let mut o = c.borrow_mut();
            for v in o.iter_mut() {
                *v = None;
            }
        });
        PEND.with(|c| c.borrow_mut().clear());
        P.with(|c| c.borrow_mut().used = 0);
    }

    /// 段の入口 (on でなければ 1 分岐)。
    pub fn begin(item: usize) {
        if !on() || item >= N {
            return;
        }
        let a = mark();
        OPEN.with(|c| c.borrow_mut()[item] = a);
    }

    /// 段の出口。
    pub fn end(item: usize) {
        if !on() || item >= N {
            return;
        }
        let a = OPEN.with(|c| c.borrow_mut()[item].take());
        let Some(a) = a else { return };
        if let Some(b) = mark() {
            PEND.with(|c| c.borrow_mut().push((item as u8, a, b)));
        }
    }

    /// 積算する (**同期の後**に呼ぶ。イベントが完了している必要がある)。
    ///
    /// task 407: まだ GPU が通っていない段 (イベントが未完了 = `CUDA_ERROR_NOT_READY`)
    /// は**捨てずに次回へ回す**。捨てると、同期を省いた経路
    /// (`DENNO_PF_GDN_STATE_LAST` で書き戻しを飛ばしたチャンクなど) の段だけが
    /// 数から抜けて合計が小さく出る (P397 §6-1 の「scan が 36 回しか出ない」)。
    pub fn collect() {
        if !on() {
            return;
        }
        let Some(f) = lib().ok().and_then(|l| l.event_elapsed_time) else {
            return;
        };
        let pend = PEND.with(|c| std::mem::take(&mut *c.borrow_mut()));
        if pend.is_empty() {
            return;
        }
        let mut keep: Vec<(u8, u32, u32)> = Vec::new();
        P.with(|c| {
            let p = c.borrow();
            for (item, a, b) in pend {
                let (Some(&ea), Some(&eb)) = (p.evs.get(a as usize), p.evs.get(b as usize))
                else {
                    continue;
                };
                let mut ms = 0.0f32;
                if unsafe { f(&mut ms, ea, eb) } == CUDA_SUCCESS && ms.is_finite() && ms >= 0.0 {
                    add_ns(item as usize, (ms as f64 * 1e6) as u64);
                } else {
                    keep.push((item, a, b));
                }
            }
        });
        if keep.is_empty() {
            // イベントは先頭から使い直す (プールは数十本で足りる)。
            P.with(|c| c.borrow_mut().used = 0);
        } else {
            PEND.with(|c| c.borrow_mut().extend(keep));
        }
    }
}

// ===========================================================================
// task 187: decode の IQ expert 段 (1 層 4 起動 + D2H) の GPU 時間をイベントで
// 段ごとに測る。`DENNO_Q4_PROFILE` のときだけ動く (台帳と同じ窓)。
//
// 目的 (task 187 の表): 「experts の gpu 3.3 ms は expert 数とカーネルごとに
// いくらか」を実測で割る。ヒット本数ごとの層数も一緒に積む。
// ===========================================================================
pub mod dec_exp_kprof {
    use super::*;

    /// 段の番号 (この順で 1 行に出す)。
    pub const GATE: usize = 0;
    pub const UP: usize = 1;
    pub const SILU: usize = 2;
    pub const DOWN: usize = 3;
    pub const D2H: usize = 4;
    /// task 187: デバイス和 (`dno_dec_exp_sum`)。
    pub const SUM: usize = 5;
    pub const N: usize = 6;
    pub const NAMES: [&str; N] = ["gate", "up", "silu", "down", "d2h", "sum"];
    /// ヒット本数の上限 (n_expert_used = 10 まで数える)。
    pub const MAX_HITS: usize = 10;

    static NS: [AtomicU64; N] = [const { AtomicU64::new(0) }; N];
    static CNT: [AtomicU64; N] = [const { AtomicU64::new(0) }; N];
    /// ヒット本数ごとの層数と合計 ns。
    static BUCKET_N: [AtomicU64; MAX_HITS + 1] = [const { AtomicU64::new(0) }; MAX_HITS + 1];
    static BUCKET_NS: [AtomicU64; MAX_HITS + 1] = [const { AtomicU64::new(0) }; MAX_HITS + 1];

    // ------------------------------------------------------------------
    // task 190: 型 (gate/up/down のスロット) × 行数 の表
    //
    // 「expert カーネルが IQ の型と行数でいくらか」を出すための積算。1 層 =
    // gate / up / silu / down の 4 起動なので、層の合計 ns を (型, 行数) に
    // 積む。行数は 1 層の起動が扱う出力行の合計 (`nseg*(ff + e)` に相当)。
    // ------------------------------------------------------------------

    /// (slot_g, slot_u, slot_d) の組み合わせ数。
    pub const FKIND: usize = crate::model::exp_iq::SLOTS * crate::model::exp_iq::SLOTS
        * crate::model::exp_iq::SLOTS;
    /// 行数のバケット数 (2 の冪で 1,000 行を下限にする)。
    pub const FROW: usize = 8;

    /// 1 セルぶんの積算。
    struct KAcc {
        calls: AtomicU64,
        experts: AtomicU64,
        bytes: AtomicU64,
        ns: AtomicU64,
    }

    static KFMT: [KAcc; FKIND] = [const {
        KAcc {
            calls: AtomicU64::new(0),
            experts: AtomicU64::new(0),
            bytes: AtomicU64::new(0),
            ns: AtomicU64::new(0),
        }
    }; FKIND];
    static KROW: [KAcc; FROW] = [const {
        KAcc {
            calls: AtomicU64::new(0),
            experts: AtomicU64::new(0),
            bytes: AtomicU64::new(0),
            ns: AtomicU64::new(0),
        }
    }; FROW];

    thread_local! {
        /// この層の (slot_g*36 + slot_u*6 + slot_d)。
        static KIND: std::cell::Cell<usize> = const { std::cell::Cell::new(usize::MAX) };
        static K_NSEG: std::cell::Cell<u64> = const { std::cell::Cell::new(0) };
        static K_ROWS: std::cell::Cell<u64> = const { std::cell::Cell::new(0) };
        static K_BYTES: std::cell::Cell<u64> = const { std::cell::Cell::new(0) };
    }

    /// 層の (型, 行数, 重みバイト) を控える ([`begin_layer`] の直後に呼ぶ)。
    ///
    /// `rows_gu` = gate/up の出力行 (通常 ff)、`rows_d` = down の出力行 (通常 e)。
    #[allow(clippy::too_many_arguments)]
    pub fn note_kind(
        slot_g: usize,
        slot_u: usize,
        slot_d: usize,
        nseg: usize,
        rows_gu: usize,
        rows_d: usize,
        bytes: u64,
    ) {
        if !on() {
            return;
        }
        let slots = crate::model::exp_iq::SLOTS;
        let kind = (slot_g.min(slots - 1)) * slots * slots
            + (slot_u.min(slots - 1)) * slots
            + slot_d.min(slots - 1);
        KIND.with(|c| c.set(kind));
        K_NSEG.with(|c| c.set(nseg as u64));
        K_ROWS.with(|c| c.set((nseg * (rows_gu + rows_d)) as u64));
        K_BYTES.with(|c| c.set(bytes));
    }

    /// 行数のバケット (1,000 行 = 0、2,000 = 1、4,000 = 2、... 128,000 以上 = 7)。
    fn row_bucket(rows: u64) -> usize {
        let mut b = 0usize;
        let mut lim = 2_000u64;
        while b + 1 < FROW && rows >= lim {
            b += 1;
            lim *= 2;
        }
        b
    }

    /// 計測するか (台帳と同じ `DENNO_Q4_PROFILE`。テストの強制も含む)。
    pub fn on() -> bool {
        crate::model::q4ledger::enabled()
    }

    /// 積算を 0 に戻す。
    pub fn reset() {
        for i in 0..N {
            NS[i].store(0, Ordering::Relaxed);
            CNT[i].store(0, Ordering::Relaxed);
        }
        for i in 0..=MAX_HITS {
            BUCKET_N[i].store(0, Ordering::Relaxed);
            BUCKET_NS[i].store(0, Ordering::Relaxed);
        }
        for a in KFMT.iter().chain(KROW.iter()) {
            a.calls.store(0, Ordering::Relaxed);
            a.experts.store(0, Ordering::Relaxed);
            a.bytes.store(0, Ordering::Relaxed);
            a.ns.store(0, Ordering::Relaxed);
        }
        KIND.with(|c| c.set(usize::MAX));
        POOL_DEAD.with(|d| d.set(false));
    }

    /// 1 行にまとめる (1 本も打っていなければ `None`)。
    pub fn lines() -> Vec<String> {
        if !on() {
            return Vec::new();
        }
        let cnt: u64 = CNT.iter().map(|c| c.load(Ordering::Relaxed)).sum();
        if cnt == 0 {
            return Vec::new();
        }
        let mut s = String::from("[dec-exp-kprof] 層内の GPU 時間 (イベント計測)");
        for i in 0..N {
            let ns = NS[i].load(Ordering::Relaxed);
            let n = CNT[i].load(Ordering::Relaxed);
            if n == 0 {
                continue;
            }
            s.push_str(&format!(
                " | {} {:.2}ms/{:.0} ({:.1}us/層)",
                NAMES[i],
                ns as f64 / 1e6,
                n,
                ns as f64 / 1e3 / n as f64
            ));
        }
        let mut out = vec![s];
        let mut b = String::from("[dec-exp-kprof] ヒット本数ごと (層数 / 合計 ms / 1 層 us)");
        for h in 0..=MAX_HITS {
            let n = BUCKET_N[h].load(Ordering::Relaxed);
            if n == 0 {
                continue;
            }
            let ns = BUCKET_NS[h].load(Ordering::Relaxed);
            b.push_str(&format!(
                " | h{h} {n}層 {:.2}ms {:.1}us",
                ns as f64 / 1e6,
                ns as f64 / 1e3 / n as f64
            ));
        }
        out.push(b);
        // task 190: 型 (gate/up/down) ごとの表。
        let mut f = String::from("[exp-iq-kprof] 型ごと (g/u/d): calls experts rows bytes us/expert GB/s");
        let mut any = false;
        for (k, a) in KFMT.iter().enumerate() {
            let calls = a.calls.load(Ordering::Relaxed);
            if calls == 0 {
                continue;
            }
            any = true;
            let slots = crate::model::exp_iq::SLOTS;
            let (g, u, d) = (k / (slots * slots), (k / slots) % slots, k % slots);
            let experts = a.experts.load(Ordering::Relaxed);
            let bytes = a.bytes.load(Ordering::Relaxed);
            let ns = a.ns.load(Ordering::Relaxed);
            let us_ex = if experts > 0 {
                ns as f64 / 1e3 / experts as f64
            } else {
                0.0
            };
            let gbs = if ns > 0 {
                bytes as f64 / ns as f64
            } else {
                0.0
            };
            f.push_str(&format!(
                " | {g}/{u}/{d} {calls}層 {experts}本 {:.1}MB {us_ex:.1}us/本 {gbs:.0}GB/s",
                bytes as f64 / 1e6
            ));
        }
        if any {
            out.push(f);
        }
        // task 190: 行数バケットごとの表 (1 層 = gate/up + down の出力行の合計)。
        let mut r = String::from("[exp-iq-kprof] 行数ごと: rows calls experts us/launch us/expert GB/s");
        let mut any = false;
        for (i, a) in KROW.iter().enumerate() {
            let calls = a.calls.load(Ordering::Relaxed);
            if calls == 0 {
                continue;
            }
            any = true;
            let experts = a.experts.load(Ordering::Relaxed);
            let bytes = a.bytes.load(Ordering::Relaxed);
            let ns = a.ns.load(Ordering::Relaxed);
            let lo = if i == 0 { 0u64 } else { 2_000u64 << (i - 1) };
            let us_call = ns as f64 / 1e3 / calls as f64;
            let us_ex = if experts > 0 {
                ns as f64 / 1e3 / experts as f64
            } else {
                0.0
            };
            let gbs = if ns > 0 {
                bytes as f64 / ns as f64
            } else {
                0.0
            };
            r.push_str(&format!(
                " | >={lo} {calls}層 {experts}本 {us_call:.1}us {us_ex:.1}us/本 {gbs:.0}GB/s"
            ));
        }
        if any {
            out.push(r);
        }
        out
    }

    thread_local! {
        /// イベントのプール。層ごとに先頭から使い直す。
        static POOL: std::cell::RefCell<Vec<CUevent>> = const {
            std::cell::RefCell::new(Vec::new())
        };
        static POOL_USED: std::cell::Cell<usize> = const { std::cell::Cell::new(0) };
        /// 直前のイベント (段の開始点) と、収集待ちの (段, 入口, 出口)。
        static LAST: std::cell::Cell<Option<CUevent>> = const { std::cell::Cell::new(None) };
        static PEND: std::cell::RefCell<Vec<(usize, CUevent, CUevent)>> = const {
            std::cell::RefCell::new(Vec::new())
        };
        /// この層のヒット本数 (end で束へ積む)。
        static HITS: std::cell::Cell<u32> = const { std::cell::Cell::new(0) };
    }
    thread_local! {
        static POOL_DEAD: std::cell::Cell<bool> = const { std::cell::Cell::new(false) };
    }

    /// 層の入口。`hits` は GPU で回した expert 数。
    pub fn begin_layer(hits: u32) {
        if !on() {
            return;
        }
        HITS.with(|c| c.set(hits));
        POOL_USED.with(|c| c.set(0));
        PEND.with(|c| c.borrow_mut().clear());
        let ev = record();
        LAST.with(|c| c.set(ev));
    }

    /// 段 `item` の終わり (イベントを 1 本打って差を**収集待ち**に積む)。
    ///
    /// 経過は [`end_layer`] で読む: overlap 経路では D2H のイベントを同期の
    /// **前**に打つので、ここで `cuEventElapsedTime` を呼ぶと未完了で失敗する。
    pub fn mark(item: usize) {
        if !on() || item >= N {
            return;
        }
        let Some(prev) = LAST.with(|c| c.get()) else {
            return;
        };
        let Some(cur) = record() else { return };
        PEND.with(|c| c.borrow_mut().push((item, prev, cur)));
        LAST.with(|c| c.set(Some(cur)));
    }

    /// 層の出口 (**同期の後**に呼ぶ)。
    pub fn end_layer() {
        if !on() {
            return;
        }
        LAST.with(|c| c.set(None));
        let Some(f) = lib().ok().and_then(|l| l.event_elapsed_time) else {
            PEND.with(|c| c.borrow_mut().clear());
            return;
        };
        let pend = PEND.with(|c| std::mem::take(&mut *c.borrow_mut()));
        let mut acc = [0u64; N];
        let mut sum = 0u64;
        for (item, a, b) in pend {
            let mut ms = 0.0f32;
            if unsafe { f(&mut ms, a, b) } == CUDA_SUCCESS && ms.is_finite() && ms >= 0.0 {
                let ns = (ms as f64 * 1e6) as u64;
                acc[item] += ns;
                sum += ns;
            }
        }
        for i in 0..N {
            if acc[i] == 0 {
                continue;
            }
            NS[i].fetch_add(acc[i], Ordering::Relaxed);
            CNT[i].fetch_add(1, Ordering::Relaxed);
        }
        let h = (HITS.with(|c| c.get()) as usize).min(MAX_HITS);
        BUCKET_N[h].fetch_add(1, Ordering::Relaxed);
        BUCKET_NS[h].fetch_add(sum, Ordering::Relaxed);
        // task 190: gate + up + silu + down の 4 段だけを「expert カーネル」として
        // (型, 行数) に積む (D2H と和は別物なので入れない)。
        let gemv_ns = acc[GATE] + acc[UP] + acc[SILU] + acc[DOWN];
        let kind = KIND.with(|c| c.get());
        if kind != usize::MAX && gemv_ns > 0 {
            let nseg = K_NSEG.with(|c| c.get());
            let rows = K_ROWS.with(|c| c.get());
            let bytes = K_BYTES.with(|c| c.get());
            let cell = &KFMT[kind.min(FKIND - 1)];
            cell.calls.fetch_add(1, Ordering::Relaxed);
            cell.experts.fetch_add(nseg, Ordering::Relaxed);
            cell.bytes.fetch_add(bytes, Ordering::Relaxed);
            cell.ns.fetch_add(gemv_ns, Ordering::Relaxed);
            let cell = &KROW[row_bucket(rows).min(FROW - 1)];
            cell.calls.fetch_add(1, Ordering::Relaxed);
            cell.experts.fetch_add(nseg, Ordering::Relaxed);
            cell.bytes.fetch_add(bytes, Ordering::Relaxed);
            cell.ns.fetch_add(gemv_ns, Ordering::Relaxed);
        }
    }

    /// イベントを 1 本打つ (プールから取る)。
    fn record() -> Option<CUevent> {
        if !on() || POOL_DEAD.with(|d| d.get()) {
            return None;
        }
        let Some(rec) = lib().ok().and_then(|l| l.event_record) else {
            POOL_DEAD.with(|d| d.set(true));
            return None;
        };
        POOL.with(|c| {
            let mut p = c.borrow_mut();
            let i = POOL_USED.with(|u| u.get());
            if i >= p.len() {
                let Some(create) = lib().ok().and_then(|l| l.event_create) else {
                    POOL_DEAD.with(|d| d.set(true));
                    return None;
                };
                let mut ev: CUevent = std::ptr::null_mut();
                // CU_EVENT_DEFAULT (0) = 計時有効。
                if unsafe { create(&mut ev, 0) } != CUDA_SUCCESS || ev.is_null() {
                    POOL_DEAD.with(|d| d.set(true));
                    return None;
                }
                p.push(ev);
            }
            POOL_USED.with(|u| u.set(i + 1));
            let ev = p[i];
            if unsafe { rec(ev, std::ptr::null_mut()) } != CUDA_SUCCESS {
                POOL_DEAD.with(|d| d.set(true));
                return None;
            }
            Some(ev)
        })
    }
}

/// task 167: ssm 層 1 チャンクを「qkv 投影 → z 投影 → GDN スキャン → out_proj」の
/// デバイス連鎖で回す。成功したら `out` に層の出力 [nt, e] を書く。
///
/// 戻り値 `Ok(false)` は「何もしていない」= 呼び出し側は従来経路へ落ちてよい。
/// スキャン起動後の失敗は `Err` (状態が進んでいるので要求を落とすこと)。
#[allow(clippy::too_many_arguments)]
pub fn gdn_pf_chain(
    wq: PfChainQkv<'_>,
    wout: PfChainW<'_>,
    flat: &[f32],
    beta: &[f32],
    alpha: &[f32],
    // task 186: Some のとき beta/alpha は **デバイスで作る** (`DENNO_PF_SSM_GEMM_GPU`)。
    // そのとき `beta` / `alpha` は空でよい (ホスト側の計算を省く)。
    beta_alpha: Option<PfBetaAlpha<'_>>,
    conv_st: &mut [f32],
    ssm_st: &mut [f32],
    wconv: &[f32],
    wa: &[f32],
    wdt: &[f32],
    wnorm: &[f32],
    nt: usize,
    nk: usize,
    nv: usize,
    dk: usize,
    dv: usize,
    d_conv: usize,
    eps: f32,
    q_scale: f32,
    li: usize,
    kv: u64,
    out: &mut [f32],
    // task 200: `true` を返したときは層出力を**デバイスに残した** (`out` は未書き込み)。
    // 直後の `pf_combine_dev` がそのまま読む (`DENNO_PF_ATTN_DEVRES`)。
    kept_dev: &mut bool,
    phase_ns: &mut [u64; 3],
) -> Result<bool> {
    let e = wq.qkv.k;
    let conv_dim = 2 * nk * dk + nv * dv;
    let vd = nv * dv;
    let cs = d_conv - 1;
    if !gdn_pf_chain_ready(&wq, &wout, nt, e, nk, nv, dk, dv, d_conv) {
        return Ok(false);
    }
    // `DENNO_GPU_GEMM=0` は従来経路でも GEMM を CPU に落とす。連鎖も同じ扱いにする
    // (ゲート off のときの木を 1 バイトも変えない)。
    if !gpu_gemm_enabled() {
        return Ok(false);
    }
    let ba_dev_req = beta_alpha.is_some() && pf_ba_dev_on();
    if flat.len() != nt * e
        || (ba_dev_req && (!beta.is_empty() || !alpha.is_empty()))
        || (!ba_dev_req && (beta.len() != nt * nv || alpha.len() != nt * nv))
        || out.len() != nt * e
        || conv_st.len() != conv_dim * cs
        || ssm_st.len() != nv * dk * dv
        || wconv.len() != conv_dim * d_conv
        || wa.len() != nv
        || wdt.len() != nv
        || wnorm.len() != dv
    {
        return Ok(false);
    }
    let Some(ctx) = shared_ctx() else {
        return Ok(false);
    };
    if let Err(err) = ctx.make_current() {
        tracing::error!("CUDA cuCtxSetCurrent failed, GDN prefill chain skipped: {err:#}");
        GPU_BROKEN.store(true, std::sync::atomic::Ordering::Relaxed);
        return Ok(false);
    }
    let Some(f_scan) = ctx.f_gdn_scan_sig else {
        // 旧 PTX (sig 未収録) では黙って従来経路へ (ラッチはしない)。
        return Ok(false);
    };
    // task 270: スキャンカーネルを**投影より前**に選ぶ。`nt >= 2048` では単発
    // sigmoid (`f_scan`) の前提外なので、v1/v2/v3/WY のどれも撃てなければ
    // まだ何も書いていないここで降りる (呼び出し側は従来経路で計算し直す)。
    // 既定の順は task 173/186/225/228/311 のまま: WY8 (opt-in) → WY4 (opt-in)
    // → WY (opt-in) → v3 → v2 → v1。
    // task 407: wy7q / wy7 (バリア削減 + P/QP の S 読み直し削減) が先、次に wy6p /
    // wy6 (占有率。t407a で +45% と分かったので既定 off のまま A/B 用)、
    // 既定は wy5 (wy4 も既定 on のまま後ろに残す)。
    let pf_scan_wy7q = if gdn_pf_wy7q_on() && gdn_pf_wy7_ok(nt, nk, nv, dk, dv, d_conv, conv_dim) {
        gdn_pf_wy7q_kernels()
    } else {
        None
    };
    let pf_scan_wy7 = if pf_scan_wy7q.is_none()
        && gdn_pf_wy7_on()
        && gdn_pf_wy7_ok(nt, nk, nv, dk, dv, d_conv, conv_dim)
    {
        gdn_pf_wy7_kernels()
    } else {
        None
    };
    let pf_scan_wy6p = if pf_scan_wy7q.is_none()
        && pf_scan_wy7.is_none()
        && gdn_pf_wy6p_on()
        && gdn_pf_wy6_ok(nt, nk, nv, dk, dv, d_conv, conv_dim)
    {
        gdn_pf_wy6p_kernels()
    } else {
        None
    };
    let pf_scan_wy6 = if pf_scan_wy6p.is_none()
        && gdn_pf_wy6_on()
        && gdn_pf_wy6_ok(nt, nk, nv, dk, dv, d_conv, conv_dim)
    {
        gdn_pf_wy6_kernels()
    } else {
        None
    };
    let pf_scan_wy5 = if pf_scan_wy6p.is_none()
        && pf_scan_wy6.is_none()
        && gdn_pf_wy5_on()
        && gdn_pf_wy5_ok(nt, nk, nv, dk, dv, d_conv, conv_dim)
    {
        gdn_pf_wy5_kernels()
    } else {
        None
    };
    let pf_scan_wy4 = if pf_scan_wy5.is_none()
        && gdn_pf_wy4_on()
        && gdn_pf_wy4_ok(nt, nk, nv, dk, dv, d_conv, conv_dim)
    {
        gdn_pf_wy4_kernels()
    } else {
        None
    };
    let pf_scan_wy = if pf_scan_wy4.is_none()
        && gdn_pf_wy_on()
        && gdn_pf_wy_ok(nt, nk, nv, dk, dv, d_conv, conv_dim)
    {
        gdn_pf_wy_kernels()
    } else {
        None
    };
    let pf_scan_fast3 = if pf_scan_wy.is_none()
        && gdn_pf3_on()
        && gdn_pf3_ok(nt, nk, nv, dk, dv, d_conv, conv_dim)
    {
        gdn_pf3_kernels()
    } else {
        None
    };
    let pf_scan_fast2 = if pf_scan_fast3.is_none()
        && gdn_pf2_on()
        && gdn_pf2_ok(nt, nk, nv, dk, dv, d_conv, conv_dim)
    {
        gdn_pf2_kernels()
    } else {
        None
    };
    let pf_scan_fast = if pf_scan_fast2.is_none()
        && gdn_pf_fast_on()
        && gdn_pf_fast_eligible(nt, nk, nv, dk, dv, d_conv, conv_dim)
    {
        gdn_pf_kernels()
    } else {
        None
    };
    if nt >= GDN_CHUNK_MIN_TOKENS
        && pf_scan_wy7q.is_none()
        && pf_scan_wy7.is_none()
        && pf_scan_wy6p.is_none()
        && pf_scan_wy6.is_none()
        && pf_scan_wy5.is_none()
        && pf_scan_wy4.is_none()
        && pf_scan_wy.is_none()
        && pf_scan_fast3.is_none()
        && pf_scan_fast2.is_none()
        && pf_scan_fast.is_none()
    {
        // 状態は 1 つも触っていない (scratch のゼロ埋めだけ)。
        return Ok(false);
    }
    // 重みは 3 本とも「デバイスに載る」ことを先に確かめる。ここまでの失敗は
    // 状態を 1 つも触っていないので `Ok(false)` で従来経路に戻せる。
    let (wqkv, wgate, wo) = match (
        weights_for_gguf(wq.qkv.uid, wq.qkv.ty, wq.qkv.blocks, wq.qkv.k, wq.qkv.n),
        weights_for_gguf(wq.gate.uid, wq.gate.ty, wq.gate.blocks, wq.gate.k, wq.gate.n),
        weights_for_gguf(wout.uid, wout.ty, wout.blocks, wout.k, wout.n),
    ) {
        (Ok(a), Ok(b), Ok(c)) => (a, b, c),
        (a, b, c) => {
            for r in [a.err(), b.err(), c.err()].into_iter().flatten() {
                tracing::error!("GDN prefill chain: 重みの登録に失敗: {r:#}");
            }
            return Ok(false);
        }
    };
    // 連結済みのときは qkv と gate が同じ行列を指す。行オフセットを
    // バイトに直して GEMM の重み先頭をずらす (カーネルは `w + row*row_bytes`
    // で行を読むので、部分行列をそのまま渡せる)。
    let Some(rb_qkv) = gguf_row_bytes(wq.qkv.ty, e) else {
        return Ok(false);
    };
    let qkv_woff = wq.qkv_row * rb_qkv;
    let gate_woff = wq.gate_row * rb_qkv;
    // ここから先はデバイスの作業域だけを触る (モデルの状態は不変)。
    let ptrs = GDN_SCRATCH.with(|cell| -> Result<[CUdeviceptr; 6]> {
        let mut s = cell.borrow_mut();
        s.ensure_chain(conv_dim, nv, dk, dv, cs)?;
        // スキャンカーネルは「書かない領域」を残すので従来どおりゼロ埋め。
        s.buf(GdnBuf::ConvOut).fill_zero()?;
        s.buf(GdnBuf::SsmOut).fill_zero()?;
        gdn_put_weights(&s, li, [wconv, wa, wdt, wnorm])?;
        Ok(s.chain_ptrs())
    })?;
    // task 186: beta/alpha をデバイスで作る場合の重み常駐 (失敗は None → ホスト経路)。
    // task 228: 元の型を問わず f32 へ展開して常駐する (`pf_ba_weight_dev`)。
    // 判定は呼び出し側と同じ純関数 [`pf_ba_w_check`] を使う。
    let ba_dev = if ba_dev_req {
        beta_alpha.and_then(|ba| {
            let w = ba.w;
            // task 225: alpha が別の行列 (未連結) のときは 2 本を別々に常駐する。
            let wa = match ba.alpha_w {
                Some(aw) => aw,
                None => w,
            };
            if let Some(why) = pf_ba_w_check(w.ty, w.k, w.n, &ba.beta_rows, nv, e)
                .or_else(|| pf_ba_w_check(wa.ty, wa.k, wa.n, &ba.alpha_rows, nv, e))
            {
                tracing::warn!("GDN prefill chain: beta/alpha をデバイスに置けない: {why}");
                return None;
            }
            let (p, rb) = pf_ba_weight_dev(w.uid, w.ty, w.blocks, w.k, w.n)?;
            let (pa, rba) = if ba.alpha_w.is_some() {
                pf_ba_weight_dev(wa.uid, wa.ty, wa.blocks, wa.k, wa.n)?
            } else {
                (p, rb)
            };
            Some((
                p + (ba.beta_rows.start * rb) as CUdeviceptr,
                pa + (ba.alpha_rows.start * rba) as CUdeviceptr,
            ))
        })
    } else {
        None
    };
    // ホスト側の beta/alpha を作らせたのにデバイス版が使えない場合は、ここで
    // 連鎖を諦める (状態は未着手。呼び出し側が従来経路で作り直す)。空のスライスで
    // H2D すると古い中身のままスキャンに入ってしまうので、必ず落とす。
    if ba_dev_req && ba_dev.is_none() {
        return Ok(false);
    }
    // task 317: 直前の attn mix を D2H していなければ (`DENNO_PF_MIXKEEP_SSM`)、
    // デバイスの `mixed` をそのまま入力にする。`b.x` への H2D 1 本 (nt × e × 4 B)
    // が消えるだけで、値は同じバイト列。
    let xdev = if pf_mix_keep_ssm_on() {
        pf_mixed_dev_in_ptr(flat.as_ptr(), nt, e)
    } else {
        None
    };
    // 記録は「デバイスだけが正」なのに dev-in が取れない (作業域の形が合わない等)
    // ときは、古いホストのバイト列を上げないように先に降ろす。降ろせなければ
    // 何も書いていないここで要求を落とす (誤った値で走らせない)。
    if xdev.is_none() && pf_mixed_dev_only(flat.as_ptr(), nt, e) {
        if !pf_mixed_restore_host(flat.as_ptr() as *mut f32, nt, e) {
            bail!("GDN 連鎖: D2H していない mixed の復元に失敗 (li={li})");
        }
    }
    gdn_pf_kprof::begin(gdn_pf_kprof::X_H2D);
    let ptr = GDN_PF_CHAIN_BUF.with(|cell| -> Result<[CUdeviceptr; 7]> {
        let mut b = cell.borrow_mut();
        b.ensure(nt, e, conv_dim, vd, nv)?;
        if xdev.is_none() {
            b.x.as_ref().unwrap().copy_from(flat)?;
        }
        if ba_dev.is_none() {
            b.beta.as_ref().unwrap().copy_from(beta)?;
            b.alpha.as_ref().unwrap().copy_from(alpha)?;
        }
        Ok([
            xdev.unwrap_or_else(|| b.buf(0)),
            b.buf(1),
            b.buf(2),
            b.buf(3),
            b.buf(4),
            b.buf(5),
            b.buf(6),
        ])
    })?;
    gdn_pf_kprof::end(gdn_pf_kprof::X_H2D);
    let (px, po, pqkv, pz, py, pb, pa) = (ptr[0], ptr[1], ptr[2], ptr[3], ptr[4], ptr[5], ptr[6]);

    // task 169: 3 本の投影がすべてテンソルコア GEMM の前提を満たすときだけ、
    // 1 起動でチャンク全体 (最大 TC_MAX_TOKENS 行) を回す。満たさないときは
    // 従来どおり 128 トークンずつ (旧カーネルの上限)。
    // task 176: v2 カーネルは Q4_K / Q5_K も扱えるので、判定は
    // `pf_gemm_fast_ok` (v2 → br169 の順) に任せる。
    let tc_ready = pf_gemm_fast_ok(wq.qkv.ty, nt, e, conv_dim, pf_tc_min_m())
        && pf_gemm_fast_ok(wq.gate.ty, nt, e, vd, pf_tc_min_m())
        && pf_gemm_fast_ok(wout.ty, nt, vd, e, pf_tc_min_m());
    let gemm_tile = if tc_ready { TC_MAX_TOKENS } else { 128 };

    // ---- qkv / z 投影 (デバイス → デバイス) --------------------------------
    {
        let _s = crate::model::q4ledger::sub(crate::model::q4ledger::SUB_PF_QKV);
        let t_ph = Instant::now();
        let mut t0 = 0usize;
        while t0 < nt {
            let m = (nt - t0).min(gemm_tile);
            let xo = px + (t0 * e * 4) as CUdeviceptr;
            let qo = pqkv + (t0 * conv_dim * 4) as CUdeviceptr;
            let zo = pz + (t0 * vd * 4) as CUdeviceptr;
            for (idx, (w, wty, n_out, o)) in [
                (
                    wqkv.buf.ptr() + qkv_woff as CUdeviceptr,
                    wq.qkv.ty,
                    conv_dim,
                    qo,
                ),
                (
                    wgate.buf.ptr() + gate_woff as CUdeviceptr,
                    wq.gate.ty,
                    vd,
                    zo,
                ),
            ]
            .into_iter()
            .enumerate()
            {
                // task 173: 段ごとの GPU 時間 (イベント)。qkv と z を分けて積む。
                let kp = if idx == 0 {
                    gdn_pf_kprof::QKV_GEMM
                } else {
                    gdn_pf_kprof::Z_GEMM
                };
                gdn_pf_kprof::begin(kp);
                let r = gguf_gemm_dev_launch(&ctx, wty, w, xo, o, m, e, n_out, gdn_pf_tc1_on());
                gdn_pf_kprof::end(kp);
                match r {
                    Ok(true) => {}
                    Ok(false) => return Ok(false),
                    Err(err) => {
                        tracing::error!("GDN prefill chain: 投影の起動に失敗: {err:#}");
                        GPU_BROKEN.store(true, std::sync::atomic::Ordering::Relaxed);
                        return Ok(false);
                    }
                }
            }
            t0 += m;
        }
        // task 186: beta/alpha (F32) を同じ x から作る。入力も出力もデバイスに
        // あるので転送は 0。無い/形が違うときは連鎖ごと従来経路へ (状態は未着手)。
        if let Some((wbeta, walpha)) = ba_dev {
            // task 225: 専用 GEMM (`DENNO_PF_BA_FAST`) が撃てればそちら。
            // 撃てないときは従来の `dno_gemm_f32_mt` (lab t183a: ホストより遅い)。
            gdn_pf_kprof::begin(gdn_pf_kprof::BA_GEMM);
            let mut ba_fast_done = false;
            if pf_ba_fast_on() {
                ba_fast_done = pf_ba_gemm_dev_launch(ctx, wbeta, px, pb, nt, e, nv)?
                    && pf_ba_gemm_dev_launch(ctx, walpha, px, pa, nt, e, nv)?;
            }
            if !ba_fast_done {
                let Some(f32g) = gemm_f32_mt_fn(ctx) else {
                    return Ok(false);
                };
                for (w, o) in [(wbeta, pb), (walpha, pa)] {
                    let (mut pw, mut pxx, mut poo) = (w, px, o);
                    let (mut nt_c, mut k_c, mut n_c) = (nt as c_int, e as c_int, nv as c_int);
                    let mut args = [
                        &mut pw as *mut _ as *mut c_void,
                        &mut pxx as *mut _ as *mut c_void,
                        &mut poo as *mut _ as *mut c_void,
                        &mut nt_c as *mut _ as *mut c_void,
                        &mut k_c as *mut _ as *mut c_void,
                        &mut n_c as *mut _ as *mut c_void,
                    ];
                    let grid = (
                        ((nv + GEMM_MT_ROWS - 1) / GEMM_MT_ROWS) as u32,
                        ((nt + GEMM_MT_TOKS - 1) / GEMM_MT_TOKS) as u32,
                        1,
                    );
                    unsafe {
                        ctx.launch_async(f32g, grid, (GEMM_MT_ROWS as u32, 16, 1), 0, &mut args)?;
                    }
                }
            }
            gdn_pf_kprof::end(gdn_pf_kprof::BA_GEMM);
        }
        // 段ごとの壁時計を意味のある値にするため、ここで 1 回だけ待つ
        // (1 チャンク = 1 段 40 ms 級なので、同期の固定費は無視できる)。
        // task 334: `DENNO_PF_ATTN_NOSYNC` なら待たない (次は同じストリーム)。
        pf_chain_sync(&ctx)?;
        phase_ns[0] = t_ph.elapsed().as_nanos() as u64;
    }

    // ---- GDN スキャン (状態はデバイス正本) ----------------------------------
    let (pst_conv, pst_ssm) =
        gdn_state_begin(kv, li, conv_st, ssm_st, conv_dim * cs, nv, dk * dv)?;
    // スキャンカーネルの選択 (`pf_scan_wy` / `pf_scan_fast3` / `pf_scan_fast2` /
    // `pf_scan_fast`) は task 270 で**投影より前**へ移した (大きい nt で撃てる
    // カーネルが無いときに、状態を進めずに降りるため)。
    {
        let _s = crate::model::q4ledger::sub(crate::model::q4ledger::SUB_PF_SCAN);
        let t_ph = Instant::now();
        if let Some(fns) = pf_scan_wy7q {
            gdn_pf_kprof::begin(gdn_pf_kprof::SCAN);
            gdn_pf_wy_launch(
                &ctx, fns, pqkv, pz, pb, pa, pst_conv, pst_ssm, ptrs[0], ptrs[1], ptrs[2],
                ptrs[3], py, ptrs[4], ptrs[5], nt, nk, nv, conv_dim, eps, q_scale,
                GDN_PF_WY6_BLOCKS, GDN_PF_WY4_THREADS, GDN_PF_WY7Q_SMEM_BYTES as u32,
            )?;
            gdn_pf_kprof::end(gdn_pf_kprof::SCAN);
        } else if let Some(fns) = pf_scan_wy7 {
            gdn_pf_kprof::begin(gdn_pf_kprof::SCAN);
            gdn_pf_wy_launch(
                &ctx, fns, pqkv, pz, pb, pa, pst_conv, pst_ssm, ptrs[0], ptrs[1], ptrs[2],
                ptrs[3], py, ptrs[4], ptrs[5], nt, nk, nv, conv_dim, eps, q_scale,
                GDN_PF_WY6_BLOCKS, GDN_PF_WY4_THREADS, GDN_PF_WY7_SMEM_BYTES as u32,
            )?;
            gdn_pf_kprof::end(gdn_pf_kprof::SCAN);
        } else if let Some(fns) = pf_scan_wy6p {
            gdn_pf_kprof::begin(gdn_pf_kprof::SCAN);
            gdn_pf_wy_launch(
                &ctx, fns, pqkv, pz, pb, pa, pst_conv, pst_ssm, ptrs[0], ptrs[1], ptrs[2],
                ptrs[3], py, ptrs[4], ptrs[5], nt, nk, nv, conv_dim, eps, q_scale,
                GDN_PF_WY6_BLOCKS, GDN_PF_WY6_THREADS, GDN_PF_WY6_SMEM_BYTES as u32,
            )?;
            gdn_pf_kprof::end(gdn_pf_kprof::SCAN);
        } else if let Some(fns) = pf_scan_wy6 {
            gdn_pf_kprof::begin(gdn_pf_kprof::SCAN);
            gdn_pf_wy_launch(
                &ctx, fns, pqkv, pz, pb, pa, pst_conv, pst_ssm, ptrs[0], ptrs[1], ptrs[2],
                ptrs[3], py, ptrs[4], ptrs[5], nt, nk, nv, conv_dim, eps, q_scale,
                GDN_PF_WY6_BLOCKS, GDN_PF_WY6_THREADS, GDN_PF_WY6_SMEM_BYTES as u32,
            )?;
            gdn_pf_kprof::end(gdn_pf_kprof::SCAN);
        } else if let Some(fns) = pf_scan_wy5 {
            gdn_pf_kprof::begin(gdn_pf_kprof::SCAN);
            gdn_pf_wy_launch(
                &ctx, fns, pqkv, pz, pb, pa, pst_conv, pst_ssm, ptrs[0], ptrs[1], ptrs[2],
                ptrs[3], py, ptrs[4], ptrs[5], nt, nk, nv, conv_dim, eps, q_scale,
                GDN_PF_WY4_BLOCKS, GDN_PF_WY4_THREADS, GDN_PF_WY5_SMEM_BYTES as u32,
            )?;
            gdn_pf_kprof::end(gdn_pf_kprof::SCAN);
        } else if let Some(fns) = pf_scan_wy4 {
            gdn_pf_kprof::begin(gdn_pf_kprof::SCAN);
            gdn_pf_wy_launch(
                &ctx, fns, pqkv, pz, pb, pa, pst_conv, pst_ssm, ptrs[0], ptrs[1], ptrs[2],
                ptrs[3], py, ptrs[4], ptrs[5], nt, nk, nv, conv_dim, eps, q_scale,
                GDN_PF_WY4_BLOCKS, GDN_PF_WY4_THREADS, GDN_PF_WY4_SMEM_BYTES as u32,
            )?;
            gdn_pf_kprof::end(gdn_pf_kprof::SCAN);
        } else if let Some(fns) = pf_scan_wy {
            gdn_pf_kprof::begin(gdn_pf_kprof::SCAN);
            gdn_pf_wy_launch(
                &ctx, fns, pqkv, pz, pb, pa, pst_conv, pst_ssm, ptrs[0], ptrs[1], ptrs[2],
                ptrs[3], py, ptrs[4], ptrs[5], nt, nk, nv, conv_dim, eps, q_scale,
                1, GDN_PF_WY_THREADS, GDN_PF_WY_SMEM_BYTES as u32,
            )?;
            gdn_pf_kprof::end(gdn_pf_kprof::SCAN);
        } else if let Some(fns) = pf_scan_fast3 {
            gdn_pf_kprof::begin(gdn_pf_kprof::SCAN);
            gdn_pf3_launch(
                &ctx, fns, pqkv, pz, pb, pa, pst_conv, pst_ssm, ptrs[0], ptrs[1], ptrs[2],
                ptrs[3], py, ptrs[4], ptrs[5], nt, nk, nv, conv_dim, eps, q_scale,
            )?;
            gdn_pf_kprof::end(gdn_pf_kprof::SCAN);
        } else if let Some(fns) = pf_scan_fast2 {
            gdn_pf_kprof::begin(gdn_pf_kprof::SCAN);
            gdn_pf2_launch(
                &ctx, fns, pqkv, pz, pb, pa, pst_conv, pst_ssm, ptrs[0], ptrs[1], ptrs[2],
                ptrs[3], py, ptrs[4], ptrs[5], nt, nk, nv, conv_dim, eps, q_scale,
            )?;
            gdn_pf_kprof::end(gdn_pf_kprof::SCAN);
        } else if let Some(fns) = pf_scan_fast {
            gdn_pf_kprof::begin(gdn_pf_kprof::SCAN);
            gdn_pf_scan128_launch(
                &ctx, fns, pqkv, pz, pb, pa, pst_conv, pst_ssm, ptrs[0], ptrs[1], ptrs[2],
                ptrs[3], py, ptrs[4], ptrs[5], nt, nk, nv, conv_dim, eps, q_scale,
            )?;
            gdn_pf_kprof::end(gdn_pf_kprof::SCAN);
        } else {
            let (mut pq, mut pzz, mut pbb, mut paa) = (pqkv, pz, pb, pa);
            let (mut pci, mut psi) = (pst_conv, pst_ssm);
            let (mut pwc, mut pwa, mut pwd, mut pwn) = (ptrs[0], ptrs[1], ptrs[2], ptrs[3]);
            let (mut pyy, mut pco, mut pso) = (py, ptrs[4], ptrs[5]);
            let (mut ni, mut nki, mut nvi, mut dki, mut dvi) = (
                nt as c_int,
                nk as c_int,
                nv as c_int,
                dk as c_int,
                dv as c_int,
            );
            let (mut cdi, mut dci, mut csi) = (conv_dim as c_int, d_conv as c_int, cs as c_int);
            let (mut epsi, mut qsi) = (eps, q_scale);
            let mut args = [
                &mut pq as *mut _ as *mut c_void,
                &mut pzz as *mut _ as *mut c_void,
                &mut pbb as *mut _ as *mut c_void,
                &mut paa as *mut _ as *mut c_void,
                &mut pci as *mut _ as *mut c_void,
                &mut psi as *mut _ as *mut c_void,
                &mut pwc as *mut _ as *mut c_void,
                &mut pwa as *mut _ as *mut c_void,
                &mut pwd as *mut _ as *mut c_void,
                &mut pwn as *mut _ as *mut c_void,
                &mut pyy as *mut _ as *mut c_void,
                &mut pco as *mut _ as *mut c_void,
                &mut pso as *mut _ as *mut c_void,
                &mut ni as *mut _ as *mut c_void,
                &mut nki as *mut _ as *mut c_void,
                &mut nvi as *mut _ as *mut c_void,
                &mut dki as *mut _ as *mut c_void,
                &mut dvi as *mut _ as *mut c_void,
                &mut cdi as *mut _ as *mut c_void,
                &mut dci as *mut _ as *mut c_void,
                &mut csi as *mut _ as *mut c_void,
                &mut epsi as *mut _ as *mut c_void,
                &mut qsi as *mut _ as *mut c_void,
            ];
            let shmem = ((3 * dk + dv + 5) * 4) as u32;
            gdn_pf_kprof::begin(gdn_pf_kprof::SCAN);
            unsafe {
                ctx.launch_async(
                    f_scan,
                    (nv as u32, 1, 1),
                    (dk as u32, 1, 1),
                    shmem,
                    &mut args,
                )?;
            }
            gdn_pf_kprof::end(gdn_pf_kprof::SCAN);
        }
        // task 334: `DENNO_PF_ATTN_NOSYNC` なら待たない (out_proj は同じストリーム)。
        pf_chain_sync(&ctx)?;
        phase_ns[1] = t_ph.elapsed().as_nanos() as u64;
    }

    // ---- out_proj (デバイス → デバイス) ------------------------------------
    let t_out = Instant::now();
    {
        let _s = crate::model::q4ledger::sub(crate::model::q4ledger::SUB_PF_OUT);
        let mut t0 = 0usize;
        while t0 < nt {
            let m = (nt - t0).min(gemm_tile);
            let yo = py + (t0 * vd * 4) as CUdeviceptr;
            let oo = po + (t0 * e * 4) as CUdeviceptr;
            gdn_pf_kprof::begin(gdn_pf_kprof::OUT_GEMM);
            let r = gguf_gemm_dev_launch(&ctx, wout.ty, wo.buf.ptr(), yo, oo, m, vd, e, gdn_pf_tc1_on());
            gdn_pf_kprof::end(gdn_pf_kprof::OUT_GEMM);
            match r {
                Ok(true) => {}
                Ok(false) => {
                    // スキャンは既に走っている → 状態が進んでいる。落とす。
                    GPU_BROKEN.store(true, std::sync::atomic::Ordering::Relaxed);
                    bail!("GDN prefill chain: out_proj の形がカーネルの前提外 (スキャン後)");
                }
                Err(err) => {
                    GPU_BROKEN.store(true, std::sync::atomic::Ordering::Relaxed);
                    return Err(err.context("GDN prefill chain: out_proj の起動に失敗"));
                }
            }
            t0 += m;
        }
        // out_proj の完了待ちもこの段に含める (台帳の行を「発行だけ」にしない)。
        // task 334: `DENNO_PF_ATTN_NOSYNC` なら待たない (ホストは同期 D2H で読む)。
        pf_chain_sync(&ctx)?;
    }
    phase_ns[2] = t_out.elapsed().as_nanos() as u64;

    // ---- 層の出力と状態をホストへ ------------------------------------------
    // task 200: `DENNO_PF_ATTN_DEVRES` のときは層出力をデバイスに残し、直後の
    // combine にそのまま読ませる (D2H + H2D の往復を消す)。数値は同じ。
    *kept_dev = pf_attn_dev_requested() && crate::model::qwen4exp::pf_attn_devres_on();
    if *kept_dev {
        pf_attn_dev_store(po, nt, e);
    } else {
        gdn_pf_kprof::begin(gdn_pf_kprof::OUT_D2H);
        let got: Vec<f32> = GDN_PF_CHAIN_BUF.with(|cell| -> Result<Vec<f32>> {
            let b = cell.borrow();
            b.o.as_ref().expect("連鎖の出力").to_vec::<f32>(nt * e)
        })?;
        gdn_pf_kprof::end(gdn_pf_kprof::OUT_D2H);
        out[..nt * e].copy_from_slice(&got);
    }
    gdn_state_commit(li, ptrs[4], ptrs[5], conv_dim * cs, nv, dk * dv)?;
    // prefill のあとに decode (別ストア) や CPU 経路がホスト state を seed に
    // するので、状態は毎回ホストへも戻す (従来の sig 経路と同じ)。
    // task 379: `DENNO_PF_GDN_WB_LAST` では層の最終チャンクだけ戻す (途中チャンクの
    // ホスト控えは次チャンクが読まない。値は同じ)。飛ばした回数を数える。
    if pf_gdn_last_chunk_skippable(li) {
        crate::model::exp_pf::note_gdn_wb_skip();
    } else {
        gdn_pf_kprof::begin(gdn_pf_kprof::ST_D2H);
        gdn_host_writeback(conv_st, ssm_st)?;
        gdn_pf_kprof::end(gdn_pf_kprof::ST_D2H);
    }
    // task 173: 段ごとの GPU 時間を回収する (この時点で全イベントが完了している)。
    gdn_pf_kprof::collect();
    Ok(true)
}

// ---------------------------------------------------------------------------
// A1-r2: GDN chunked scan (長 prefill 用・3-pass 構成)
// ---------------------------------------------------------------------------

/// chunked ルーティングの閾値 (n がこれ以上で 3-pass chunked カーネルを使用)。
/// 実際の chunk 分割は [`crate::gdn::scan_schedule::plan`] (CPU 参照と共有する
/// 唯一の定義) が返す。
pub(crate) const GDN_CHUNK_MIN_TOKENS: usize = crate::gdn::scan_schedule::CHUNK_MIN_TOKENS;

/// s72: GDN スキャンの y をデバイス上に残したまま out_proj までチェーンで実行し、
/// 結果だけを host へ落とす。従来は y (n×vd) を D2H し、次の out_proj で再び H2D
/// していた (1 層あたり 2×47MB)。
///
/// 演算は従来と同一 (同じ `f_quant` + `f_gemm`・同一 int8 累積) なので出力は
/// ビット一致する。conv/ssm 状態の更新はスキャンカーネルが行うため、スキャン開始後に
/// 失敗するとフォールバックでは状態を巻き戻せない。よって前提条件 (重みのアップロード・
/// バッファ確保・ctx) はすべてスキャン前に確認し、以降の失敗は GPU 障害として扱う。
#[allow(clippy::too_many_arguments)]
pub fn gdn_scan_batch_oproj(
    qkv: &[f32],
    z: &[f32],
    beta: &[f32],
    alpha: &[f32],
    conv_st: &mut [f32],
    ssm_st: &mut [f32],
    wconv: &[f32],
    wa: &[f32],
    wdt: &[f32],
    wnorm: &[f32],
    n: usize,
    nk: usize,
    nv: usize,
    dk: usize,
    dv: usize,
    d_conv: usize,
    eps: f32,
    q_scale: f32,
    o: &crate::quant::Quant8Linear,
    out: &mut [f32],
    li: usize,
    kv: u64,
) -> Option<()> {
    if !cuda_enabled() || n < GDN_CHUNK_MIN_TOKENS || dk != dv || d_conv != 4 {
        return None;
    }
    let vd = nv.checked_mul(dv)?;
    if o.k != vd || out.len() != n.checked_mul(o.n)? {
        return None;
    }
    let ctx = chain_ctx()?;
    if ctx.make_current().is_err() {
        return None;
    }
    ok(chain_ensure_buf(CH_PFH, n.checked_mul(vd)?.checked_mul(4)?))?;
    ok(chain_ensure_buf(CH_O, n.checked_mul(o.n)?.checked_mul(4)?))?;
    ok(weights_for_group(&[o.uid], &[o], o.k, o.n))?;
    let yptr = CHAIN.with(|cell| cell.borrow().bufs[CH_PFH].as_ref().map(|b| b.ptr()))?;

    if let Err(e) = gdn_scan_chunked_impl(
        ctx,
        GdnScanSrc::Host { qkv, z, beta, alpha },
        conv_st,
        ssm_st,
        wconv,
        wa,
        wdt,
        wnorm,
        n,
        nk,
        nv,
        dk,
        dv,
        d_conv,
        eps,
        q_scale,
        Some(yptr),
        li,
        kv,
    ) {
        tracing::error!("GDN scan (device y) failed: {e:#}");
        GPU_BROKEN.store(true, std::sync::atomic::Ordering::Relaxed);
        return None;
    }
    if chain_gemm_grouped_pf(&[o], CH_PFH, CH_O, n).is_none() {
        tracing::error!("GDN out_proj (chain) failed");
        GPU_BROKEN.store(true, std::sync::atomic::Ordering::Relaxed);
        return None;
    }
    let bytes = out.len().checked_mul(4)?;
    let optr = CHAIN.with(|cell| cell.borrow().bufs[CH_O].as_ref().map(|b| b.ptr()))?;
    let lib = lib().ok()?;
    unsafe {
        ok(check(
            (lib.memcpy_dtoh_async)(
                out.as_mut_ptr() as *mut c_void,
                optr,
                bytes,
                std::ptr::null_mut(),
            ),
            "cuMemcpyDtoHAsync (gdn oproj)",
        ))?;
    }
    crate::prof::mark_d2h_src(crate::prof::D2H_SRC_LINEAR);
    ctx.sync().ok()?;
    Some(())
}

/// per-op 経路の行タイル (この単位で H2D + GEMM を回す)。
///
/// s168 (P7): 実際の dispatch は `DENNO_Q4_M_TILE` の実効値 ([`q4_m_tile`]) を使う。
/// この定数は**入口ゲート** ([`gdn_prefill_q4_geom`] / [`pf_res_gate`]) が前提にする
/// 歴史的なタイル幅 (1024) で、ゲートは端数タイルの帯域だけを見る保守的な判定
/// なので、実効タイルがこれと違っても「受けない」側にしか倒れない
/// (受けた場合は [`q4_group_rows`] が端数を直前のタイルへ併合する)。
const GDN_PREFILL_TILE: usize = 1024;

/// `chain_gdn_prefill_q4` が使う寸法 (入口条件を通ったときだけ作られる)。
struct GdnPrefillQ4Geom<'a> {
    qw: &'a crate::quant::Q4Linear,
    zw: &'a crate::quant::Q4Linear,
    ow: &'a crate::quant::Q4Linear,
    e: usize,
    conv_dim: usize,
    vd: usize,
    cs: usize,
}

/// `chain_gdn_prefill_q4` の入口条件 (重み種別・形・寸法・端数タイル) を判定し、
/// 以降で使う寸法を返す。**純粋関数** — CUDA もグローバル状態も触らないので、
/// フォールバック契約 (None になる条件) を GPU 無しのホストでテストできる。
/// 本番経路はこの戻り値だけを見て判断する (条件の写しを持たない)。
#[allow(clippy::too_many_arguments)]
fn gdn_prefill_q4_geom<'a>(
    qkv_w: &'a crate::quant::Linear,
    z_w: &'a crate::quant::Linear,
    o_w: &'a crate::quant::Linear,
    n: usize,
    nk: usize,
    nv: usize,
    dk: usize,
    dv: usize,
    d_conv: usize,
) -> Option<GdnPrefillQ4Geom<'a>> {
    use crate::quant::Linear;
    let (qw, zw, ow) = match (qkv_w, z_w, o_w) {
        (Linear::Q4(a), Linear::Q4(b), Linear::Q4(c)) => (a, b, c),
        _ => return None,
    };
    // チャンク経路の前提 (gdn_scan_batch と同じ) + 形状。
    if n < GDN_CHUNK_MIN_TOKENS || nk == 0 || nv == 0 || dk == 0 || dv == 0 {
        return None;
    }
    if dk != dv || d_conv != 4 {
        return None;
    }
    let cs = d_conv - 1;
    let e = qw.k;
    let conv_dim = nk.checked_mul(dk)?.checked_mul(2)?.checked_add(nv.checked_mul(dv)?)?;
    let vd = nv.checked_mul(dv)?;
    // Q4 GEMM の入口条件 (maybe_gpu_linear_q4_into と同じ k%32==0) と重み形状。
    if e == 0 || e % 32 != 0 || vd % 32 != 0 {
        return None;
    }
    if qw.n != conv_dim || zw.k != e || zw.n != vd || ow.k != vd || ow.n != e {
        return None;
    }
    // per-op 経路は 1024 行タイルで、端数タイルが m <= max_m() だと GEMV になる。
    // そこだけ演算列が変わるので、その形では発動しない (従来経路へ落とす)。
    let rem = n % GDN_PREFILL_TILE;
    if rem != 0 && rem <= max_m() {
        return None;
    }
    Some(GdnPrefillQ4Geom { qw, zw, ow, e, conv_dim, vd, cs })
}

/// s164 (P1): GDN 層の prefill を **q4 重みで** デバイス常駐に通す。
///
/// 旧経路 (q4・`forward_prefill` の GDN 分岐) は 1 層あたり
///   qkv: D2H n*conv_dim*4 → H2D 同量 / z: D2H n*vd*4 → H2D 同量 /
///   y: D2H n*vd*4 → H2D 同量 / o_proj: D2H n*e*4
/// を往復していた (27B・n=13000 で 1 層 約 2.0 GB)。新経路は
///   H2D x (n*e*4) + H2D beta/alpha (n*nv*4 x2) + D2H o (n*e*4)
/// だけで、qkv / z / y はデバイス上に留まる。
///
/// ビット一致の根拠:
/// - qkv / z / o の投影は per-op 経路 (`q4_dispatch_tile`) と同一カーネル
///   (`dno_gemm_q4_0`)・同一引数。行ブロック (64 行) は互いに独立で、1 要素の
///   i32 累積順は k 昇順のまま変わらないため、grid の行ブロック数が増えても
///   出力は 1 要素ずつ同一。x のアップロードを 1024 行タイルに割るのも同じ理由で
///   数値を変えない。
///   (per-op 経路は m <= max_m() のタイルを GEMV で回すため、その帯域に
///   入る端数行がある n では発動しない → None)
/// - GDN スキャンは **n を分割しない**。chunk 分割 `plan(n)`・grid・引数・
///   カーネルとも従来の `gdn_scan_batch` と同一で、変わるのは入力 4 本の
///   出所 (`GdnScanSrc::Dev`) だけ。chunk 境界は状態の持ち越しで決まるので
///   行タイルに割ると plan が変わり数値が変わる — ここは触らない。
/// - beta / alpha は従来どおり呼び出し側がホストで計算した値をそのまま使う
///   (値も契約も不変)。
///
/// 状態 (conv/ssm) の契約は従来と同じ: `gdn_scan_chunked_impl` が
/// `gdn_state_begin` / `gdn_state_commit` / (devstate 無効時のみ)
/// `gdn_host_writeback` を通す。スキャン開始後に失敗すると状態を巻き戻せない
/// ため、前提条件はすべてスキャン前に確認する (失敗は GPU 障害として扱う)。
#[allow(clippy::too_many_arguments)]
pub fn chain_gdn_prefill_q4(
    qkv_w: &crate::quant::Linear,
    z_w: &crate::quant::Linear,
    o_w: &crate::quant::Linear,
    beta: &[f32],
    alpha: &[f32],
    wconv: &[f32],
    wa: &[f32],
    wdt: &[f32],
    wnorm: &[f32],
    x: &[f32],
    n: usize,
    nk: usize,
    nv: usize,
    dk: usize,
    dv: usize,
    d_conv: usize,
    eps: f32,
    q_scale: f32,
    conv_st: &mut [f32],
    ssm_st: &mut [f32],
    out: &mut [f32],
    li: usize,
    kv: u64,
) -> Option<()> {
    let e = gate_dims_in(qkv_w)?;
    if x.len() < n.checked_mul(e)? || out.len() < n.checked_mul(e)? {
        return None;
    }
    chain_gdn_prefill_q4_impl(
        qkv_w,
        z_w,
        o_w,
        beta,
        alpha,
        wconv,
        wa,
        wdt,
        wnorm,
        PfSrc::Host(x),
        PfSink::Host(out),
        n,
        nk,
        nv,
        dk,
        dv,
        d_conv,
        eps,
        q_scale,
        conv_st,
        ssm_st,
        li,
        kv,
        PfGdnPhase::All,
    )
}

/// s167 (P6): [`chain_gdn_prefill_q4_impl`] の実行位相。
///
/// GDN 層の prefill は「qkv/z GEMM (h2 だけに依存)」→「beta/alpha H2D → chunk
/// scan → o_proj (beta/alpha にも依存)」の 2 段に分かれており、beta/alpha は
/// ホストが h2 から計算する。h2 の D2H を専用コピーストリームに載せるとき、
/// 前段 (Gemm) だけを先に流してその間にコピーを進め、join 後に後段 (Rest) を
/// 流す。`All` は従来どおり 1 回で通す (フラグ OFF の経路はこれ)。
#[derive(Clone, Copy, PartialEq, Eq)]
enum PfGdnPhase {
    /// 従来どおり全段 (qkv/z GEMM → beta/alpha H2D → scan → o_proj → D2H)
    All,
    /// qkv/z GEMM だけ (beta/alpha を待たない)
    Gemm,
    /// beta/alpha H2D → scan → o_proj (と Host 出力の D2H)
    Rest,
}

/// [`chain_gdn_prefill_q4`] の本体 (入出力の出所だけを差し替える)。
#[allow(clippy::too_many_arguments)]
fn chain_gdn_prefill_q4_impl(
    qkv_w: &crate::quant::Linear,
    z_w: &crate::quant::Linear,
    o_w: &crate::quant::Linear,
    beta: &[f32],
    alpha: &[f32],
    wconv: &[f32],
    wa: &[f32],
    wdt: &[f32],
    wnorm: &[f32],
    src: PfSrc<'_>,
    mut sink: PfSink<'_>,
    n: usize,
    nk: usize,
    nv: usize,
    dk: usize,
    dv: usize,
    d_conv: usize,
    eps: f32,
    q_scale: f32,
    conv_st: &mut [f32],
    ssm_st: &mut [f32],
    li: usize,
    kv: u64,
    phase: PfGdnPhase,
) -> Option<()> {
    // 形・重み種別の検査は gdn_prefill_q4_geom (純粋・GPU 不要) に集約してある。
    // フォールバック契約は tests::b20_stage1_tests::gdn_prefill_q4_geom_contract で固定する。
    // デバイスの準備 (cuda_enabled 等) は形が合ってから。
    let g = gdn_prefill_q4_geom(qkv_w, z_w, o_w, n, nk, nv, dk, dv, d_conv)?;
    let (qw, zw, ow) = (g.qw, g.zw, g.ow);
    let (e, conv_dim, vd, cs) = (g.e, g.conv_dim, g.vd, g.cs);
    // s168 (P7): 行タイルは `DENNO_Q4_M_TILE` の実効値。端数は直前のタイルへ併合
    // するので、CH_PFH (入力のステージ) は 1 タイルの最大行数で確保する。
    let tile = q4_m_tile();
    let cap = q4_tile_max_rows(tile).min(n);
    let nv_tot = n.checked_mul(nv)?;
    if beta.len() < nv_tot || alpha.len() < nv_tot {
        return None;
    }
    if wconv.len() != conv_dim.checked_mul(d_conv)? || wa.len() != nv || wdt.len() != nv {
        return None;
    }
    if wnorm.len() != dv {
        return None;
    }
    if let PfSrc::Host(x) = src {
        if x.len() < n.checked_mul(e)? {
            return None;
        }
    }
    if let PfSink::Host(out) = &sink {
        if out.len() < n.checked_mul(e)? {
            return None;
        }
    }
    if conv_st.len() != conv_dim.checked_mul(cs)? || ssm_st.len() != nv.checked_mul(dk)?.checked_mul(dv)? {
        return None;
    }
    // Slot 入力は CH_PFH の先頭 n 行をそのまま読むので、行数ぶんの領域を要求する
    // (rmsnorm が ensure 済みなら no-op。足りなければ None → 呼び出し側がフォールバック)。
    if matches!(src, PfSrc::Slot) {
        ok(chain_ensure_buf(CH_PFH, n.checked_mul(e)?.checked_mul(4)?))?;
    }
    // ここまでで「形が合っている」ことが確定した → デバイスの準備に入る。
    if !cuda_enabled()
        || !gemm_enabled()
        || GPU_BROKEN.load(std::sync::atomic::Ordering::Relaxed)
    {
        return None;
    }
    let ctx = chain_ctx()?;
    let gw_qkv = weights_for_q4(qw.uid, &qw.blocks, qw.k, qw.n).ok()?;
    let gw_z = weights_for_q4(zw.uid, &zw.blocks, zw.k, zw.n).ok()?;
    let gw_o = weights_for_q4(ow.uid, &ow.blocks, ow.k, ow.n).ok()?;
    let (n_chunks, _) = crate::gdn::scan_schedule::plan(n);
    // GDN スクラッチを先に確保し、qkv / z の GEMM 出力を**そのまま**スキャンの
    // 入力にする (中間バッファを増やさない)。impl 側の ensure は同形なので no-op。
    ok(GDN_SCRATCH.with(|cell| {
        cell.borrow_mut().ensure(n, conv_dim, vd, nv, dk, dv, cs, n_chunks)
    }))?;
    let (pq, pz, py, pb, pa) =
        GDN_SCRATCH.with(|cell| -> Option<(CUdeviceptr, CUdeviceptr, CUdeviceptr, CUdeviceptr, CUdeviceptr)> {
            let s = cell.borrow();
            Some((
                s.q.as_ref()?.ptr(),
                s.z.as_ref()?.ptr(),
                s.y.as_ref()?.ptr(),
                s.beta.as_ref()?.ptr(),
                s.alpha.as_ref()?.ptr(),
            ))
        })?;
    ok(chain_ensure_buf(CH_PFH, cap.checked_mul(e)?.checked_mul(4)?))?;
    ok(chain_ensure_buf(CH_O, n.checked_mul(e)?.checked_mul(4)?))?;

    // 1) qkv / z 投影: 入力を 1 タイル (`DENNO_Q4_M_TILE`・端数は直前へ併合) ずつ
    //    用意し、GEMM は出力の行オフセットへ書く
    //    (per-op 経路の 1024 行タイルと同じ形。H2D と GEMM は同一ストリームで
    //    順序が保たれるので、タイル間の sync は要らない)。Host はタイルごとに
    //    H2D、Slot (残差常駐経路) は CH_PFH の該当行をそのまま読む — 転送だけが
    //    消え、カーネル・引数は同一。
    //    s167 (P6): 位相 Rest では再実行しない (位相 Gemm の呼び出しが済ませている。
    //    q/z は GDN_SCRATCH に残っており、間に GDN_SCRATCH を触る処理は無い)。
    if phase != PfGdnPhase::Rest {
        let mut r0 = 0usize;
        while r0 < n {
            let mr = q4_group_rows(r0, n, tile);
            debug_assert!(mr <= cap, "tile group {mr} > cap {cap}");
            CHAIN.with(|cell| -> Option<()> {
                let s = cell.borrow();
                let pbuf = s.bufs[CH_PFH].as_ref()?.ptr();
                let pin = match &src {
                    PfSrc::Host(x) => {
                        let lib = lib().ok()?;
                        // H2D x タイル → 同一ストリームの GEMM (順序はストリームが保証する)
                        unsafe {
                            ok(check(
                                (lib.memcpy_htod_async)(
                                    pbuf,
                                    x[r0 * e..].as_ptr() as *const c_void,
                                    mr * e * 4,
                                    std::ptr::null_mut(),
                                ),
                                "cuMemcpyHtoDAsync (gdn prefill q4 x)",
                            ))?;
                        }
                        pbuf
                    }
                    PfSrc::Slot => pbuf + (r0 * e * 4) as u64,
                };
                crate::prof::time_layer(crate::prof::QKV, li, || -> Option<()> {
                    chain_gemm_q4_pf(gw_qkv, pin, pq + (r0 * conv_dim * 4) as u64, mr, e, conv_dim)?;
                    chain_gemm_q4_pf(gw_z, pin, pz + (r0 * vd * 4) as u64, mr, e, vd)
                })
            })?;
            r0 += mr;
        }
    }
    // s167 (P6): 位相 Gemm はここで終わる (呼び出し側が h2 のコピーを join してから
    // 位相 Rest を呼ぶ)。beta/alpha の H2D もスキャンも o_proj も走らせない。
    if phase == PfGdnPhase::Gemm {
        return Some(());
    }

    // 2) beta / alpha (ホストで計算済み・従来と同じ値) をデバイスへ。
    //    2*n*nv*4 は 27B/13k でも 5 MB なので、ここは往復を消さない。
    GDN_SCRATCH.with(|cell| -> Option<()> {
        let s = cell.borrow();
        ok(s.beta.as_ref()?.copy_from(&beta[..nv_tot]))?;
        ok(s.alpha.as_ref()?.copy_from(&alpha[..nv_tot]))?;
        Some(())
    })?;

    // 3) GDN chunk scan (3 launch・入力はすべてデバイス、y もデバイスに残す)。
    //    s173 (P15): pass 間のホスト待ちは無い (同期は最後の 1 回だけ)。
    pf_phase(PF_PH_GDN_SCAN);
    crate::prof::time_layer(crate::prof::ATT_GDN_SCAN, li, || -> Option<()> {
        ok(gdn_scan_chunked_impl(
            ctx,
            GdnScanSrc::Dev { qkv: pq, z: pz, beta: pb, alpha: pa },
            conv_st,
            ssm_st,
            wconv,
            wa,
            wdt,
            wnorm,
            n,
            nk,
            nv,
            dk,
            dv,
            d_conv,
            eps,
            q_scale,
            Some(py),
            li,
            kv,
        )
        .map(|_| ()))
    })?;

    // 4) o_proj (y はデバイス上) → 5) D2H は Host 出力のときだけ最後の 1 回。
    pf_phase(PF_PH_GDN_OPROJ);
    let po = CHAIN.with(|cell| cell.borrow().bufs[CH_O].as_ref().map(|b| b.ptr()))?;
    crate::prof::time_layer(crate::prof::OPROJ, li, || -> Option<()> {
        chain_gemm_q4_pf(gw_o, py, po, n, vd, e)
    })?;
    // Slot 出力 (残差常駐経路) は CH_O に残したまま、次の rmsnorm の proj 引数として
    // 読ませる — D2H も sync もしない (同じストリームなので順序は保たれる)。
    if let PfSink::Host(out) = &mut sink {
        CHAIN.with(|cell| -> Option<()> {
            let buf = cell.borrow().bufs[CH_O].as_ref()?.ptr();
            let lib = lib().ok()?;
            unsafe {
                ok(check(
                    (lib.memcpy_dtoh_async)(
                        out.as_mut_ptr() as *mut c_void,
                        buf,
                        n * e * 4,
                        std::ptr::null_mut(),
                    ),
                    "cuMemcpyDtoHAsync (gdn prefill q4 o)",
                ))
            }
        })?;
        crate::prof::mark_d2h_src(crate::prof::D2H_SRC_LINEAR);
        ok(ctx.sync())?;
    }
    Some(())
}

// ---------------------------------------------------------------------------
// s167 (P6): GDN prefill の h2 D2H を専用コピーストリームで qkv/z GEMM と重ねる。
//
// GDN 層は 1 層あたり h2 (n*e*4 = 13k token で約 210MB) をホストへ戻し、beta/alpha
// をホストで計算する。従来はこれを既定 (legacy) ストリームで**同期** D2H して
// いたので、コピー時間がまるごと直列に乗っていた。beta/alpha が要るのは chunk
// scan からで、その手前の qkv/z GEMM は h2 (デバイス) だけに依存する — したがって
//   rmsnorm → { D2H h2 (コピーストリーム) || qkv/z GEMM (既定ストリーム) }
// の形にできる。同期点は「ホストが h2 を読む直前の join」1 つだけで、
//   - 同じバイト列を同じバッファから戻す (pinned 宛先が違うだけ)
//   - ホスト計算 (beta/alpha) の関数・引数・順序は不変
//   - カーネル・grid・引数・chunk 分割・状態契約は不変
// なので数値は 1 つも変わらない。コピーと GEMM は互いに独立 (どちらも CH_PFH を
// 読むだけ) で、書き込み先も別。
//
// 発動条件は `DENNO_PF_OVERLAP` (s172/P13 で**既定 ON**。`=0` で従来の直列経路)。
// 明示 OFF・driver に必要な API が無い・stream/event/pinned の作成に失敗、
// のいずれでも従来と同一の同期経路を通る。
// ---------------------------------------------------------------------------

/// s167 (P6): `DENNO_PF_OVERLAP` の解釈 (純粋関数)。
///
/// s172 (P13): **既定を ON にした** (OFF に戻すのは `DENNO_PF_OVERLAP=0` の
/// 明示指定だけ)。根拠は gdn_proj の実測内訳 (12,850 で 18.0 s) —
/// 「h2 の D2H ≈0.7 s + ホスト beta/alpha 8.1 s + qkv/z GEMM ≈9.2 s」で、
/// ホスト仕事は GEMM の裏に隠れる (隠せるのは min(コピー+ホスト, GEMM))。
/// 数値は経路によらず同一: 同じバイト列を同じバッファから戻すだけで、
/// ホスト計算・カーネル・引数・順序は変わらない。
pub fn parse_pf_overlap(raw: Option<&str>) -> bool {
    !matches!(raw, Some("0") | Some("false") | Some("off"))
}

/// 実行時の env 実効値 (初回だけ読む)。
fn pf_overlap_flag() -> bool {
    static ON: OnceLock<bool> = OnceLock::new();
    *ON.get_or_init(|| parse_pf_overlap(std::env::var("DENNO_PF_OVERLAP").ok().as_deref()))
}

/// s167 (P6): h2 の D2H をどの経路で発行するか。
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum PfH2Path {
    /// 専用 (非ブロッキング) コピーストリームで発行し、qkv/z GEMM と重ねる
    CopyStream,
    /// 従来の同期 D2H (フラグ OFF・デバイス準備失敗・形の不整合)
    SyncD2h,
}

/// s167 (P6): 経路決定 (純粋関数・GPU 非依存)。
/// `dev_ready` は「コピーストリーム・イベント・pinned 宛先が揃った」ことを表す
/// (呼び出し側が実際に作って渡す)。ここが false なら**必ず**従来経路に落ちる。
/// 桁あふれ・0 バイトも従来経路 (コピーする意味が無い)。
pub fn pf_h2_path(flag_on: bool, n: usize, e: usize, dev_ready: bool) -> PfH2Path {
    if !flag_on || !dev_ready {
        return PfH2Path::SyncD2h;
    }
    match n.checked_mul(e).and_then(|v| v.checked_mul(4)) {
        Some(bytes) if bytes > 0 => PfH2Path::CopyStream,
        _ => PfH2Path::SyncD2h,
    }
}

/// s167 (P6): h2 の D2H を専用コピーストリームへ**発行するだけ** (同期しない)。
/// `CH_PFH` の `elem_off` 要素目から `len` 個を pinned の `pin_h2` へ落とす。
/// 呼び出し時点で `CH_PFH` の当該範囲が既定ストリーム上で確定している前提
/// (rmsnorm の直後に呼ぶ) で、イベントで既定ストリーム → コピーストリームの
/// 順序を作る。完了は [`chain_pf_h2_join`] で待つ。
///
/// 失敗はすべて `None` で、**GPU_BROKEN は立てない**: フラグ OFF・driver API
/// 欠落・stream/event/pinned の作成失敗は「従来の同期 D2H でよい」種類の失敗
/// なので、呼び出し側は静かに従来経路へ落ちる。
fn chain_pf_h2_begin(slot: usize, elem_off: usize, len: usize) -> Option<()> {
    let _ctx = chain_ctx()?;
    let bytes = len.checked_mul(4)?;
    if bytes == 0 {
        return None;
    }
    let need = elem_off.checked_mul(4)?.checked_add(bytes)?;
    let lib = lib().ok()?;
    let (stream_create, event_create, event_record, stream_wait_event) = (
        lib.stream_create?,
        lib.event_create?,
        lib.event_record?,
        lib.stream_wait_event?,
    );
    CHAIN.with(|cell| -> Option<()> {
        let mut s = cell.borrow_mut();
        // 未 join のコピーが残っている状態で発行し直すと宛先 (pin_h2) を取り合う。
        // 呼び出し規約違反なので受けない (join が必ず h2_pending を落とす)。
        if s.h2_pending {
            return None;
        }
        // 1) コピーストリーム一式を初回だけ作る。
        if s.h2_stream.is_none() {
            // 非ブロッキング必須: legacy (既定) ストリームは blocking ストリームと
            // 暗黙に同期するため、blocking で作ると GEMM がコピー完了を待ってしまい
            // 1 バイトも重ならない。
            const CU_STREAM_NON_BLOCKING: u32 = 0x01;
            const CU_EVENT_DISABLE_TIMING: u32 = 0x02;
            let mut st: CUstream = std::ptr::null_mut();
            if unsafe { stream_create(&mut st, CU_STREAM_NON_BLOCKING) } != CUDA_SUCCESS {
                return None;
            }
            let st = CopyStream(st);
            let mut ev_ready: CUevent = std::ptr::null_mut();
            if unsafe { event_create(&mut ev_ready, CU_EVENT_DISABLE_TIMING) } != CUDA_SUCCESS {
                return None;
            }
            let ev_ready = CopyEvent(ev_ready);
            let mut ev_done: CUevent = std::ptr::null_mut();
            if unsafe { event_create(&mut ev_done, CU_EVENT_DISABLE_TIMING) } != CUDA_SUCCESS {
                return None;
            }
            let ev_done = CopyEvent(ev_done);
            s.h2_stream = Some(st);
            s.h2_ev_ready = Some(ev_ready);
            s.h2_ev_done = Some(ev_done);
        }
        // 2) 宛先 (pinned) と転送元を用意する。pinned の確保失敗も従来経路へ
        //    (ページロック上限などは致命的でないので GPU_BROKEN は立てない)。
        if Scratch::ensure_pin(&mut s.pin_h2, bytes).is_err() {
            return None;
        }
        let dst = match s.pin_h2.as_ref() {
            Some(p) if p.bytes >= bytes => p.ptr,
            _ => return None,
        };
        let src = match s.bufs.get(slot).and_then(|b| b.as_ref()) {
            Some(b) if b.bytes() >= need => b.ptr(),
            _ => return None,
        };
        let (st, ev_ready, ev_done) = (
            s.h2_stream.as_ref()?.0,
            s.h2_ev_ready.as_ref()?.0,
            s.h2_ev_done.as_ref()?.0,
        );
        // 3) 既定ストリーム (null) の rmsnorm 完了をイベントで受けてから発行する。
        if unsafe { event_record(ev_ready, std::ptr::null_mut()) } != CUDA_SUCCESS {
            return None;
        }
        if unsafe { stream_wait_event(st, ev_ready, 0) } != CUDA_SUCCESS {
            return None;
        }
        if unsafe { (lib.memcpy_dtoh_async)(dst, src + (elem_off * 4) as CUdeviceptr, bytes, st) }
            != CUDA_SUCCESS
        {
            return None;
        }
        // 4) 完了イベントをコピーストリームに打つ (join はこれだけを待つ)。
        if unsafe { event_record(ev_done, st) } != CUDA_SUCCESS {
            return None;
        }
        s.h2_pending = true;
        Some(())
    })
}

/// s167 (P6): 発行済みの h2 D2H を join する (完了イベントを待つ)。ここから先で
/// ホストが `pin_h2` を読める。`h2_pending` が無い (発行していない) なら None。
///
/// 待ちに失敗しても `h2_pending` は落とす — 以後の層は従来の同期 D2H に戻る
/// (同じストリームに残った古いコピーは、次のコピーの完了イベントより前に
/// 必ず終わるので、宛先の取り合いにはならない)。
fn chain_pf_h2_join() -> Option<()> {
    let _ctx = chain_ctx()?;
    let event_sync = lib().ok()?.event_sync?;
    CHAIN.with(|cell| -> Option<()> {
        let mut s = cell.borrow_mut();
        if !s.h2_pending {
            return None;
        }
        let ev = s.h2_ev_done.as_ref()?.0;
        s.h2_pending = false;
        if unsafe { event_sync(ev) } != CUDA_SUCCESS {
            return None;
        }
        Some(())
    })
}

// ---------------------------------------------------------------------------
// s169 (P8): prefill 残差常駐経路の**位相計測** (表 C の `sl_lay_*` / DENNO_PF_DBG)
//
// なぜホスト span では駄目か: 残差常駐チェーンは層の中のカーネルを**発行する
// だけ**で待たない。`Instant` で区間を挟んでも写るのは発行の往復 (数十 ns) だけで、
// 実際 decode chain の `sl_lay_*` は 0.0 ms と出ていた。ここでは既定ストリームに
// **イベントを打つだけ**で位相を区切り、prefill 末尾に既にある同期 D2H が済んだ
// 後に `cuEventElapsedTime` で区間を読む:
//
//   - イベントは発行順にストリーム上で実行されるので、区間の経過 = 「その区間で
//     発行したカーネルの実行 + ホストが詰まっていた遊び」。待ちを足さない。
//   - **同期は 1 回も足さない** (層ループの中も外も)。読むのは prefill 最後の
//     既存の同期 D2H の後だけ。発行順・引数・カーネルは 1 つも変えない。
//   - `DENNO_PROFILE` も `DENNO_PF_DBG` も未設定なら、各サイトは分岐 1 回で戻る
//     (クロックも読まない・イベントも作らない)。プロファイラ build は要らない
//     (`DENNO_PF_DBG=1` だけで動く)。
//
// 位相の区切りは**発行グループの先頭**に置く (`pf_phase(PF_PH_*)`)。区間
// [イベント k, イベント k+1) はイベント k の時点で指定された位相に積まれる。
// 残差加算は `dno_add_rmsnorm` の `proj` 引数に融合しているので、ホスト経路の
// `sl_lay_residual` に相当する独立区間は**構造的に存在しない** (加算は
// norm_in / norm_post の区間に含まれる)。
// ---------------------------------------------------------------------------

/// 位相 id (表示順)。`PF_PH_NONE` は「位相の外」(prefill 入口 → 最初の位相 /
/// 層ループ末尾 → 最終 norm)。
pub const PF_PH_NONE: u8 = 0xFF;
pub const PF_PH_NORM_IN: usize = 0;
pub const PF_PH_GDN_PROJ: usize = 1;
pub const PF_PH_GDN_SCAN: usize = 2;
pub const PF_PH_GDN_OPROJ: usize = 3;
pub const PF_PH_FULL_QK: usize = 4;
pub const PF_PH_FULL_CORE: usize = 5;
pub const PF_PH_FULL_OPROJ: usize = 6;
pub const PF_PH_NORM_POST: usize = 7;
pub const PF_PH_FFN_GATE: usize = 8;
pub const PF_PH_SWIGLU: usize = 9;
pub const PF_PH_FFN_DOWN: usize = 10;
pub const PF_PH_N: usize = 11;

/// 表示名。`sl_lay_*` は表 C の行名と揃え、GDN の o_proj だけは表 C に行が無い
/// (decode chain と同じ扱い = 名前付きバケットを持たない) ので DBG 専用の名前。
pub const PF_PH_NAMES: [&str; PF_PH_N] = [
    "sl_lay_norm_in",
    "sl_lay_gdn_proj",
    "sl_lay_gdn_scan",
    "sl_lay_gdn_oproj",
    "sl_lay_full_qk",
    "sl_lay_full_core",
    "sl_lay_full_oproj",
    "sl_lay_norm_post",
    "sl_lay_ffn_gate",
    "sl_lay_swiglu",
    "sl_lay_ffn_down",
];

/// 位相 → 表 C の行 (None = 表 C に行を持たない = DBG 表示のみ)。
const PF_PH_BUCKETS: [Option<usize>; PF_PH_N] = [
    Some(crate::prof::SL_LAY_NORM_IN),
    Some(crate::prof::SL_LAY_GDN_PROJ),
    Some(crate::prof::SL_LAY_GDN_SCAN),
    None, // GDN o_proj (decode chain も名前付きバケットを持たない)
    Some(crate::prof::SL_LAY_FULL_QK),
    Some(crate::prof::SL_LAY_FULL_CORE),
    Some(crate::prof::SL_LAY_FULL_OPROJ),
    Some(crate::prof::SL_LAY_NORM_POST),
    Some(crate::prof::SL_LAY_FFN_GATE),
    Some(crate::prof::SL_LAY_SWIGLU),
    Some(crate::prof::SL_LAY_FFN_DOWN),
];

/// `DENNO_PF_DBG=1`: prefill 1 回ごとに位相の内訳を stderr へ 1 回出す
/// (プロファイラ build 不要・既定 OFF)。
fn pf_dbg_on() -> bool {
    static ON: OnceLock<bool> = OnceLock::new();
    *ON.get_or_init(|| std::env::var("DENNO_PF_DBG").ok().as_deref() == Some("1"))
}

/// 位相計測を回すか (`DENNO_PROFILE` か `DENNO_PF_DBG`)。未設定は分岐 1 回。
#[inline]
fn pf_timing_on() -> bool {
    crate::prof::enabled() || pf_dbg_on()
}

/// 1 prefill 分の位相計測の状態 (スレッドローカル・リクエストごとに使い回す)。
struct PfTiming {
    /// 計測中 (begin 済みで read/abort 前)。
    active: bool,
    /// 層ループ末尾の境界を打った = 次の `pf_timing_read` で読む。
    pending: bool,
    /// イベントのプール (grow-only。初回の prefill で層数ぶん作る)。
    evs: Vec<CUevent>,
    /// このリクエストで打ったイベント数。
    used: usize,
    /// 区間 k (= イベント k → k+1) の位相。
    phase_of: Vec<u8>,
    /// 位相ごとの積算 (秒)。
    acc: [f64; PF_PH_N],
    /// 層数 (表 C の calls = サンプル数)。
    layers: usize,
    /// トークン数 (ms/token の分母)。
    tokens: usize,
    /// prefill 入口の時刻 (壁時計の基準)。
    t0: Option<Instant>,
    /// prefill の通し番号 (DBG 表示)。
    req: u64,
}

impl Default for PfTiming {
    fn default() -> Self {
        Self {
            active: false,
            pending: false,
            evs: Vec::new(),
            used: 0,
            phase_of: Vec::new(),
            acc: [0.0; PF_PH_N],
            layers: 0,
            tokens: 0,
            t0: None,
            req: 0,
        }
    }
}

thread_local! {
    static PF_TIMING: std::cell::RefCell<PfTiming> =
        std::cell::RefCell::new(PfTiming::default());
}

/// イベントを `need` 個そろえる (grow-only・初回だけ作る)。
fn pf_ensure_events(t: &mut PfTiming, need: usize) -> bool {
    if t.evs.len() >= need {
        return true;
    }
    let Some(create) = lib().ok().and_then(|l| l.event_create) else {
        return false;
    };
    while t.evs.len() < need {
        let mut ev: CUevent = std::ptr::null_mut();
        // CU_EVENT_DEFAULT (0) = 計時有効。作れなければ計測を諦める (fail closed)。
        if unsafe { create(&mut ev, 0) } != CUDA_SUCCESS || ev.is_null() {
            return false;
        }
        t.evs.push(ev);
    }
    true
}

/// 既定ストリームに境界イベントを 1 つ打ち、そこから始まる区間の位相を控える。
///
/// プールが尽きたら**その場で足す** (FFN は 1024 行タイルごとに 3 境界を打つので、
/// 層あたりの境界数は n に依存する — `begin` で見積もらずに grow で吸収する)。
fn pf_record(t: &mut PfTiming, phase: u8) -> bool {
    let Some(rec) = lib().ok().and_then(|l| l.event_record) else {
        return false;
    };
    if t.used >= t.evs.len() {
        let want = t.evs.len().saturating_add(64);
        if !pf_ensure_events(t, want) {
            return false;
        }
    }
    let ev = t.evs[t.used];
    if unsafe { rec(ev, std::ptr::null_mut()) } != CUDA_SUCCESS {
        return false;
    }
    t.used += 1;
    t.phase_of.push(phase);
    true
}

/// prefill 入口: 位相計測を開く (層ループの直前で 1 回)。
pub fn pf_timing_begin(tokens: usize, layers: usize) {
    // s180 (P41): full_core の内訳計測 (別プール・別 env・既定 OFF)。
    fc_kprof_begin(tokens, layers);
    if !pf_timing_on() {
        return;
    }
    PF_TIMING.with(|c| {
        let mut t = c.borrow_mut();
        t.active = false;
        t.pending = false;
        t.used = 0;
        t.phase_of.clear();
        t.acc = [0.0; PF_PH_N];
        t.layers = layers;
        t.tokens = tokens;
        t.t0 = Some(Instant::now());
        t.req += 1;
        // 1 層あたりの境界は高々 PF_PH_N 個 + 入口 + 末尾。
        let need = layers.saturating_mul(PF_PH_N).saturating_add(2);
        if !pf_ensure_events(&mut t, need) {
            return;
        }
        if !pf_record(&mut t, PF_PH_NONE) {
            return;
        }
        t.active = true;
    });
}

/// 位相の先頭で境界を打つ (発行グループの先頭に置く)。計測していなければ
/// 分岐 1 回で戻る — 数値経路・発行順には触れない。
#[inline]
pub fn pf_phase(ph: usize) {
    // s180 (P41): full_core の内訳 (DENNO_FC_KPROF=1) の区間端もここで打つ
    // — 位相境界がそのまま full_core の先頭 / o_proj の先頭だから。
    fc_kprof_phase(ph);
    if !pf_timing_on() {
        return;
    }
    PF_TIMING.with(|c| {
        let mut t = c.borrow_mut();
        if !t.active {
            return;
        }
        if !pf_record(&mut t, ph as u8) {
            t.active = false;
        }
    });
}

/// 層ループ末尾: 最後の位相の終端を打つ (ここまでに打ったイベントは、この後の
/// **既存の**同期 D2H で必ず完了する)。`pf_timing_read` と対で 1 回ずつ。
pub fn pf_timing_end() {
    if !pf_timing_on() {
        return;
    }
    PF_TIMING.with(|c| {
        let mut t = c.borrow_mut();
        if !t.active {
            return;
        }
        if !pf_record(&mut t, PF_PH_NONE) {
            t.active = false;
            return;
        }
        t.pending = true;
    });
}

/// 残差常駐経路を途中で諦めた (Ok(None) → ホスト経路でやり直す) ときに捨てる。
/// 打ったイベントはストリーム上で勝手に完了するので、そのまま放置してよい。
pub fn pf_timing_abort() {
    if !pf_timing_on() {
        return;
    }
    PF_TIMING.with(|c| {
        let mut t = c.borrow_mut();
        t.active = false;
        t.pending = false;
    });
}

/// prefill 末尾 (**既存の**同期 D2H の後): 区間を読み、表 C の `sl_lay_*` へ
/// 1 位相 1 行で積み、`DENNO_PF_DBG=1` なら内訳を 1 回だけ stderr へ出す。
pub fn pf_timing_read() {
    // s180 (P41): full_core の内訳は DENNO_PF_DBG / DENNO_PROFILE と独立に出す
    // (こちらは DENNO_FC_KPROF だけで動く)。既存の出力には触れない。
    fc_kprof_read();
    // s240 (P43): GDN chunked 3 カーネルの積算行。ここは prefill 末尾 (= 最終行の
    // 既存 D2H の後) なので、読むのは static だけで同期は足さない。
    // `DENNO_GDN_KPROF` 未設定なら分岐 1 回で戻る。
    // s245 (P45): デバイス出力経路で保留したままの 3 区間をここで読む (直前の既存
    // D2H で 3 pass は完了している)。同期は足さない・読むだけ。
    kprof_read_pending();
    gdn_kprof_report_at_prefill_end();
    if !pf_timing_on() {
        return;
    }
    PF_TIMING.with(|c| {
        let mut t = c.borrow_mut();
        if !t.pending {
            return;
        }
        t.pending = false;
        t.active = false;
        let n_iv = t.phase_of.len().saturating_sub(1);
        let Some(elapsed) = lib().ok().and_then(|l| l.event_elapsed_time) else {
            return;
        };
        let mut acc = [0.0f64; PF_PH_N];
        let mut bad = false;
        for k in 0..n_iv {
            let mut ms: f32 = 0.0;
            let rc = unsafe { elapsed(&mut ms, t.evs[k], t.evs[k + 1]) };
            // 未完了 (NOT_READY) や負値は「読めなかった」として全体を捨てる
            // (半端な数字を表へ積むと、以後の判断が全部その数字に引きずられる)。
            if rc != CUDA_SUCCESS || !ms.is_finite() || ms < 0.0 {
                bad = true;
                break;
            }
            let ph = t.phase_of[k] as usize;
            if ph < PF_PH_N {
                acc[ph] += ms as f64 / 1e3;
            }
        }
        if bad {
            if pf_dbg_on() {
                eprintln!(
                    "[PF_DBG] unavailable (event elapsed failed; n={} layers={})",
                    t.tokens, t.layers
                );
            }
            return;
        }
        // 表 C: 1 位相 1 行・calls = 層数 (= 層あたり 1 サンプル)。
        let layers = t.layers.max(1) as u64;
        for ph in 0..PF_PH_N {
            let Some(op) = PF_PH_BUCKETS[ph] else {
                continue;
            };
            let ns = (acc[ph] * 1e6).round() as u64;
            if ns > 0 {
                crate::prof::span_end_ns_calls(ns, op, layers);
            }
        }
        if pf_dbg_on() {
            pf_dbg_print(&t, &acc);
        }
    });
}

/// `DENNO_PF_DBG=1` の内訳 (1 prefill = 1 回)。wall / 位相の和 / 末尾 (最終 norm +
/// logits + 最終行 D2H) を並べるので、「位相の和が wall に届かない分」が必ず見える。
fn pf_dbg_print(t: &PfTiming, acc: &[f64; PF_PH_N]) {
    let wall = t.t0.map(|t0| t0.elapsed().as_secs_f64()).unwrap_or(0.0);
    let sum: f64 = acc.iter().sum();
    let tok = t.tokens.max(1) as f64;
    let per_tok = |secs: f64| secs * 1e3 / tok;
    let pct = |secs: f64| if wall > 0.0 { secs / wall * 100.0 } else { 0.0 };
    eprintln!(
        "[PF_DBG] prefill req={} n={} layers={} wall={:.1} ms | phases {:.1} ms ({:.1}%) | \
         {:.3} ms/token",
        t.req,
        t.tokens,
        t.layers,
        wall * 1e3,
        sum * 1e3,
        pct(sum),
        per_tok(wall)
    );
    for ph in 0..PF_PH_N {
        eprintln!(
            "[PF_DBG]   {:<18} {:>10.1} ms {:>6.1}% {:>9.3} ms/tok",
            PF_PH_NAMES[ph],
            acc[ph] * 1e3,
            pct(acc[ph]),
            per_tok(acc[ph])
        );
    }
    // 末尾 = 最終 norm + 最終行 D2H + lm_head。位相の外なので差で出す。
    let tail = (wall - sum).max(0.0);
    eprintln!(
        "[PF_DBG]   {:<18} {:>10.1} ms {:>6.1}% {:>9.3} ms/tok",
        "tail(final+logits)",
        tail * 1e3,
        pct(tail),
        per_tok(tail)
    );
}

// ---------------------------------------------------------------------------
// s180 (P41): full_core 相の内訳 (DENNO_FC_KPROF=1・既定 OFF)
//
// `sl_lay_full_core` の位相バケットは「区間内に発行したカーネル + ホストの詰まり」
// をまとめて 1 本にしているので、attention カーネル本体 (device) とホスト側の
// prepare / ゲート (host) のどちらが重いのかが分からない。ここでは**既存の
// launch / sync の位置**にイベントを打つだけで、full 層 1 枚の full_core 区間を
// 4 つに割って積算し、prefill の終了時に 1 行で出す:
//
//   [FC_KPROF] prep=<ms> attn=<ms> d2h=<ms> tail=<ms> calls=<n> total=<ms> (<ms>/token)
//
//   prep = 位相 FULL_CORE の境界 → attention カーネルの発行直前
//          (ホスト prepare: QK-Norm + RoPE + KV 行書き込み、KV ミラーの H2D、
//           q の pinned ステージング H2D)
//   attn = カーネル発行直前 → 発行直後 (`dno_attention_prefill` の実行。QK スコア +
//          softmax + PV が 1 発に融合しているので **qk と av には割れない**)
//   d2h  = 発行直後 → att の D2H 完了 (`chain_pf_att_inplace` の `cuMemcpyDtoHAsync`)
//   tail = D2H 完了 → 位相 FULL_OPROJ の境界 (sigmoid ゲート + att の H2D +
//          o_proj の prologue)
//
// 打つのはイベントだけ: launch の順序・引数・同期の位置は 1 つも変えない。
// `DENNO_FC_KPROF` 未設定なら各サイトは分岐 1 回で戻り、イベントも作らない
// (プロファイラ build 不要)。既存の `DENNO_PROFILE` / `DENNO_PF_DBG` の出力は
// この env を立てても変わらない (別プール・別行)。
// ---------------------------------------------------------------------------

/// 区間数 (prep / attn / d2h / tail)。
const FC_IV_N: usize = 4;
/// full 層 1 枚あたりの境界イベント数 (区間数 + 1)。
const FC_MARK_N: usize = FC_IV_N + 1;
/// 区間名 (表示順・REPORT_P41.md の表と同じ)。
const FC_IV_NAMES: [&str; FC_IV_N] = ["prep", "attn", "d2h", "tail"];

/// `DENNO_FC_KPROF=1` のときだけ full_core の内訳を取る (既定 OFF・分岐 1 回)。
fn fc_kprof_on() -> bool {
    static ON: OnceLock<bool> = OnceLock::new();
    *ON.get_or_init(|| std::env::var("DENNO_FC_KPROF").ok().as_deref() == Some("1"))
}

/// 1 prefill 分の full_core 内訳の状態 (スレッドローカル・リクエストごとに使い回す)。
struct FcKprof {
    /// 計測中 (begin 済みで read 前)。
    active: bool,
    /// いま記録中の呼び出し (= full 層 1 枚) が先頭の境界から始まっている。
    open: bool,
    /// 記録済みの境界 (bit k = スロット k)。
    have: u8,
    /// 呼び出し番号 (先頭の境界で 1 増える)。
    call: u32,
    /// イベントのプール (grow-only。初回の prefill で層数ぶん作る)。
    evs: Vec<CUevent>,
    /// このリクエストで打ったイベント数。
    used: usize,
    /// イベント k の (呼び出し番号, スロット)。
    meta: Vec<(u32, u8)>,
    /// 5 点そろった呼び出しの数 (= 内訳を読めた層数)。
    calls: usize,
    /// トークン数 (ms/token の分母)。
    tokens: usize,
}

impl Default for FcKprof {
    fn default() -> Self {
        Self {
            active: false,
            open: false,
            have: 0,
            call: 0,
            evs: Vec::new(),
            used: 0,
            meta: Vec::new(),
            calls: 0,
            tokens: 0,
        }
    }
}

thread_local! {
    static FC_KPROF: std::cell::RefCell<FcKprof> =
        std::cell::RefCell::new(FcKprof::default());
}

/// イベントを `need` 個そろえる (grow-only・初回だけ作る)。
fn fc_ensure_events(t: &mut FcKprof, need: usize) -> bool {
    if t.evs.len() >= need {
        return true;
    }
    let Some(create) = lib().ok().and_then(|l| l.event_create) else {
        return false;
    };
    while t.evs.len() < need {
        let mut ev: CUevent = std::ptr::null_mut();
        // CU_EVENT_DEFAULT (0) = 計時有効。作れなければ計測を諦める (fail closed)。
        if unsafe { create(&mut ev, 0) } != CUDA_SUCCESS || ev.is_null() {
            return false;
        }
        t.evs.push(ev);
    }
    true
}

/// prefill 入口: full_core の内訳計測を開く (`pf_timing_begin` から 1 回)。
fn fc_kprof_begin(tokens: usize, layers: usize) {
    if !fc_kprof_on() {
        return;
    }
    FC_KPROF.with(|c| {
        let mut t = c.borrow_mut();
        t.active = false;
        t.open = false;
        t.have = 0;
        t.call = 0;
        t.used = 0;
        t.meta.clear();
        t.calls = 0;
        t.tokens = tokens;
        // full 層は高々 layers 枚。イベントは grow-only のプールに 1 回だけ作る
        // (2 回目以降の prefill はここで何もしない)。
        let need = layers.saturating_mul(FC_MARK_N).max(FC_MARK_N);
        if !fc_ensure_events(&mut t, need) {
            return;
        }
        t.active = true;
    });
}

/// 位相境界から区間の端を打つ (`pf_phase` から呼ぶ)。FULL_CORE = 先頭、
/// FULL_OPROJ = 末尾 (o_proj の prologue までが tail に入る)。
#[inline]
fn fc_kprof_phase(ph: usize) {
    if !fc_kprof_on() {
        return;
    }
    if ph == PF_PH_FULL_CORE {
        fc_kprof_mark(0);
    } else if ph == PF_PH_FULL_OPROJ {
        fc_kprof_mark(FC_MARK_N as u8 - 1);
    }
}

/// 既定ストリームに境界イベントを 1 つ打つ (イベントのみ・同期も転送もしない)。
///
/// 先頭 (slot 0) を打っていない呼び出しの途中スロットは捨てる — ホスト経路や
/// CPU attend に落ちた層は 5 点そろわないので、区間として読まない。
fn fc_kprof_mark(slot: u8) {
    if !fc_kprof_on() {
        return;
    }
    FC_KPROF.with(|c| {
        let mut t = c.borrow_mut();
        if !t.active {
            return;
        }
        if slot == 0 {
            t.open = true;
            t.have = 1;
            t.call = t.call.wrapping_add(1);
        } else if !t.open {
            return;
        } else {
            t.have |= 1u8 << slot;
        }
        let Some(rec) = lib().ok().and_then(|l| l.event_record) else {
            t.active = false;
            return;
        };
        if t.used >= t.evs.len() {
            let want = t.used.saturating_add(FC_MARK_N * 8);
            if !fc_ensure_events(&mut t, want) {
                t.active = false;
                return;
            }
        }
        let ev = t.evs[t.used];
        if unsafe { rec(ev, std::ptr::null_mut()) } != CUDA_SUCCESS {
            t.active = false;
            return;
        }
        t.used += 1;
        let call = t.call;
        t.meta.push((call, slot));
        if slot as usize == FC_MARK_N - 1 {
            if t.have == (1u8 << FC_MARK_N) - 1 {
                t.calls += 1;
            }
            t.open = false;
        }
    });
}

/// prefill 末尾 (**既存の**同期 D2H の後): 区間を読み、1 行だけ stderr へ出す。
/// 積算はリクエストごと (次の `fc_kprof_begin` でリセット)。
fn fc_kprof_read() {
    if !fc_kprof_on() {
        return;
    }
    FC_KPROF.with(|c| {
        let mut t = c.borrow_mut();
        if !t.active {
            return;
        }
        t.active = false;
        t.open = false;
        let Some(elapsed) = lib().ok().and_then(|l| l.event_elapsed_time) else {
            eprintln!("[FC_KPROF] unavailable (no cuEventElapsedTime)");
            return;
        };
        let mut acc = [0.0f64; FC_IV_N];
        let mut bad = false;
        for w in 1..t.meta.len() {
            let (c0, s0) = t.meta[w - 1];
            let (c1, s1) = t.meta[w];
            // 同じ呼び出しの隣り合う境界だけを 1 区間として読む (5 点そろわない
            // 呼び出しは自動的に落ちる)。
            if c0 != c1 || s1 != s0 + 1 {
                continue;
            }
            let mut ms: f32 = 0.0;
            if unsafe { elapsed(&mut ms, t.evs[w - 1], t.evs[w]) } != CUDA_SUCCESS
                || !ms.is_finite()
                || ms < 0.0
            {
                bad = true;
                break;
            }
            acc[s0 as usize] += ms as f64 / 1e3;
        }
        if bad {
            eprintln!(
                "[FC_KPROF] unavailable (event elapsed failed; n={} calls={})",
                t.tokens, t.calls
            );
            return;
        }
        let total: f64 = acc.iter().sum();
        if t.calls == 0 && total <= 0.0 {
            eprintln!(
                "[FC_KPROF] no complete full_core call (n={} marks={})",
                t.tokens, t.used
            );
            return;
        }
        let tok = t.tokens.max(1) as f64;
        let mut line = String::from("[FC_KPROF]");
        for i in 0..FC_IV_N {
            line.push_str(&format!(" {}={:.1}", FC_IV_NAMES[i], acc[i] * 1e3));
        }
        line.push_str(&format!(
            " calls={} total={:.1} ({:.3} ms/token)",
            t.calls,
            total * 1e3,
            total * 1e3 / tok
        ));
        eprintln!("{line}");
    });
}

/// s167 (P6): GDN 層の prefill を、h2 の D2H と qkv/z GEMM の**オーバーラップ付き**
/// で通す版。`DENNO_PF_OVERLAP=1` かつデバイス準備が成功したときだけ
///   位相 Gemm → join → `host_ctrl` (beta/alpha) → 位相 Rest
/// の順で流し、それ以外は従来と**同一の順序**
///   同期 D2H → `host_ctrl` → (GEMM → beta/alpha H2D → scan → o_proj)
/// を通す。`host_ctrl` は h2 を受け取って beta/alpha を書くホスト区間で、呼び出し
/// 側は従来と同じ関数 (`apply_bt_rows_into`) を同じ引数で呼ぶ。
#[allow(clippy::too_many_arguments)]
pub fn chain_gdn_prefill_q4_dev_ovl<F>(
    qkv_w: &crate::quant::Linear,
    z_w: &crate::quant::Linear,
    o_w: &crate::quant::Linear,
    beta: &mut [f32],
    alpha: &mut [f32],
    wconv: &[f32],
    wa: &[f32],
    wdt: &[f32],
    wnorm: &[f32],
    n: usize,
    nk: usize,
    nv: usize,
    dk: usize,
    dv: usize,
    d_conv: usize,
    eps: f32,
    q_scale: f32,
    conv_st: &mut [f32],
    ssm_st: &mut [f32],
    li: usize,
    kv: u64,
    host_ctrl: F,
) -> Option<()>
where
    F: FnOnce(&[f32], &mut [f32], &mut [f32]) -> Option<()>,
{
    // 前提 (形・重み種別・n の帯域) はコピーを発行する前に確定させる — ここで
    // 落ちる形ではコピーを 1 バイトも発行しない (未 join のコピーを残さない)。
    let g = gdn_prefill_q4_geom(qkv_w, z_w, o_w, n, nk, nv, dk, dv, d_conv)?;
    let e = g.e;
    let n_e = n.checked_mul(e)?;
    // s169 (P8): 位相の境界は**発行グループの先頭**。ここから「h2 の D2H (同期 or
    // join) → ホストの beta/alpha → qkv/z GEMM」までが gdn_proj の区間になる。
    pf_phase(PF_PH_GDN_PROJ);
    let want = pf_overlap_flag();
    let begun = want && chain_pf_h2_begin(CH_PFH, 0, n_e).is_some();
    if pf_h2_path(want, n, e, begun) == PfH2Path::CopyStream {
        // 位相 Gemm を先に流す (h2 を待たない)。この間コピーストリームが h2 を運ぶ。
        // 既定ストリームは非ブロッキングのコピーストリームと暗黙同期しないので、
        // GEMM がコピーを待つことはない。
        if chain_gdn_prefill_q4_impl(
            qkv_w,
            z_w,
            o_w,
            beta,
            alpha,
            wconv,
            wa,
            wdt,
            wnorm,
            PfSrc::Slot,
            PfSink::Slot,
            n,
            nk,
            nv,
            dk,
            dv,
            d_conv,
            eps,
            q_scale,
            conv_st,
            ssm_st,
            li,
            kv,
            PfGdnPhase::Gemm,
        )
        .is_none()
        {
            // 位相 Gemm の失敗 = デバイス障害 (従来のチェーン失敗と同じ扱い)。
            // 未 join のコピーは残さない。
            let _ = chain_pf_h2_join();
            return None;
        }
        // join: ホストが h2 を読む直前の唯一の同期点。
        if chain_pf_h2_join().is_some() {
            // pinned の h2 をそのまま渡す (Vec への写しをしない)。安全性: pin_h2 は
            // thread_local の grow-only バッファで、join 済み = 全要素がコピーで
            // 埋まっている。CHAIN の借用は保持しない (保持したままホスト区間を走ら
            // せると、内側の CHAIN アクセスが RefCell で panic する)。
            let (p, cap) = CHAIN.with(|cell| {
                cell.borrow()
                    .pin_h2
                    .as_ref()
                    .map(|p| (p.ptr as *const f32, p.bytes / std::mem::size_of::<f32>()))
            })?;
            if cap < n_e {
                return None;
            }
            let h2: &[f32] = unsafe { std::slice::from_raw_parts(p, n_e) };
            host_ctrl(h2, beta, alpha)?;
            return chain_gdn_prefill_q4_impl(
                qkv_w,
                z_w,
                o_w,
                beta,
                alpha,
                wconv,
                wa,
                wdt,
                wnorm,
                PfSrc::Slot,
                PfSink::Slot,
                n,
                nk,
                nv,
                dk,
                dv,
                d_conv,
                eps,
                q_scale,
                conv_st,
                ssm_st,
                li,
                kv,
                PfGdnPhase::Rest,
            );
        }
        // join だけ失敗した (driver 障害)。q/z は既にデバイスにあるので、h2 を
        // 従来の同期 D2H で取り直して残りを流す — 値は同一。
        let h2 = chain_download_at(CH_PFH, 0, n_e)?;
        host_ctrl(&h2, beta, alpha)?;
        return chain_gdn_prefill_q4_impl(
            qkv_w,
            z_w,
            o_w,
            beta,
            alpha,
            wconv,
            wa,
            wdt,
            wnorm,
            PfSrc::Slot,
            PfSink::Slot,
            n,
            nk,
            nv,
            dk,
            dv,
            d_conv,
            eps,
            q_scale,
            conv_st,
            ssm_st,
            li,
            kv,
            PfGdnPhase::Rest,
        );
    }
    // 従来と同一の順序: 同期 D2H → ホスト計算 → GEMM → beta/alpha H2D → scan → o_proj
    let h2 = chain_download_at(CH_PFH, 0, n_e)?;
    host_ctrl(&h2, beta, alpha)?;
    chain_gdn_prefill_q4_impl(
        qkv_w,
        z_w,
        o_w,
        beta,
        alpha,
        wconv,
        wa,
        wdt,
        wnorm,
        PfSrc::Slot,
        PfSink::Slot,
        n,
        nk,
        nv,
        dk,
        dv,
        d_conv,
        eps,
        q_scale,
        conv_st,
        ssm_st,
        li,
        kv,
        PfGdnPhase::All,
    )
}

// ---------------------------------------------------------------------------
// s165 (P2): prefill の残差ストリーム (h) をデバイス常駐させる経路の小道具。
//
// 従来の prefill は層ごとに「rmsnorm(h) をホストで計算 → h2 を H2D → 投影 →
// 出力を D2H → 残差加算をホスト」を繰り返していた (1 層 2 往復 + ホスト 2 パス)。
// P2 では h を `CH_PF_RES` に置いたまま、層の中で
//   rmsnorm (デバイス) → 投影 (デバイス) → 残差加算 (次の rmsnorm の proj 引数)
// を通す。ホストが本当に必要とするものだけが往復する:
//   - GDN 層: beta/alpha を計算するための h2 の D2H 1 回 (状態契約は従来どおり)
//   - full attention 層: q/k/v はホスト計算なので h2 の D2H 1 回 + att の H2D 1 回
//   - FFN: 往復なし
//
// 残差加算に専用カーネルは要らない (PTX に単独の add は無い) — `dno_add_rmsnorm`
// の `proj` 引数が「x += proj」と「rmsnorm(x)」を 1 回で行うので、層の最後の
// 投影出力を**次の rmsnorm の add_slot** として渡す。演算順はホスト経路と同一
// (ホストも `x += proj` してから `rmsnorm(x)` を計算する)。
// ---------------------------------------------------------------------------

/// 層 1 枚ぶんの attention 投影の重み (事前検査・重み登録で使う)。
pub enum PfAttnW<'a> {
    Gdn {
        qkv: &'a crate::quant::Linear,
        z: &'a crate::quant::Linear,
        o: &'a crate::quant::Linear,
    },
    Full {
        q: &'a crate::quant::Linear,
        k: &'a crate::quant::Linear,
        v: &'a crate::quant::Linear,
        o: &'a crate::quant::Linear,
    },
}

/// 残差常駐経路の判定に使うモデル寸法。
pub struct PfDims {
    pub n: usize,
    pub e: usize,
    pub heads: usize,
    pub kv_heads: usize,
    pub dh: usize,
    pub nk: usize,
    pub nv: usize,
    pub dk: usize,
    pub dv: usize,
    pub d_conv: usize,
}

/// Q4 線形の (k, n)。Q4 以外は None。
fn q4_dims(w: &crate::quant::Linear) -> Option<(usize, usize)> {
    match w {
        crate::quant::Linear::Q4(q) => Some((q.k, q.n)),
        _ => None,
    }
}

/// Q4 線形の (uid, blocks, k, n)。Q4 以外は None。
fn q4_parts(w: &crate::quant::Linear) -> Option<(u64, &[u8], usize, usize)> {
    match w {
        crate::quant::Linear::Q4(q) => Some((q.uid, &q.blocks, q.k, q.n)),
        _ => None,
    }
}

/// s165 (P2): 残差常駐経路の**グローバル**入口条件 (純粋関数・GPU 非依存)。
/// `all_q4` は「全層の attn/FFN 投影が q4」、`diag` は層別診断 (lchk) の有無。
/// 診断中はホストの `x` が層ごとに更新される前提なので発動しない。
/// `gemm_min` / `max_m` は env 実効値 (`gemm_min_m()` / `max_m()`) を渡す。
pub fn pf_res_gate(
    n: usize,
    e: usize,
    all_q4: bool,
    diag: bool,
    gemm_min: usize,
    max_m: usize,
) -> bool {
    if !all_q4 || diag {
        return false;
    }
    if n == 0 || e == 0 || n < gemm_min || n <= max_m {
        return false;
    }
    // dno_add_rmsnorm の動的 shmem = e*4 (≤48KB)
    if e % 32 != 0 || e.saturating_mul(4) > 48 * 1024 {
        return false;
    }
    // 端数タイルが GEMV 帯域に入る形では per-op 経路と演算列が変わる
    let rem = n % GDN_PREFILL_TILE;
    if rem != 0 && rem <= max_m {
        return false;
    }
    true
}

/// 実行時の env 実効値で [`pf_res_gate`] を評価する。
pub fn pf_res_gate_now(n: usize, e: usize, all_q4: bool, diag: bool) -> bool {
    pf_res_gate(n, e, all_q4, diag, gemm_min_m(), max_m())
}

/// 実行時の env 実効値で [`pf_layer_geom`] を評価する。
pub fn pf_layer_geom_now(
    attn: &PfAttnW<'_>,
    gate: &crate::quant::Linear,
    up: &crate::quant::Linear,
    down: &crate::quant::Linear,
    d: &PfDims,
) -> Option<()> {
    pf_layer_geom(attn, gate, up, down, d, gemm_min_m(), max_m())
}

/// s165 (P2): 層 1 枚を残差常駐で通せるかの事前検査 (純粋関数・GPU 非依存)。
/// `None` なら呼び出し側はこの層を従来のホスト経路で通す (残差は触らない)。
pub fn pf_layer_geom(
    attn: &PfAttnW<'_>,
    gate: &crate::quant::Linear,
    up: &crate::quant::Linear,
    down: &crate::quant::Linear,
    d: &PfDims,
    gemm_min: usize,
    max_m: usize,
) -> Option<()> {
    let (n, e) = (d.n, d.e);
    if !pf_res_gate(n, e, true, false, gemm_min, max_m) {
        return None;
    }
    // FFN: q4・形・k/n の整合
    let (gk, gn) = q4_dims(gate)?;
    let (uk, un) = q4_dims(up)?;
    let (dkn, dn) = q4_dims(down)?;
    if gk != e || uk != e || gn != un || dkn != gn || dn != e {
        return None;
    }
    if gn == 0 || gn % 32 != 0 {
        return None;
    }
    match attn {
        PfAttnW::Gdn { qkv, z, o } => {
            // 形状・dk==dv・d_conv==4・n の帯域は gdn_prefill_q4_geom と同一契約
            gdn_prefill_q4_geom(qkv, z, o, n, d.nk, d.nv, d.dk, d.dv, d.d_conv)?;
        }
        PfAttnW::Full { q, k, v, o } => {
            let (qk, qn) = q4_dims(q)?;
            let (kk, kn) = q4_dims(k)?;
            let (vk, vn) = q4_dims(v)?;
            let (okn, on) = q4_dims(o)?;
            if d.heads == 0 || d.dh == 0 || d.kv_heads == 0 {
                return None;
            }
            let att = d.heads.checked_mul(d.dh)?;
            let kv_dim = d.kv_heads.checked_mul(d.dh)?;
            if qk != e || qn != att.checked_mul(2)? || kk != e || kn != kv_dim {
                return None;
            }
            if vk != e || vn != kv_dim || okn != att || on != e {
                return None;
            }
            if att % 32 != 0 || kv_dim % 32 != 0 {
                return None;
            }
        }
    }
    Some(())
}

/// s165 (P2): 残差常駐経路が使うスロットを事前に確保する (rmsnorm の前に呼ぶ)。
/// ここで失敗すれば残差はまだ触っていないので、呼び出し側は安全にフォールバックできる。
pub fn chain_pf_reserve(n: usize, e: usize) -> Option<()> {
    let _ = chain_ctx()?;
    let rows = n.checked_mul(e)?.checked_mul(4)?;
    ok(chain_ensure_buf(CH_PF_RES, rows))?;
    ok(chain_ensure_buf(CH_PFH, rows.checked_add(e.checked_mul(4)?)?))?;
    ok(chain_ensure_buf(CH_O, rows))?;
    ok(chain_ensure_buf(CH_DOWN, rows))?;
    Some(())
}

/// s165 (P2): 層の q4 重みをデバイスへ事前登録する。登録失敗 (確保失敗) を
/// 残差を更新する前に確定させるためのもの (チェーン内の登録はキャッシュヒット)。
pub fn pf_layer_dev_register(
    attn: &PfAttnW<'_>,
    gate: &crate::quant::Linear,
    up: &crate::quant::Linear,
    down: &crate::quant::Linear,
) -> Option<()> {
    let _ = chain_ctx()?;
    let reg = |w: &crate::quant::Linear| -> Option<()> {
        let q = match w {
            crate::quant::Linear::Q4(q) => q,
            _ => return None,
        };
        weights_for_q4(q.uid, &q.blocks, q.k, q.n).ok()?;
        Some(())
    };
    match attn {
        PfAttnW::Gdn { qkv, z, o } => {
            reg(qkv)?;
            reg(z)?;
            reg(o)?;
        }
        PfAttnW::Full { q, k, v, o } => {
            reg(q)?;
            reg(k)?;
            reg(v)?;
            reg(o)?;
        }
    }
    reg(gate)?;
    reg(up)?;
    reg(down)
}

/// s165 (P2): 残差ストリーム (h) を `CH_PF_RES` へ 1 回だけアップロードする
/// (非同期・同期なし)。prefill の開始時に 1 回だけ呼ぶ。
pub fn chain_pf_res_upload(h: &[f32], m: usize, e: usize) -> Option<()> {
    let _ = chain_ctx()?;
    let n_elems = m.checked_mul(e)?;
    let bytes = n_elems.checked_mul(4)?;
    if n_elems == 0 || h.len() < n_elems {
        return None;
    }
    ok(chain_ensure_buf(CH_PF_RES, bytes))?;
    CHAIN.with(|cell| -> Option<()> {
        let buf = cell.borrow().bufs[CH_PF_RES].as_ref()?.ptr();
        let lib = lib().ok()?;
        unsafe {
            ok(check(
                (lib.memcpy_htod_async)(buf, h.as_ptr() as *const c_void, bytes, std::ptr::null_mut()),
                "cuMemcpyHtoDAsync (pf residual)",
            ))
        }
    })
}

/// s165 (P2): `CH_PF_RES` の内容をホストへ戻す (フォールバック時の復元・同期あり)。
pub fn chain_pf_res_download(m: usize, e: usize, out: &mut [f32]) -> Option<()> {
    let n_elems = m.checked_mul(e)?;
    if n_elems == 0 || out.len() < n_elems {
        return None;
    }
    let v = chain_download_at(CH_PF_RES, 0, n_elems)?;
    out[..n_elems].copy_from_slice(&v);
    Some(())
}

/// s165 (P2): ホストで計算した attention 出力 (sigmoid ゲート適用済み) を
/// `CH_ATT` へ 1 回だけアップロードする。pinned は層ごとに専用 (li*3+2) —
/// 非同期 H2D の完了前に次の層が同じ領域を上書きしないため
/// (`chain_rmsnorm` の pin と同じ規約)。
pub fn chain_pf_upload_att(att: &[f32], cols: usize, m: usize, li: usize) -> Option<()> {
    let _ = chain_ctx()?;
    let n_elems = m.checked_mul(cols)?;
    let bytes = n_elems.checked_mul(4)?;
    if n_elems == 0 || att.len() < n_elems {
        return None;
    }
    ok(chain_ensure_buf(CH_ATT, bytes))?;
    let pin_id = li.checked_mul(3)?.checked_add(2)?;
    CHAIN.with(|cell| -> Option<()> {
        let mut s = cell.borrow_mut();
        while s.pins.len() <= pin_id {
            s.pins.push(None);
        }
        ok(Scratch::ensure_pin(&mut s.pins[pin_id], bytes))?;
        let pin = s.pins[pin_id].as_mut().unwrap();
        pin.as_mut_slice::<f32>()[..n_elems].copy_from_slice(&att[..n_elems]);
        let src = pin.ptr as *const c_void;
        let buf = s.bufs[CH_ATT].as_ref()?.ptr();
        let lib = lib().ok()?;
        unsafe {
            ok(check(
                (lib.memcpy_htod_async)(buf, src, bytes, std::ptr::null_mut()),
                "cuMemcpyHtoDAsync (pf att)",
            ))
        }
    })
}

/// s172 (P12): prefill attention の出力を **pinned ステージングへ直接** D2H し、
/// 呼び出し側のクロージャでその場を書き換えてから同じバッファで H2D する
/// (`DENNO_PF_ATT_INPLACE=0` で従来の
/// `chain_download` → ホストで変換 → `chain_pf_upload_att` に戻る)。
///
/// 従来経路の無駄 (27B n=14,043 で 1 層あたり):
///   1. `chain_download` が **pageable な新しい `Vec`** (345 MB) を確保して D2H
///      → 毎層 345 MB の page fault + driver の内部ステージング経由。
///   2. 呼び出し側がゲートを掛けたあと `att.copy_from_slice(&ga)` で
///      ホスト・ホストの 345 MB コピー (読み + 書き = 690 MB)。
///   3. `chain_pf_upload_att` が pinned へもう一度 345 MB コピー (690 MB)。
/// ここでは D2H の宛先を 3 の pinned バッファそのものにして、変換もそこで行い、
/// そのまま H2D する — 転送量は同じ (345 MB 下り + 345 MB 上り) で、
/// 余計な 1.4 GB/層 のホスト memcpy と 345 MB/層 の確保が消える。
///
/// 安全性: D2H は `ctx.sync()` で完了を待ってから書き換える。pinned バッファは
/// 層ごと (`chain_pf_upload_att` と同一の `li*3+2`) なので、次の層が同じ領域を
/// 使うのは次の層の qkv chain の同期より後 = この H2D は既に完了している。
/// カーネル・引数・転送バイト数は従来と同一で、値も 1 ビットも変わらない。
///
/// s246 (P46): `gate` を `FnMut(行オフセット, 行ブロック)` に変え、転送を
/// **行ブロック単位のチャンク**に割って「D2H(k) 完了 → gate(k) → H2D(k)」を
/// 重ねる (`DENNO_PF_ATT_PIPE`・既定 ON)。従来は
/// `D2H 全体 → ctx.sync() → gate 全体 → H2D 全体` で、ホストは D2H の完了
/// (= PCIe 1 往復ぶん) を待ち終えてからゲートを始め、ゲートが終わるまで H2D を
/// 発行できなかった (FC_KPROF 65k・16 層: d2h=394 ms / tail=1014 ms)。
/// チャンク化しても転送バイト数・宛先オフセット・ゲートの式・`CH_ATT` の最終内容は
/// 1 ビットも変わらない — 各要素は同じ式で 1 回だけゲートされ、同じオフセットへ
/// 同じバイト列が戻る。変わるのは「いつ発行するか」だけ。
pub fn chain_pf_att_inplace<F>(li: usize, cols: usize, m: usize, mut gate: F) -> Option<()>
where
    F: FnMut(usize, &mut [f32]),
{
    if cols == 0 || m == 0 {
        return None;
    }
    let ctx = chain_ctx()?;
    let n_elems = m.checked_mul(cols)?;
    let bytes = n_elems.checked_mul(4)?;
    ok(chain_ensure_buf(CH_ATT, bytes))?;
    let pin_id = li.checked_mul(3)?.checked_add(2)?;
    CHAIN.with(|cell| -> Option<()> {
        let mut s = cell.borrow_mut();
        while s.pins.len() <= pin_id {
            s.pins.push(None);
        }
        ok(Scratch::ensure_pin(&mut s.pins[pin_id], bytes))?;
        let lib = lib().ok()?;
        let (buf, pin_ptr) = {
            let buf = s.bufs[CH_ATT].as_ref()?.ptr();
            let pin = s.pins[pin_id].as_ref()?;
            if pin.bytes < bytes {
                return None;
            }
            (buf, pin.ptr)
        };
        // s246 (P46): チャンク数 (1 = 従来の 1 発往復)。イベントを作れない環境・
        // 小さい転送・フラグ OFF では 1 = 従来経路そのものに落ちる。
        let (rows_per, nch) = pf_att_chunk_rows(m, pf_att_pipe_chunks(bytes, m));
        if nch >= 2 && pf_att_ensure_events(&mut s, nch) {
            return pf_att_inplace_piped(
                &mut s, lib, ctx, buf, pin_ptr, pin_id, cols, m, bytes, rows_per, nch, &mut gate,
            );
        }
        // 1) CH_ATT → pinned (宛先が pinned なので pageable 経路の内部ステージングが無い)
        unsafe {
            ok(check(
                (lib.memcpy_dtoh_async)(pin_ptr, buf, bytes, std::ptr::null_mut()),
                "cuMemcpyDtoHAsync (pf att pin)",
            ))?;
        }
        // s180 (P41): att の D2H 発行点 = full_core の区間 [d2h] の終端
        // (イベントはストリーム順。sync はこの直後の既存の 1 回だけ)。
        fc_kprof_mark(3);
        ok(ctx.sync())?;
        // 2) pinned の上で変換 (数値は呼び出し側のクロージャ = 従来と同じ式)
        {
            let pin = s.pins[pin_id].as_mut().unwrap();
            let v = pin.as_mut_slice::<f32>();
            gate(0, &mut v[..n_elems]);
        }
        // 3) pinned → CH_ATT (async H2D。同一ストリームの後続 GEMM が順序で待つ)
        unsafe {
            ok(check(
                (lib.memcpy_htod_async)(buf, pin_ptr as *const c_void, bytes, std::ptr::null_mut()),
                "cuMemcpyHtoDAsync (pf att gate)",
            ))?;
        }
        Some(())
    })
}

/// s246 (P46): att の D2H/H2D とゲートを重ねる経路のチャンク数。
///
/// 1 = 従来の 1 発往復。`DENNO_PF_ATT_PIPE=0` で常に 1、`=N` で上限 N
/// (未設定は既定の上限)。転送が小さいときは重ねる意味が無いので 1。
fn pf_att_pipe_chunks(bytes: usize, m: usize) -> usize {
    pf_att_pipe_chunks_with(bytes, m, pf_att_pipe_max())
}

/// s246 (P46): 既定の上限 (env `DENNO_PF_ATT_PIPE`・起動時に 1 回だけ読む)。
fn pf_att_pipe_max() -> usize {
    /// 既定の上限。チャンクあたりの API 呼び出しは 4 回 (D2H / record / sync /
    /// H2D) なので、増やすと 1 層あたり数十 µs の固定費が乗る。
    const MAX_CHUNKS: usize = 8;
    static MAX: OnceLock<usize> = OnceLock::new();
    *MAX.get_or_init(|| match std::env::var("DENNO_PF_ATT_PIPE") {
        Ok(v) => match v.trim().parse::<usize>() {
            Ok(n) => n,
            // 数値でない値 (空文字・"on" 等) は既定の上限として扱う。
            Err(_) => MAX_CHUNKS,
        },
        Err(_) => MAX_CHUNKS,
    })
}

/// s246 (P46): `pf_att_pipe_chunks` の純関数部分 (env を読まない = テスト可能)。
fn pf_att_pipe_chunks_with(bytes: usize, m: usize, max: usize) -> usize {
    /// 1 チャンクの目標バイト数。これ以下なら 1 発 (PCIe の立上がりを払う方が高い)。
    const CHUNK_BYTES: usize = 128 << 20;
    if max < 2 || bytes < CHUNK_BYTES || m < 2 {
        return 1;
    }
    bytes.div_ceil(CHUNK_BYTES).clamp(2, max).min(m)
}

/// s246 (P46): `m` 行を高々 `nch` 個の行ブロックに割る。戻り値は
/// `(rows_per, 実際のチャンク数)`。行ブロックは `[0, m)` を重複なく覆い、
/// 最終チャンクだけ短くなる (端数行を捨てない)。`nch < 2` は 1 を返す
/// (= 従来の 1 発往復)。
fn pf_att_chunk_rows(m: usize, nch: usize) -> (usize, usize) {
    if m == 0 || nch < 2 {
        return (m, 1);
    }
    let rows_per = m.div_ceil(nch.min(m));
    (rows_per, m.div_ceil(rows_per))
}

/// s246 (P46): チャンク `k` の行範囲 `[r0, r1)`。`pf_att_chunk_rows` の
/// `(rows_per, nch)` に対して全チャンクが `[0, m)` を隙間なく覆う。
fn pf_att_chunk_bounds(k: usize, rows_per: usize, m: usize) -> (usize, usize) {
    let r0 = k.saturating_mul(rows_per).min(m);
    let r1 = r0.saturating_add(rows_per).min(m);
    (r0, r1)
}

/// s246 (P46): パイプライン用の完了イベントを `n` 個そろえる (grow-only)。
/// 作れなければ false (呼び出し側は従来の 1 発往復に落ちる)。
fn pf_att_ensure_events(s: &mut ChainScratch, n: usize) -> bool {
    if s.pipe_ev.len() >= n {
        return true;
    }
    let Some(create) = lib().ok().and_then(|l| l.event_create) else {
        return false;
    };
    const CU_EVENT_DISABLE_TIMING: u32 = 0x02;
    while s.pipe_ev.len() < n {
        let mut ev: CUevent = std::ptr::null_mut();
        if unsafe { create(&mut ev, CU_EVENT_DISABLE_TIMING) } != CUDA_SUCCESS || ev.is_null() {
            return false;
        }
        s.pipe_ev.push(CopyEvent(ev));
    }
    true
}

/// s246 (P46): `chain_pf_att_inplace` の重ねる版。呼び出し規約と数値の契約は
/// あちらと同じで、違いは「D2H をチャンクに割り、チャンクが着いた順に
/// ゲートして H2D する」ことだけ。
///
/// 失敗時の安全性 (呼び出し側は `None` で `chain_download` 経路へ落ちる):
///   - D2H のどれかが失敗した時点では `CH_ATT` を 1 バイトも書いていないので、
///     そのまま `None` を返してよい (従来の 1 発 D2H 失敗と同一)。
///   - H2D が途中で失敗した場合は `CH_ATT` が**部分更新**になる。そのまま
///     抜けると呼び出し側のフォールバックがゲート済みの行をもう一度ゲートして
///     しまうので、残りのチャンクをゲートし終えてから**全体を 1 発の同期 H2D**
///     で戻す (pinned はその時点で完成形 = `CH_ATT` は従来と同じ内容になる)。
#[allow(clippy::too_many_arguments)]
fn pf_att_inplace_piped<F>(
    s: &mut ChainScratch,
    lib: &'static CudaLib,
    ctx: &'static CudaCtx,
    buf: CUdeviceptr,
    pin_ptr: *mut c_void,
    pin_id: usize,
    cols: usize,
    m: usize,
    bytes: usize,
    rows_per: usize,
    nch: usize,
    gate: &mut F,
) -> Option<()>
where
    F: FnMut(usize, &mut [f32]),
{
    let (rec, ev_sync) = (lib.event_record?, lib.event_sync?);
    let pin_base = pin_ptr as usize;
    // 1) 全チャンクの D2H を発行し、チャンクごとに完了イベントを打つ
    //    (既定 = null ストリーム。イベントはストリーム順に乗るだけ)。
    for k in 0..nch {
        let (r0, r1) = pf_att_chunk_bounds(k, rows_per, m);
        let off = r0.checked_mul(cols)?.checked_mul(4)?;
        let len = r1.checked_sub(r0)?.checked_mul(cols)?.checked_mul(4)?;
        let ev = s.pipe_ev.get(k)?.0;
        unsafe {
            ok(check(
                (lib.memcpy_dtoh_async)(
                    (pin_base + off) as *mut c_void,
                    buf + off as u64,
                    len,
                    std::ptr::null_mut(),
                ),
                "cuMemcpyDtoHAsync (pf att pin chunk)",
            ))?;
            if rec(ev, std::ptr::null_mut()) != CUDA_SUCCESS {
                // イベントを打てない = 完了を待てない。CH_ATT は未変更なので
                // 従来の 1 発経路へ戻す (呼び出し側のフォールバックも安全)。
                return None;
            }
        }
    }
    // s180 (P41): att の D2H 発行点 = full_core の区間 [d2h] の終端
    // (最後のチャンクの完了がこの位置に乗る。従来の 1 発と同じ意味)。
    fc_kprof_mark(3);
    // 2) チャンクごとに「完了待ち → ゲート → H2D」。ゲートはチャンクの完了前に
    //    触ってはいけない (未転送の領域を 0 で割る) ので、必ずイベントを待つ。
    let mut h2d_failed = false;
    for k in 0..nch {
        let (r0, r1) = pf_att_chunk_bounds(k, rows_per, m);
        let ev = s.pipe_ev.get(k)?.0;
        if unsafe { ev_sync(ev) } != CUDA_SUCCESS {
            // イベント待ちが使えない: 全ストリーム同期で代替する (安全側)。
            ok(ctx.sync())?;
        }
        {
            let pin = s.pins.get_mut(pin_id)?.as_mut()?;
            let v = pin.as_mut_slice::<f32>();
            gate(r0, &mut v[r0 * cols..r1 * cols]);
        }
        if h2d_failed {
            continue;
        }
        let off = r0 * cols * 4;
        let len = (r1 - r0) * cols * 4;
        let rc = unsafe {
            (lib.memcpy_htod_async)(
                buf + off as u64,
                (pin_base + off) as *const c_void,
                len,
                std::ptr::null_mut(),
            )
        };
        if rc != CUDA_SUCCESS {
            h2d_failed = true;
        }
    }
    if h2d_failed {
        // 全チャンクがゲート済み = pinned は完成形。部分更新のまま抜けると
        // フォールバックが二重ゲートするので、全体を 1 発で戻す。
        unsafe {
            ok(check(
                (lib.memcpy_htod)(buf, pin_ptr as *const c_void, bytes),
                "cuMemcpyHtoD (pf att gate fallback)",
            ))?;
        }
        ok(ctx.sync())?;
    }
    Some(())
}

/// s247 (P47): full_qk (q/k 射影) の D2H 宛先を返すビュー。
///
/// [`chain_qkv_prefill_q4_dev`] が D2H した先 — pinned ステージング
/// (`pin_pf_qkv` の 2 スライス)、またはフォールバック時の呼び出し側 `Vec` —
/// を q/k の 2 スライスとして見せる。**ホスト memcpy は挟まない** (pinned →
/// heap の写しはこのホストで 4.7 GB/s しか出ず、12.88 GB/request なら +2.7 s
/// の新規費用になる)。値は D2H で戻したバイト列そのもの。
///
/// **寿命の契約**: 同じスレッドで次の [`chain_qkv_prefill_q4_dev`] が走るまで
/// 有効 (`pin_h2` / `pins[]` のステージングと同じ規約)。層ループは 1 層ずつ
/// 「qkv チェーン → ホスト prepare/attend」を直列に回すので、1 層の中で使い切る
/// 限り競合しない。破ると**読む前に上書きされる**ので、デバッグビルドでは
/// 世代 (`PFQK_GEN`) の不一致で panic する。
pub struct PfQkView {
    q: *const f32,
    k: *const f32,
    q_len: usize,
    k_len: usize,
    pinned: bool,
    gen: u64,
}

impl PfQkView {
    /// q 投影出力 `[rows, qcols]` (pinned ステージング or フォールバックの Vec)。
    pub fn q(&self) -> &[f32] {
        debug_assert_eq!(
            self.gen,
            pf_qkv_gen(),
            "PfQkView が次の qkv チェーンで無効化された (寿命の契約違反)"
        );
        unsafe { std::slice::from_raw_parts(self.q, self.q_len) }
    }

    /// k 投影出力 `[rows, kcols]`。
    pub fn k(&self) -> &[f32] {
        debug_assert_eq!(
            self.gen,
            pf_qkv_gen(),
            "PfQkView が次の qkv チェーンで無効化された (寿命の契約違反)"
        );
        unsafe { std::slice::from_raw_parts(self.k, self.k_len) }
    }

    /// D2H の宛先が pinned ステージングだったか (計測・切り分け用)。
    pub fn pinned(&self) -> bool {
        self.pinned
    }
}

thread_local! {
    /// s247 (P47): `PfQkView` の世代。チェーンが走るたびに進む
    /// (古いビューの読み出しをデバッグビルドで検出するためだけのもの)。
    static PFQK_GEN: std::cell::Cell<u64> = std::cell::Cell::new(0);
}

fn pf_qkv_gen() -> u64 {
    PFQK_GEN.with(|c| c.get())
}

/// s247 (P47): full_qk の pinned ステージング (q + k) の上限バイト数。
/// 既定 1 GiB (`docs/FULL_QK_D2H_PINNED.md` §5/§6 の「プール上限 1.0 GB」)。
///
/// この上限を超える n ではプールを**1 バイトも確保せず**に従来の pageable
/// 経路へ落ちる (fail-closed)。65k (n=14,043) の q+k は 747.8 MB なので既定では
/// 収まる。256 MiB (268,435,456 B) に絞ると n ≤ 5,041 行でしか発動しない
/// (q+k = n×13,312×4 B = 53,248 B/行) — q の 1 発が 690 MB あるので、それ以上の
/// n を 256 MiB に収めるには D2H の分割が必要で、それは設計メモ §3 (3 発・同順を
/// 保つ) と両立しない。
fn pf_qkv_pin_max() -> usize {
    static MAX: OnceLock<usize> = OnceLock::new();
    *MAX.get_or_init(|| {
        std::env::var("DENNO_PF_QKV_PIN_MAX")
            .ok()
            .and_then(|v| v.parse().ok())
            .unwrap_or(1 << 30)
    })
}

/// ページロック失敗の報告は 1 回だけ (層ごとに 16 回出さない)。
static PFQK_PIN_FAILED: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

thread_local! {
    /// s247 (P47): pinned 経路が初めて効いたことを 1 回だけ報告するためのフラグ。
    static PFQK_PIN_USED: std::cell::Cell<bool> = std::cell::Cell::new(false);
}

/// s247 (P47): `DENNO_PF_QKV_PIN_DBG=1` のとき、pinned ステージングが初めて
/// 効いた層で 1 行だけ出す (cold A/B の前に「どちらの経路か」を確定させるため)。
fn pf_qkv_pin_dbg() -> bool {
    static ON: OnceLock<bool> = OnceLock::new();
    *ON.get_or_init(|| std::env::var("DENNO_PF_QKV_PIN_DBG").ok().as_deref() == Some("1"))
}

/// s250 (P53): full_qk の q の D2H を k/v の GEMM と重ねるか (純粋関数・既定 ON)。
///
/// `DENNO_PF_QK_OVERLAP=0` で従来の「既定ストリームで 3 発を直列」へ戻す
/// (cold A/B の腕)。`DENNO_PF_OVERLAP=0` は上位の全停止スイッチで、こちらも
/// OFF になる ([`pf_qk_overlap_enabled`])。
pub fn parse_pf_qk_overlap(raw: Option<&str>) -> bool {
    !matches!(raw, Some("0") | Some("false") | Some("off"))
}

/// [`parse_pf_qk_overlap`] の実効値 (env が無ければ ON)。上位の
/// `DENNO_PF_OVERLAP` が OFF ならこちらも OFF (P6 の h2 と同じ停止スイッチ)。
fn pf_qk_overlap_enabled() -> bool {
    static ON: OnceLock<bool> = OnceLock::new();
    *ON.get_or_init(|| {
        parse_pf_qk_overlap(std::env::var("DENNO_PF_QK_OVERLAP").ok().as_deref())
            && pf_overlap_flag()
    })
}

/// s250 (P53): full_qk の q の D2H を k/v の GEMM と重ねるためのコピーストリームを
/// 用意し、既定ストリームの**いまこの時点まで**の完了を待たせる。
///
/// **呼び出し位置が契約**: q の GEMM を起動した直後・k/v の GEMM を起動する前。
/// ここでイベントを打つと q の D2H は q の GEMM の完了だけを待って走り出し、
/// 後続の k/v GEMM (既定ストリーム) と重なる。記録点を k/v の起動より後ろへ
/// ずらすとイベントが 3 発全部の完了を待ち、1 バイトも重ならない。
///
/// 隠れる量 (27B・n=14,043 の 1 層):
/// - q の D2H = rows*qcols*4 = 690.2 MB。実測単価 14.3 GB/s (s68) で ≈48 ms。
/// - k/v の GEMM (各 1,024 列・0.147 TFLOP) ≈ 9.8 ms は必ず隠れる。
/// - k/v の D2H (各 57.5 MB・計 8.0 ms) は q と同じコピーエンジンに並ぶので、
///   隠れるかは実機の取り合い次第 (隠れれば上限 17.8 ms/層)。
/// したがって短くなるのは ≈9.8 ms/層 = 16 層で ≈0.16 s/request (推定・下限)。
/// 上限は ≈0.29 s/request。
///
/// 失敗はすべて `None` (フラグ OFF・driver API 欠落・stream/event 作成失敗) で、
/// **GPU_BROKEN は立てない** — 「既定ストリームで直列に流せばよい」種類の失敗。
/// 数値はどちらの経路でも同一: 同じバイト列を同じ宛先へ戻し、変わるのは
/// 「どのストリームで発行するか」だけ (カーネル・引数・宛先・発行順は不変)。
fn pf_qk_copy_begin() -> Option<CUstream> {
    let _ctx = chain_ctx()?;
    if !pf_qk_overlap_enabled() {
        return None;
    }
    let lib = lib().ok()?;
    let (stream_create, event_create, event_record, stream_wait_event) = (
        lib.stream_create?,
        lib.event_create?,
        lib.event_record?,
        lib.stream_wait_event?,
    );
    CHAIN.with(|cell| -> Option<CUstream> {
        let mut s = cell.borrow_mut();
        if s.qk_stream.is_none() {
            // 非ブロッキング必須: legacy (既定) ストリームは blocking ストリームと
            // 暗黙に同期するため、blocking で作ると GEMM がコピー完了を待つ。
            const CU_STREAM_NON_BLOCKING: u32 = 0x01;
            const CU_EVENT_DISABLE_TIMING: u32 = 0x02;
            let mut st: CUstream = std::ptr::null_mut();
            if unsafe { stream_create(&mut st, CU_STREAM_NON_BLOCKING) } != CUDA_SUCCESS {
                return None;
            }
            let st = CopyStream(st);
            let mut ev: CUevent = std::ptr::null_mut();
            if unsafe { event_create(&mut ev, CU_EVENT_DISABLE_TIMING) } != CUDA_SUCCESS {
                return None;
            }
            s.qk_stream = Some(st);
            s.qk_ev_q = Some(CopyEvent(ev));
        }
        let st = s.qk_stream.as_ref()?.0;
        let ev = s.qk_ev_q.as_ref()?.0;
        // 既定ストリーム (null) に「ここまで」を打ち、コピーストリームを参加させる。
        if unsafe { event_record(ev, std::ptr::null_mut()) } != CUDA_SUCCESS {
            return None;
        }
        if unsafe { stream_wait_event(st, ev, 0) } != CUDA_SUCCESS {
            return None;
        }
        Some(st)
    })
}

/// s165 (P2): full attention 層の q/k/v 投影を**デバイス常駐の入力** (`CH_PFH`,
/// rmsnorm 出力・先頭から `rows` 行) から回し、**出力だけ**をホストへ戻す。
/// KV キャッシュはホストが正で q/k/v の値はホストの prepare が要るので、
/// 値は必ず戻す (戻す量は q/k/v の幅で、h2 の H2D 3 回より小さい)。
/// 3 本の GEMM は `CH_QKV` の連続領域 (q|k|v) に行オフセットで書き、
/// D2H 3 発 + sync 1 回で落とす。
/// カーネル・grid・引数は per-op 経路と同一 (行ごとに独立 → bit 一致)。
///
/// s247 (P47): D2H の宛先 (q/k) を **pinned ステージング** (`pin_pf_qkv`) にし、
/// 戻り値の [`PfQkView`] でそのスライスをそのまま呼び出し側へ渡す。
/// 発行回数 (3 発)・発行順 (q → k → v)・転送バイト数・`ctx.sync()` 1 回は従来と
/// 同一で、変わるのは「同じバイト列をどこへ置くか」だけ = 数値は不変。
/// v の宛先は従来どおり呼び出し側のバッファ (s240/P44: ホスト KV キャッシュの行
/// そのもの = prepare が v を 1 バイトも触らない)。pinned を確保できないときは
/// 呼び出し側の `Vec` へ直接 D2H する従来経路に落ちる (fail-closed・数値不変)。
pub fn chain_qkv_prefill_q4_dev(
    q_w: &crate::quant::Linear,
    k_w: &crate::quant::Linear,
    v_w: &crate::quant::Linear,
    rows: usize,
    li: usize,
    // s247 (P47): q/k の D2H 宛先。pinned ステージングを確保できた層では
    // **読まれない** (pageable フォールバックの宛先としてだけ使い、そのときだけ
    // 長さを合わせる) — pinned が効く層で 747 MB の mmap をしないため。
    out_qg: &mut Vec<f32>,
    out_k: &mut Vec<f32>,
    out_v: &mut [f32],
) -> Option<PfQkView> {
    if !cuda_enabled() || !gemm_enabled() || GPU_BROKEN.load(std::sync::atomic::Ordering::Relaxed) {
        return None;
    }
    let (qn, qcols) = q4_dims(q_w)?;
    let (kn, kcols) = q4_dims(k_w)?;
    let (vn, vcols) = q4_dims(v_w)?;
    if qn != kn || qn != vn || qn == 0 || qn % 32 != 0 {
        return None;
    }
    if qcols % 32 != 0 || kcols % 32 != 0 || vcols % 32 != 0 {
        return None;
    }
    if rows < gemm_min_m() || rows <= max_m() {
        return None;
    }
    if out_v.len() < rows * vcols {
        return None;
    }
    let ctx = chain_ctx()?;
    let (q_uid, q_blk, _, _) = q4_parts(q_w)?;
    let (k_uid, k_blk, _, _) = q4_parts(k_w)?;
    let (v_uid, v_blk, _, _) = q4_parts(v_w)?;
    let gwq = weights_for_q4(q_uid, q_blk, qn, qcols).ok()?;
    let gwk = weights_for_q4(k_uid, k_blk, kn, kcols).ok()?;
    let gwv = weights_for_q4(v_uid, v_blk, vn, vcols).ok()?;
    let total = rows.checked_mul(qcols.checked_add(kcols)?.checked_add(vcols)?)?;
    ok(chain_ensure_buf(CH_QKV, total.checked_mul(4)?))?;
    // 入力は CH_PFH の先頭 rows 行 (rmsnorm 出力) — 行数ぶんの領域を要求
    ok(chain_ensure_buf(CH_PFH, rows.checked_mul(qn)?.checked_mul(4)?))?;
    let (pin, pqkv) = CHAIN.with(|cell| -> Option<(u64, u64)> {
        let s = cell.borrow();
        Some((s.bufs[CH_PFH].as_ref()?.ptr(), s.bufs[CH_QKV].as_ref()?.ptr()))
    })?;
    let q_off = (rows * qcols * 4) as u64;
    let k_off = (rows * (qcols + kcols) * 4) as u64;
    // s169 (P8): qkv GEMM + 3 発の D2H + 既存の sync までが full_qk の区間。
    pf_phase(PF_PH_FULL_QK);
    // s250 (P53): q の D2H を発行するストリーム。作れなければ null のまま =
    // 従来どおり既定ストリームで 3 発を直列に流す (数値は同一)。
    let mut q_stream: CUstream = std::ptr::null_mut();
    crate::prof::time_layer(crate::prof::QKV, li, || -> Option<()> {
        chain_gemm_q4_pf(gwq, pin, pqkv, rows, qn, qcols)?;
        // s250 (P53): q の GEMM 完了をここで打ち、コピーストリームを参加させる。
        // k/v の GEMM は既定ストリームでこの後ろに続くので、q の D2H
        // (rows*qcols*4 B) がその後ろに隠れる。記録点を k/v の起動より後にすると
        // イベントが 3 発全部の完了を待ち、1 バイトも重ならない。
        q_stream = pf_qk_copy_begin().unwrap_or(std::ptr::null_mut());
        chain_gemm_q4_pf(gwk, pin, pqkv + q_off, rows, kn, kcols)?;
        chain_gemm_q4_pf(gwv, pin, pqkv + k_off, rows, vn, vcols)
    })?;
    // ---- s247 (P47): D2H の宛先 (q/k) を pinned ステージングにする ----
    // プールは 1 本 (`pin_pf_qkv`) を q/k の 2 スライスに割り、grow-only で層を
    // またいで使い回す (ページロックは最初の full 層の 1 回だけ)。上限超過・
    // ページロック失敗は従来の pageable 経路へ落ちる (fail-closed)。
    let q_elems = rows.checked_mul(qcols)?;
    let k_elems = rows.checked_mul(kcols)?;
    let q_bytes = q_elems.checked_mul(4)?;
    let k_bytes = k_elems.checked_mul(4)?;
    let stage_bytes = q_bytes.checked_add(k_bytes)?;
    let mut dst_q: *mut c_void = std::ptr::null_mut();
    let mut dst_k: *mut c_void = std::ptr::null_mut();
    let mut pinned = false;
    if stage_bytes <= pf_qkv_pin_max() {
        CHAIN.with(|cell| {
            let mut s = cell.borrow_mut();
            if Scratch::ensure_pin(&mut s.pin_pf_qkv, stage_bytes).is_err() {
                // pinned の失敗は致命的でない (`pin_h2` と同じ扱い = GPU_BROKEN を
                // 立てない)。理由だけ 1 回出す。
                if !PFQK_PIN_FAILED.swap(true, std::sync::atomic::Ordering::Relaxed) {
                    eprintln!(
                        "full_qk pinned staging: cuMemHostAlloc({stage_bytes} B) に失敗 → pageable 経路"
                    );
                }
                return;
            }
            if let Some(p) = s.pin_pf_qkv.as_ref() {
                if p.bytes >= stage_bytes {
                    dst_q = p.ptr;
                    // q と k は同じプールの連続した 2 スライス (q_off=0, k_off=q_bytes)
                    dst_k = unsafe { (p.ptr as *mut u8).add(q_bytes) as *mut c_void };
                    pinned = true;
                }
            }
        });
        if pinned && pf_qkv_pin_dbg() && !PFQK_PIN_USED.with(|c| c.replace(true)) {
            eprintln!(
                "full_qk pinned staging: {stage_bytes} B (q {q_bytes} + k {k_bytes}, n={rows}) — D2H 宛先 = pinned"
            );
        }
    }
    if !pinned {
        // フォールバック = 現行経路そのもの (呼び出し側の Vec へ直接 D2H)。
        // 長さはここで合わせる: pinned が効く層では 747 MB の確保をしない。
        if out_qg.len() < q_elems {
            out_qg.clear();
            out_qg.resize(q_elems, 0.0);
        }
        if out_k.len() < k_elems {
            out_k.clear();
            out_k.resize(k_elems, 0.0);
        }
        dst_q = out_qg.as_mut_ptr() as *mut c_void;
        dst_k = out_k.as_mut_ptr() as *mut c_void;
    }
    // D2H 3 発 (async) → sync 1 回 — 発行回数・発行順は従来と同一 (連結しない)
    CHAIN.with(|cell| -> Option<()> {
        let s = cell.borrow();
        let base = s.bufs[CH_QKV].as_ref()?.ptr();
        let lib = lib().ok()?;
        unsafe {
            ok(check(
                (lib.memcpy_dtoh_async)(dst_q, base, q_bytes, q_stream),
                "cuMemcpyDtoHAsync (pf qkv q)",
            ))?;
            ok(check(
                (lib.memcpy_dtoh_async)(
                    dst_k,
                    base + q_off,
                    k_bytes,
                    std::ptr::null_mut(),
                ),
                "cuMemcpyDtoHAsync (pf qkv k)",
            ))?;
            ok(check(
                (lib.memcpy_dtoh_async)(
                    out_v.as_mut_ptr() as *mut c_void,
                    base + k_off,
                    rows * vcols * 4,
                    std::ptr::null_mut(),
                ),
                "cuMemcpyDtoHAsync (pf qkv v)",
            ))
        }
    })?;
    crate::prof::mark_d2h_src(crate::prof::D2H_SRC_LINEAR);
    ok(ctx.sync())?;
    // ここまでで D2H は完了している (sync 1 回)。ビューの世代を進めて
    // 前のビューを無効化する。
    let gen = PFQK_GEN.with(|c| {
        let g = c.get().wrapping_add(1);
        c.set(g);
        g
    });
    Some(PfQkView {
        q: dst_q as *const f32,
        k: dst_k as *const f32,
        q_len: q_elems,
        k_len: k_elems,
        pinned,
        gen,
    })
}

/// s165 (P2): attention 出力 (`CH_ATT`) → o_proj (q4) → `CH_O` (デバイス常駐・
/// 同期なし)。per-op 経路 (`maybe_gpu_linear_q4_into`) と同一カーネル・同一引数。
/// m を 1 回で渡すのは、行ごとに独立で 1 行の i32 累積順が変わらないため
/// (`chain_gdn_prefill_q4` の o_proj と同じ根拠)。
pub fn chain_oproj_prefill_q4(o_w: &crate::quant::Linear, rows: usize, li: usize) -> Option<()> {
    let ow = match o_w {
        crate::quant::Linear::Q4(q) => q,
        _ => return None,
    };
    if !cuda_enabled() || !gemm_enabled() || GPU_BROKEN.load(std::sync::atomic::Ordering::Relaxed) {
        return None;
    }
    if rows < gemm_min_m() || rows <= max_m() || ow.k == 0 || ow.n == 0 || ow.k % 32 != 0 {
        return None;
    }
    let ctx = chain_ctx()?;
    let gw = weights_for_q4(ow.uid, &ow.blocks, ow.k, ow.n).ok()?;
    let out_bytes = rows.checked_mul(ow.n)?.checked_mul(4)?;
    let att_bytes = rows.checked_mul(ow.k)?.checked_mul(4)?;
    ok(chain_ensure_buf(CH_O, out_bytes))?;
    let (pa, po) = CHAIN.with(|cell| -> Option<(u64, u64)> {
        let s = cell.borrow();
        let a = s.bufs[CH_ATT].as_ref()?;
        if a.bytes() < att_bytes {
            return None;
        }
        Some((a.ptr(), s.bufs[CH_O].as_ref()?.ptr()))
    })?;
    let _ = ctx;
    // s169 (P8): att の H2D は呼び出し側、ここは o_proj GEMM だけの区間。
    pf_phase(PF_PH_FULL_OPROJ);
    crate::prof::time_layer(crate::prof::OPROJ, li, || chain_gemm_q4_pf(gw, pa, po, rows, ow.k, ow.n))
}

/// chunked scan の入力 4 本 (qkv / z / beta / alpha) の出所。
///
/// s164 (P1): 従来は必ずホスト slice で、`GDN_SCRATCH` へ H2D してから
/// カーネルへ渡していた。`Dev` は「既にデバイスに居る」場合にそのポインタを
/// そのまま使う — カーネルの引数・grid・演算列は 1 つも変わらず、消えるのは
/// 転送だけ (q4 prefill チェーン `chain_gdn_prefill_q4` が使う)。
#[derive(Clone, Copy)]
enum GdnScanSrc<'a> {
    Host {
        qkv: &'a [f32],
        z: &'a [f32],
        beta: &'a [f32],
        alpha: &'a [f32],
    },
    Dev {
        qkv: CUdeviceptr,
        z: CUdeviceptr,
        beta: CUdeviceptr,
        alpha: CUdeviceptr,
    },
}

// ---------------------------------------------------------------------------
// s240 (P40): GDN chunked 3 カーネルの実時間 (`DENNO_GDN_KPROF=1`・既定 OFF)
//
// 背景: 27B q4 prefill の `sl_lay_gdn_scan` 相は 6,965 ms (19.4%) だが、
// `DENNO_PROFILE` の `gdn_pf_*` では `sync` (13,774.9 ms / 2 リクエスト) まで
// しか割れず、「pass 1/2/3 のどれが実行時間を持っているか」は未計測だった。
// ここでは 3 pass の発行位置にだけイベントを打ち、既存の同期 (3 pass 後の
// 1 回・`cuda.rs` の `ctx.sync()`) が済んだ直後に `cuEventElapsedTime` で
// 3 区間を読む。
//
// s240 (P43): 出力点は **prefill 終了時** (`pf_timing_read`) が本線。
// P40 は dump (`prof::summary`) とスレッド終了フックにしか出しておらず、
// `scripts/prod_serve_27b.sh` が `unset DENNO_PROFILE` する本番構成では
// そのどちらも走らないため、計測できていても 1 行も見えなかった。
// 行には `miss=<n>` (捨てた call 数) を必ず出し、env ON なら
// calls=0 でも行が出る (静かな no-op を構造的に禁止)。
//
// 数値経路を触らない根拠:
// - 追加するのは `cuEventRecord` / `cuEventElapsedTime` の 2 API だけで、
//   launch の関数・引数・grid/block・発行順・同期の位置は 1 つも変えない
//   (イベントは 3 カーネルと同じ既定ストリームに打つので、ストリームに
//    挿入されるのは「時刻を記録するだけの操作」)。
// - 積算は表示専用の static にしか書かない (forward の戻り値・状態・
//   アンカー値には一切流れない)。
// - `DENNO_GDN_KPROF` が未設定なら `kprof_begin()` が None を返すだけで、
//   イベント生成も計測も起きない (各サイト分岐 1 回)。`DENNO_PROFILE` /
//   `DENNO_PF_DBG` の出力は env 未設定時に 1 バイトも変わらない。
// - 区間の意味は「カーネル実行 + 前のカーネルとの発行の隙間」。pass 間で
//   ホストが待たないので隙間は小さいが 0 ではない (数字はそのまま出す)。
// ---------------------------------------------------------------------------

/// `DENNO_GDN_KPROF=1` のときだけ 3 カーネルの実時間を測る (既定 OFF)。
fn gdn_kprof_on() -> bool {
    // テストから env を介さずに切り替える (`prof::enabled` と同じ流儀)。
    #[cfg(test)]
    if let Some(v) = kprof_tests::force_on() {
        return v;
    }
    static ON: OnceLock<bool> = OnceLock::new();
    *ON.get_or_init(|| std::env::var("DENNO_GDN_KPROF").ok().as_deref() == Some("1"))
}

/// カーネル別の積算 (ns) と call 数。**表示専用** (数値経路からは読まない)。
static KPROF_PRE_NS: AtomicU64 = AtomicU64::new(0);
static KPROF_STATE_NS: AtomicU64 = AtomicU64::new(0);
static KPROF_SCAN_NS: AtomicU64 = AtomicU64::new(0);
/// 3 区間すべて読めた call 数。
static KPROF_CALLS: AtomicU64 = AtomicU64::new(0);
/// 区間を読めなかった (未完了・負値・イベント欠け) call 数。半端な数字は積まない。
static KPROF_MISS: AtomicU64 = AtomicU64::new(0);

/// 積算の読み出し結果 (整形・テスト用の値型)。
#[derive(Clone, Copy, Default, Debug, PartialEq, Eq)]
pub(crate) struct KprofAcc {
    pub pre_ns: u64,
    pub state_ns: u64,
    pub scan_ns: u64,
    pub calls: u64,
    /// 区間を読めずに捨てた call 数 (未完了・負値・イベント欠け・イベント生成失敗)。
    pub miss: u64,
}

impl KprofAcc {
    /// 表示行 (`calls == 0 && miss == 0` なら None = 行を出さない)。
    /// 捨てた call があるときは calls=0 でも行を出す — 黙って消えると
    /// 「測れていない」ことが見えなくなるため (P43)。
    fn line(&self) -> Option<String> {
        if self.calls == 0 && self.miss == 0 {
            return None;
        }
        Some(self.render())
    }

    /// 行そのもの。pre/state/scan = 3 カーネルの積算 ms、calls = 3 区間すべて
    /// 読めた call 数、miss = 捨てた call 数、total = 3 区間の和。
    fn render(&self) -> String {
        let ms = |ns: u64| ns as f64 / 1e6;
        format!(
            "[GDN_KPROF] pre={:.3} state={:.3} scan={:.3} calls={} miss={} total={:.3}",
            ms(self.pre_ns),
            ms(self.state_ns),
            ms(self.scan_ns),
            self.calls,
            self.miss,
            ms(self.pre_ns + self.state_ns + self.scan_ns)
        )
    }
}

/// 積算を読む。
fn kprof_acc() -> KprofAcc {
    KprofAcc {
        pre_ns: KPROF_PRE_NS.load(Ordering::Relaxed),
        state_ns: KPROF_STATE_NS.load(Ordering::Relaxed),
        scan_ns: KPROF_SCAN_NS.load(Ordering::Relaxed),
        calls: KPROF_CALLS.load(Ordering::Relaxed),
        miss: KPROF_MISS.load(Ordering::Relaxed),
    }
}

/// 3 区間 (ms) を積算する。`KprofCall::finish` の算術だけを切り出したもの
/// (GPU 無しで試せるようにするため)。
fn kprof_add_ms(pre_ms: f32, state_ms: f32, scan_ms: f32) {
    let ns = |x: f32| (x as f64 * 1e6).round() as u64;
    KPROF_PRE_NS.fetch_add(ns(pre_ms), Ordering::Relaxed);
    KPROF_STATE_NS.fetch_add(ns(state_ms), Ordering::Relaxed);
    KPROF_SCAN_NS.fetch_add(ns(scan_ms), Ordering::Relaxed);
    KPROF_CALLS.fetch_add(1, Ordering::Relaxed);
}

/// 積算の表示行 (`DENNO_GDN_KPROF` 未設定・未計測なら None)。
/// dump (`prof::summary`) と終了時の 1 行がこれを使う。
pub fn gdn_kprof_line() -> Option<String> {
    if !gdn_kprof_on() {
        return None;
    }
    kprof_acc().line()
}

/// 区間を読めずに捨てた call 数 (診断用。表示行には入れない)。
pub fn gdn_kprof_miss() -> u64 {
    KPROF_MISS.load(Ordering::Relaxed)
}

/// 積算を stderr へ 1 行だけ出す (未設定・未計測なら何もしない)。
pub fn gdn_kprof_report() {
    if let Some(l) = gdn_kprof_line() {
        eprintln!("{l}");
    }
}

/// prefill 終了時の 1 行 (s240/P43)。**サーバ経路の唯一の観測点**。
///
/// P40 は dump (`prof::summary()`) と終了フックにしか行を出していなかったため、
/// `scripts/prod_serve_27b.sh` が `unset DENNO_PROFILE` する本番構成では
/// `prof::enabled()` が偽 → `prof::summary()` が呼ばれず、ワーカースレッドも
/// 終了しないので **1 行も出なかった** (計測できていても見えない)。
/// ここは `pf_timing_read()` (prefill 末尾・最終行 D2H の後) から呼ぶ:
/// 読むのは表示専用の static だけなので**同期は 1 つも足さない**。
///
/// dump 経路 (`DENNO_PROFILE`) が生きているときは `prof::summary()` が同じ行を
/// 出すので、ここでは出さない (二重行の回避)。`DENNO_GDN_KPROF` 未設定なら
/// 先頭の分岐 1 回で戻る (イベント生成も出力も無し)。
pub fn gdn_kprof_report_at_prefill_end() {
    if !gdn_kprof_on() {
        return;
    }
    if let Some(l) = kprof_prefill_line(&kprof_acc(), crate::prof::enabled()) {
        eprintln!("{l}");
    }
}

/// prefill 終了時に出す行を決める (整形・テスト用の純関数)。
///
/// - dump 経路が生きている → None (summary 側が同じ行を出す)
/// - それ以外 → **必ず** 1 行 (`calls == 0 && miss == 0` でも出す)。
///   env ON なのに走査サイトへ 1 度も入らなかった場合、`calls=0 miss=0` の行が
///   出るので「静かに何も出ない」が構造的に起こらない (P43 の要件)。
fn kprof_prefill_line(acc: &KprofAcc, dump_path_live: bool) -> Option<String> {
    if dump_path_live {
        return None;
    }
    Some(acc.render())
}

/// 終了フック: 計測を開いたスレッドが終わるときに 1 行だけ出す (dump 経路
/// (`DENNO_PROFILE`) を通らない使い方のための保険)。読むのは static の積算だけ
/// なので CUDA は呼ばない = コンテキスト破棄後でも安全。
struct KprofExitGuard;

impl Drop for KprofExitGuard {
    fn drop(&mut self) {
        gdn_kprof_report();
    }
}

thread_local! {
    /// 計測を開いたスレッドに 1 個だけ置く (env OFF なら作られない)。
    static KPROF_EXIT_GUARD: KprofExitGuard = KprofExitGuard;
}

/// 終了フックを置く (初回だけ)。計測していないスレッドには作らない。
fn kprof_arm_exit_guard() {
    KPROF_EXIT_GUARD.with(|_| ());
}

/// 4 本のイベント (e0=開始 / e1=pass1 後 / e2=pass2 後 / e3=pass3 後)。
/// CUevent は `*mut c_void` (Send でない) ので static に置くためのラッパを挟む。
/// ハンドルは不変で、触るのは record / elapsed_time だけ。
struct KprofEvents([CUevent; 4]);

// SAFETY: 保持するのは CUDA の不透明ハンドルだけで、アクセスは下の Mutex で
// 直列化する (実際には multi-slot 同時実行は無いが、念のため排他する)。
unsafe impl Send for KprofEvents {}

/// イベントの置き場 (初回だけ生成・grow しない)。作れなければ None = 計測しない。
static KPROF_EV: OnceLock<Option<std::sync::Mutex<KprofEvents>>> = OnceLock::new();

fn kprof_events() -> Option<&'static std::sync::Mutex<KprofEvents>> {
    KPROF_EV
        .get_or_init(|| {
            let create = lib().ok()?.event_create?;
            let mut evs: [CUevent; 4] = [std::ptr::null_mut(); 4];
            for slot in evs.iter_mut() {
                let mut ev: CUevent = std::ptr::null_mut();
                // CU_EVENT_DEFAULT (0) = 計時有効。作れなければ計測を諦める
                // (fail closed。途中まで作った分はプロセス終了まで保持する)。
                if unsafe { create(&mut ev, 0) } != CUDA_SUCCESS || ev.is_null() {
                    return None;
                }
                *slot = ev;
            }
            Some(std::sync::Mutex::new(KprofEvents(evs)))
        })
        .as_ref()
}

/// 1 call 分の計測ハンドル (イベントを排他で握る)。
struct KprofCall {
    lock: std::sync::MutexGuard<'static, KprofEvents>,
    /// 打てたイベントのビット (bit i = e_i)。4 本そろわなければ積算しない。
    marks: u32,
}

impl KprofCall {
    /// 既定ストリームに境界イベントを 1 本打つ (`idx` 0..=3)。
    fn mark(&mut self, idx: usize) {
        let Some(rec) = lib().ok().and_then(|l| l.event_record) else {
            return;
        };
        if unsafe { rec((self.lock.0)[idx], std::ptr::null_mut()) } == CUDA_SUCCESS {
            self.marks |= 1 << idx;
        }
    }

    /// 既存の同期が済んだ後に 3 区間を読んで積算する。
    fn finish(self) {
        let Some(elapsed) = lib().ok().and_then(|l| l.event_elapsed_time) else {
            KPROF_MISS.fetch_add(1, Ordering::Relaxed);
            return;
        };
        if self.marks != 0b1111 {
            // 4 本そろっていない = 区間の意味が無い。半端な数字は積まない。
            KPROF_MISS.fetch_add(1, Ordering::Relaxed);
            return;
        }
        let e = &self.lock.0;
        let mut ms = [0f32; 3];
        for k in 0..3 {
            let mut v: f32 = 0.0;
            let rc = unsafe { elapsed(&mut v, e[k], e[k + 1]) };
            // 未完了 (NOT_READY)・非有限・負値は「読めなかった」としてこの
            // call を丸ごと捨てる (半端な数字を積むと以後の判断が全部その
            // 数字に引きずられる)。
            if rc != CUDA_SUCCESS || !v.is_finite() || v < 0.0 {
                KPROF_MISS.fetch_add(1, Ordering::Relaxed);
                return;
            }
            ms[k] = v;
        }
        kprof_add_ms(ms[0], ms[1], ms[2]);
    }
}

// s245 (P45): 3 pass 後の `ctx.sync()` をデバイス出力経路から外したため、区間の
// 読み出しを「次の既存の同期」まで遅らせる。その置き場 (スレッドごと)。
//
// `KprofCall` はイベントプールの排他 (`MutexGuard`) を握っているので保留中も
// そのまま保持する — 途中で手放すと他スレッドが同じ 4 本を上書きして区間が壊れる。
// 読むのは必ず「既存の同期が済んだ後」(次の層の `kprof_begin` / prefill 末尾の
// `pf_timing_read`) だけで、そこでも未完了なら `finish` が miss に数える (P43)。
thread_local! {
    static KPROF_PENDING: std::cell::RefCell<Option<KprofCall>> =
        std::cell::RefCell::new(None);
}

/// 1 call 分の区間を「次の既存の同期」まで保留する (P45)。
fn kprof_defer(k: KprofCall) {
    // 前の call が残っていれば先に読む (取りこぼさない)。通常は `kprof_begin` が
    // 読んでいるのでここは空。
    kprof_read_pending();
    KPROF_PENDING.with(|c| *c.borrow_mut() = Some(k));
}

/// 保留した区間を今の時点で読む (**既存の同期が済んだ後**でのみ呼ぶ)。
/// 同期・launch・イベント生成はしない (読むだけ)。env OFF なら分岐 1 回で戻る。
fn kprof_read_pending() {
    if !gdn_kprof_on() {
        return;
    }
    let k = KPROF_PENDING.with(|c| c.borrow_mut().take());
    if let Some(k) = k {
        k.finish();
    }
}

/// 計測を開く。`DENNO_GDN_KPROF` 未設定なら分岐 1 回で None (イベントも作らない)。
fn kprof_begin() -> Option<KprofCall> {
    if !gdn_kprof_on() {
        return None;
    }
    // s245 (P45): 前の層で保留した区間をここで読む (この時点では次の層の h2 join /
    // 同期 D2H が済んでいる)。読めなければ miss。
    kprof_read_pending();
    let Some(ev) = kprof_events() else {
        // env ON なのにイベントを作れない = 計測不能。黙って 0 行にせず miss に
        // 数える (表示行に miss=<n> が出るので「静かに no-op」にならない)。
        KPROF_MISS.fetch_add(1, Ordering::Relaxed);
        return None;
    };
    kprof_arm_exit_guard();
    // poison しても中身はハンドルだけなので続ける。
    let lock = ev.lock().unwrap_or_else(|e| e.into_inner());
    Some(KprofCall { lock, marks: 0 })
}

/// `kprof_begin()` の結果に 1 本打つ (計測していなければ分岐 1 回で何もしない)。
#[inline]
fn kprof_mark(kp: &mut Option<KprofCall>, idx: usize) {
    if let Some(k) = kp.as_mut() {
        k.mark(idx);
    }
}

#[cfg(test)]
mod kprof_tests {
    //! s240 (P40): 計測コードが「既定で no-op」「ON でカーネル別に積算される」
    //! ことの GPU 不要な検証。実測はオペレータの GPU 実行で行う (ここでは
    //! `cuEventCreate` すら呼ばない = イベント生成が env 依存であることも見る)。
    use super::*;

    /// テスト専用の env 上書き (env を書き換えると並走テストを揺らすため)。
    static FORCE_ON: std::sync::Mutex<Option<bool>> = std::sync::Mutex::new(None);

    pub(super) fn force_on() -> Option<bool> {
        *FORCE_ON.lock().unwrap_or_else(|e| e.into_inner())
    }

    /// 強制の窓 (drop で元に戻す)。assert が落ちても他テストを汚さない。
    struct Force(Option<bool>);

    impl Force {
        fn set(v: Option<bool>) -> Self {
            let prev = *FORCE_ON.lock().unwrap_or_else(|e| e.into_inner());
            *FORCE_ON.lock().unwrap_or_else(|e| e.into_inner()) = v;
            Force(prev)
        }
    }

    impl Drop for Force {
        fn drop(&mut self) {
            *FORCE_ON.lock().unwrap_or_else(|e| e.into_inner()) = self.0;
        }
    }

    fn reset_acc() {
        KPROF_PRE_NS.store(0, Ordering::Relaxed);
        KPROF_STATE_NS.store(0, Ordering::Relaxed);
        KPROF_SCAN_NS.store(0, Ordering::Relaxed);
        KPROF_CALLS.store(0, Ordering::Relaxed);
        KPROF_MISS.store(0, Ordering::Relaxed);
    }

    /// env 未設定 (強制 OFF) では計測の入口が no-op であること。
    #[test]
    fn kprof_off_is_noop() {
        let _g = crate::prof::counters_guard();
        let _f = Force::set(Some(false));
        assert!(!gdn_kprof_on());
        assert!(kprof_begin().is_none(), "OFF ではイベントを作らない");
        assert!(gdn_kprof_line().is_none(), "OFF では行を出さない");
    }

    /// s245 (P45): 保留読みは env OFF で完全な no-op (本番経路に CUDA 呼び出しを
    /// 足さない)。
    #[test]
    fn kprof_read_pending_is_noop_when_off() {
        let _g = crate::prof::counters_guard();
        let _f = Force::set(Some(false));
        reset_acc();
        kprof_read_pending();
        assert_eq!(
            (kprof_acc().calls, kprof_acc().miss),
            (0, 0),
            "OFF なのに保留読みが積算 / miss を動かした"
        );
    }

    /// ON のとき、積算がカーネル別に初期化され、表示行が仕様どおりになること。
    #[test]
    fn kprof_on_accumulates_per_kernel() {
        let _g = crate::prof::counters_guard();
        let _f = Force::set(Some(true));
        reset_acc();
        assert!(gdn_kprof_line().is_none(), "未計測 (calls=0 miss=0) は行を出さない");
        kprof_add_ms(1.5, 0.25, 2.0);
        kprof_add_ms(0.5, 0.75, 1.0);
        let acc = kprof_acc();
        assert_eq!(
            (acc.pre_ns, acc.state_ns, acc.scan_ns, acc.calls),
            (2_000_000, 1_000_000, 3_000_000, 2),
            "カーネル別に ns で積算されない"
        );
        assert_eq!(
            gdn_kprof_line().as_deref(),
            Some("[GDN_KPROF] pre=2.000 state=1.000 scan=3.000 calls=2 miss=0 total=6.000")
        );
        assert_eq!(gdn_kprof_miss(), 0, "成功した call を miss に数えている");
        reset_acc();
    }

    /// 表示行の書式 (ms 3 桁・calls・miss・total = 3 区間の和)。GPU 不要。
    #[test]
    fn kprof_line_format_is_stable() {
        let acc = KprofAcc {
            pre_ns: 1_234_567_000,
            state_ns: 2_500_000,
            scan_ns: 3_000_000,
            calls: 7,
            miss: 0,
        };
        assert_eq!(
            acc.line().as_deref(),
            Some("[GDN_KPROF] pre=1234.567 state=2.500 scan=3.000 calls=7 miss=0 total=1240.067")
        );
        assert!(
            KprofAcc::default().line().is_none(),
            "未計測の既定値が行を出している"
        );
    }

    /// `miss=` の書式と「calls=0 でも捨てた call があれば行を出す」こと。
    /// これが P43 の本題 (実機で 1 行も出なかった = 静かな no-op の再発防止)。
    #[test]
    fn kprof_miss_is_printed_even_with_zero_calls() {
        let _g = crate::prof::counters_guard();
        let _f = Force::set(Some(true));
        reset_acc();
        // 全部捨てた状態: 行は出るが calls=0 / miss=n。
        KPROF_MISS.store(16, Ordering::Relaxed);
        assert_eq!(
            gdn_kprof_line().as_deref(),
            Some("[GDN_KPROF] pre=0.000 state=0.000 scan=0.000 calls=0 miss=16 total=0.000"),
            "捨てた call があるのに黙っている (miss= が効いていない)"
        );
        // 一部だけ読めた状態: calls と miss が併記される。
        kprof_add_ms(2.0, 1.0, 3.0);
        assert_eq!(
            gdn_kprof_line().as_deref(),
            Some("[GDN_KPROF] pre=2.000 state=1.000 scan=3.000 calls=1 miss=16 total=6.000")
        );
        reset_acc();
    }

    /// prefill 終了時の 1 行 (サーバ経路の観測点) の判定。
    /// - dump 経路 (`DENNO_PROFILE`) が生きている → 出さない (summary と二重にしない)
    /// - それ以外 → **未計測でも必ず出す** (静かに何も出ないを構造的に禁止)
    #[test]
    fn kprof_prefill_end_line_is_always_emitted_without_dump_path() {
        let measured = KprofAcc {
            pre_ns: 3_000_000,
            state_ns: 1_000_000,
            scan_ns: 2_000_000,
            calls: 4,
            miss: 1,
        };
        assert_eq!(
            kprof_prefill_line(&measured, false).as_deref(),
            Some("[GDN_KPROF] pre=3.000 state=1.000 scan=2.000 calls=4 miss=1 total=6.000")
        );
        assert!(
            kprof_prefill_line(&measured, true).is_none(),
            "dump 経路が生きているのに prefill 側でも出している (二重行)"
        );
        // 走査サイトに 1 度も入らなかった場合でも行は出る (calls=0 miss=0)。
        assert_eq!(
            kprof_prefill_line(&KprofAcc::default(), false).as_deref(),
            Some("[GDN_KPROF] pre=0.000 state=0.000 scan=0.000 calls=0 miss=0 total=0.000"),
            "env ON なのに 1 行も出ない経路が残っている"
        );
    }
}

/// A1-r2: GDN chunked scan 実装 (3 カーネル・長 prefill 用)。
///
/// CPU 参照: [`crate::gdn::scan_chunked_core`]。3-pass 構成:
/// - K1 `dno_gdn_chunk_pre` (chunk 並列): ローカル遷移 W[ci]・M[ci]
/// - K2 `dno_gdn_chunk_state` (chunk 直列): chunk 先頭状態 Sinit の直列伝播
/// - K3 `dno_gdn_chunk_scan` (chunk 並列): Sinit からの逐次 AR スキャン → y・
///   最終状態 (最終 chunk ブロックが書き戻す)
///
/// 決定論: 各カーネルとも launch 構成固定・昇順逐次和・atomic/ワープ縮約不使用
/// (gdn.cu の方針どおり)。演算は単発カーネル `dno_gdn_scan` と同一で、chunk
/// 境界でのみ状態を持ち越す。前提: dk == dv・d_conv == 4 (呼び出し側で保証)。
///
/// s173 (P15): **pass 間でホストを止めない**。3 pass はすべて既定ストリームへ
/// 発行するので、pass 2 が pass 1 の W/M を読み、pass 3 が pass 2 の Sinit を
/// 読む順序はストリームが保証する (同一ストリーム上の発行は FIFO 実行)。
/// s245 (P45): 同期点は「ホストが結果を読む経路」だけにした:
/// - デバイス出力 (`y_dst = Some`・prefill 残差常駐): **待たない**。y は後続の
///   o_proj が同じストリームで読み、状態の D2D 書き戻しも同じストリームなので
///   FIFO で足りる。従来の 1 回は「3 pass の実行時間を `DENNO_PROFILE` の
///   `gdn_pf_sync` に写す」ためだけに残していた (表示専用) — P45 で外した。
/// - ホスト出力 (`y_dst = None`) は `to_vec` の `cuMemcpyDtoH` (同期) で y を
///   読むので、その手前で 1 回待つ (従来どおり)。
/// 1 層あたり: launch 3 (不変) / 同期 0 (デバイス出力) または 1 (ホスト出力)。
/// カーネル・引数・grid・chunk 分割・発行順は 1 つも変えないので出力ビットは不変。
#[allow(clippy::too_many_arguments)]
fn gdn_scan_chunked_impl(
    ctx: &CudaCtx,
    src: GdnScanSrc<'_>,
    conv_st: &mut [f32],
    ssm_st: &mut [f32],
    wconv: &[f32],
    wa: &[f32],
    wdt: &[f32],
    wnorm: &[f32],
    n: usize,
    nk: usize,
    nv: usize,
    dk: usize,
    dv: usize,
    d_conv: usize,
    eps: f32,
    q_scale: f32,
    y_dst: Option<CUdeviceptr>,
    li: usize,
    kv: u64,
) -> Result<Vec<f32>> {
    let cs = d_conv - 1;
    let conv_dim = 2 * nk * dk + nv * dv;
    let vd = nv * dv;
    if let GdnScanSrc::Host { qkv, z, beta, alpha } = &src {
        debug_assert_eq!(qkv.len(), n * conv_dim);
        debug_assert_eq!(z.len(), n * vd);
        debug_assert_eq!(beta.len(), n * nv);
        debug_assert_eq!(alpha.len(), n * nv);
    }
    debug_assert_eq!(conv_st.len(), conv_dim * cs);
    debug_assert_eq!(ssm_st.len(), nv * dk * dv);
    debug_assert_eq!(dk, dv, "chunked scan は dk == dv 前提");
    debug_assert_eq!(d_conv, 4, "chunked scan は d_conv == 4 前提");

    let (n_chunks, chunk_len) = crate::gdn::scan_schedule::plan(n);

    // s90 (P1-1): 2 launch 経路 (`f_gdn_chunk_scan_hoist`) の入り口判定は
    // `crate::gdn::scan_schedule::route_hoist` の 1 か所。この forward は
    // 「3 launch 経路に対して別 launch の書き手」を保証できない
    // (gdn/scan_schedule.rs のモジュール冒頭) ので、route_hoist(.., false) = false
    // が既定 → 下の 3 pass が走る。将来 常駐を実装したときに、ここで
    // route_hoist(.., true) 側の分岐を足す (今は分岐を持たない = 死んだ
    // パスを疑似的に走らせない)。
    if crate::gdn::scan_schedule::route_hoist(n, nv, dk, dv, false) {
        unreachable!("s90: route_hoist(.., false) は常に偽 (既定は 3 launch)");
    }
    // 帳簿の健全性 (debug のみ): 境界行の書き手は読み手より前の chunk であること。
    // 「別 launch の書き手」になるのはこの条件が満たされたうえで前の launch が
    // 実際に存在する場合だけなので、ここでは順序関係だけを見る。
    debug_assert!(
        crate::gdn::scan_schedule::read_write_conflicts(n, chunk_len, n_chunks)
            .iter()
            .all(|(reader, writer, _)| writer < reader),
        "s90: 境界行の書き手が読み手より後になっている"
    );

    ctx.make_current()?;
    // s64 (T5b L1 Step 1 計測): `gdn_scan_impl` と同一の 4 区間細分 (表示専用)。
    // s173 (P15): 区間は「確保/アップロード (alloc) → 3 pass の発行 (launch) →
    // 同期 1 回の待ち (sync) → 状態の書き戻し・y の読み出し (d2h)」の 4 つ。
    // pass 間で待たないので、3 pass の実行時間は最後の sync にまとめて乗る。
    let mut q = crate::prof::Seq::begin(crate::prof::D2H_GDN_PF_ALLOC, Instant::now());
    // s67: 16 本の作業領域は層をまたいで再利用する (確保は初回のみ・形が同じ間は
    // 何もしない)。中身は毎回 copy_from で上書きするので従来と同じ状態になる。
    // w/m/sinit/y は各 pass が全要素を書くためゼロ埋め不要 (旧実装は
    // `from_slice(&vec![0.0; …])` でゼロを H2D していた — その転送も消える)。
    // conv_out/ssm_out だけは「最終 chunk ブロックのみ書き込み」なので従来どおり
    // ゼロで初期化する (未書込部は未使用・挙動を変えない)。
    let dp = GDN_SCRATCH.with(|cell| -> Result<GdnPtrs> {
        let mut s = cell.borrow_mut();
        s.ensure(n, conv_dim, vd, nv, dk, dv, cs, n_chunks)?;
        let p = s.ptrs();
        s.buf(GdnBuf::ConvOut).fill_zero()?;
        s.buf(GdnBuf::SsmOut).fill_zero()?;
        // s164: ホスト入力のときだけ H2D する (Dev は呼び出し側が既に置いている)。
        if let GdnScanSrc::Host { qkv, z, beta, alpha } = &src {
            s.q.as_ref().unwrap().copy_from(qkv)?;
            s.z.as_ref().unwrap().copy_from(z)?;
            s.beta.as_ref().unwrap().copy_from(beta)?;
            s.alpha.as_ref().unwrap().copy_from(alpha)?;
        }
        gdn_put_weights(&s, li, [wconv, wa, wdt, wnorm])?;
        Ok(p)
    })?;
    // Dev のときは入力 4 本のポインタだけ差し替える (他はスクラッチのまま)。
    let dp = match src {
        GdnScanSrc::Dev { qkv, z, beta, alpha } => GdnPtrs { q: qkv, z, beta, alpha, ..dp },
        GdnScanSrc::Host { .. } => dp,
    };
    q.lap(crate::prof::D2H_GDN_PF_LAUNCH);

    // ---- pass 1: chunk 並列でローカル遷移 (W[ci], M[ci]) --------------------
    let (pst_conv, pst_ssm) =
        gdn_state_begin(kv, li, conv_st, ssm_st, conv_dim * cs, nv, dk * dv)?;
    let (mut pq, mut pb, mut pa) = (dp.q, dp.beta, dp.alpha);
    let (mut pci, mut pwc, mut pwa, mut pwd) = (pst_conv, dp.wc, dp.wa, dp.wd);
    let (mut pw, mut pm) = (dp.w, dp.m);
    let (mut ni, mut cli, mut nki, mut nvi, mut dki, mut dvi) = (
        n as c_int,
        chunk_len as c_int,
        nk as c_int,
        nv as c_int,
        dk as c_int,
        dv as c_int,
    );
    let (mut cdi, mut csi, mut epsi) = (conv_dim as c_int, cs as c_int, eps);
    let mut args_pre = [
        &mut pq as *mut _ as *mut c_void,
        &mut pb as *mut _ as *mut c_void,
        &mut pa as *mut _ as *mut c_void,
        &mut pci as *mut _ as *mut c_void,
        &mut pwc as *mut _ as *mut c_void,
        &mut pwa as *mut _ as *mut c_void,
        &mut pwd as *mut _ as *mut c_void,
        &mut pw as *mut _ as *mut c_void,
        &mut pm as *mut _ as *mut c_void,
        &mut ni as *mut _ as *mut c_void,
        &mut cli as *mut _ as *mut c_void,
        &mut nki as *mut _ as *mut c_void,
        &mut nvi as *mut _ as *mut c_void,
        &mut dki as *mut _ as *mut c_void,
        &mut dvi as *mut _ as *mut c_void,
        &mut cdi as *mut _ as *mut c_void,
        &mut csi as *mut _ as *mut c_void,
        &mut epsi as *mut _ as *mut c_void,
    ];
    let shmem_pre = ((2 * dk + 3) * 4) as u32;
    // s239 (P36): 4 レーン版 (DK=128 専用) は `DENNO_GDN_LANES=4` のときだけ。
    // block は列 dk × 4 レーン。数値は旧版と bit 一致しない (木縮約)。
    // P55: 共有メモリ版 (`DENNO_GDN_PRE_SM=1`・dk <= 128・opt-in 成功) は
    // 4 レーン版の**後ろ**に置く。4 レーン版が PTX にあり `DENNO_GDN_LANES=4` が
    // 立っていればそちらが勝ち、無ければ共有メモリ版のゲートへ進む
    // (両方 opt-in なので優先順位を明示しておく)。数値経路はどの枝でも
    // 下の launch 1 本だけで、カーネル・引数・grid・発行順は共通
    // (block と shmem だけが違う)。
    let smem_pre_sm = gdn_pre_sm_smem_bytes(dk);
    let (f_pre, blk_pre, shm_pre) = match (gdn_lanes4(), ctx.f_gdn_chunk_pre_l4) {
        (true, Some(f)) if dk == 128 && dv == 128 => (f, (dk as u32) * 4, shmem_pre),
        _ => {
            let use_sm = gdn_pre_sm_gate(
                gdn_pre_sm_enabled(),
                ctx.f_gdn_chunk_pre_sm.is_some(),
                dk,
                dv,
                smem_pre_sm,
                ctx.gdn_pre_sm_dyn_smem,
            );
            match (use_sm, ctx.f_gdn_chunk_pre_sm) {
                (true, Some(f)) => (f, dk as u32, smem_pre_sm as u32),
                _ => (ctx.f_gdn_chunk_pre, dk as u32, shmem_pre),
            }
        }
    };
    // s240 (P40): pass 1 の実時間 (`DENNO_GDN_KPROF=1` のときだけ・既定 OFF)。
    let mut kp = kprof_begin();
    kprof_mark(&mut kp, 0);
    unsafe {
        ctx.launch_async(
            f_pre,
            (n_chunks as u32, nv as u32, 1),
            (blk_pre, 1, 1),
            shm_pre,
            &mut args_pre,
        )?;
    }
    kprof_mark(&mut kp, 1);
    // s173 (P15): pass 1 → pass 2 は同一ストリームの発行順で足りる (pass 2 は
    // pass 1 が書いた W/M を読むが、既定ストリームは FIFO なので待つ必要が無い)。
    // 従来ここにあった `ctx.sync()` (cuCtxSynchronize = デバイス全体の drain) は
    // 削除した — 数値・発行順は不変で、消えたのはホストの待ちだけ。

    // ---- pass 2: chunk 先頭状態 Sinit の直列伝播 ----------------------------
    let (mut psi, mut pm2, mut pw2, mut psinit) = (pst_ssm, dp.m, dp.w, dp.sinit);
    let (mut nc2, mut nv2, mut dk2, mut dv2) =
        (n_chunks as c_int, nv as c_int, dk as c_int, dv as c_int);
    let mut args_state = [
        &mut psi as *mut _ as *mut c_void,
        &mut pm2 as *mut _ as *mut c_void,
        &mut pw2 as *mut _ as *mut c_void,
        &mut psinit as *mut _ as *mut c_void,
        &mut nc2 as *mut _ as *mut c_void,
        &mut nv2 as *mut _ as *mut c_void,
        &mut dk2 as *mut _ as *mut c_void,
        &mut dv2 as *mut _ as *mut c_void,
    ];
    unsafe {
        ctx.launch_async(
            ctx.f_gdn_chunk_state,
            (nv as u32, 1, 1),
            (dk as u32, 1, 1),
            0,
            &mut args_state,
        )?;
    }
    kprof_mark(&mut kp, 2);
    // s173 (P15): pass 2 → pass 3 も同じ理由で待たない (pass 3 は pass 2 の
    // Sinit を読むが、発行順で足りる)。

    // ---- pass 3: Sinit[ci] からの逐次 AR スキャン (chunk 並列) ---------------
    let (mut pq3, mut pz3, mut pb3, mut pa3) = (dp.q, dp.z, dp.beta, dp.alpha);
    // s131: pass 3 の conv 入力もデバイス正本 (スクラッチの conv_in はもう書かない)。
    let (mut pci3, mut psinit3) = (pci, dp.sinit);
    let (mut pwc3, mut pwa3, mut pwd3, mut pwn3) = (dp.wc, dp.wa, dp.wd, dp.wn);
    // s72: y_dst があれば y はチェーンスロットへ直接書く (host へ落とさない)。
    let (mut py, mut pco, mut pso) = (y_dst.unwrap_or(dp.y), dp.conv_out, dp.ssm_out);
    let (mut ni3, mut cli3) = (n as c_int, chunk_len as c_int);
    let (mut nki3, mut nvi3, mut dki3, mut dvi3) =
        (nk as c_int, nv as c_int, dk as c_int, dv as c_int);
    let (mut cdi3, mut csi3, mut epsi3, mut qsi3) =
        (conv_dim as c_int, cs as c_int, eps, q_scale);
    let mut args_scan = [
        &mut pq3 as *mut _ as *mut c_void,
        &mut pz3 as *mut _ as *mut c_void,
        &mut pb3 as *mut _ as *mut c_void,
        &mut pa3 as *mut _ as *mut c_void,
        &mut pci3 as *mut _ as *mut c_void,
        &mut psinit3 as *mut _ as *mut c_void,
        &mut pwc3 as *mut _ as *mut c_void,
        &mut pwa3 as *mut _ as *mut c_void,
        &mut pwd3 as *mut _ as *mut c_void,
        &mut pwn3 as *mut _ as *mut c_void,
        &mut py as *mut _ as *mut c_void,
        &mut pco as *mut _ as *mut c_void,
        &mut pso as *mut _ as *mut c_void,
        &mut ni3 as *mut _ as *mut c_void,
        &mut cli3 as *mut _ as *mut c_void,
        &mut nki3 as *mut _ as *mut c_void,
        &mut nvi3 as *mut _ as *mut c_void,
        &mut dki3 as *mut _ as *mut c_void,
        &mut dvi3 as *mut _ as *mut c_void,
        &mut cdi3 as *mut _ as *mut c_void,
        &mut csi3 as *mut _ as *mut c_void,
        &mut epsi3 as *mut _ as *mut c_void,
        &mut qsi3 as *mut _ as *mut c_void,
    ];
    let shmem_scan = ((3 * dk + dv + 5) * 4) as u32;
    unsafe {
        ctx.launch_async(
            ctx.f_gdn_chunk_scan,
            (n_chunks as u32, nv as u32, 1),
            (dk as u32, 1, 1),
            shmem_scan,
            &mut args_scan,
        )?;
    }
    kprof_mark(&mut kp, 3);
    // s245 (P45): y をデバイスに残す経路 (`y_dst = Some` = prefill 残差常駐) では
    // **ホストが結果を読まない**ので待たない。3 pass は同一ストリームへ発行順に並び、
    // pass 3 が書いた y を後続の o_proj が同じストリームで読み、状態の D2D 書き戻しと
    // 次の層の beta/alpha H2D (cuMemcpyHtoD = ホスト同期コピー) も同じストリームなので、
    // バッファ再利用の順序もストリームが保証する (s173/P15 で pass 間の 2 回を外したのと
    // 同じ根拠)。数値経路・発行順は 1 つも変えない。
    if y_dst.is_some() {
        // s72: y はデバイス上に残す (呼び出し側がチェーンで消費する)。
        // s131: 状態もデバイス正本へ D2D で戻す (ホストへは落とさない)。
        q.end();
        // s245 (P45): 3 区間の読み出しは次の既存の同期 (次の層の kprof_begin /
        // prefill 末尾の pf_timing_read) へ回す。そこで未完了なら finish が miss に
        // 数える (P43 の規則) — 計測のために同期を足さない。
        if let Some(k) = kp.take() {
            kprof_defer(k);
        }
        gdn_state_commit(li, dp.conv_out, dp.ssm_out, conv_dim * cs, nv, dk * dv)?;
        return Ok(Vec::new());
    }
    // ホスト出力 (`y_dst = None`) は y を `to_vec` (同期 D2H) で読むので 1 回待つ。
    // この 1 回は数値のため (従来どおり) で、細分の意味も変えない。
    q.lap(crate::prof::D2H_GDN_PF_SYNC);
    ctx.sync()?;
    q.lap(crate::prof::D2H_GDN_PF_D2H);
    // s240 (P40): 既存の同期が済んだ直後に 3 区間を読む (待ちは足さない)。
    // `q.lap(D2H)` の後に置くのは、3 回の `cuEventElapsedTime` (数 µs) を
    // 既存の `gdn_pf_sync` の数字に混ぜないため (d2h は表示専用の細分)。
    if let Some(k) = kp.take() {
        k.finish();
    }
    let y = GDN_SCRATCH.with(|cell| -> Result<Vec<f32>> {
        let s = cell.borrow();
        s.buf(GdnBuf::Y).to_vec::<f32>(n * vd)
    })?;
    // s131: 状態はホストへ落とさずデバイス正本へ D2D で戻す。
    gdn_state_commit(li, dp.conv_out, dp.ssm_out, conv_dim * cs, nv, dk * dv)?;
    crate::prof::mark_d2h_src(crate::prof::D2H_SRC_LINEAR);
    q.end();
    Ok(y)
}


// ===========================================================================
#[cfg(test)]
mod b7_stage_tests {
    //! s141 (Task B7): GDN 状態のホスト受け皿が**再利用**されることの検証。
    //!
    //! 背景 (s140 の計測): decode の `gdn_pf_alloc` が 98 us/call・4.7 ms/token
    //! あり、中身は層ごとの `to_vec` (`Vec::with_capacity` を 2 本 x 48 層) だった。
    //! 実転送 (D2H) は GPU が要るので、ここでは**確保の規則そのもの**
    //! (`reserve_exact_grow` — `d2h_raw` が実際に呼ぶ関数) を回して、
    //! 確保回数が層・ステップ数に比例して増えないことを確かめる。
    use super::*;

    /// Vec の再確保を数える (これが 0 件 = 確保していない)。
    fn count_regrows(stage: &mut GdnHostStage, conv_len: usize, ssm_len: usize, layers: usize) -> usize {
        let (c0, s0) = stage.capacities();
        for _ in 0..layers {
            reserve_exact_grow(&mut stage.conv, conv_len);
            reserve_exact_grow(&mut stage.ssm, ssm_len);
        }
        let (c1, s1) = stage.capacities();
        usize::from(c1 != c0) + usize::from(s1 != s0)
    }

    #[test]
    fn gdn_host_stage_is_reused_across_layers_and_steps() {
        // 27B q4 の実形状: conv = conv_dim*cs = 8448、ssm = nv*dk*dv = 786432 要素。
        let (conv_len, ssm_len) = (8_448usize, 786_432usize);
        let mut stage = GdnHostStage::new();
        assert_eq!(stage.capacities(), (0, 0), "作りたては未確保");

        // 1 ステップ目は伸びてよい (= 初回だけ確保する)。
        let first = count_regrows(&mut stage, conv_len, ssm_len, 48);
        assert_eq!(first, 2, "初回は conv/ssm の 2 本だけ確保する (実際 {first})");
        assert_eq!(stage.capacities(), (conv_len, ssm_len));

        // 2 ステップ目以降は 48 層回しても 1 本も確保しない (ここが本題)。
        for step in 1..8 {
            let regrown = count_regrows(&mut stage, conv_len, ssm_len, 48);
            assert_eq!(
                regrown, 0,
                "step={step}: 容量が層ループで再確保された (再利用できていない)"
            );
            assert_eq!(
                stage.capacities(),
                (conv_len, ssm_len),
                "step={step}: 容量がステップ数で増えた"
            );
        }
    }

    #[test]
    fn gdn_host_stage_grows_only_when_shape_grows() {
        // 形が大きくなったときだけ伸びる (grow-only)。縮んでも手放さない。
        let mut stage = GdnHostStage::new();
        reserve_exact_grow(&mut stage.conv, 100);
        assert_eq!(stage.capacities().0, 100);
        reserve_exact_grow(&mut stage.conv, 50); // 縮小 → 何もしない
        assert_eq!(stage.capacities().0, 100, "縮小で解放しない (grow-only)");
        reserve_exact_grow(&mut stage.conv, 8_448); // 拡大 → 伸ばす
        assert_eq!(stage.capacities().0, 8_448);
    }

    #[test]
    fn reserve_grow_reuses_pointer_so_no_per_layer_allocation() {
        // 同じ長さを繰り返しても**同じ領域**を使う (アドレスが変わらない = 再確保なし)。
        let mut stage = GdnHostStage::new();
        reserve_exact_grow(&mut stage.ssm, 786_432);
        let p0 = stage.ssm.as_ptr();
        for _ in 0..480 {
            reserve_exact_grow(&mut stage.ssm, 786_432);
            assert_eq!(stage.ssm.as_ptr(), p0, "同じ長さで確保し直している");
        }
    }
}

// ===========================================================================
#[cfg(test)]
mod b7c_ownership_tests {
    //! s141b (Task B7c): GDN 状態の所有者規則を固定する。
    //!
    //! 新しい規則:
    //! - decode 中はデバイスミラーが権威。ホスト `KvCache::gdn` は**遅延リフレッシュ
    //!   対象**で、`gdn_stale[li]` が真の間は古い可能性がある。
    //! - seed (位置不一致でミラーを埋め直す) は**デバイス正本から D2D**。ホストを
    //!   経由しない (= 層あたり 3.2 MiB の PCIe 往復が消える)。
    //! - 遅延フラッシュは**ホストが古い層だけ**読む (古くない層を読み直さない
    //!   = 「何も要らないステップでホストバイトをコピーしない」)。
    //!
    //! 実転送は GPU が要るので、ここでは判定の実体 (`gdn_flush_step` /
    //! `gdn_state_take_dev` / `gdn_stale`) を回す。デバイスを伴う確認は
    //! `cuda_gdn_flush_pending_faces_positions_and_epoch` (GPU 必須・ignored) が
    //! デバイスを伴う確認を受け持つ。
    use super::*;

    const LAYERS: usize = 48;
    const STEPS: usize = 8;
    /// ミラーの番兵キー (既存テストの u64::MAX-1 / u64::MAX-3 と衝突しない)。
    const MIRROR_TEST_KEY_B7C: u64 = u64::MAX - 5;

    /// 決定論のビットパターン (GPU テストの既知値用。`cuda::tests` の
    /// `pseudo_random` は別モジュールなので私有で持つ)。
    fn b7c_pattern(len: usize, seed: u32) -> Vec<f32> {
        let mut s = seed.wrapping_mul(1_664_525).wrapping_add(1_013_904_223);
        (0..len)
            .map(|_| {
                s = s.wrapping_mul(1_664_525).wrapping_add(1_013_904_223);
                ((s >> 8) as f32) / ((1u32 << 24) as f32) - 0.5
            })
            .collect()
    }

    /// decode 1 ステップ分のホストバイト数 (48 層 x (conv 8,448 + ssm 786,432) f32)。
    fn host_bytes_per_step(copied_layers: usize) -> usize {
        copied_layers * (8_448 + 786_432) * std::mem::size_of::<f32>()
    }

    /// decode 1 ステップの層ループを回した結果。
    #[derive(Clone, Copy, Debug, Default)]
    struct StepIo {
        /// seed で**ホストから読んだ**層数 (B7c が削る対象。正本が有効なら 0)
        host_seeded: usize,
        /// flush で D2H した層数 (スキャンした層だけ)
        flushed: usize,
    }

    #[derive(Clone, Copy, Debug)]
    struct Layer {
        pos: Option<usize>,
        stale: bool,
    }

    /// flush 段だけを回す (target = このステップ後の `cache.len()`)。
    fn flush(layers: &mut [Layer], target: usize) -> usize {
        let mut copied = 0;
        for l in layers.iter_mut() {
            let (need, _aligned) = gdn_flush_step(true, l.stale, target, l.pos);
            if need {
                l.stale = false;
                copied += 1;
            }
        }
        copied
    }

    /// `chain_q35_gdn_scan` の層ループをそのまま写す:
    /// 1. seed (位置不一致): 正本が有効なら D2D (ホストを読まない) / 無効ならホストから
    /// 2. scan: 書き込み面が新状態になる → `gdn_pos = pos0+1`, `gdn_stale = true`
    /// 3. flush (ステップ末尾): `gdn_flush_step` が真の層だけ D2H
    fn step(layers: &mut [Layer], pos0: usize, dev_valid: bool) -> StepIo {
        let mut io = StepIo::default();
        // 1. seed (位置不一致 = 前ステップの pos0+1 が今の pos0 と合わない層)
        for l in layers.iter_mut() {
            if l.pos != Some(pos0) {
                if dev_valid {
                    // 正本から D2D — ホストは 1 バイトも読まない。ただしホストは
                    // この時点で古い可能性があるので遅延フラグは立てたままにする
                    // (落とすと flush がこの層を飛ばして古いホストを正にしてしまう)。
                    l.stale = true;
                } else {
                    // 正本が無効 = ホストが正。ホストを読んで面 0 を書く。
                    io.host_seeded += 1;
                    l.stale = false;
                }
                l.pos = Some(pos0);
            }
        }
        // 2. scan
        for l in layers.iter_mut() {
            l.pos = Some(pos0 + 1);
            l.stale = true;
        }
        // 3. flush (cache.len() は advance 後 = pos0+1)
        io.flushed = flush(layers, pos0 + 1);
        io
    }

    /// 27B q4 の decode ではミラーの cap 成長で `gdn_pos` が落ちるため、seed は
    /// **毎ステップ全層**走る (実測: `gdn_pf_alloc` 5,712 call = 48 層 x 119 step)。
    /// その条件を再現する。
    fn reset_pos(layers: &mut [Layer]) {
        for l in layers.iter_mut() {
            l.pos = None;
        }
    }

    /// 1) decode 形 (48 層 x 8 ステップ): 正本が有効なステップの seed は D2D なので
    ///    ホストを 1 バイトも読まない (従来は層あたり ~3.2 MiB の D2H 往復)。
    #[test]
    fn decode_loop_seeds_from_device_and_never_reads_host() {
        // 初回要求: まだ正本が無い → 全層をホストから seed (これは従来どおり)。
        let mut layers = vec![Layer { pos: None, stale: false }; LAYERS];
        let first = step(&mut layers, 4, false);
        assert_eq!(first.host_seeded, LAYERS, "正本が無い初回はホストから");
        // 2 ステップ目以降は正本が有効 = seed は D2D。ホストは読まれない。
        let mut host_bytes = 0usize;
        for s in 0..STEPS {
            reset_pos(&mut layers);
            let io = step(&mut layers, 5 + s, true);
            assert_eq!(io.host_seeded, 0, "step={s}: 正本が有効なのにホストを読んだ");
            host_bytes += host_bytes_per_step(io.host_seeded);
            assert_eq!(io.flushed, LAYERS, "step={s}: スキャンした層は flush で 1 度だけ読む");
        }
        assert_eq!(host_bytes, 0, "8 ステップで seed のホスト読みは 0 バイト");
        // flush は全層を 1 度ずつ読んでフラグを落とす = 最終状態は「ホストと一致」。
        assert!(layers.iter().all(|l| !l.stale), "flush 後はフラグが落ちる");
    }

    /// 2) flush は「ホストが古い層」だけを読み、読んだ層はフラグを落とす
    ///    (= 二度読まない)。スキャンしていない層 (stale = false) は読まない。
    #[test]
    fn flush_reads_only_the_layers_whose_host_is_stale() {
        let mut layers = vec![Layer { pos: Some(10), stale: true }; LAYERS];
        layers[7].stale = false; // この層はスキャンしていない = ホストが最新
        let copied = flush(&mut layers, 10);
        assert_eq!(copied, LAYERS - 1, "古い層だけ読む");
        // 1 層 = (8,448 + 786,432) x 4 B = 3,179,520 B。
        assert_eq!(
            host_bytes_per_step(copied),
            3_179_520 * (LAYERS - 1),
            "スキャンした 47 層分だけ (48 層分ではない)"
        );
        // 2 回目の flush は何も読まない (フラグを落としたので)。
        assert_eq!(flush(&mut layers, 10), 0);
        // 位置が合わない (target でも target+1 でもない) 層は stale なら
        // 「不整合」= 呼び出し側が None にする (読みもしない)。
        assert_eq!(gdn_flush_step(true, true, 10, Some(9)), (false, false));
    }

    /// 3) 位置が合っているかどうかの判定 (無効化・位置不一致・新規要求の経路)。
    #[test]
    fn flush_decision_matches_the_old_position_rules() {
        // ホストが古い (stale) 層: 成功ステップ後 (target) の面だけを読む。
        assert_eq!(gdn_flush_step(true, true, 10, Some(10)), (true, true));
        // 層途中失敗 (target+1): 読む面は seed 直後に書かれた = ホストと一致 = 読まない。
        assert_eq!(gdn_flush_step(true, true, 10, Some(11)), (false, true));
        assert_eq!(gdn_flush_step(true, false, 10, Some(11)), (false, true));
        // stale かつ位置が合わない (None / 遠い) → 「読むべきか」は偽、整列も偽。
        // 呼び出し側はこれを不整合 (None) として扱う (旧実装の Some(_) と同じ)。
        assert_eq!(gdn_flush_step(true, true, 10, None), (false, false));
        assert_eq!(gdn_flush_step(true, true, 10, Some(4)), (false, false));
        // ホストが古くない層: 位置が合っていても読まない (ここが B7c の本体)。
        assert_eq!(gdn_flush_step(true, false, 10, Some(10)), (false, true));
        // GDN 層でない層は常に対象外。
        assert_eq!(gdn_flush_step(false, true, 10, Some(10)), (false, false));
    }

    /// 4) 1 リクエスト相当 (prefill で seed → decode 120 ステップ) でも、decode 中に
    ///    seed がホストから読むバイトは 0 (ミラーの cap 成長で seed が毎ステップ
    ///    走る条件を含む)。
    #[test]
    fn one_request_of_decode_never_pulls_the_host_mirror() {
        let mut layers = vec![Layer { pos: None, stale: false }; LAYERS];
        let _prefill_seed = step(&mut layers, 3_000, false);
        let mut total = 0usize;
        for s in 0..120 {
            reset_pos(&mut layers);
            total += host_bytes_per_step(step(&mut layers, 3_001 + s, true).host_seeded);
        }
        assert_eq!(total, 0, "1 リクエスト分の decode で seed がホストから読むバイトは 0");
    }

    /// 5) invalidate-then-seed: ホストが正に戻った (reset/restore/新要求) ときの
    ///    seed 入力はホストのままで、ホストの値は 1 ビットも変わらない。
    ///    `gdn_state_take_dev` は valid=false (= ホストが正) の層では None を返す
    ///    こと = デバイス正本を上書きに使わないこと。
    #[test]
    fn invalidate_then_seed_uses_host_and_keeps_its_bits() {
        // キャッシュの「ホスト正」状態を模す (値は f32 のビットパターンで比較)。
        let conv_len = 192usize;
        let ssm_len = 256usize;
        let host_conv: Vec<f32> = (0..conv_len).map(|i| (i as f32) * 1.5e-3).collect();
        let host_ssm: Vec<f32> = (0..ssm_len).map(|i| -((i as f32) * 3.0)).collect();
        let before_c: Vec<u32> = host_conv.iter().map(|v| v.to_bits()).collect();
        let before_s: Vec<u32> = host_ssm.iter().map(|v| v.to_bits()).collect();

        // 正本を「無効」にした状態 = ホストが正。
        let mut dev = GdnStateCache::empty();
        dev.invalidate();
        let devseed = gdn_state_take_dev(12345, 0, &mut dev);
        assert!(devseed.is_none(), "無効な正本を seed に使ってはいけない");

        // 呼び出し側 (chain_q35_gdn_scan の None 分岐) はホストからコピーする。
        // ここでは H2D の代わりに「ホストを読んで書き戻す」ことを確かめる
        // (転送は値そのままなので bit 一致のまま)。
        assert_eq!(
            host_conv.iter().map(|v| v.to_bits()).collect::<Vec<_>>(),
            before_c,
            "conv は bit 一致のまま"
        );
        assert_eq!(
            host_ssm.iter().map(|v| v.to_bits()).collect::<Vec<_>>(),
            before_s,
            "ssm は bit 一致のまま"
        );
    }

    /// 6) 正本が有効な層は D2D 経路 (seed に使ってよい) で、使った層は無効化される
    ///    (scan がミラーを更新するので正本とずれる)。デバイス確保は要らない。
    #[test]
    fn dev_take_only_for_valid_layers_and_invalidates_them() {
        let mut dev = GdnStateCache::empty();
        // 層 0/1 を「有効」にする — DevBuffer は確保せず、判定だけを見るため
        // valid と cur_kv を直接立てる (確保の無い層は ptr が取れず None)。
        dev.cur_kv = Some(7);
        dev.valid = vec![true, true, false];
        // デバイスバッファが無いので ptr は取れない = None。ここで重要なのは
        // 「valid でない層は絶対に None」かつ「同じ kv でない層も None」。
        assert!(gdn_state_take_dev(8, 0, &mut dev).is_none(), "別 kv_id は不可");
        assert!(gdn_state_take_dev(7, 2, &mut dev).is_none(), "valid=false は不可");
        assert!(gdn_state_take_dev(7, 9, &mut dev).is_none(), "範囲外は不可");
    }

    /// 7) ホスト遅延フラグは層ごとに独立: 1 層だけ「古い」なら、その層だけが flush の
    ///    対象になり、他の 47 層は読まれない (別層の状態で代用しない)。
    #[test]
    fn stale_flag_is_per_layer() {
        let mut stale = vec![false; LAYERS];
        stale[31] = true;
        let pos = vec![Some(42); LAYERS];
        let need: Vec<usize> = (0..LAYERS).filter(|&li| gdn_flush_step(true, stale[li], 42, pos[li]).0).collect();
        assert_eq!(need, vec![31], "古い層だけが読まれる");
        // 隣の層 (30 / 32) は位置が合っていても読まない — 代用読みをしない。
        assert_eq!(gdn_flush_step(true, stale[30], 42, pos[30]), (false, true));
        assert_eq!(gdn_flush_step(true, stale[32], 42, pos[32]), (false, true));
    }

    /// 8) GPU 必須: ミラーの面 0 が**古い値**のままでも、seed がデバイス正本から
    ///    D2D で入ることを、ミラー面 0 を読み戻してビットで確かめる
    ///    (ホストは古い値 = 使われていないことが分かる)。
    ///    実行: `cargo test --features cuda --lib cuda_b7c_seed_copies_from_device_mirror -- --ignored`
    #[test]
    #[ignore] // GPU 必須
    fn cuda_b7c_seed_copies_from_device_mirror() {
        let _g = test_lock().lock().unwrap_or_else(std::sync::PoisonError::into_inner);
        enable_for_tests();
        let _ctx = CudaCtx::new().expect("GPU 必須 (ignored テスト)");
        let (conv_len, ssm_len) = (192usize, 256usize);
        let key = MIRROR_TEST_KEY_B7C;
        let kv_id = 7u64;
        let dev_conv = b7c_pattern(conv_len, 91);
        let dev_ssm = b7c_pattern(ssm_len, 92);
        let stale_conv = vec![1.0f32; conv_len];
        let stale_ssm = vec![2.0f32; ssm_len];

        // ミラーを作り、面 0 に「古い値」を書く (seed で上書きされるはずの場所)。
        with_mirror_ext(key, 0, 1, 8, 0, 0, false, |m, _| {
            let mut g = GdnDev { conv: [None, None], ssm: [None, None], cur: 0 };
            ok(Scratch::ensure(&mut g.conv[0], conv_len * 4))?;
            ok(Scratch::ensure(&mut g.conv[1], conv_len * 4))?;
            ok(Scratch::ensure(&mut g.ssm[0], ssm_len * 4))?;
            ok(Scratch::ensure(&mut g.ssm[1], ssm_len * 4))?;
            ok(g.conv[0].as_ref().unwrap().copy_from(&stale_conv))?;
            ok(g.ssm[0].as_ref().unwrap().copy_from(&stale_ssm))?;
            m.gdn[0] = Some(g);
            m.gdn_pos[0] = None; // 位置不一致 = seed が走る
            m.gdn_stale[0] = true; // ホストは古い可能性がある
            Some(())
        })
        .unwrap();

        // デバイス正本に既知の値を入れて「有効」にする (s131 の正本と同じ持ち方)。
        GDN_STATE.with(|cell| {
            let mut c = cell.borrow_mut();
            c.cur_kv = Some(kv_id);
            c.invalidate();
            assert!(c.ensure_layer(0, 1, ssm_len).is_ok(), "ssm 確保");
            assert!(c.ensure_conv(0, conv_len).is_ok(), "conv 確保");
            assert!(c.conv[0].as_ref().unwrap().copy_from(&dev_conv).is_ok());
            assert!(c.ssm[0].as_ref().unwrap().copy_from(&dev_ssm).is_ok());
            c.valid[0] = true;
        });

        // seed の入力 (関数そのもの) を取る。取り出した層は無効化される。
        let seed = GDN_STATE.with(|cell| gdn_state_take_dev(kv_id, 0, &mut cell.borrow_mut()));
        let (pc, ps) = seed.expect("有効な正本から読める");
        // ミラー面 0 へ D2D (chain_q35_gdn_scan の seed と同じ操作)。
        with_mirror_ext(key, 0, 1, 8, 0, 0, false, |m, _| {
            let gd = m.gdn[0].as_mut().unwrap();
            ok(gd.conv[0].as_ref().unwrap().copy_from_dev(pc, conv_len))?;
            ok(gd.ssm[0].as_ref().unwrap().copy_from_dev(ps, ssm_len))?;
            m.gdn_pos[0] = Some(0);
            m.gdn_stale[0] = false;
            Some(())
        })
        .unwrap();

        // ミラー面 0 を読み戻して、正本の値とビット一致・「古い値」ではないことを見る。
        with_mirror_ext(key, 0, 1, 8, 0, 0, false, |m, _| {
            let gd = m.gdn[0].as_ref().unwrap();
            let cv = gd.conv[0].as_ref().unwrap().to_vec::<f32>(conv_len).unwrap();
            let sm = gd.ssm[0].as_ref().unwrap().to_vec::<f32>(ssm_len).unwrap();
            assert_eq!(cv.len(), dev_conv.len());
            assert!(
                cv.iter().zip(&dev_conv).all(|(a, b)| a.to_bits() == b.to_bits()),
                "seed はデバイス正本の conv とビット一致"
            );
            assert!(
                sm.iter().zip(&dev_ssm).all(|(a, b)| a.to_bits() == b.to_bits()),
                "seed はデバイス正本の ssm とビット一致"
            );
            assert!(cv.iter().all(|&v| v != 1.0), "古いホスト値が使われていない");
            assert!(sm.iter().all(|&v| v != 2.0), "古いホスト値が使われていない");
            Some(())
        })
        .unwrap();
        // 一度読んだ層は無効化されている (次は必ず seed し直す = 取り違えない)。
        let again = GDN_STATE.with(|cell| gdn_state_take_dev(kv_id, 0, &mut cell.borrow_mut()));
        assert!(again.is_none(), "取り出した層は無効化される");
    }
}

#[cfg(test)]
mod b20_stage1_tests {
    //! s157 (Task B20 段階 1): q4 線形を chain に載せる入口の**判定だけ**を固定する。
    //! 実カーネルは GPU が要るので、ここでは (a) `DENNO_GPU_Q4_CHAIN` の解釈、
    //! (b) `chain_linear` が空・混在グループを**受けない**こと (= per-op 経路へ
    //! 静かに委譲する) を確かめる。数値の一致は実機 (supervisor) の担当。
    use super::*;

    /// `DENNO_GPU_Q4_CHAIN` は **"0" だけ**が off。未設定・空・"off" などは on。
    #[test]
    fn q4_chain_flag_is_off_only_for_explicit_zero() {
        assert!(!parse_q4_chain(Some("0")), "\"0\" だけが per-op 経路へ戻す");
        for raw in [None, Some(""), Some("1"), Some("off"), Some(" 0"), Some("0 ")] {
            assert!(parse_q4_chain(raw), "raw={raw:?} は on (既定) のはず");
        }
    }

    /// `chain_linear` は空グループ・int8/q4 混在グループを受けない (None → per-op)。
    #[test]
    fn chain_linear_rejects_empty_and_mixed_groups() {
        assert_eq!(chain_linear(&[], CH_H, CH_O, 1), None, "空グループは受けない");
        let w = vec![0.0f32; 32 * 64];
        let a = crate::quant::Linear::Q8(crate::quant::Quant8Linear::quantize(&w, 32, 64));
        let b = crate::quant::Linear::Q4(crate::quant::Q4Linear::quantize(&w, 32, 64));
        assert_eq!(
            chain_linear(&[&a, &b], CH_H, CH_O, 1),
            None,
            "int8 と q4 の混在は受けない"
        );
        // 単独グループは GPU が無い環境では `chain_ctx()` が None → これも None
        // (per-op 経路へ委譲)。**panic しないこと**がここの主眼。
        assert_eq!(chain_linear(&[&b], CH_H, CH_O, 1), None);
        assert_eq!(chain_linear(&[&a], CH_H, CH_O, 1), None);
    }

    /// P1c: `chain_gdn_prefill_q4` の入口条件 (フォールバック契約) を GPU 無しで固定する。
    /// 本番経路は `gdn_prefill_q4_geom` の戻り値だけを見て発動/委譲を決めるので、
    /// ここで None になる条件がそのまま「従来経路へ落とす」契約になる。
    /// CUDA は一切呼ばない (デバイス不要)。
    #[test]
    fn gdn_prefill_q4_geom_contract() {
        use crate::quant::{Linear, Q4Linear};
        let q4 = |k: usize, n: usize| {
            Linear::Q4(Q4Linear { blocks: Vec::new().into(), k, n, uid: 0 })
        };
        // 成立する形: nk=2, nv=2, dk=dv=64, d_conv=4, e=64
        //   conv_dim = nk*dk*2 + nv*dv = 384, vd = nv*dv = 128
        let (nk, nv, dk, dv, dc) = (2usize, 2usize, 64usize, 64usize, 4usize);
        let (e, conv_dim, vd) = (64usize, 384usize, 128usize);
        let n_ok = GDN_CHUNK_MIN_TOKENS; // 2048 (1024 の倍数なので端数タイル無し)
        let base = || (q4(e, conv_dim), q4(e, vd), q4(vd, e));
        let dims = (nk, nv, dk, dv, dc);
        let sup = |w: &(Linear, Linear, Linear), n: usize, d: (usize, usize, usize, usize, usize)| {
            gdn_prefill_q4_geom(&w.0, &w.1, &w.2, n, d.0, d.1, d.2, d.3, d.4).is_some()
        };

        // 0) 基準形は通り、寸法が正しく返る
        let w = base();
        let g = gdn_prefill_q4_geom(&w.0, &w.1, &w.2, n_ok, nk, nv, dk, dv, dc)
            .expect("基準形は発動してよい");
        assert_eq!((g.e, g.conv_dim, g.vd, g.cs), (e, conv_dim, vd, dc - 1));

        // 1) 3 本のどれかが Q4 でない → 受けない
        let f32w = |k: usize, n: usize| Linear::F32 { w: Vec::new(), k, n };
        let bad = (f32w(e, conv_dim), w.1.clone(), w.2.clone());
        assert!(!sup(&bad, n_ok, dims), "qkv が Q4 でなければ受けない");
        let bad = (w.0.clone(), f32w(e, vd), w.2.clone());
        assert!(!sup(&bad, n_ok, dims), "z が Q4 でなければ受けない");
        let bad = (w.0.clone(), w.1.clone(), f32w(vd, e));
        assert!(!sup(&bad, n_ok, dims), "o が Q4 でなければ受けない");

        // 2) 重み形状の不一致 (各辺 1 つずつ)
        let bad = (q4(e, conv_dim + 32), w.1.clone(), w.2.clone());
        assert!(!sup(&bad, n_ok, dims), "qkv.n != conv_dim は受けない");
        let bad = (w.0.clone(), q4(e + 32, vd), w.2.clone());
        assert!(!sup(&bad, n_ok, dims), "z.k != e は受けない");
        let bad = (w.0.clone(), q4(e, vd + 32), w.2.clone());
        assert!(!sup(&bad, n_ok, dims), "z.n != vd は受けない");
        let bad = (w.0.clone(), w.1.clone(), q4(vd + 32, e));
        assert!(!sup(&bad, n_ok, dims), "o.k != vd は受けない");
        let bad = (w.0.clone(), w.1.clone(), q4(vd, e + 32));
        assert!(!sup(&bad, n_ok, dims), "o.n != e は受けない");

        // 3) n が閾値未満 → 受けない (閾値ちょうどは通る)
        assert!(
            !sup(&w, GDN_CHUNK_MIN_TOKENS - 1, dims),
            "n < GDN_CHUNK_MIN_TOKENS は受けない"
        );

        // 4) dk != dv / d_conv != 4 → 受けない
        assert!(!sup(&w, n_ok, (nk, nv, dk, dv / 2, dc)), "dk != dv は受けない");
        assert!(!sup(&w, n_ok, (nk, nv, dk, dv, 3)), "d_conv != 4 は受けない");

        // 5) 次元 0 / 32 の倍数でない k / vd → 受けない
        assert!(!sup(&w, n_ok, (0, nv, dk, dv, dc)), "nk == 0 は受けない");
        assert!(!sup(&w, n_ok, (nk, 0, dk, dv, dc)), "nv == 0 は受けない");
        assert!(!sup(&w, n_ok, (nk, nv, 0, 0, dc)), "dk == dv == 0 は受けない");
        let bad = (q4(48, conv_dim), q4(48, vd), q4(vd, 48));
        assert!(!sup(&bad, n_ok, dims), "e % 32 != 0 は受けない");
        let bad = (q4(0, conv_dim), q4(0, vd), q4(vd, 0));
        assert!(!sup(&bad, n_ok, dims), "e == 0 は受けない");
        // vd = nv*dv = 3*16 = 48 (% 32 != 0), e = 32 は条件を満たす
        let bad = (q4(32, 112), q4(32, 48), q4(48, 32));
        assert!(!sup(&bad, n_ok, (2, 3, 16, 16, dc)), "vd % 32 != 0 は受けない");

        // 6) 端数タイルが m <= max_m() → 受けない (per-op 経路が GEMV になる帯域)
        let rem_small = GDN_PREFILL_TILE * 2 + max_m();
        assert!(
            !sup(&w, rem_small, dims),
            "端数 {} 行 (<= max_m()={}) は受けない",
            max_m(),
            max_m()
        );
        // 端数が max_m() を超える / 端数なしは通る
        assert!(sup(&w, rem_small + 1, dims), "端数 max_m()+1 は通る");
        assert!(sup(&w, GDN_PREFILL_TILE * 2, dims), "端数なしは通る");

        // 7) 桁あふれは checked_mul で None
        assert!(!sup(&w, n_ok, (usize::MAX, nv, dk, dv, dc)), "conv_dim の桁あふれは受けない");
    }

    /// task 154: `gdn_scan_batch_sig` の入口 ([`gdn_sig_accepts`]) の境界。
    /// GPU を呼ばないので、この判定だけで「19 トークンの next turn が CPU へ落ちる」
    /// ことを固定できる。
    #[test]
    fn gdn_sig_accepts_short_columns_decline() {
        // 実形に近い寸法 (nk=8, nv=8, dk=dv=128, d_conv=4)。
        let ok = |n: usize| gdn_sig_accepts(n, 8, 8, 128, 128, 4);
        assert!(ok(GDN_SIG_MIN_TOKENS), "境界ちょうど (64) は受ける");
        assert!(ok(GDN_SIG_MIN_TOKENS + 1));
        assert!(ok(GDN_CHUNK_MIN_TOKENS - 1), "chunked の手前までは受ける");
        assert!(!ok(GDN_CHUNK_MIN_TOKENS), "chunked 側 (n >= 2048) は受けない");
        assert!(!ok(19), "next turn の 19 トークンは受けない (CPU のほうが速い)");
        assert!(!ok(GDN_SIG_MIN_TOKENS - 1), "63 は受けない");
        assert!(!ok(0));
        // 形の制約は据え置き (64 以上でも落ちる = 短列ガードで緩んでいない)。
        assert!(!gdn_sig_accepts(64, 0, 8, 128, 128, 4), "nk == 0 は受けない");
        assert!(!gdn_sig_accepts(64, 8, 0, 128, 128, 4), "nv == 0 は受けない");
        assert!(!gdn_sig_accepts(64, 8, 8, 128, 64, 4), "dk != dv は受けない");
        assert!(!gdn_sig_accepts(64, 8, 8, 512, 512, 4), "dk > 256 は受けない");
        assert!(!gdn_sig_accepts(64, 8, 8, 128, 128, 3), "d_conv != 4 は受けない");
    }
}

#[cfg(test)]
mod p14_ffn_fused_tests {
    //! s173 (Task P14): prefill FFN の **gate|up 1 回 GEMM** の前提契約を固定する。
    //!
    //! `pf_ffn_fused_ready` が true のときだけ 1 回の GEMM 経路 (n = 2*ff を
    //! `CH_GA` へ行内 [gate|up] で書く) に入る。条件を 1 つでも落とすと
    //! 連結重みの行範囲が別の重みを指しうる (数値が変わる) ので、
    //! `ffn_fused_shape_ok` の false 側を全部固定する。
    //! GPU が無い環境でも走る (形状だけの純粋関数・エイリアス表に触らない)。
    use super::*;
    use crate::quant::{Linear, Q4Linear};

    fn q4(k: usize, n: usize, uid: u64) -> Q4Linear {
        // 形状だけを見るので blocks は空でよい (weights_for_q4 は呼ばない)。
        Q4Linear { blocks: Vec::new().into(), k, n, uid }
    }

    #[test]
    fn ffn_fused_shape_accepts_gate_up_concat() {
        // 27B: e = 5120, ff = 17408 → gate_up は [2*ff, e]、down は [ff, e]
        let (e, ff) = (5120usize, 17408usize);
        let c = q4(e, 2 * ff, 1);
        let g = q4(e, ff, 2);
        let u = q4(e, ff, 3);
        let d = q4(ff, e, 4);
        assert!(ffn_fused_shape_ok(&c, &g, &u, &d));
    }

    #[test]
    fn ffn_fused_shape_fail_closed() {
        let (e, ff) = (5120usize, 17408usize);
        let c = q4(e, 2 * ff, 1);
        let g = q4(e, ff, 2);
        let u = q4(e, ff, 3);
        let d = q4(ff, e, 4);
        // 連結幅が 2*ff でない (短い / 長い)
        assert!(!ffn_fused_shape_ok(&q4(e, 2 * ff - 1, 1), &g, &u, &d));
        assert!(!ffn_fused_shape_ok(&q4(e, 2 * ff + 1, 1), &g, &u, &d));
        // gate と up の行数が違う (和だけ合っていても駄目)
        assert!(!ffn_fused_shape_ok(&c, &q4(e, ff - 32, 2), &q4(e, ff + 32, 3), &d));
        // k が食い違う
        assert!(!ffn_fused_shape_ok(&q4(e + 32, 2 * ff, 1), &g, &u, &d));
        assert!(!ffn_fused_shape_ok(&c, &q4(e + 32, ff, 2), &u, &d));
        assert!(!ffn_fused_shape_ok(&c, &g, &q4(e + 32, ff, 3), &d));
        // down の形が [ff, e] でない
        assert!(!ffn_fused_shape_ok(&c, &g, &u, &q4(ff + 32, e, 4)));
        assert!(!ffn_fused_shape_ok(&c, &g, &u, &q4(ff, e + 32, 4)));
    }

    /// Q4 以外が混ざったら (int8 / fp32 のモデル) 1 回 GEMM 経路には入らない。
    /// エイリアス表は空のままなので `q4_fused_ready` も false を返す。
    #[test]
    fn ffn_fused_ready_requires_all_q4() {
        let (e, ff) = (5120usize, 17408usize);
        let c = Linear::Q4(q4(e, 2 * ff, 1));
        let g = Linear::Q4(q4(e, ff, 2));
        let u = Linear::Q4(q4(e, ff, 3));
        let d = Linear::Q4(q4(ff, e, 4));
        // 全部 Q4 だがエイリアス未登録 (GPU 無し / 登録失敗) → 従来経路
        assert!(!pf_ffn_fused_ready(&c, &g, &u, &d));
        // 1 本でも Q4 でなければ false
        let f32w = Linear::F32 { w: Vec::new(), k: ff, n: e };
        assert!(!pf_ffn_fused_ready(&c, &g, &u, &f32w));
        assert!(!pf_ffn_fused_ready(&f32w, &g, &u, &d));
    }

    /// A/B スイッチの解釈: `"0"` だけが off (タイポで静かに経路が変わるのを避ける)。
    #[test]
    fn env_switch_only_zero_is_off() {
        assert!(parse_pf_ffn_fused(None));
        assert!(parse_pf_ffn_fused(Some("")));
        assert!(parse_pf_ffn_fused(Some("1")));
        assert!(parse_pf_ffn_fused(Some("off")));
        assert!(!parse_pf_ffn_fused(Some("0")));
    }
}

#[cfg(test)]
mod p3_alias_tests {
    //! s165 (Task P3): 連結重みの行範囲エイリアスの**形状契約**を固定する。
    //!
    //! 27B q4 の FFN は decode chain が `gate_up_w` (連結 1 本)、Q4 prefill が
    //! `gate_w` / `up_w` (2 本) を使うため、同じ 2×ff×e パラメータが VRAM に
    //! 2 度載っていた。`q4_row_alias_offsets` が「parts の行数の和 = 連結側の
    //! 行数・k は全部同じ」を満たすときだけ行オフセットを返すことを固定する。
    //! ここが崩れると別の重みを読む (数値が変わる) ので、満たさない入力は
    //! すべて None (= 従来の個別転送へフォールバック) であることを確かめる。
    use super::*;

    #[test]
    fn alias_offsets_gate_up_layout() {
        // 27B: e = 5120, ff = 17408 → 連結は [gate(17408 行) | up(17408 行)]
        let k = 5120;
        let ff = 17408;
        assert_eq!(
            q4_row_alias_offsets(k, 2 * ff, &[(k, ff), (k, ff)]),
            Some(vec![0, ff])
        );
        // 3 本以上でも累積する (汎用の行連結)
        assert_eq!(
            q4_row_alias_offsets(k, 3 * ff, &[(k, ff), (k, ff), (k, ff)]),
            Some(vec![0, ff, 2 * ff])
        );
    }

    #[test]
    fn alias_offsets_fail_closed() {
        let k = 5120;
        let ff = 17408;
        // 行数の和が合わない (連結側が短い/長い)
        assert_eq!(q4_row_alias_offsets(k, 2 * ff - 1, &[(k, ff), (k, ff)]), None);
        assert_eq!(q4_row_alias_offsets(k, 2 * ff + 1, &[(k, ff), (k, ff)]), None);
        // k が食い違う
        assert_eq!(q4_row_alias_offsets(k, 2 * ff, &[(k, ff), (k + 32, ff)]), None);
        // 空・0 行・0 列・32 の倍数でない k
        assert_eq!(q4_row_alias_offsets(k, 2 * ff, &[]), None);
        assert_eq!(q4_row_alias_offsets(k, ff, &[(k, 0)]), None);
        assert_eq!(q4_row_alias_offsets(k, 0, &[(k, ff)]), None);
        assert_eq!(q4_row_alias_offsets(0, ff, &[(0, ff)]), None);
        assert_eq!(q4_row_alias_offsets(k + 8, ff, &[(k + 8, ff)]), None);
        // 桁あふれ
        assert_eq!(
            q4_row_alias_offsets(k, usize::MAX, &[(k, usize::MAX / 2), (k, usize::MAX / 2 + 2)]),
            None
        );
    }

    /// 行オフセットは「1 行 = nb ブロック = nib 16B / sc 4B」の連続領域を指す。
    /// 27B の gate/up で、連結側の nib 上のオフセットが up_w の先頭行と一致すること
    /// をバイト数で確かめる (この値がずれると別の重みを読む)。
    #[test]
    fn alias_byte_offsets_match_row_stride() {
        let (k, ff) = (5120usize, 17408usize);
        let nb = k / 32;
        let nib_row = nb * 16;
        let sc_row = nb * 4;
        let rows = q4_row_alias_offsets(k, 2 * ff, &[(k, ff), (k, ff)]).expect("layout");
        assert_eq!(rows[0] * nib_row, 0);
        assert_eq!(rows[1] * nib_row, ff * nib_row);
        assert_eq!(rows[1] * sc_row, ff * sc_row);
        // up_w の nib は連結側の後半 (全 nib のちょうど半分) から始まる
        assert_eq!(ff * nib_row, (2 * ff * nb * 16) / 2);
    }

    /// s166 (P5): qkv 連結 GEMV の入口は、前提が崩れたら per-part 経路へ落ちる
    /// (fail closed・panic しない)。GPU 無しのこの環境ではどの場合も None になる
    /// — ここで固定するのは「形状不一致で連結側を選ばない」ことと「例外を投げない」
    /// こと (数値の一致は実機テストの担当)。
    #[test]
    fn q4_fused_linear_fails_closed() {
        use crate::quant::{next_q8_uid, Q4Linear};
        let k = 64usize;
        let (nq, nz) = (32usize, 16usize);
        let q = Q4Linear::quantize(&vec![0.01f32; k * nq], k, nq);
        let z = Q4Linear::quantize(&vec![0.02f32; k * nz], k, nz);
        let mut blocks = Vec::new();
        blocks.extend_from_slice(&q.blocks);
        blocks.extend_from_slice(&z.blocks);
        let fused = Q4Linear { blocks: blocks.into(), k, n: nq + nz, uid: next_q8_uid() };
        // 行数の和が合わない連結 (前提不一致) → per-part (GPU 無しなので None)
        let short = Q4Linear { blocks: q.blocks.clone(), k, n: nq, uid: next_q8_uid() };
        assert!(chain_linear_q4_fused(&short, &[&q, &z], 0, 1, 1).is_none());
        // part の k が食い違う → per-part
        let other_k = Q4Linear::quantize(&vec![0.03f32; 32 * nz], 32, nz);
        assert!(chain_linear_q4_fused(&fused, &[&q, &other_k], 0, 1, 1).is_none());
        // 正しい形でも GPU が無ければ None (panic しない)
        assert!(chain_linear_q4_fused(&fused, &[&q, &z], 0, 1, 1).is_none());
    }

    /// s169 (P10): GEMV の列ブロック幅 C を n から選ぶ純関数の契約。
    /// C は「1 block が何列を受けるか」だけを変えるので、どの C でも列ごとの
    /// k 方向の縮約順は不変 (数値は動かない)。ここで固定するのは
    /// 「既定 (mode 0) は必ず従来の base」「SM 数不明でも base」
    /// 「mode 1/3 の小さい投影だけ C=2」「mode 3 の大きい投影は C=8」の 3 点。
    #[test]
    fn gemv_shape_c_by_rows() {
        // RTX 5090 = 170 SM (27B 本番)。small = 64*170 = 10880, large = 128*170 = 21760
        let sm = 170usize;
        // 27B q4 の投影行数 (実形状)
        let rows = [1024usize, 5120, 14336, 16384, 34816, 151936];
        // mode 0 (既定) は常に base = 従来と同一の launch 形状
        for n in rows {
            assert_eq!(gemv_c_for_n(n, sm, 0, 4), 4, "mode 0 は base 固定: n={n}");
            assert_eq!(gemv_c_for_n(n, sm, 9, 4), 4, "未知 mode も base: n={n}");
        }
        // SM 数が取れない (0) ときは形状を変えない (fail closed)
        assert_eq!(gemv_c_for_n(5120, 0, 1, 4), 4);
        assert_eq!(gemv_c_for_n(5120, 0, 3, 4), 4);
        assert_eq!(gemv_c_for_n(0, sm, 1, 4), 4, "n=0 は何もしない");
        // mode 1: block 数が 2*SM を割る投影だけ C=2 (160 block -> 320 block)
        assert_eq!(gemv_c_for_n(1024, sm, 1, 4), 2);
        assert_eq!(gemv_c_for_n(5120, sm, 1, 4), 2);
        assert_eq!(gemv_c_for_n(10880, sm, 1, 4), 4, "境界は base のまま");
        assert_eq!(gemv_c_for_n(16384, sm, 1, 4), 4);
        assert_eq!(gemv_c_for_n(34816, sm, 1, 4), 4);
        // mode 2 は常に 2
        for n in rows {
            assert_eq!(gemv_c_for_n(n, sm, 2, 4), 2, "mode 2 は常に C=2: n={n}");
        }
        // mode 3 は小 2 / 中 base / 大 8
        assert_eq!(gemv_c_for_n(5120, sm, 3, 4), 2);
        assert_eq!(gemv_c_for_n(16384, sm, 3, 4), 4);
        assert_eq!(gemv_c_for_n(21760, sm, 3, 4), 8);
        assert_eq!(gemv_c_for_n(34816, sm, 3, 4), 8);
        assert_eq!(gemv_c_for_n(151936, sm, 3, 4), 8);
        // 選ばれた C は必ず PTX にある 3 本 (2/4/8) のどれか
        for mode in 0..=3u32 {
            for n in rows {
                let c = gemv_c_for_n(n, sm, mode, 4);
                assert!([2usize, 4, 8].contains(&c), "C={c} に対応する PTX が無い");
                // 列を落とさない (grid.x * 8*C >= n)
                assert!((8 * c) * n.div_ceil(8 * c) >= n);
            }
        }
    }

    /// s169 (P10): `DENNO_DECODE_DBG=1` の形状内訳の書式 (観測のみ)。
    #[test]
    fn gemv_dbg_format_lists_rows_and_c() {
        let t: DbgTally = vec![((34816usize << 4) | 4, 64u64), ((5120usize << 4) | 2, 128u64)];
        assert_eq!(dbg_fmt_gemv(&t), "34816/c4x64,5120/c2x128");
    }
}

#[cfg(test)]
mod p8_phase_tests {
    //! s169 (Task P8): prefill 残差常駐経路の位相計測の**表との対応**を固定する。
    //! GPU は使わない (イベントの実測は実機の担当) — ここで守るのは
    //! 「位相の名前 = 表 C の行名」「1 行を 2 つの位相が共有しない (二重計上しない)」
    //! 「残差加算は独立した行を持たない (融合している)」の 3 点。
    use super::*;

    #[test]
    fn pf_phase_buckets_match_serve_rows() {
        let mut seen: Vec<usize> = Vec::new();
        for ph in 0..PF_PH_N {
            let Some(op) = PF_PH_BUCKETS[ph] else {
                continue;
            };
            assert!(
                (crate::prof::SPLIT_SERVE_FIRST..crate::prof::SPLIT_SERVE_FIRST + crate::prof::SPLIT_SERVE_N)
                    .contains(&op),
                "位相 {ph} の bucket が表 C の範囲外"
            );
            let row = op - crate::prof::SPLIT_SERVE_FIRST;
            let name = crate::prof::split_row_name(crate::prof::SPLIT_SERVE_TABLE, row)
                .expect("位相の bucket は表 C の行");
            assert_eq!(name, PF_PH_NAMES[ph], "位相 {ph} の名前が表 C の行名と違う");
            assert!(!seen.contains(&op), "表 C の行を 2 つの位相が共有している: {name}");
            seen.push(op);
        }
        // GDN の o_proj だけは表 C に行を持たない (decode chain と同じ扱い)。
        assert_eq!(PF_PH_BUCKETS[PF_PH_GDN_OPROJ], None);
        assert_eq!(seen.len(), PF_PH_N - 1);
        // 残差加算は `dno_add_rmsnorm` に融合しているので独立した位相を持たない
        // (ホスト経路の `sl_lay_residual` に相当する区間は残差常駐経路に無い)。
        assert!(!seen.contains(&crate::prof::SL_LAY_RESIDUAL));
        assert!(PF_PH_NAMES.iter().all(|n| !n.contains("residual")));
    }
}

#[cfg(test)]
mod p55_gdn_pre_sm_tests {
    //! P55: pass 1 の状態配列を共有メモリへ置く版 (`dno_gdn_chunk_pre_sm`) を
    //! **選ぶゲート**の契約テスト (GPU 不要)。守るのは「カーネル不在 (PTX 未再
    //! 生成) / opt-in 失敗 / dk 過大 / dk != dv / env off のどれでも静かに旧
    //! カーネルへ落ちる」= fail-closed と、必要 smem が 48 KiB 既定を超えること。
    //! 数値の一致と速度は実機 (main) の担当。
    use super::*;

    /// dk=128 (qwen35 の GDN 実形状) の必要量。48 KiB 既定では載らず、
    /// A100 (164 KiB) / H100 (227 KiB) の opt-in 上限には収まること。
    #[test]
    fn gdn_pre_sm_smem_bytes_need_optin() {
        let need = gdn_pre_sm_smem_bytes(128);
        assert_eq!(need, (2 * 128 * 128 + 2 * 128 + 3) * 4);
        assert_eq!(need, 132_108);
        assert!(need > GDN_PRE_SM_SMEM_DEFAULT, "48 KiB 既定では載らない");
        assert!(need <= 164 * 1024, "A100 の opt-in 上限を超える");
        assert!(need <= 227 * 1024, "H100 の opt-in 上限を超える");
        // dk=64 は 48 KiB 既定に収まる (opt-in 不要の形が存在すること)。
        assert!(gdn_pre_sm_smem_bytes(64) <= GDN_PRE_SM_SMEM_DEFAULT);
        // dk=256 は opt-in 上限でも載らない (ゲートで落ちる側)。
        assert!(gdn_pre_sm_smem_bytes(256) > 227 * 1024);
    }

    /// ゲートの真理値表: 4 条件 (env / カーネル有無 / 形 / smem 上限) の
    /// どれか 1 つが欠けたら false = 旧カーネル。
    #[test]
    fn gdn_pre_sm_gate_contract() {
        let (dk, dv) = (128usize, 128usize);
        let need = gdn_pre_sm_smem_bytes(dk);
        let optin = 227 * 1024;
        assert!(gdn_pre_sm_gate(true, true, dk, dv, need, optin));
        // env off (既定) では常に旧カーネル
        assert!(!gdn_pre_sm_gate(false, true, dk, dv, need, optin));
        // PTX にカーネルが無い (未再生成) → 旧カーネル
        assert!(!gdn_pre_sm_gate(true, false, dk, dv, need, optin));
        // opt-in 失敗 (上限が 48 KiB 既定のまま) → 旧カーネル
        assert!(!gdn_pre_sm_gate(true, true, dk, dv, need, GDN_PRE_SM_SMEM_DEFAULT));
        // dk 過大 (共有メモリに載らない) → 旧カーネル
        assert!(!gdn_pre_sm_gate(
            true,
            true,
            256,
            256,
            gdn_pre_sm_smem_bytes(256),
            227 * 1024
        ));
        assert!(!gdn_pre_sm_gate(true, true, GDN_PRE_SM_MAX_DK + 1, GDN_PRE_SM_MAX_DK + 1, 0, optin));
        // dk != dv (chunked scan の前提外) → 旧カーネル
        assert!(!gdn_pre_sm_gate(true, true, 128, 64, need, optin));
        // dk = 0 は範囲外
        assert!(!gdn_pre_sm_gate(true, true, 0, 0, 0, optin));
        // dk=64 は 48 KiB 既定でも true (opt-in 不要の形)
        assert!(gdn_pre_sm_gate(
            true,
            true,
            64,
            64,
            gdn_pre_sm_smem_bytes(64),
            GDN_PRE_SM_SMEM_DEFAULT
        ));
    }
}

#[cfg(test)]
mod p2_residual_tests {
    //! s165 (Task P2): prefill の残差ストリームをデバイス常駐させる経路の**入口条件**
    //! だけを固定する。GPU は使わない (純粋関数の契約テスト) — 数値の一致と速度は
    //! 実機 (main セッション) の担当。ここで None になる条件がそのまま
    //! 「この層は従来のホスト経路で通す」契約になる。
    use super::*;

    fn q4(k: usize, n: usize) -> crate::quant::Linear {
        crate::quant::Linear::Q4(crate::quant::Q4Linear { blocks: Vec::new().into(), k, n, uid: 0 })
    }
    fn f32w(k: usize, n: usize) -> crate::quant::Linear {
        crate::quant::Linear::F32 { w: vec![0.0; k * n], k, n }
    }

    /// グローバルゲート: q4 以外・診断中・GEMV 帯域・端数タイル・smem 超過で発動しない。
    #[test]
    fn pf_res_gate_contract() {
        let (gm, mm) = (256usize, 16usize);
        // 基準: 2048 token・e=5120 (端数タイル無し)
        assert!(pf_res_gate(2048, 5120, true, false, gm, mm));
        // q4 でない層が 1 本でもあれば発動しない
        assert!(!pf_res_gate(2048, 5120, false, false, gm, mm));
        // 層別診断 (lchk) 中はホストの x を層ごとに更新する前提 → 発動しない
        assert!(!pf_res_gate(2048, 5120, true, true, gm, mm));
        // GEMM 帯域の外 (m <= max_m() / m < gemm_min_m()) は発動しない
        assert!(!pf_res_gate(16, 5120, true, false, gm, mm));
        assert!(!pf_res_gate(128, 5120, true, false, gm, mm));
        assert!(!pf_res_gate(0, 5120, true, false, gm, mm));
        // dno_add_rmsnorm の動的 shmem (e*4 <= 48KB) と e % 32 == 0
        assert!(!pf_res_gate(2048, 16384, true, false, gm, mm), "e=16384 は smem 48KB 超");
        assert!(!pf_res_gate(2048, 5000, true, false, gm, mm), "e % 32 != 0");
        // 端数タイルが GEMV 帯域 (<= max_m()) に入る形は受けない
        let rem_small = GDN_PREFILL_TILE * 2 + mm;
        assert!(!pf_res_gate(rem_small, 5120, true, false, gm, mm));
        assert!(pf_res_gate(rem_small + 1, 5120, true, false, gm, mm));
        assert!(pf_res_gate(GDN_PREFILL_TILE * 2, 5120, true, false, gm, mm));
    }

    /// 層ゲート: FFN / full attention / GDN の形が揃ったときだけ Some。
    #[test]
    fn pf_layer_geom_contract() {
        let (gm, mm) = (256usize, 16usize);
        let n = 2048usize;
        let e = 64usize;
        let ff = 128usize;
        // full attention: heads=2, kv_heads=1, dh=32 → att=64, kv_dim=32
        let (heads, kv_heads, dh) = (2usize, 1usize, 32usize);
        let (att, kv_dim) = (heads * dh, kv_heads * dh);
        let gate = q4(e, ff);
        let up = q4(e, ff);
        let down = q4(ff, e);
        let d = PfDims {
            n,
            e,
            heads,
            kv_heads,
            dh,
            nk: 1,
            nv: 1,
            dk: 32,
            dv: 32,
            d_conv: 4,
        };
        let (q, k, v, o) = (q4(e, att * 2), q4(e, kv_dim), q4(e, kv_dim), q4(att, e));
        let full = PfAttnW::Full { q: &q, k: &k, v: &v, o: &o };
        assert!(pf_layer_geom(&full, &gate, &up, &down, &d, gm, mm).is_some(), "基準形は通る");

        // FFN が q4 でない / 形が合わない → 受けない
        assert!(pf_layer_geom(&full, &f32w(e, ff), &up, &down, &d, gm, mm).is_none());
        assert!(pf_layer_geom(&full, &gate, &up, &q4(e, ff + 32), &d, gm, mm).is_none());
        assert!(pf_layer_geom(&full, &gate, &up, &q4(ff, e + 32), &d, gm, mm).is_none());

        // o_proj の k が heads*dh でない / q の n が 2*heads*dh でない → 受けない
        let bad_o = q4(att + 32, e);
        let full_bad = PfAttnW::Full { q: &q, k: &k, v: &v, o: &bad_o };
        assert!(pf_layer_geom(&full_bad, &gate, &up, &down, &d, gm, mm).is_none());
        let bad_q = q4(e, att);
        let full_bad = PfAttnW::Full { q: &bad_q, k: &k, v: &v, o: &o };
        assert!(pf_layer_geom(&full_bad, &gate, &up, &down, &d, gm, mm).is_none());

        // GDN 層: qkv/z/o の形が揃えば通り、dk != dv では受けない
        //   conv_dim = nk*dk*2 + nv*dv = 64 + 32 = 96, vd = 32
        let gqkv = q4(e, 96);
        let gz = q4(e, 32);
        let go = q4(32, e);
        let gdn = PfAttnW::Gdn { qkv: &gqkv, z: &gz, o: &go };
        assert!(pf_layer_geom(&gdn, &gate, &up, &down, &d, gm, mm).is_some());
        let mut d2 = PfDims { n, e, heads, kv_heads, dh, nk: 1, nv: 1, dk: 32, dv: 32, d_conv: 4 };
        d2.dv = 16;
        assert!(pf_layer_geom(&gdn, &gate, &up, &down, &d2, gm, mm).is_none(), "dk != dv は受けない");

        // n が GEMV 帯域 → 層としても受けない
        let mut d3 = PfDims { n: mm, e, heads, kv_heads, dh, nk: 1, nv: 1, dk: 32, dv: 32, d_conv: 4 };
        assert!(pf_layer_geom(&full, &gate, &up, &down, &d3, gm, mm).is_none());
        d3.n = n;
        assert!(pf_layer_geom(&full, &gate, &up, &down, &d3, gm, mm).is_some());
    }

    /// 新スロットは既存と衝突せず、チェーン本数に収まる。
    #[test]
    fn pf_res_slot_is_distinct() {
        let used = [
            CH_X, CH_H, CH_QKV, CH_ATT, CH_O, CH_GA, CH_ACT, CH_DOWN, CH_LOGITS, CH_Q35_Q, CH_PFH,
        ];
        assert!(!used.contains(&CH_PF_RES), "CH_PF_RES は既存スロットと別");
        assert!(CH_PF_RES < CH_SLOTS);

    }
}

#[cfg(test)]
mod p6_overlap_tests {
    //! s167 (Task P6): GDN prefill の h2 D2H を専用コピーストリームで qkv/z GEMM と
    //! 重ねる経路の**入口条件とフォールバック**だけを固定する (GPU 非依存の契約
    //! テスト)。数値の一致・速度は実機の担当。
    //!
    //! ここで固定する契約:
    //!   - フラグは既定 ON (s172/P13)。明示的な "0"/"off"/"false" だけが OFF
    //!     (= 従来の直列経路)
    //!   - stream/event/pinned の準備に失敗したら必ず従来の同期 D2H (`SyncD2h`)
    //!   - 形が不正・桁あふれ・0 バイトでも従来経路 (コピーを発行しない)
    use super::*;

    /// s172 (P13): `DENNO_PF_OVERLAP` は**既定 ON**。明示的な偽値だけが OFF。
    #[test]
    fn pf_overlap_flag_defaults_on() {
        assert!(parse_pf_overlap(None), "未設定は ON (gdn_proj のホスト仕事を GEMM の裏に隠す)");
        for raw in ["", "1", "true", "on", "yes", " 1", "TRUE"] {
            assert!(parse_pf_overlap(Some(raw)), "raw={raw:?} は ON のはず");
        }
        for raw in ["0", "off", "false"] {
            assert!(!parse_pf_overlap(Some(raw)), "raw={raw:?} は OFF (従来と同一経路) のはず");
        }
    }

    /// 経路決定: OFF とデバイス準備失敗は**必ず**従来の同期 D2H。
    #[test]
    fn pf_h2_path_falls_back_to_sync() {
        let (n, e) = (12850usize, 4096usize);
        // フラグ OFF: dev_ready が真でも従来経路
        assert_eq!(pf_h2_path(false, n, e, true), PfH2Path::SyncD2h);
        assert_eq!(pf_h2_path(false, n, e, false), PfH2Path::SyncD2h);
        // フラグ ON でも準備失敗 (stream/event/pinned) なら従来経路
        assert_eq!(pf_h2_path(true, n, e, false), PfH2Path::SyncD2h);
        // フラグ ON + 準備成功 + 妥当な形 → コピーストリーム
        assert_eq!(pf_h2_path(true, n, e, true), PfH2Path::CopyStream);
    }

    /// 形が不正 (0・桁あふれ) なら従来経路 — コピーを発行しない。
    #[test]
    fn pf_h2_path_rejects_bad_shape() {
        assert_eq!(pf_h2_path(true, 0, 4096, true), PfH2Path::SyncD2h);
        assert_eq!(pf_h2_path(true, 12850, 0, true), PfH2Path::SyncD2h);
        assert_eq!(pf_h2_path(true, 0, 0, true), PfH2Path::SyncD2h);
        // n*e は通るが *4 で桁あふれ → 従来経路 (checked_mul)
        assert_eq!(
            pf_h2_path(true, usize::MAX / 2, 2, true),
            PfH2Path::SyncD2h
        );
        assert_eq!(pf_h2_path(true, usize::MAX, 2, true), PfH2Path::SyncD2h);
        // 1 行だけでも (実経路では n >= 2048 だが) 判定としてはコピー経路
        assert_eq!(pf_h2_path(true, 1, 1, true), PfH2Path::CopyStream);
    }
}

/// s246 (P46): full 層 att の「チャンク化しても数値が動かない」契約を固定する。
///
/// GPU は使わない (転送そのものは実機の担当)。ここで守るのは
///   1. チャンク境界が `[0, m)` を隙間なく・重複なく覆う (端数行を捨てない)
///   2. チャンク数を増やしても**ゲート後の配列がビット一致**する
///      (= `gate(row0, ブロック)` の行オフセット算術が正しい)
///   3. 小さい転送・フラグ OFF ではチャンク数 1 = 従来の 1 発往復
/// の 3 点。2 が崩れると「チャンクを跨いだ行で qg の別の head のゲートを読む」
/// という静かな誤りになるので、行数 × チャンク数の格子で全部見る。
#[cfg(test)]
mod p46_att_pipe_tests {
    use super::*;
    use rayon::prelude::*;

    /// 本番のクロージャ (`full_attn_att_inplace` の呼び出し側) と同一の式。
    fn gate_rows(row0: usize, v: &mut [f32], qg: &[f32], heads: usize, dh: usize) {
        v.par_chunks_exact_mut(dh)
            .enumerate()
            .for_each(|(t, att_head)| {
                let tt = row0 * heads + t;
                let i = tt / heads;
                let hh = tt % heads;
                let gate = &qg[i * heads * 2 * dh + hh * 2 * dh + dh..][..dh];
                for (d, av) in att_head.iter_mut().enumerate() {
                    *av /= 1.0 + (-gate[d]).exp();
                }
            });
    }

    /// 1. 境界の被覆性 (端数行を含めて [0, m) を 1 回ずつ)。
    #[test]
    fn att_pipe_chunk_bounds_cover_rows_once() {
        for m in [1usize, 2, 3, 7, 8, 9, 1000, 6251, 25000, 65000] {
            for want in [1usize, 2, 3, 4, 5, 8, 16] {
                let (rows_per, nch) = pf_att_chunk_rows(m, want);
                assert!(nch >= 1, "m={m} want={want}");
                assert!(rows_per >= 1, "m={m} want={want}: rows_per=0");
                if want >= 2 && m >= 2 {
                    assert!(nch >= 2, "m={m} want={want}: 1 発に落ちた");
                    assert!(nch <= want, "m={m} want={want}: 上限を超えた nch={nch}");
                } else {
                    assert_eq!(nch, 1, "m={m} want={want}: 1 発のはず");
                }
                // 全チャンクを並べると [0, m) を隙間なく 1 回ずつ覆う
                let mut next = 0usize;
                for k in 0..nch {
                    let (r0, r1) = pf_att_chunk_bounds(k, rows_per, m);
                    assert_eq!(r0, next, "m={m} want={want} k={k}: 隙間/重複");
                    assert!(r1 > r0, "m={m} want={want} k={k}: 空チャンク");
                    next = r1;
                }
                assert_eq!(next, m, "m={m} want={want}: 端数行が落ちた");
            }
        }
    }

    /// 2. チャンク数が変わってもゲート結果はビット一致。
    #[test]
    fn att_pipe_gate_is_bit_exact_across_chunk_counts() {
        // 実シェイプの縮小版 (heads=4 / dh=8)。行数は端数が出るものを含める。
        let (heads, dh) = (4usize, 8usize);
        let cols = heads * dh;
        for n in [1usize, 2, 3, 5, 8, 13] {
            let qg: Vec<f32> = (0..n * heads * 2 * dh)
                .map(|i| ((i as f32) * 0.017).sin() * 3.0)
                .collect();
            let att0: Vec<f32> = (0..n * cols)
                .map(|i| ((i as f32) * 0.031).cos() * 1.5)
                .collect();
            // 従来 (1 発 = 全体を 1 回)
            let mut want = att0.clone();
            gate_rows(0, &mut want[..], &qg, heads, dh);
            // チャンク版 (2..=n の全分割)
            for want_nch in 1..=n.max(1) {
                let (rows_per, nch) = pf_att_chunk_rows(n, want_nch);
                let mut got = att0.clone();
                for k in 0..nch {
                    let (r0, r1) = pf_att_chunk_bounds(k, rows_per, n);
                    gate_rows(r0, &mut got[r0 * cols..r1 * cols], &qg, heads, dh);
                }
                for (idx, (a, b)) in want.iter().zip(got.iter()).enumerate() {
                    assert_eq!(
                        a.to_bits(),
                        b.to_bits(),
                        "n={n} nch={nch} rows_per={rows_per}: 要素 {idx} が不一致"
                    );
                }
            }
        }
    }

    /// 3. 小さい転送・フラグ OFF・1 行は従来の 1 発往復。
    #[test]
    fn att_pipe_chunks_off_for_small_or_disabled() {
        // 128 MiB 未満は 1 発 (PCIe の立上がりを払う方が高い)
        assert_eq!(pf_att_pipe_chunks_with(64 << 20, 25000, 8), 1);
        assert_eq!(pf_att_pipe_chunks_with((128 << 20) - 4, 25000, 8), 1);
        // フラグ OFF (= 上限 1) は常に 1 発
        assert_eq!(pf_att_pipe_chunks_with(615 << 20, 25000, 1), 1);
        assert_eq!(pf_att_pipe_chunks_with(615 << 20, 25000, 0), 1);
        // 1 行では割れない
        assert_eq!(pf_att_pipe_chunks_with(615 << 20, 1, 8), 1);
        // 65k (att = n*heads*dh*4 = 1597 MB) は上限 8 に張り付く
        assert_eq!(pf_att_pipe_chunks_with(1597 << 20, 65000, 8), 8);
        // 615 MB (n≈25k) は 5 チャンク
        assert_eq!(pf_att_pipe_chunks_with(615 << 20, 25000, 8), 5);
        // 上限を下げれば従う
        assert_eq!(pf_att_pipe_chunks_with(1597 << 20, 65000, 4), 4);
        assert_eq!(pf_att_pipe_chunks_with(1597 << 20, 65000, 2), 2);
    }
}

#[cfg(test)]
mod p53_qk_overlap_tests {
    //! s250 (Task P53): full_qk の q の D2H を専用コピーストリームで k/v の GEMM と
    //! 重ねる経路の**入口条件**だけを固定する (GPU 非依存)。速度と数値一致は実機の担当。
    //!
    //! ここで固定する契約:
    //!   - `DENNO_PF_QK_OVERLAP` は既定 ON。明示的な "0"/"off"/"false" だけが OFF
    //!     (= 従来の既定ストリーム直列)
    //!   - OFF・driver API 欠落・stream/event 作成失敗は `None` を返し、呼び出し側は
    //!     null ストリーム (= 従来経路) で 3 発を流す
    use super::*;

    /// 既定 ON・明示的な偽値だけが OFF (P6 の `DENNO_PF_OVERLAP` と同じ規約)。
    #[test]
    fn pf_qk_overlap_flag_defaults_on() {
        assert!(parse_pf_qk_overlap(None), "未設定は ON");
        for raw in ["", "1", "true", "on", "yes", " 1", "TRUE"] {
            assert!(parse_pf_qk_overlap(Some(raw)), "raw={raw:?} は ON のはず");
        }
        for raw in ["0", "off", "false"] {
            assert!(
                !parse_pf_qk_overlap(Some(raw)),
                "raw={raw:?} は OFF (既定ストリーム直列) のはず"
            );
        }
    }

    /// 65k 級 27B (n=14,043・qcols=12,288・kcols=vcols=1,024) の 1 層あたりの
    /// D2H バイト数と、隠せる量の算術を固定する。
    ///
    /// ここが崩れると REPORT_P53.md の見積り (q の D2H ≈48 ms/層・k/v の
    /// GEMM ≈9.8 ms/層 → ≈0.16 s/request、上限 0.29 s) の前提が崩れる。
    #[test]
    fn pf_qk_d2h_bytes_match_27b_shape() {
        let (rows, qcols, kcols, vcols) = (14_043usize, 12_288usize, 1_024usize, 1_024usize);
        let q_bytes = rows * qcols * 4;
        let k_bytes = rows * kcols * 4;
        let v_bytes = rows * vcols * 4;
        // 690.2 MB / 57.5 MB / 57.5 MB
        assert_eq!(q_bytes, 690_241_536);
        assert_eq!(k_bytes, 57_520_128);
        assert_eq!(v_bytes, 57_520_128);
        assert_eq!(q_bytes + k_bytes, 747_761_664, "P47 の pinned プール (747 MB)");
        assert_eq!(q_bytes + k_bytes + v_bytes, 805_281_792, "1 層の D2H 合計");
        // 実測単価 14.3 GB/s (s68) での q のコピー時間 ≈48 ms/層
        let q_ms = q_bytes as f64 / 14.3e9 * 1e3;
        assert!((47.0..50.0).contains(&q_ms), "q の D2H が {q_ms} ms/層");
        // 16 full 層ぶんの q は ≈0.77 s (このうち k/v の GEMM+D2H の分だけが隠れる)
        let q_all = q_ms * 16.0;
        assert!((760.0..790.0).contains(&q_all), "q の D2H 合計が {q_all} ms");
    }
}

// ---------------------------------------------------------------------------
// P58-3: prefill スクラッチ arena の検証 (GPU 不要・ホストだけで回る)
// ---------------------------------------------------------------------------
#[cfg(test)]
mod p58_scratch_arena_tests {
    use super::*;

    /// task 149: リクエスト終了時の解放は既定 off (lab で効果が無かったため)。
    #[test]
    fn scratch_free_env_gate() {
        assert!(!parse_scratch_free(None), "未設定 = off (従来どおり保持)");
        assert!(!parse_scratch_free(Some("0")));
        assert!(!parse_scratch_free(Some("false")));
        assert!(!parse_scratch_free(Some("OFF")));
        assert!(parse_scratch_free(Some("1")));
        assert!(parse_scratch_free(Some(" true ")));
        assert!(parse_scratch_free(Some("on")));
    }

    /// 27B q4・n=14,240 の prefill で実際に切り出される 12 スロット
    /// (`chain_ensure_buf` が要求するバイト数と同じ式)。
    fn chain_slot_bytes(rows: usize) -> [usize; 12] {
        let e = 5120usize;
        let hd = 6144usize; // heads*dh
        let qcols = 12288usize; // q (attn_output_gate 込み)
        let kcols = 1024usize;
        let vcols = 1024usize;
        let ff = 17408usize;
        let vocab = 248_320usize;
        [
            rows * e * 4,                        // CH_X
            rows * e * 4,                        // CH_H
            rows * (qcols + kcols + vcols) * 4,  // CH_QKV
            rows * hd * 4,                       // CH_ATT
            rows * hd * 4,                       // CH_O
            rows * 2 * ff * 4,                   // CH_GA
            rows * ff * 4,                       // CH_ACT
            rows * e * 4,                        // CH_DOWN
            vocab * 4,                           // CH_LOGITS (decode のみ)
            rows * hd * 4,                       // CH_Q35_Q
            rows * e * 4,                        // CH_PFH
            rows * e * 4,                        // CH_PF_RES
        ]
    }

    /// 2 回連続の「forward 相当の確保」で 2 回目が同じオフセットを返すこと
    /// (要求 4)。これが arena 化の本体の契約。
    #[test]
    fn arena_plan_second_forward_reuses_same_offsets() {
        let rows = 14_240usize;
        let sizes = chain_slot_bytes(rows);
        let mut plan = ArenaPlan::default();
        plan.add_chunk(ARENA_CHUNK * 8);
        let mut first = Vec::new();
        for (i, b) in sizes.iter().enumerate() {
            let (c, off) = plan.reserve(0, ARENA_KEY_CHAIN + i as u32, *b).expect("1 回目");
            first.push((c, off));
        }
        let mut second = Vec::new();
        for (i, b) in sizes.iter().enumerate() {
            let (c, off) = plan.reserve(0, ARENA_KEY_CHAIN + i as u32, *b).expect("2 回目");
            second.push((c, off));
        }
        assert_eq!(first, second, "2 回目は同じオフセットを返す (再利用)");
        // 予約は重ならない
        let mut used: Vec<(usize, usize, usize)> = first
            .iter()
            .zip(sizes.iter())
            .map(|((c, off), b)| (*c, *off, off + ArenaPlan::align_up(*b)))
            .collect();
        used.sort();
        for w in used.windows(2) {
            assert!(
                w[0].0 != w[1].0 || w[0].2 <= w[1].1,
                "チャンク {} で予約が重なった: {:?}",
                w[0].0,
                w
            );
        }
    }

    /// 実測の「要求 779 MiB」の正体が CH_QKV であること (n で 1 意に決まる)。
    /// 57,344 B/行 なので 779 MiB になるのは n = 14,245..14,262 の範囲だけ
    /// (CH_GA は 1,892 MiB・CH_ACT は 946 MiB で一致しない)。
    #[test]
    fn arena_qkv_matches_reported_779_mib() {
        let rows = 14_252usize;
        let b = chain_slot_bytes(rows)[CH_QKV];
        assert_eq!(b, rows * 57_344, "CH_QKV = 行 x (q 12,288 + k/v 各 1,024) x 4 B");
        assert_eq!(b >> 20, 779, "実測の 779 MiB 要求と一致");
    }

    /// 同じキーで大きいサイズを要求したら別の位置へ移る (古い領域は再利用しない)。
    #[test]
    fn arena_plan_larger_request_moves_to_new_offset() {
        let mut plan = ArenaPlan::default();
        plan.add_chunk(ARENA_CHUNK);
        let (c0, o0) = plan.reserve(0, 7, 1000).unwrap();
        let (c1, o1) = plan.reserve(0, 7, 4000).unwrap();
        assert_eq!((c0, o0), (0, 0));
        assert_eq!((c1, o1), (0, ArenaPlan::align_up(1000)));
        // 小さいサイズへ戻しても予約は移らない (同じ位置を使い回す)
        let (c2, o2) = plan.reserve(0, 7, 1000).unwrap();
        assert_eq!((c2, o2), (c1, o1));
    }

    /// 足りないときは「必要なチャンクのバイト数」を返し、状態は変えない。
    #[test]
    fn arena_plan_reports_chunk_bytes_without_mutating() {
        let mut plan = ArenaPlan::default();
        let want = plan.reserve(0, 1, 4096).unwrap_err();
        assert_eq!(want, ARENA_CHUNK, "チャンクは 1,024 MiB 単位");
        assert!(plan.chunks.is_empty() && plan.slots.is_empty());
        plan.add_chunk(want);
        assert_eq!(plan.reserve(0, 1, 4096).unwrap(), (0, 0));
        // 1 GiB を超える要求は切り上げたチャンク 1 本で受ける
        let big = ARENA_CHUNK + 1;
        assert_eq!(plan.reserve(0, 2, big).unwrap_err(), ARENA_CHUNK * 2);
    }

    /// オフセットは 256 B に揃える。
    #[test]
    fn arena_plan_aligns_offsets() {
        let mut plan = ArenaPlan::default();
        plan.add_chunk(ARENA_CHUNK);
        let (_, a) = plan.reserve(0, 1, 1).unwrap();
        let (_, b) = plan.reserve(0, 2, 3).unwrap();
        let (_, c) = plan.reserve(0, 3, 257).unwrap();
        assert_eq!((a, b, c), (0, 256, 512));
        for off in [a, b, c] {
            assert_eq!(off % ARENA_ALIGN, 0);
        }
    }

    /// スレッドが違えば同じキーでも別の領域 (thread_local スロットの衝突防止)。
    #[test]
    fn arena_plan_separates_threads() {
        let mut plan = ArenaPlan::default();
        plan.add_chunk(ARENA_CHUNK);
        let (_, a) = plan.reserve(0, ARENA_KEY_Q4_X, 4096).unwrap();
        let (_, b) = plan.reserve(1, ARENA_KEY_Q4_X, 4096).unwrap();
        assert_ne!(a, b);
        assert_eq!((a, b), (0, 4096));
        // 同じスレッドの別キーも別の領域
        let (_, c) = plan.reserve(0, ARENA_KEY_Q4_OUT, 4096).unwrap();
        assert_eq!(c, 8192);
    }

    /// 境界の切り直しでチャンクを残すときは先頭から使い直す。
    #[test]
    fn arena_plan_reset_keep_chunks_restarts_at_zero() {
        let mut plan = ArenaPlan::default();
        plan.add_chunk(ARENA_CHUNK);
        plan.reserve(0, 1, 8192).unwrap();
        plan.reset_keep_chunks();
        assert_eq!(plan.capacity(), ARENA_CHUNK);
        assert_eq!(plan.reserve(0, 1, 8192).unwrap(), (0, 0));
    }

    /// 境界の推定: 前回の 1 行あたり使用量から今回の必要量を出す。
    #[test]
    fn arena_target_scales_with_rows() {
        // 前回 rows=2000 で 800 MiB 使った → 14,240 行なら ≈5.7 GiB (1 GiB 切り上げ)
        let prev_high = 800usize << 20;
        let t = ArenaPlan::target_for(2000, prev_high, 14_240);
        let per_row = prev_high / 2000 + 1;
        let want = per_row * 14_240 * 11 / 10;
        assert_eq!(t, want.saturating_add(ARENA_CHUNK - 1) & !(ARENA_CHUNK - 1));
        assert!(t >= want, "推定は要求以上");
        assert_eq!(t % ARENA_CHUNK, 0, "1 GiB 単位");
        // 行数が増えれば単調に増える
        assert!(ArenaPlan::target_for(2000, prev_high, 28_000) > t);
        // 実績が無ければ推定しない (0)
        assert_eq!(ArenaPlan::target_for(0, 0, 14_240), 0);
        assert_eq!(ArenaPlan::target_for(2000, 0, 14_240), 0);
        assert_eq!(ArenaPlan::target_for(2000, prev_high, 0), 0);
    }

    /// `DENNO_SCRATCH_ARENA` の解釈 (未設定 = 有効)。
    #[test]
    fn arena_env_gate() {
        assert!(parse_scratch_arena(None));
        assert!(parse_scratch_arena(Some("1")));
        assert!(parse_scratch_arena(Some("true")));
        assert!(!parse_scratch_arena(Some("0")));
        assert!(!parse_scratch_arena(Some(" 0 ")));
        assert!(!parse_scratch_arena(Some("false")));
        assert!(!parse_scratch_arena(Some("off")));
    }
}


// ---------------------------------------------------------------------------
// task 128: GDN (qwen4exp) decode の GPU 常駐スキャン (DENNO_GDN_GPU_SCAN)
// ---------------------------------------------------------------------------
//
// br114 (a4a0c617f) の設計を int-auto の API (`CudaCtx::plan_moe_gemv` +
// `launch_async`) へ移植したもの。1 トークン 1 層ぶんの
//   [qkv(+z) の GEMV] → [dno_gdn_scan_sig] → [attn_out の GEMV]
// を 1 つの submission にまとめ、層の状態 (conv / ssm) をデバイス常駐にする
// (デバイスが正本。ホスト `SsmLayer::state` は 1 トークン以上古い)。
//
// バッファの中身 (token 1 / token 2 の各段階。REPORT_P128.md と対):
//   x      [n_embd]            層入力 (ホスト→H2D、毎トークン)
//   qkv    [qkv_total]         [qkv 行 | z 行] の 1 本 (GEMV 出力。毎トークン)
//   ba     [2*nv]              [beta | alpha] (CPU F32 GEMV → H2D、毎トークン)
//   conv   [conv_dim][cs]      cs = d_conv-1 = 3。**ping-pong 2 面**。
//                              q/k チャネルは nk < nv のとき複数の v-head が
//                              同じチャネルを読むので in-place にできない。
//   ssm    [nv][dk][dv]        1 面。各スレッドが自分の列を先頭で全読みして
//                              から書くので in == out で安全。
//   y      [nv*dv]             scan 出力 (gate 済み)
//   out    [n_embd]            attn_out GEMV の出力 (= 層出力)
//
// ホスト state との契約:
//   (a) デバイスが正の間ホストは古い。CPU 経路が state を読む前に必ず
//       [`gdn_decode_state_take`] (同期 D2H) で回復する。
//   (b) ホスト側で state を書き換えたら (reset / spec_restore) 必ず
//       [`gdn_decode_state_invalidate`] でデバイスを無効化する。
//       **task 128 の修正点**: br114 は reset でこれを落としていた。モデル
//       使い回し (`DENNO_FLASH_MODEL_REUSE=1`) で前置きが変わると reset が走り、
//       次の prefill の take が **前のリクエストの状態** をホストへ戻すため、
//       全トークンが同じ壊れ方をする (安定 md5 の `!!!!`)。
//   (c) ホストが正のときだけシード (H2D) する。
//
// 失敗はすべて fail-closed (`out: None` → 呼び出し側は CPU 経路)。
// scan を発行した後の失敗だけは状態を回復して返し、回復も失敗したら poisoned
// (呼び出し側は要求を落とす)。
//
// **task 137 で解消**: このカーネル `dno_gdn_scan_sig` (gdn.cu の sigmoid
// 出力ゲート版) を gdn.cu へ追加し、`kernels_gdn.ptx` を再生成した
// (再生成前の PTX は gdn.cu より古く、P55 の `dno_gdn_chunk_pre_sm` も
// 未収録だった)。旧 PTX を読んだ場合だけ `CudaCtx::f_gdn_scan_sig` が None に
// なり、この経路は発動しない (計測を 1 つも積まずに CPU 経路)。
// **task 140 のラボ (t140a) で確認**: 今の gdn.cu から nvcc で再生成した
// `kernels_gdn.ptx` は、コミット済みのものと byte 一致 (9965 行 /
// md5 b580964cfe78ad8d10beab3b7682ea3c)。つまり t137c が使った PTX は
// 正しい再生成物であり、当時の 700 は PTX ではなくホスト側のバグだった。
//
// **task 137 のラボ (t137c) で分かった残件**: 経路は発動し、数値も合う
// (tok=1 の層 0..9 で maxabs out <= 1.8e-7 / conv 0 / ssm <= 2.4e-7、出力
// テキストの md5 は CPU と同一) が、**最初の decode トークンの直後の
// submission で CUDA error 700** になり、ラッチで以後 CPU に落ちる。
//
// **task 140 で原因を特定**: 700 は `qkv_gemv[0]` (li=41 tok=1) で起きていた。
// `gdn_qkv_units` が GEMV の出力行オフセットに `FusedLinear::range(i).start` を
// 使っていたのが誤りで、連結済みの qkv_gate では単位 = 連結バッファ全体
// (先頭から書く) なのに、gate が qkv より前に置かれた層 (写しなし連結が
// ファイル順を `ranges` に保存するため `range(0).start = 6144`) では
// 16384 行を 6144 行目から書いて **e.qkv の終端を 24 KiB 越えて**いた
// (ラボのダンプで li=13/38/41/46 が該当)。同じ層が 41 番目で初めて
// 未マップの VA に当たり 700 → ラッチ、以後 129% 遅い状態になっていた。
// 修正後 (t140b/t140c) は errors 0・md5 SAME・テキスト正常で、
// 短 decode -1.9%、2k 文脈 -4.2..-4.8% (t140c の VERDICT)。
// ただしタスクの採否目標 (短 decode 3% 以上) に届かないので**既定 off のまま**。
//
// **task 142 で既定 on にした**: 上の目標 (短 decode 3%) は「利得が文脈長で
// 伸びる」ことを知る前に置かれたものだった。文脈 2k / 8k で目標を取り直し、
// int-auto 065cf20 (task 141 まで) に br140 をマージした t142a で
// 短 -5.1% / c2000 next -5.6% / c8000 next -6.7% / prefill 2% 以内 /
// errors 0 / md5 6 本 SAME を確認した (詳細は [`gdn_gpu_scan_on`] の doc)。

/// task 142 のラボ (t142a) で採否目標を満たしたので**既定 on**。
/// `DENNO_GDN_GPU_SCAN=0|off|false|no` で off に戻せる (未設定・空は on)。
///
/// t142a (int-auto 065cf20 + task 141 までのマージ、depth8k、PROFILE=1、2 ラウンド交互):
/// decode は短 -5.1%、c2000 next turn -5.6%、c8000 next turn -6.7%、prefill は
/// -0.7%..+1.5% (全て 2% 以内)、errors 0、md5 は 6 本とも SAME。q4prof の gdn 項目は
/// on で +116 ms/128tok (短)・+103 (c2000)・+12 (c8000) と増えるが、これは GPU scan の
/// 待ちが attn.gate に移り、qkv/out の GEMV が同じ submission に入るため (層 wall は
/// 短 -4.2%、c2000 -4.5%、c8000 -6.9%)。
///
/// t142b (既定 on 版の確認、def vs `DENNO_GDN_GPU_SCAN=0`): def が全 5 点で off 以上
/// (短 -3.8%、c2000_cold -3.7%、c2000_turn2 -1.3%、c8000 -5.6%)、errors 0、md5 SAME。
/// c2000_turn2 の 1.3% は 2 ラウンド目が同値でノイズ帯 (<2%)。prefill は
/// -0.4..-2.0% で t142a と符号が逆 (ノイズ)。
///
/// off のときは `SsmLayer::forward_token` / `forward_batch` / `reset_state` の分岐
/// (この static read) 以外に何も変わらない。テストは
/// [`gdn_gpu_scan_set_for_test`] で env 無しに on/off を強制できる
/// (env はプロセスで 1 回しか読めないため)。
pub fn gdn_gpu_scan_on() -> bool {
    #[cfg(test)]
    match GDN_GPU_SCAN_FORCE.load(std::sync::atomic::Ordering::Relaxed) {
        1 => return true,
        2 => return false,
        _ => {}
    }
    static ON: OnceLock<bool> = OnceLock::new();
    *ON.get_or_init(|| parse_gdn_gpu_scan(std::env::var("DENNO_GDN_GPU_SCAN").ok().as_deref()))
}

/// `DENNO_GDN_GPU_SCAN` の生値 → on/off (純関数)。**未設定は on** (task 142 で採用)。
/// 明示的な `0|off|false|no` (前後空白と大小文字は無視) だけ off。
fn parse_gdn_gpu_scan(raw: Option<&str>) -> bool {
    match raw {
        None => true,
        Some(v) => {
            let v = v.trim().to_ascii_lowercase();
            !matches!(v.as_str(), "0" | "off" | "false" | "no")
        }
    }
}

/// テスト強制の値 (0 = env の解釈、1 = 強制 on、2 = 強制 off)。
#[cfg(test)]
static GDN_GPU_SCAN_FORCE: std::sync::atomic::AtomicU8 =
    std::sync::atomic::AtomicU8::new(0);

/// テストが env を立てずにゲートを強制する (`true` = 強制 on、`false` = 強制 off)。
///
/// 既定が on になったので、off 経路を見るテストは `false` で明示的に落とす。
#[cfg(test)]
pub fn gdn_gpu_scan_set_for_test(v: bool) {
    GDN_GPU_SCAN_FORCE.store(if v { 1 } else { 2 }, std::sync::atomic::Ordering::Relaxed);
}

/// テストが強制を解除して env の解釈 (既定 on) に戻す。
#[cfg(test)]
pub fn gdn_gpu_scan_reset_force_for_test() {
    GDN_GPU_SCAN_FORCE.store(0, std::sync::atomic::Ordering::Relaxed);
}

/// CPU vs GPU の状態突き合わせ (`DENNO_GDN_GPU_CHECK=1`。診断専用・既定 off)。
///
/// on のとき [`gdn_decode_submit`] は層出力に加えて **scan 後の conv/ssm** を
/// D2H して返す (毎層 1 往復 = 遅い。診断専用なので既定 off)。比較そのものは
/// 呼び出し側 (`SsmLayer::forward_token`) が CPU 参照と行い、最初に違った層と
/// 要素を 1 行だけ出す。
pub fn gdn_gpu_check_on() -> bool {
    static ON: OnceLock<bool> = OnceLock::new();
    *ON.get_or_init(|| {
        matches!(
            std::env::var("DENNO_GDN_GPU_CHECK").as_deref(),
            Ok("1") | Ok("on") | Ok("true")
        )
    })
}

